typedef struct {
    int connection_id;
    time_t last_active_timestamp;
    float current_throughput;
    struct flow* active_flows;
} ConnectionState;

typedef struct {
    int flow_id;
    size_t bytes_transferred;
} Flow;

// Global lock for thread-safe operations
pthread_mutex_t connections_lock = PTHREAD_MUTEX_INITIALIZER;

// Array to manage ConnectionStates, allocated during initialization
ConnectionState** connections;

// Function to initialize the connection manager
int init_connections(int max_connections) {
    connections = (ConnectionState**)malloc(max_connections * sizeof(ConnectionState*));
    for (int i = 0; i < max_connections; i++) {
        connections[i] = (ConnectionState*)malloc(sizeof(ConnectionState));
        connections[i]->connection_id = i;
        connections[i]->last_active_timestamp = time(NULL);
        connections[i]->current_throughput = 0.0f;
        connections[i]->active_flows = NULL;
    }
    return 0;
}

// Function to add a new connection
int add_connection(ConnectionState* connection) {
    pthread_mutex_lock(&connections_lock);
    // Allocate a new slot in the connections array
    ConnectionState** temp_connections = (ConnectionState**)realloc(connections, (connections != NULL ? connections + 1 : 1));
    connection->connection_id = temp_connections->length++;
    temp_connections[connection->connection_id] = connection;
    pthread_mutex_unlock(&connections_lock);
    return 0;
}

// Function to remove a connection
int remove_connection(int connection_id) {
    pthread_mutex_lock(&connections_lock);
    // Find the connection and remove it from the array
    for (int i = 0; i < connections->length; i++) {
        if (connections[i]->connection_id == connection_id) {
            free(connections[connection_id]);
            for (int j = i + 1; j < connections->length; j++) {
                connections[j - 1] = connections[j];
            }
            connections->length--;
            break;
        }
    }
    pthread_mutex_unlock(&connections_lock);
    return 0;
}

// Function to update connection state
int update_connection_state(int connection_id, float new_throughput) {
    pthread_mutex_lock(&connections_lock);
    // Find the connection and update its state
    for (int i = 0; i < connections->length; i++) {
        if (connections[i]->connection_id == connection_id) {
            connections[i]->current_throughput = new_throughput;
            break;
        }
    }
    pthread_mutex_unlock(&connections_lock);
    return 0;
}

