int main() {
    // Example usage
    int n_records = 1000;
    int min_value = 1;
    int max_value = 10000;

    int* dataset = (int*)malloc(n_records * sizeof(int));
    if(dataset == NULL) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    // Initialize the dynamic dataset
    int result = initialize_dataset(n_records, min_value, max_value);
    if(result != 0) {
        printf("Error initializing dataset: %d\n", result);
        free(dataset);
        return -1;
    }

    printf("Dataset initialized successfully.\n");

    // Free allocated memory
    free(dataset);

    return 0;
}

int initialize_dataset(int n_records, int min_value, int max_value) {
    srand(time(NULL)); // Initialize random number generator

    int* offset = (int*)malloc((n_records + 1) * sizeof(int));
    if(offset == NULL) {
        printf("Memory allocation for offset array failed.\n");
        return -1;
    }

    int** key = (int**)calloc(n_records, sizeof(int*));
    if(key == NULL) {
        printf("Memory allocation for key array failed.\n");
        free(offset);
        return -2;
    }

    // Initialize the offset array
    for(int i = 0; i <= n_records; i++) {
        offset[i] = i;
    }

    // Initialize the key array with unique integer values
    for(int i = 0; i < n_records; i++) {
        int val = (rand() % ((max_value - min_value) + 1)) + min_value;
        key[i] = &val;
    }

    // Set record values to random integers within the given range
    for(int i = 0; i < n_records; i++) {
        *(key[i]) = (rand() % ((max_value - min_value) + 1)) + min_value;
    }

    free(offset);
    free(key);

    return 0;
}
