#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <inttypes.h>
#include <pthread.h>

#define CHUNK_SIZE 4096
#define MAX_THREADS 16

typedef struct {
    char* file_path;
    char* output_file_path;
    int chunk_size;
    pthread_t thread[MAX_THREADS];
} Config;

void* process_chunk(void* arg) {
    Config* config = (Config*)arg;
    FILE* file = fopen(config->file_path, "rb");
    if (!file) {
        printf("Error opening file: %s\n", config->file_path);
        return NULL;
    }

    uint8_t buffer[CHUNK_SIZE];
    while (fread(buffer, 1, CHUNK_SIZE, file) > 0) {
        // Perform byte extraction based on user-specified criteria
        for (int i = 0; i < CHUNK_SIZE; i++) {
            if ((buffer[i] & 0x01) == config->chunk_size % 2) {
                // Extract the desired byte
                uint8_t extracted_byte;
                memcpy(&extracted_byte, buffer + i, sizeof(uint8_t));
                printf("%02x", extracted_byte);
            }
        }
    }

    fclose(file);
    return NULL;
}

int main(int argc, char* argv[]) {
    Config config;

    // Parse command-line arguments
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> [chunk_size]\n", argv[0]);
        return 1;
    }

    config.file_path = argv[1];
    config.output_file_path = argv[2];
    config.chunk_size = atoi(argv[3]);

    // Create and join threads for concurrent processing
    pthread_create(&config.thread[0], NULL, process_chunk, &config);
    pthread_join(config.thread[0], NULL);

    return 0;
}
