#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define LOG_DIR "logs/"
#define REPORT_FILE "aggregated_report.txt"
#define ERROR_SERVICE_URL "https://error-service.com/api/log"

// Define the logging levels
enum LogLevel { DEBUG, INFO, WARNING, ERROR };

// Define the logging structure
typedef struct {
    enum LogLevel level;
    char message[256];
} LogEntry;

// Function to process a log file
void* process_log_file(void* arg) {
    // Get the log file path from the argument
    char* log_file = (char*)arg;

    // Open the log file and read its contents
    FILE* file = fopen(log_file, "r");
    if (!file) return NULL;
    fseek(file, 0L, SEEK_END);
    long end = ftell(file);
    rewind(file);
    char* buffer = malloc(end + 1);
    fread(buffer, 1, end, file);
    fclose(file);

    // Parse the log entries from the file
    LogEntry* log_entries = NULL;
    size_t log_entry_count = 0;
    char* token = strtok(buffer, "\n");
    while (token) {
        LogEntry log_entry;
        strcpy(log_entry.message, token);
        // Set the logging level based on the log message content
        // ...
        log_entries = realloc(log_entries, sizeof(LogEntry)*(log_entry_count + 1));
        log_entries[log_entry_count] = log_entry;
        log_entry_count++;
        token = strtok(NULL, "\n");
    }

    // Process each log entry concurrently
    pthread_t threads[log_entry_count];
    for (int i = 0; i < log_entry_count; i++) {
        pthread_create(&threads[i], NULL, process_log_entry, &log_entries[i]);
    }
    for (int i = 0; i < log_entry_count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the log entries and buffer
    free(log_entries);
    free(buffer);

    return NULL;
}

// Function to process a single log entry
void* process_log_entry(void* arg) {
    LogEntry* log_entry = (LogEntry*)arg;

    // Send the log entry to the error service
    char request[256];
    sprintf(request, "https://error-service.com/api/log?level=%s&message=%s", 
            log_entry->level == DEBUG ? "debug" : 
            log_entry->level == INFO ? "info" : 
            log_entry->level == WARNING ? "warning" : "error", 
            log_entry->message);
    FILE* file = fopen("report.txt", "a");
    fprintf(file, "%s\n", request);
    fclose(file);

    return NULL;
}

// Function to generate the aggregated report
void generate_report() {
    // Read the error service report
    FILE* file = fopen(REPORT_FILE, "r");
    if (!file) return;
    char buffer[1024];
    while (fgets(buffer, 1024, file)) {
        // Process each log entry in the report
        LogEntry log_entry;
        sscanf(buffer, "%s\n", log_entry.message);
        // ...
    }
    fclose(file);

    // Write the aggregated report to a new file
    FILE* output_file = fopen("aggregated_report.txt", "w");
    if (!output_file) return;
    fprintf(output_file, "Aggregated Report:\n");
    // ...
    fclose(output_file);
}

// Function to start the logging aggregation tool
int main(int argc, char** argv) {
    // Parse command-line options for configuration and frequency
    // ...

    // Start processing log files concurrently
    pthread_t threads[argc];
    for (int i = 0; i < argc; i++) {
        pthread_create(&threads[i], NULL, process_log_file, argv[i]);
    }
    for (int i = 0; i < argc; i++) {
        pthread_join(threads[i], NULL);
    }

    // Generate the aggregated report
    generate_report();

    return 0;
}
```

Please note that this is just a sample code to give you an idea of how to structure your program. You will need to add error handling, implement the actual processing logic for each log entry and file, handle concurrency, etc.']

