import hashlib
import requests
from threading import Thread
from queue import Queue
import time

class FileHasher:
    def __init__(self, api_url):
        self.api_url = api_url
        self.hash_algorithm = hashlib.sha256()

    def hash_file(self, file_path):
        chunk_size = 1024 * 1024  # 1MB chunks for large files
        chunk_queue = Queue()
        result_queue = Queue()

        def worker():
            while True:
                chunk = chunk_queue.get()
                if chunk is None:
                    break
                self.hash_algorithm.update(chunk)
                chunk_queue.task_done()

        hash_thread = Thread(target=worker, daemon=True)
        hash_thread.start()

        with open(file_path, 'rb') as file:
            while True:
                chunk = file.read(chunk_size)
                if not chunk:
                    break
                chunk_queue.put(chunk)

        chunk_queue.put(None)  # Signal the end of the file

        self.hash_thread.join()  # Wait for the hashing to finish

        final_hash = self.hash_algorithm.hexdigest()
        api_request = {'file_path': file_path, 'hash': final_hash}

        response = requests.post(self.api_url, json=api_request)
        if response.status_code == 200:
            report_response = response.json()
            return final_hash, report_response
        else:
            raise Exception(f"API request failed with status code {response.status_code}")

    def update_hash(self, file_path):
        api_request = {'file_path': file_path}
        response = requests.post(self.api_url, json=api_request)
        if response.status_code == 200:
            report_response = response.json()
            return report_response
        else:
            raise Exception(f"API request failed with status code {response.status_code}")

    def get_hash_reports(self):
        api_request = {}
        response = requests.post(self.api_url, json=api_request)
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception(f"API request failed with status code {response.status_code}")
