#define LIBRARY_PATH "/path/to/your/library"

typedef void (*encrypt_func)(const unsigned char* data, size_t len);
typedef int (*hash_func)(const unsigned char* data, size_t len);

int main() {
    char *library_names[] = {"libopenssl.so", "libbotan.so", "libsodium.so"};
    int i;

    // Dynamic library loading
    void *handle;
    for (i = 0; i < sizeof(library_names)/sizeof(library_names[0]); i++) {
        handle = dlopen(LIBRARY_PATH "/" library_names[i], RTLD_LAZY);
        if (!handle) {
            fprintf(stderr, "Failed to load %s: %s\n", library_names[i], dlerror());
            return 1;
        }
    }

    // Function registration
    encrypt_func encrypt_f;
    hash_func hash_f;

    for (i = 0; i < sizeof(library_names)/sizeof(library_names[0]); i++) {
        if (dlfunc(handle, "encrypt", &encrypt_f)) {
            printf("Loaded %s with encrypt function\n", library_names[i]);
        } else {
            fprintf(stderr, "Failed to load %s: %s\n", library_names[i], dlerror());
            return 1;
        }

        if (dlfunc(handle, "hash", &hash_f)) {
            printf("Loaded %s with hash function\n", library_names[i]);
        } else {
            fprintf(stderr, "Failed to load %s: %s\n", library_names[i], dlerror());
            return 1;
        }
    }

    // Usage example
    const unsigned char* data = "Hello, World!";
    size_t len = strlen((char*)data);

    encrypt_f(data, len);
    hash_f(data, len);

    for (i = 0; i < sizeof(library_names)/sizeof(library_names[0]); i++) {
        dlclose(handle);
    }

    return 0;
}

int dlfunc(void *handle, const char* func_name, void **func_ptr) {
    *func_ptr = dlsym(handle, func_name);
    if (*func_ptr == NULL) {
        fprintf(stderr, "Failed to load function %s: %s\n", func_name, dlerror());
        return -1;
    }
    return 0;
}
