#include <openssl/ssl.h>
#include <openssl/rand.h>
#include <openssl/aes.h>
#include <libpq-fe.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_BUFFER_SIZE 1024 * 1024 * 10 // 10MB

void encrypt_data(const char* input_file, const char* output_file, const char* key) {
    int bytes_read;
    unsigned char buffer[MAX_BUFFER_SIZE];
    FILE* in = fopen(input_file, "rb");
    FILE* out = fopen(output_file, "wb");

    // Open SSL connection
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    SSL* ssl = SSL_new(ctx);
    SSL_set_fd(ssl, stdin, 0);

    while ((bytes_read = fread(buffer, 1, MAX_BUFFER_SIZE, in)) > 0) {
        AES_encrypt(buffer, bytes_read, key); // Encrypt the data using the provided key
        fwrite(buffer, 1, bytes_read, out);
    }

    fclose(in);
    fclose(out);

    SSL_free(ssl);
    SSL_CTX_free(ctx);
}

void decrypt_data(const char* input_file, const char* output_file, const char* key) {
    int bytes_read;
    unsigned char buffer[MAX_BUFFER_SIZE];
    FILE* in = fopen(input_file, "rb");
    FILE* out = fopen(output_file, "wb");

    // Open SSL connection
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    SSL* ssl = SSL_new(ctx);
    SSL_set_fd(ssl, stdin, 0);

    while ((bytes_read = fread(buffer, 1, MAX_BUFFER_SIZE, in)) > 0) {
        AES_decrypt(buffer, bytes_read, key); // Decrypt the data using the provided key
        fwrite(buffer, 1, bytes_read, out);
    }

    fclose(in);
    fclose(out);

    SSL_free(ssl);
    SSL_CTX_free(ctx);
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        printf("Usage: %s [encrypt|decrypt] [input_file] [output_file]\n", argv[0]);
        return 1;
    }

    const char* operation = argv[1];
    const char* input_file = argv[2];
    const char* output_file = argv[3];

    if (strcmp(operation, "encrypt") == 0) {
        encrypt_data(input_file, output_file, "<your_key_here>");
    } else if (strcmp(operation, "decrypt") == 0) {
        decrypt_data(input_file, output_file, "<your_key_here>");
    } else {
        printf("Invalid operation.\n");
        return 1;
    }

    return 0;
}
