['Here is the C application that integrates semaphore-based thread synchronization for managing concurrent access to shared resources in a distributed system:

```c
#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

// Semaphore definitions
sem_t mutex;
sem_t data_sem;

// Data structure to hold shared data
typedef struct {
    int value;
} SharedData;

SharedData* shared_data = NULL;

// Function to initialize semaphores and shared data
void init_semaphore(int value) {
    // Initialize semaphores with the specified initial values
    if (sem_init(&mutex, 0, 1) < 0 || 
        sem_init(&data_sem, 0, 1) < 0) {
        printf("Error initializing semaphore!\n");
        exit(-1);
    }

    // Initialize shared data structure with the specified value
    shared_data = (SharedData*)malloc(sizeof(SharedData));
    shared_data->value = value;
}

// Function to release semaphores and clean up resources
void cleanup() {
    if (sem_destroy(&mutex) < 0 || 
        sem_destroy(&data_sem) < 0) {
        printf("Error destroying semaphore!\n");
    }

    free(shared_data);
}

// Function to update shared data value
void* update_shared_data(void* arg) {
    int new_value = ((int*)arg)[0];
    sem_wait(&mutex); // Acquire the mutex

    // Update the shared data value
    shared_data->value = new_value;

    sem_post(&mutex); // Release the mutex
    return NULL;
}

// Function to read shared data value
void* read_shared_data(void* arg) {
    int value = shared_data->value;
    sem_wait(&data_sem); // Acquire the data semaphore

    printf("Current value: %d\n", value);

    sem_post(&data_sem); // Release the data semaphore
    return NULL;
}

int main() {
    int initial_value = 5; // Initial value for shared data

    init_semaphore(initial_value);

    // Spawn threads to update and read shared data concurrently
    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, update_shared_data, &initial_value);
    pthread_create(&thread2, NULL, read_shared_data, NULL);

    // Wait for both threads to complete
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    cleanup();

    return 0;
}

