#include <functional>
#include <forward_list>
#include <mutex>
#include <shared_mutex>

class LoggerInterface {
public:
    virtual void log(const std::string& message) = 0;
};

void insertAfterOrLogError(std::forward_list<std::string>& list, const char* target, const char* toInsert,
                             std::shared_ptr<LoggerInterface> logger) {
    std::lock_guard<std::mutex> lock(list.mutex);

    auto it = std::find_if(list.begin(), list.end(),
        [target](const std::string& s) { return s.find(target) != std::string::npos; });

    if (it != list.end()) {
        list.insert_after(it, toInsert);
    } else {
        logger->log(std::string("Error: Target string not found. Inserting at the end instead.") +
                    " Target: " + target + ", To insert: " + std::string(toInsert));
        list.append(toInsert);
    }
}
