int main() {
    // Initialize the ASIO IO context
    boost::asio::io_context ioContext;

    // Set up the timer for sending periodic requests
    boost::asio::steady_timer timer(ioContext, boost::posix_time::milliseconds(1000));

    // Create a Sandesh client to send GET requests
    boost::beast::http::request<boost::beast::http::string_body> request;
    request.method(boost::beast::http::verb::get);
    request.target("http://example.com/api/service");

    while (true) {
        try {
            // Send the request and get the response
            boost::beast::http::response<boost::beast::http::string_body> response;
            boost::asio::connect(ioContext, request, response);

            // Process the response
            if (response.status == 200) {
                std::cout << "Successful request: " << response.body << std::endl;
            } else {
                std::cout << "Failed request: " << response.body << std::endl;
            }
        } catch (const boost::system::system_error& e) {
            std::cerr << "Error: " << e.what() << std::endl;
        }

        // Schedule the next request
        timer.expires_from_now(boost::posix_time::milliseconds(1000));
        timer.async_wait(boost::asio::yield_context yield);
    }
}
