public static class SecureQueryExecutor
{
    public static IDataReader ExecuteSecureQuery(
        AuthenticationContext context,
        string connectionString,
        List<SqlParameter> parameters,
        Func<IDataReader, Task> callback)
    {
        // Validate user token against external authentication service
        if (!ValidateUserToken(context.UserToken))
            return ErrorCodes.InvalidToken;

        try
        {
            // Establish secure SQL connection with retry mechanism
            using (var connection = CreateSecureSqlConnection(connectionString))
            {
                for (int attempt = 1; attempt <= 3; attempt++)
                {
                    try
                    {
                        connection.Open();
                        break;
                    }
                    catch (SqlException e)
                    {
                        if (e.Number == 10054) // Connection timed out
                            Thread.Sleep(500); // Wait before retrying
                        else
                            return ErrorCodes.TransientFailure;
                    }
                }

                // Execute parameterized SQL query asynchronously
                var task = connection.ExecuteAsync("SELECT * FROM ...", parameters);
                callback(task.Result);

                // Read and return results from IDataReader instance
                using (var reader = task.Result)
                {
                    while (reader.Read())
                        yield return new { Column1 = reader["Column1"], Column2 = reader["Column2"] };
                }
            }
        }
        catch (Exception e)
        {
            // Log critical operations and errors to centralized logging service
            LogError(e.Message, context.SessionID);

            if (e is SqlException sqlE)
                return ErrorCodes.DatabaseFailure;
            else
                return ErrorCodes.GenericFailure;
        }

        return task.Result;
    }

    // Helper methods for establishing secure connection
    private static SqlConnection CreateSecureSqlConnection(string connectionString)
    {
        var connection = new SqlConnection(connectionString);
        connection.EnableEncryption = true;
        connection.Encryption = ServerMode.EncryptAndTrustServerCertificate;
        return connection;
    }

    // Helper method to validate user token against external authentication service
    private static bool ValidateUserToken(string token)
    {
        // Call external API or perform custom validation logic here
        return true; // Replace with actual validation result
    }
}

public enum ErrorCodes
{
    InvalidToken,
    TransientFailure,
    DatabaseFailure,
    GenericFailure
}
