                if (!authenticated) return;

                // Apply the configuration update to the distributed database
                await ApplyUpdateToDatabaseAsync(key, value);

                // Update the cache with the new configuration value
                lock (_syncLock)
                {
                    _cache[key] = value;
                }

                _logger.LogInformation($"Updated configuration setting '{key}' to '{value}'.");
            }
            catch (Exception ex)
            {
                // Handle errors and retry mechanisms for network failures and service unavailability
                await HandleErrorAsync(ex);
