export async function handler(event: APIGatewayProxyEvent): Promise<APIGatewayProxyResult> {
  try {
    // Handle authentication and authorization
    const authHeader = event.headers['Authorization'];
    if (!authHeader) throw new Error('Unauthorized');

    const cognitoAuth = await cognitoidentityservice.getUserAttributes({
      AccessToken: authHeader.replace('Bearer ', ''),
    }).promise;

    // Validate the user's permissions for the requested action
    if (cognitoAuth.Attributes.find(attr => attr.Name === 'profile:update') !== true) {
      throw new Error('Forbidden');
    }

    switch (event.pathParameters.action) {
      case 'create':
        return await createUserProfile(event.body);
      case 'update':
        return await updateUserProfile(event.body);
      case 'delete':
        return await deleteUserProfile(event.pathParameters.id);
      default:
        return { statusCode: 404, body: 'Not Found' };
    }
  } catch (err) {
    // Handle errors
    return { statusCode: err.statusCode || 500, body: JSON.stringify({ message: err.message }) };
  }
}

// Helper functions for handling CRUD operations
async function createUserProfile(profileData: any): Promise<APIGatewayProxyResult> {
  try {
    const params = {
      TableName: 'your-table-name',
      Item: profileData,
    };

    await dynamodb.put(params).promise;
    return { statusCode: 201, body: JSON.stringify({ message: 'Profile created successfully' }) };
  } catch (err) {
    // Handle errors
    return { statusCode: err.statusCode || 500, body: JSON.stringify({ message: err.message }) };
  }
}

// Implement retry logic for database operations
async function updateUserProfile(profileData: any): Promise<APIGatewayProxyResult> {
  try {
    const params = {
      TableName: 'your-table-name',
      Key: { id: profileData.id },
      UpdateExpression: 'set #profile = :profile',
      ExpressionAttributeNames: { '#profile': 'profile' },
      ExpressionAttributeValues: { ':profile': profileData.profile },
    };

    await dynamodb.update(params).promise;
    return { statusCode: 200, body: JSON.stringify({ message: 'Profile updated successfully' }) };
  } catch (err) {
    // Implement retry logic here
    if (err.statusCode === 500) {
      console.log('Error updating profile:', err);
      setTimeout(() => {
        updateUserProfile(profileData).then((response) => {
          return response;
        }).catch((err) => {
          console.log('Error updating profile:', err);
        });
      }, 1000); // Retry after 1 second
    } else {
      return { statusCode: err.statusCode || 500, body: JSON.stringify({ message: err.message }) };
    }
  }
}

// Implement retry logic for database operations
async function deleteUserProfile(id: string): Promise<APIGatewayProxyResult> {
  try {
    const params = {
      TableName: 'your-table-name',
      Key: { id },
    };

    await dynamodb.delete(params).promise;
    return { statusCode: 200, body: JSON.stringify({ message: 'Profile deleted successfully' }) };
  } catch (err) {
    // Implement retry logic here
    if (err.statusCode === 500) {
      console.log('Error deleting profile:', err);
      setTimeout(() => {
        deleteUserProfile(id).then((response) => {
          return response;
        }).catch((err) => {
          console.log('Error deleting profile:', err);
        });
      }, 1000); // Retry after 1 second
    } else {
      return { statusCode: err.statusCode || 500, body: JSON.stringify({ message: err.message }) };
    }
  }
}
