            _httpClient = httpClient;
            _cache = cache;
            _concurrentThreads = concurrentThreads;
            _apiEndpoint = apiEndpoint;
            _evictionTimeSpan = evictionTimeSpan;
        }

        public async Task ProcessXmlFilesAsync(string[] fileNames)
        {
            foreach (var fileName in fileNames)
            {
                await ProcessXmlFileAsync(fileName);
            }
        }

        private async Task ProcessXmlFileAsync(string fileName)
        {
            using var xmlFile = File.OpenRead(fileName);
            var xmlDoc = XDocument.Load(xmlFile);

            await Parallel.ForEach(xmlDoc.Root.Elements(), async (element) =>
            {
                string enrichedMetadata;
                if (_cache.TryGetValue(element.Name.LocalName, out enrichedMetadata))
                {
                    // Use cached metadata
                }
                else
                {
                    try
                    {
                        var response = await _httpClient.GetAsync($"{_apiEndpoint}/metadata/{element.Name.LocalName}");
                        response.EnsureSuccessStatusCode();
                        enrichedMetadata = await response.Content.ReadAsStringAsync();
                        _cache.TryAdd(element.Name.LocalName, enrichedMetadata);
                    }
                    catch (HttpRequestException ex)
                    {
                        // Handle API error
                    }
                }

                // Process the XML element with the enriched metadata
            });
        }
