import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

import javax.ws.rs.Consumes;
import javax.ws.rs.DELETE;
import javax.ws.rs.GET;
import javax.ws.rs.PUT;
import javax.ws.rs.Path;
import javax.ws.rs.PathParam;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;

@Path("/resources")
public class ResourceService {

    private Map<String, String> resources = new HashMap<>();
    private ExternalDatabase db;
    private ExternalAuthentication auth;

    public ResourceService() {
        // Initialize the external database and authentication services
        db = new ExternalDatabase();
        auth = new ExternalAuthentication();
    }

    @Path("/{id}")
    @GET
    @Produces(MediaType.TEXT_PLAIN)
    public String getResource(@PathParam("id") String id) {
        try {
            // Fetch resource from the database using the provided ID
            String resourceData = db.getResource(id);
            return resourceData;
        } catch (Exception e) {
            // Log and handle errors gracefully
            System.out.println("Error fetching resource: " + e.getMessage());
            return "Failed to retrieve resource";
        }
    }

    @Path("/{id}")
    @PUT
    @Consumes(MediaType.APPLICATION_JSON)
    public Response updateResource(@PathParam("id") String id, String request) {
        try {
            // Update the resource in the database using the provided ID and updated data
            db.updateResource(id, request);
            return Response.ok().build();
        } catch (Exception e) {
            // Log and handle errors gracefully
            System.out.println("Error updating resource: " + e.getMessage());
            return Response.status(500).entity("Failed to update resource").build();
        }
    }

    @Path("/{id}")
    @DELETE
    public Response deleteResource(@PathParam("id") String id) {
        try {
            // Delete the resource from the database using the provided ID and confirm deletion
            db.deleteResource(id);
            return Response.ok().entity("Resource deleted successfully").build();
        } catch (Exception e) {
            // Log and handle errors gracefully
            System.out.println("Error deleting resource: " + e.getMessage());
            return Response.status(500).entity("Failed to delete resource").build();
        }
    }

    public String generateMD5Hash(String id) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = id.getBytes();
            md.update(bytes);
            byte[] hashBytes = md.digest();
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.length; i++) {
                String hex = Integer.toHexString(0xff & hashBytes[i]);
                if (hex.length() == 1) {
                    sb.append('0');
                }
                sb.append(hex);
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            // Log and handle errors gracefully
            System.out.println("Error generating MD5 hash: " + e.getMessage());
            return "";
        }
    }
}
