<?php
namespace UserAccountService;

use Ramsey\Uuid\Uuid;
use Illuminate\Support\Facades\Auth;

class UserController {
    public function __construct(private $db) {}

    public function createAccount(array $data): \stdClass {
        // Validate and sanitize input data
        $validatedData = array_filter($data);

        // Generate a unique user ID using UUID
        $userId = Uuid::uuid4()->toString();

        // Create the account in the database
        $this->db->insert('users', [
            'id' => $userId,
            'username' => $validatedData['username'],
            'password' => password_hash($validatedData['password'], PASSWORD_DEFAULT),
        ]);

        return (object) ['message' => 'Account created successfully'];
    }

    public function updateAccount(array $data): \stdClass {
        // Validate and sanitize input data
        $validatedData = array_filter($data);

        // Update the account in the database
        $this->db->update('users', [
            'username' => $validatedData['username'],
            'password' => password_hash($validatedData['password'], PASSWORD_DEFAULT),
        ], ['id' => $validatedData['userId']]);

        return (object) ['message' => 'Account updated successfully'];
    }

    public function deleteAccount(string $userId): \stdClass {
        // Delete the account from the database
        $this->db->delete('users', ['id' => $userId]);

        return (object) ['message' => 'Account deleted successfully'];
    }
}

class CBackend {
    private $db;

    public function __construct(private $db) {}

    public function getRecords() {
        // Retrieve records from the database
        $records = $this->db->select('records', '*');

        return $records;
    }

    public function putRecord(array $data) {
        // Validate and sanitize input data
        $validatedData = array_filter($data);

        // Insert or update the record in the database
        if (isset($validatedData['id'])) {
            $this->db->update('records', [
                'offset' => $validatedData['offset'],
                'key' => $validatedData['key'],
                'int' => random_int(1, 100),
            ], ['id' => $validatedData['id']]);
        } else {
            $this->db->insert('records', [
                'offset' => $validatedData['offset'],
                'key' => $validatedData['key'],
                'int' => random_int(1, 100),
            ]);
        }
    }

    public function deleteRecord(string $id) {
        // Delete the record from the database
        $this->db->delete('records', ['id' => $id]);
    }
}
