package com.example.stateloader;

import java.io.Closeable;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.archivers.ZipArchiveInputStream;
import org.apache.commons.configuration.CompositeConfiguration;
import org.apache.commons.configuration.Configuration;

public class StateLoader {

    private final CompositeConfiguration config = new CompositeConfiguration();
    private final Map<String, Class<?>> classes = new HashMap<>();
    private final Map<String, Object> cache = new WeakHashMap<>();
    private final int maxMemoryUsage;
    private final long maxLoadTime;

    public StateLoader(int maxMemoryUsage, long maxLoadTime) {
        this.maxMemoryUsage = maxMemoryUsage;
        this.maxLoadTime = maxLoadTime;
    }

    public <T> T loadState(String stateName) throws IOException, ClassNotFoundException {

        Configuration configSection = config.getConfiguration("states." + stateName);
        String filePath = configSection.getString("file.path");
        int compressionLevel = Integer.parseInt(configSection.getString("compression.level"));
        boolean cacheEnabled = Boolean.parseBoolean(configSection.getString("cache.enabled"));

        File file = new File(filePath);

        if (!file.exists()) {
            throw new FileNotFoundException("State file not found: " + filePath);
        }

        try (FileInputStream inputStream = new FileInputStream(file)) {

            ArchiveInputStream archiveStream;
            switch (compressionLevel) {
                case 1:
                    // Use Apache Commons Compress for basic compression
                    archiveStream = new ZipArchiveInputStream(inputStream, "zip");
                    break;
                default:
                    throw new IOException("Unsupported compression level: " + compressionLevel);
            }

            try {
                Class<?> clazz = classes.computeIfAbsent(stateName, name -> {
                    try {
                        return Class.forName(configSection.getString("class.name"));
                    } catch (ClassNotFoundException e) {
                        // handle class not found
                        return null;
                    }
                });

                if (clazz == null) {
                    throw new ClassNotFoundException("State class not found: " + stateName);
                }

                Object state = clazz.getConstructor().newInstance();

                try (Closeable closeable = inputStream) {

                    long loadTimeStart = System.currentTimeMillis();
                    Object deserializedState = deserialize(state, archiveStream);
                    long loadTimeEnd = System.currentTimeMillis();

                    logLoadMetrics(stateName, loadTimeEnd - loadTimeStart);

                    if (cacheEnabled) {
                        cache.put(stateName, state);
                    }

                    return (T) state;
                } catch (Exception e) {
                    // handle exceptions
                    throw new IOException("Error loading state: " + stateName, e);
                }
            } finally {
                archiveStream.close();
            }
        } catch (IOException | ClassNotFoundException e) {
            throw new IOException("Error loading state: " + stateName, e);
        }
    }

    private Object deserialize(Object state, ArchiveInputStream archiveStream) throws IOException {

        // Implement deserialization logic based on the state object's class
        // For example, for JSON serialization:
        // return Jackson.databind.ObjectMapper.readValue(archiveStream, state.getClass());

        // or for YAML serialization:
        // return Snakeyaml.Yaml.loadAs(archiveStream, state.getClass());

        // and so on...
    }

    private void logLoadMetrics(String stateName, long loadTime) {
        System.out.println("Loaded state: " + stateName + ", duration: " + loadTime + "ms");
    }
}
