const { promisify } = require('util');
const { rateLimit } = require('express-rate-limit');
const { asyncReadFile } = require('./async-file-reader');
const { validateJson } = require('./json-validator');
const { aggregateFiles } = require('./file-aggregator');

const apiToken = 'YOUR_API_TOKEN';
const apiKey = 'YOUR_API_KEY';
const apiEndpoint = 'https://api.example.com/files';

const fileReaderPool = new Map();

class FileService {
  async fetchMetadata() {
    const metadata = await promisify(fetch)(`${apiEndpoint}?access_token=${apiToken}&api_key=${apiKey}`);
    return await metadata.json();
  }

  async readFiles(files) {
    const results = [];
    for (const file of files) {
      if (!fileReaderPool.has(file)) {
        fileReaderPool.set(file, asyncReadFile(file));
      }
      results.push(await fileReaderPool.get(file));
    }
    return aggregateFiles(results);
  }

  async validateFiles(files) {
    const errors = [];
    for (const file of files) {
      try {
        await validateJson(file);
      } catch (err) {
        errors.push(err);
      }
    }
    return errors;
  }

  async run() {
    const metadata = await this.fetchMetadata();
    if (!metadata || !Array.isArray(metadata)) {
      throw new Error('Failed to fetch file list');
    }

    const files = metadata.map((file) => ({ name: file.name, size: file.size }));
    const results = await this.readFiles(files);
    const errors = await this.validateFiles(results);

    if (errors.length > 0) {
      console.error(`Validation errors: ${errors}`);
    } else {
      console.log('File validation successful');
    }
  }
}

const service = new FileService();

(async () => {
  try {
    await rateLimit({
      windowMs: 15 * 60 * 1000, // 15 minutes
      max: 100,
      delayMs: 0,
    })(async () => {
      await service.run();
    });
  } catch (err) {
    console.error('Error running file service:', err);
  }
})();
