async function runModuleTests(labels, f) {
  const testResults = { total: 0, successes: 0, failures: 0 };
  const logger = require('logger-service')();
  const mockingService = require('mocking-service')();
  const rateLimiter = require('rate-limiter')();

  for (const label of labels) {
    try {
      // Load module and test suite
      const module = await loadModule(label);
      const testSuite = f(module);

      // Reset mocking service
      await mockingService.reset();

      // Run tests
      const testResultsForModule = await runTests(testSuite, module, label);
      testResults.total += testResultsForModule.total;
      testResults.successes += testResultsForModule.successes;
      testResults.failures += testResultsForModule.failures;

    } catch (error) {
      // Log error and retry up to 3 times
      for (let i = 0; i < 3; i++) {
        try {
          await runTests(testSuite, module, label);
          break;
        } catch (error) {
          logger.error(`Error running tests for ${label}: ${error.stack}`);
          if (i === 2) {
            testResults.failures++;
          }
        }
      }
    }

    // Reset mocking service after each module
    await mockingService.reset();
  }

  return { total: testResults.total, successes: testResults.successes, failures: testResults.failures };
}

async function loadModule(label) {
  const moduleRegistry = require('module-registry')();
  return await moduleRegistry.loadModule(label);
}

async function runTests(testSuite, module, label) {
  let total = 0;
  let successes = 0;

  for (const test of testSuite()) {
    try {
      // Run test
      await test();

      // Log success
      logger.info(`Test ${label} succeeded: ${test.name}`);

      successes++;
      total++;

    } catch (error) {
      // Log error and retry up to 3 times
      for (let i = 0; i < 3; i++) {
        try {
          await test();
          break;
        } catch (error) {
          logger.error(`Error running test ${label}: ${error.stack}`);
          if (i === 2) {
            total++;
          }
        }
      }
    }
  }

  return { total, successes };
}
