const express = require('express');
const app = express();
const port = 3000;
const axios = require('axios');

// Load sentiment analysis API credentials from environment variables
const apiKey = process.env.SENTIMENT_API_KEY;
const apiEndpoint = process.env.SENTIMENT_API_ENDPOINT;

// Define a helper function to extract product features and sentiments from text
async function analyzeText(text) {
  // Tokenize the text and filter out common stop words and punctuation
  const tokens = text.toLowerCase().replace(/[^a-z0-9\s]/g, '').split(/\s+/);
  const stopWords = ['the', 'and', 'of', 'to', 'in'];
  const filteredTokens = tokens.filter(token => !stopWords.includes(token));

  // Extract product features and sentiments using NLP techniques
  // For example, you could use a library like spaCy or Stanford CoreNLP
  const features = [];
  const sentiments = [];

  for (const token of filteredTokens) {
    // Perform sentiment analysis on the token using the external API
    try {
      const response = await axios.get(`${apiEndpoint}/sentiment`, {
        params: { text: token },
        headers: { 'Authorization': `Bearer ${apiKey}` }
      });
      const sentimentScore = response.data.score;
      sentiments.push(sentimentScore);

      // Extract product features from the token
      // For example, you could use regular expressions or machine learning models
      const featureRegex = /product-feature/i;
      if (featureRegex.test(token)) {
        features.push(token);
      }
    } catch (error) {
      console.error(error);
    }
  }

  return { features, sentiments };
}

// Define a route to process real-time customer feedback from multiple sources
app.post('/processFeedback', async (req, res) => {
  const feedback = req.body;
  const processedFeedback = {};

  for (const source in feedback) {
    for (const item of feedback[source]) {
      if (item.text) {
        // Analyze the text using the helper function
        const analysisResult = await analyzeText(item.text);
        processedFeedback[source] = { features: analysisResult.features, sentiments: analysisResult.sentiments };
      }
    }
  }

  res.json(processedFeedback);
});

