```javascript
const { EventEmitter } = require('events');
const { promisify } = require('util');
const request = require('request');
const redis = require('redis');

class ThemeManager extends EventEmitter {
  constructor(options) {
    super();
    this.options = options;
    this.cache = redis.createClient({
      host: options.redisHost,
      port: options.redisHash,
      password: options.redisPass
    });
    this.themeBitmaps = {};
    this.fetching = false;
  }

  async fetchThemes() {
    if (this.fetching) return;

    this.fetching = true;
    const retryInterval = 1000;
    const maxRetries = 5;

    for (let i = 1; i <= 10; i++) {
      try {
        const response = await promisify(request.get)(`https://api.image-service.com/themes/${i}.png`);
        if (!response.ok) {
          throw new Error(`Failed to fetch theme ${i}: ${response.status} ${response.statusText}`);
        }
        this.themeBitmaps[i] = response.body;
      } catch (error) {
        if (error.name === 'RateLimitError' || error.name === 'TimeoutError') {
          // Exponential backoff for transient errors
          await new Promise(resolve => setTimeout(() => resolve(), Math.min(1000 * 2 ** (maxRetries - 1), 30000)));
          i--;
        } else if (i < maxRetries) {
          await new Promise(resolve => setTimeout(() => resolve(), retryInterval));
          i--;
        } else {
          throw error;
        }
      }
    }

    this.fetching = false;
    this.emit('themesFetched');
  }

  async getThemeBitmap(themeId) {
    if (!this.themeBitmaps[themeId]) {
      await new Promise(resolve => setTimeout(() => resolve(), 100));
      const response = await promisify(request.get)(`https://api.image-service.com/themes/${themeId}.png`);
      this.themeBitmaps[themeId] = response.body;
    }
    return this.themeBitmaps[themeId];
  }

  async checkThemeAvailability(themeId) {
    return !!this.themeBitmaps[themeId];
  }

  startFetching() {
    if (!this.fetching) {
      this.fetching = true;
      this.emit('fetchStarted');
    }
  }

  stopFetching() {
    if (this.fetching) {
      this.fetching = false;
      this.emit('fetchStopped');
    }
  }
}

module.exports = ThemeManager;
