async function loadResourceBundle(config) {
  const { primarySource, secondarySource } = config;
  const cache = {};
  let items = [];

  async function loadFromPrimary() {
    try {
      if (primarySource.startsWith('http')) {
        const response = await fetch(primarySource);
        const buffer = Buffer.allocUnsafe(1024 * 1024); // 1MB buffer
        await response.arrayBuffer().then((data) => {
          items = JSON.parse(data.toString());
        });
      } else {
        const fileContents = await fs.promises.readFile(primarySource, 'utf8');
        items = JSON.parse(fileContents);
      }
    } catch (error) {
      console.error(`Error loading from primary source: ${error}`);
      if (secondarySource) return loadFromSecondary();
    }
  }

  async function loadFromSecondary() {
    try {
      const response = await fetch(secondarySource);
      const buffer = Buffer.allocUnsafe(1024 * 1024); // 1MB buffer
      await response.arrayBuffer().then((data) => {
        items = JSON.parse(data.toString());
      });
    } catch (error) {
      console.error(`Error loading from secondary source: ${error}`);
    }
  }

  async function loadFromCache(key) {
    if (!cache[key]) {
      const cachedItem = await fs.promises.readFile(key, 'utf8');
      cache[key] = JSON.parse(cachedItem);
    }
    return cache[key];
  }

  function retryLoad() {
    setTimeout(() => {
      loadResourceBundle(config).then((result) => {
        console.log('Retried successfully!');
      }).catch((error) => {
        console.error(`Error on retry: ${error}`);
      });
    }, 5000); // 5-second delay
  }

  function validateItems() {
    if (!items || items.length === 0) return { count: 0, items: [] };
    const itemStats = {};
    for (const item of items) {
      const itemType = typeof item;
      if (!itemStats[itemType]) itemStats[itemType] = 1;
      else itemStats[itemType]++;
    }
    return { count: items.length, items };
  }

  try {
    await loadFromPrimary();
    const result = validateItems();
    return Promise.resolve(result);
  } catch (error) {
    if (!secondarySource) throw error;
    retryLoad();
    return loadResourceBundle(config).then((result) => {
      return result;
    });
  }
}

// Example usage:
const config = {
  primarySource: 'http://example.com/data.json',
  secondarySource: 'file:///path/to/fallback.json',
};
loadResourceBundle(config)
  .then((result) => {
    console.log(result);
  })
  .catch((error) => {
    console.error(error);
  });
