["```javascript
import { HTMLElement } from 'domino';
import fetch from 'node-fetch';

class LazyLoader {
  constructor(rootElement, apiEndpoint) {
    this.rootElement = rootElement;
    this.apiEndpoint = apiEndpoint;
    this.loadedElements = {};
    this.pendingRequests = [];
  }

  async load(elements, filterSelector) {
    if (!elements || !Array.isArray(elements)) return;

    for (const element of elements) {
      if (!element.selector || !this.isMatching(element.selector, filterSelector))
        continue;

      const loadedElement = await this.loadElement(element);
      if (loadedElement)
        this.rootElement.appendChild(loadedElement);

      if (element.children && element.children.length > 0) {
        await this.load(element.children, filterSelector);
      }
    }

    return this.rootElement;
  }

  async loadElement({ selector, children }) {
    if (this.loadedElements[selector])
      return this.loadedElements[selector];

    const request = fetch(`${this.apiEndpoint}/${selector}`);
    const response = await request.then((res) => res.json());

    if (!response || !Array.isArray(response)) {
      console.error(`Failed to load element: ${selector}`);
      return null;
    }

    try {
      const html = response[0];
      const element = new HTMLElement(html);
      this.loadedElements[selector] = element;

      if (children && children.length > 0) {
        await this.load(children, selector);
      }
    } catch (error) {
      console.error(`Error loading element: ${selector} - ${error}`);
    }

    return this.loadedElements[selector];
  }

  isMatching(selector, filterSelector) {
    if (!filterSelector || !Array.isArray(filterSelector)) return true;

    for (const fs of filterSelector)
      if (fs.toString() === selector.toString()) return false;

    return true;
  }
}

export default LazyLoader;
```

