import { dirname, join } from 'path';
import { fileURLToPath } from 'url';
import { importModule } from './moduleLoader.js';
import { retry, timeout, exponentialBackoff } from './utils.js';

const moduleDir = join(dirname(fileURLToPath(import.meta.url)), 'modules');

let activeModules = {};
let modulePool = {};

async function loadModule(moduleName) {
  if (activeModules[moduleName]) return;

  try {
    const moduleDef = await importModule(moduleName);
    const moduleInst = new moduleDef.default();
    activeModules[moduleName] = moduleInst;
    modulePool[moduleName] = moduleInst;
  } catch (error) {
    console.error(`Error loading module ${moduleName}: ${error}`);
  }
}

async function unloadModule(moduleName) {
  if (!activeModules[moduleName]) return;

  try {
    delete activeModules[moduleName];
    delete modulePool[moduleName];
  } catch (error) {
    console.error(`Error unloading module ${moduleName}: ${error}`);
  }
}

async function reloadModule(moduleName) {
  await unloadModule(moduleName);
  await loadModule(moduleName);
}

async function handleConfigUpdate(config) {
  try {
    const { moduleName, config } = config;
    if (modulePool[moduleName]) {
      // Update module configuration
      modulePool[moduleName].updateConfig(config);
    }
  } catch (error) {
    console.error(`Error updating module ${moduleName} config: ${error}`);
  }
}

async function handleApiRequest(req, res) {
  try {
    const { moduleName } = req.body;
    await loadModule(moduleName);

    // Process the request
    const response = await modulePool[moduleName].handleRequest(req);
    res.send(response);
  } catch (error) {
    console.error(`Error handling request for module ${moduleName}: ${error}`);
    res.status(500).send({ message: 'Internal Server Error' });
  }
}

async function apiHandler(req, res) {
  try {
    const response = await handleConfigUpdate(req.body);
    if (response) {
      res.send(response);
    } else {
      res.status(404).send({ message: 'Not Found' });
    }
  } catch (error) {
    console.error(`Error handling API request: ${error}`);
    res.status(500).send({ message: 'Internal Server Error' });
  }
}

async function startService() {
  // Start the external API
  try {
    await retry(() => {
      return apiHandler();
    }, 3, 1000);
  } catch (error) {
    console.error(`Error starting service: ${error}`);
  }
}

startService();
