import java.io.*;
import java.net.*;
import java.nio.channels.*;
import java.security.*;
import javax.net.ssl.*;

public class SecureService {
    public static void main(String[] args) throws Exception {
        // Initialize SSL context
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(new KeyManager[] { new MyKeyManager() },
                new TrustManager[] { new MyTrustManager() }, null);

        // Create a ServerSocketChannel
        ServerSocketChannel serverSocketChannel =
                ServerSocketChannel.open();
        InetSocketAddress address = new InetSocketAddress(8443);
        serverSocketChannel.bind(address);

        // Set up selector to handle connections
        Selector selector = Selector.open();

        // Register the channel with the selector
        serverSocketChannel.configureBlocking(false);
        SelectionKey key = serverSocketChannel.keyFor(selector);
        if (!key.isValid()) {
            key = serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);
        }

        while (true) {
            selector.select();
            Set<SelectionKey> keys = selector.selectedKeys();

            for (SelectionKey key : keys) {
                if (key.isAcceptable()) {
                    ServerSocketChannel ch = (ServerSocketChannel) key.channel();
                    Socket socket = ch.accept();
                    // Handle connection
                    handleConnection(socket);
                }
            }

            keys.clear();
        }
    }

    private static void handleConnection(Socket socket) throws Exception {
        // Get the SSLContext and wrap the socket with a SSLSocket
        SSLContext sslContext = SSLContext.getInstance("TLS");
        SSLSocketFactory factory = sslContext.getSocketFactory();
        SSLSocket sslSocket = (SSLSocket) factory.createSocket(socket);
        sslSocket.startHandshake();

        // Set up authentication for mutual TLS verification
        Authenticator authenticator = new MyAuthenticator(sslSocket);
        sslSocket.setSoTimeout(5000);

        // Handle incoming data
        DataInputStream in = new DataInputStream(new InputStreamReader(
                new FileInputStream(new File("input.txt")), "UTF-8"));
        DataOutputStream out = new DataOutputStream(socket.getOutputStream());
        while (true) {
            String line = in.readLine();
            if (line == null || line.equals("quit")) {
                break;
            }
            out.writeBytes(line);
            out.flush();
        }

        // Close the socket
        sslSocket.close();
    }
}

