public class TaskManagerService {
    private static final Logger logger = LoggerFactory.getLogger(TaskManagerService.class);
    private static final int CORE_POOL_SIZE = 5;
    private static final int MAXIMUM_POOL_SIZE = 10;
    private static final long KEEP_ALIVE_TIME = TimeUnit.SECONDS.toNanos(30);

    private ExecutorService executorService;

    public TaskManagerService() {
        this.executorService = Executors.newFixedThreadPool(CORE_POOL_SIZE, new CustomThreadFactory());
    }

    public void start() {
        ScheduledExecutorService scheduledExecutorService = Executors.newScheduledThreadPool(CORE_POOL_SIZE);
        scheduledExecutorService.scheduleAtFixedRate(() -> processQueue(), 0, 1, TimeUnit.MINUTES);
    }

    private void processQueue() {
        try {
            while (true) {
                Task task = getTaskFromQueue();
                if (task != null) {
                    processTask(task);
                } else {
                    break;
                }
            }
        } catch (Exception e) {
            logger.error("Error processing queue", e);
            Thread.sleep(1000 * 60); // retry after 1 minute
        }
    }

    private Task getTaskFromQueue() {
        // implement logic to retrieve task from the queue
    }

    private void processTask(Task task) {
        try {
            if (task.isHighPriority()) {
                executorService.submit(() -> processHighPriorityTask(task));
            } else {
                executorService.submit(() -> processRegularTask(task));
            }
        } catch (RejectedExecutionException e) {
            // task rejected due to max queue size, retry later
            Thread.sleep(1000 * 60); // retry after 1 minute
        }
    }

    private void processHighPriorityTask(Task task) {
        // implement logic to process high-priority tasks
    }

    private void processRegularTask(Task task) {
        // implement logic to process regular tasks
    }

    public class CustomThreadFactory implements ThreadFactory {
        @Override
        public Thread newThread(Runnable r) {
            Thread thread = new Thread(r);
            thread.setDaemon(true);
            return thread;
        }
    }
