mod build_and_resource_loader {
    use std::fs::{read_dir, read_to_string};
    use std::path::Path;
    use anyhow::{Result, ensure};
    use serde_json::{json, to_string_pretty};
    use walkdir::{DirEntry, WalkDir};

    pub struct BuildAndResourceLoader {
        lib_path: String,
        cache_dir: String,
    }

    impl BuildAndResourceLoader {
        pub fn new(lib_path: &str, cache_dir: &str) -> Self {
            Self {
                lib_path: lib_path.to_string(),
                cache_dir: cache_dir.to_string(),
            }
        }

        pub fn build_and_load(&self, src_path: &str) -> Result<(i32, usize), String> {
            // Load the resource bundle
            let mut bundles = Vec::new();
            for entry in WalkDir::new(src_path).into_iter().filter_map(|e| e.ok()) {
                if let Some(ext) = entry.file_name().and_then(|n| n.to_str().rfind(".json")) {
                    let path = entry.path();
                    let contents = read_to_string(&path)?;
                    bundles.push(json!({
                        "name": path.file_name().unwrap().to_str().unwrap(),
                        "contents": to_string_pretty(&serde_json::from_str(&contents)?)?
                    }));
                }
            }

            // Compile the Rust code
            let mut build_result = std::process::Command::new("rustc")
                .arg("--crate-type=lib")
                .arg(src_path)
                .output();

            // Handle errors and caching
            if !build_result.is_ok() {
                ensure!(false, "Compilation failed");
            }

            Ok((build_result.status().code(), bundles.len()))
        }
    }
}
