    public function updateClinicStatus($clinicId, $status) {
        $client = new Client(['base_uri' => $this->messageBrokerUrl]);
        $rabbitMQQueueName = 'clinics_queue';

        // Send a message to the RabbitMQ queue
        $client->publish([
            'queue' => $rabbitMQQueueName,
            'body' => json_encode(['clinic_id' => $clinicId, 'status' => $status]),
            'persistent' => true,
        ]);

        // Update the PostgreSQL database table
        $dbConn = pg_connect("host=$this->dbHost dbname=$this->dbName user=$this->dbUsername password=$this->dbPassword");
        if (!$dbConn) {
            throw new Exception('Database connection failed');
        }
        $query = "UPDATE clinics SET status = '$status', last_modified_ip = inet_server_addr(), timestamp = current_timestamp WHERE id = $clinicId";
        pg_query($dbConn, $query);
        pg_close($dbConn);

        return new JsonResponse(['success' => true]);
    }
}

