#include <pthread.h>
#include <semaphore.h>
#include <sys/mman.h>
#include <fcntl.h>

// Semaphore key for the clinic status update semaphore
#define SEM_KEY 0x12345678

// Mutex and semaphore variables
pthread_mutex_t mutex;
sem_t *clinicStatusSemaphore;

void* clinic_status_util(void*) {
    // Initialize the mutex and semaphore
    pthread_mutex_init(&mutex, NULL);
    int sem_fd = shm_open(SEM_KEY, O_RDWR | O_CREAT, 0644);
    if (sem_fd < 0) {
        perror("shm_open");
        return NULL;
    }
    clinicStatusSemaphore = sem_open(sem_fd, O_RDWR);
    if (!clinicStatusSemaphore) {
        perror("sem_open");
        return NULL;
    }

    // Wait for the semaphore to be released
    while (1) {
        sem_wait(clinicStatusSemaphore);
        // Critical section: update clinic status here
        // ...
        sem_post(clinicStatusSemaphore);
    }
}

int main() {
    pthread_t thread;
    int ret = pthread_create(&thread, NULL, clinic_status_util, NULL);
    if (ret) {
        perror("pthread_create");
        return -1;
    }

    // Clean up semaphore resources
    sem_close(clinicStatusSemaphore);
    shm_unlink(SEM_KEY);

    return 0;
}
