    private final CacheManager cacheManager;

    public EmployeeService(RestTemplate restTemplate, CacheManager cacheManager) {
        this.restTemplate = restTemplate;
        this.cacheManager = cacheManager;
    }

    public List<Employee> getEmployeesByManagerId(String managerId) {
        // Fetch employee details from HR API
        String url = "https://hr-api.com/employees?manager_id=" + managerId;
        ResponseEntity<String> response = restTemplate.getForEntity(url, String.class);

        if (response.getStatusCode() == HttpStatus.OK) {
            List<Employee> employees = new ArrayList<>();
            JSONObject jsonObject = new JSONObject(response.getBody());
            for (Iterator<String> iterator = jsonObject.keys(); iterator.hasNext();) {
                String employeeId = iterator.next();
                JSONObject employeeData = jsonObject.getJSONObject(employeeId);
                Employee employee = new Employee(
                    employeeId,
                    employeeData.getString("name"),
                    employeeData.getString("city"),
                    employeeData.getString("address"),
                    employeeData.getString("department")
                );
                employees.add(employee);
            }
            return employees;
        } else {
            // Handle API failure or rate limit
            return Collections.emptyList();
        }
    }

    public void updateEmployee(Employee employee) {
        // Update employee details in HR API
        String url = "https://hr-api.com/employees/" + employee.getId();
        restTemplate.put(url, employee);
    }
