<?php

class SessionManager {
    private $redis;
    private $maxLifetime;

    public function __construct($redisHost = 'localhost', $redisPort = 6379) {
        $this->redis = new Redis();
        $this->redis->connect($redisHost, $redisPort);
        $this->maxLifetime = 31536000; // 1 year in seconds
    }

    public function startSession() {
        $sessionId = $this->generateUniqueSessionId();
        $this->redis->setex("sess:$sessionId", $this->maxLifetime, json_encode(array()));
        return $sessionId;
    }

    private function generateUniqueSessionId() {
        $id = bin2hex(random_bytes(10));
        while ($this->redis->exists("sess:$id")) {
            $id = bin2hex(random_bytes(10));
        }
        return $id;
    }

    public function getSession($sessionId) {
        if (!$this->isValidSession($sessionId)) {
            throw new Exception('Invalid session ID');
        }
        return json_decode($this->redis->get("sess:$sessionId"), true);
    }

    private function isValidSession($sessionId) {
        return $this->redis->exists("sess:$sessionId") && time() - $this->redis->ttl("sess:$sessionId") < $this->maxLifetime;
    }

    public function updateSession($sessionId, array $data) {
        if (!$this->isValidSession($sessionId)) {
            throw new Exception('Invalid session ID');
        }
        $this->redis->set("sess:$sessionId", json_encode(array_merge(json_decode($this->redis->get("sess:$sessionId"), true), $data)));
    }

    public function destroySession($sessionId) {
        if (!$this->isValidSession($sessionId)) {
            throw new Exception('Invalid session ID');
        }
        $this->redis->delete("sess:$sessionId");
    }

    public function regenerateSessionId($oldSessionId, $newSessionId) {
        if (!$this->isValidSession($oldSessionId)) {
            throw new Exception('Invalid old session ID');
        }
        $this->updateSession($oldSessionId, array('id' => $newSessionId));
        $this->destroySession($oldSessionId);
    }
}

class SessionHandler implements SessionHandlerInterface {
    private $manager;

    public function __construct(SessionManager $manager) {
        $this->manager = $manager;
    }

    public function open() {}

    public function close() {}

    public function read($id) {
        return $this->manager->getSession($id);
    }

    public function write($id, $data) {
        $this->manager->updateSession($id, $data);
    }

    public function destroy($id) {
        $this->manager->destroySession($id);
    }
}

interface SessionHandlerInterface {
    public function open();
    public function close();
    public function read($id);
    public function write($id, $data);
    public function destroy($id);
}
