class AttackCooldown {
public:
    AttackCooldown(int minCooldown, int maxCooldown) : 
        minCooldown_(minCooldown), maxCooldown_(maxCooldown),
        cooldownTimer_(std::chrono::milliseconds(std::rand() % (maxCooldown - minCooldown) + minCooldown)) {}

    void startCooldown() {
        std::unique_lock<std::mutex> lock(mutex_);
        if (!cooldownTimer_.load()) {
            // Already in cooldown, nothing to do
            return;
        }
        cooldownTimer_ = std::chrono::milliseconds(std::rand() % (maxCooldown - minCooldown) + minCooldown);
        lock.unlock();
        cv_.notify_one(); // Notify one waiting thread
    }

    bool isReady() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (!cooldownTimer_.load()) {
            // Wait for cooldown timer to expire or interrupted by another thread
            cv_.wait(lock);
        }
        return true;
    }

private:
    int minCooldown_;
    int maxCooldown_;
    std::atomic<std::chrono::milliseconds> cooldownTimer_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

void executeStrategicAttack(std::vector<AttackCooldown*> attacks, int currentPlayer) {
    // Select attack based on player's character and situation
    AttackCooldown* selectedAttack = &attacks[currentPlayer];

