Error check_length(const char* str, size_t delimiter_len) {
    size_t new_len = strlen(str) + delimiter_len + 1; // Add length of delimiter and null terminator
    if (new_len > MAX_LENGTH) {
        return (Error){-1, "String exceeds maximum length"};
    }
    return (Error){0, NULL}; // No error
}

void append_delimiter(const char* str, size_t delimiter_len, Error* e) {
    size_t new_len = strlen(str) + delimiter_len + 1; // Add length of delimiter and null terminator
    char* new_str = malloc(new_len * sizeof(char)); // Allocate memory for the new string
    if (new_str == NULL) {
        *e = (Error){-2, "Memory allocation failed"};
    } else {
        strcpy(new_str, str);
        strcat(new_str, DELIMITER); // Append the delimiter
        *e = check_length(new_str, delimiter_len); // Check the length of the new string
        if (*e->code != 0) {
            log_error(*e); // Log any errors that occurred during the process
            free(new_str);
            *e = (Error){-3, "String exceeded maximum length"};
        } else {
            printf("%s\n", new_str); // Print the modified string if no errors occurred
        }
    }
}

int main() {
    Error e;
    append_delimiter("Hello", strlen(DELIMITER), &e);
    return 0;
}
