Event* process_event(const char* line) {
    Event* event = (Event*)malloc(sizeof(Event));
    char* token = strtok(line, ",");
    if (token != NULL && sscanf(token, "%d", &event->num1) == 1) {
        token = strtok(NULL, ",");
        if (token != NULL && sscanf(token, "%d", &event->num2) == 1) {
            return event;
        }
    }
    free(event);
    return NULL;
}

int calculate_average(Event* event) {
    int sum = event->num1 + event->num2;
    return sum / 2;
}

void print_event(Event* event, char* output_format) {
    if (output_format != NULL) {
        printf("%s, %d\n", output_format, calculate_average(event));
    } else {
        printf(",%d\n", calculate_average(event));
    }
}

