    int debug_mode = 0;
    char* output_format = NULL;

    yaml_config_file_t config;
    vendor_autoloader_init();

    if (yaml_load_config(&config, "path_to_config_file.yml") == 1) {
        log_level = config.log_level;
        debug_mode = config.debug_mode;
        output_format = config.output_format;
    }

    FILE* file = fopen("log_file.log", "r");
    if (file == NULL) {
        vendor_autoloader_error(VENDOR_AUTOLOADER_ERROR_FILE_NOT_FOUND);
        return 1;
    }

