    Event* event = NULL;

    while (fgets(line, MAX_LINE_LENGTH, file)) {
        event = process_event(line);
        if (event != NULL) {
            print_event(event, output_format);
            free(event);
        } else {
            vendor_autoloader_error(VENDOR_AUTOLOADER_ERROR_INVALID_ENTRY);
        }
    }

    fclose(file);

    return 0;
}

