// Renames all files within the specified directory, appending a timestamp and version number to each file's name
RenameErrorCode renameDirectoryWithVersioning(const char* directoryPath, int initialVersionNumber) {
    // Initialize error code
    RenameErrorCode errorCode = RENAME_SUCCESS;

    // Validate the directory path
    if (!isValidDirectoryPath(directoryPath)) {
        errorCode = RENAME_ERROR_DIR_NOT_FOUND;
    }

    // Initialize the file rename information array
    FileRenameInfo* filesToRename = NULL;
    int numFilesToRename = 0;

    // Scan the directory for files to rename
    DIR* dir = opendir(directoryPath);
    if (dir != NULL) {
        struct dirent* ent;
        while ((ent = readdir(dir)) != NULL) {
            if (!isHiddenFile(ent->d_name)) { // Skip hidden files, if needed
                char filePath[MAX_FILE_NAME_LENGTH + 1];
                sprintf(filePath, "%s/%s", directoryPath, ent->d_name);

                // Validate the file name and calculate its length
                int fileNameLength = validateFileName(filePath);
                if (fileNameLength >= MAX_FILE_NAME_LENGTH) {
                    errorCode = RENAME_ERROR_MAX_FILE_NAME_LENGTH;
                    break; // Stop processing further files
                }

                // Create a new FileRenameInfo structure for this file
                FileRenameInfo* fileToRename = malloc(sizeof(FileRenameInfo));
                fileToRename->originalName = strdup(ent->d_name);
                fileToRename->versionNumber = initialVersionNumber;
                fileToRename->timestamp = time(NULL);

                // Add the file to the array and increment the count
                filesToRename = realloc(filesToRename, (numFilesToRename + 1) * sizeof(FileRenameInfo));
                filesToRename[numFilesToRename] = fileToRename;
                numFilesToRename++;
            }
        }
        closedir(dir);
    }

    // Perform the actual renaming
    for (int i = 0; i < numFilesToRename; i++) {
        FileRenameInfo* fileToRename = &filesToRename[i];
        char* newFileName = malloc(strlen(fileToRename->originalName) + 21); // Account for timestamp and version number

        // Format the new file name with the timestamp and version number
        sprintf(newFileName, "%s-%ld-v%03d", fileToRename->originalName, fileToRename->timestamp, fileToRename->versionNumber);

        // Perform the actual rename operation (consider a locking mechanism for concurrency)
        errorCode = renameFile(directoryPath, fileToRename->originalName, newFileName);
        if (errorCode != RENAME_SUCCESS) {
            break; // Stop processing further files in case of error
        }

        // Increment the version number
        initialVersionNumber++;
        free(fileToRename->originalName);
    }

    // Clean up and return the result
    for (int i = 0; i < numFilesToRename; i++) {
        free(filesToRename[i].newFileName);
        free(filesToRename[i].originalName);
        free(filesToRename[i]);
    }
    free(filesToRename);

    if (errorCode == RENAME_SUCCESS) {
        // Return the final version number
        return errorCode;
    } else {
        // Return the error code and log any issues
