package com.commandexecutor;

import java.io.IOException;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.http.client.HttpComponentsClientHttpRequestFactory;
import org.springframework.web.client.RestTemplate;

@SpringBootApplication
public class CommandExecutorApplication {

    @Value("${api.endpoint}")
    private String apiEndpoint;

    @Bean
    public RestTemplate restTemplate() {
        return new RestTemplate(new HttpComponentsClientHttpRequestFactory());
    }

    @Bean
    public ThreadPoolExecutor threadPoolExecutor(@Value("${concurrency.limit}") int concurrencyLimit) {
        return (ThreadPoolExecutor) Executors.newFixedThreadPool(concurrencyLimit);
    }

    @Bean
    public BlockingQueue<Runnable> taskQueue() {
        return new LinkedBlockingQueue<>();
    }

    public static void main(String[] args) {
        SpringApplication.run(CommandExecutorApplication.class, args);
    }
}

package com.commandexecutor.api;

import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.TimeUnit;

import org.apache.commons.io.FileUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.core.ParameterizedTypeReference;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;
import org.springframework.web.client.RestTemplate;

public class TaskExecutor {

    @Autowired
    private RestTemplate restTemplate;

    @Autowired
    private ThreadPoolTaskExecutor threadPoolTaskExecutor;

    @Autowired
    private BlockingQueue<Runnable> taskQueue;

    public void executeTasks() {
        while (true) {
            try {
                Runnable task = taskQueue.take();
                long start = Instant.now().toEpochMilli();
                int attempts = 0;
                boolean success = false;
                do {
                    try {
                        ResponseEntity<List<String>> response = restTemplate.exchange(apiEndpoint, HttpMethod.GET, null, new ParameterizedTypeReference<List<String>>() {
                        });
                        if (response.getStatusCode() == HttpStatus.OK) {
                            List<String> tasks = response.getBody();
                            for (String taskName : tasks) {
                                TaskRunnable runnable = new TaskRunnable(taskName);
                                threadPoolTaskExecutor.submit(runnable);
                            }
                            success = true;
                            break;
                        } else {
                            // handle API failure
                            attempts++;
                            if (attempts >= 5) {
                                // exponential backoff and jitter
                                long delay = (long) Math.pow(2, attempts - 1) * 1000 + new java.util.Random().nextInt((int) Math.pow(2, attempts));
                                try {
                                    Thread.sleep(delay);
                                } catch (InterruptedException e) {
                                    Thread.currentThread().interrupt();
                                }
                            }
                        }
                    } catch (IOException e) {
                        // handle connection failure
                    }
                } while (!success || attempts < 5);
                long end = Instant.now().toEpochMilli();
                System.out.println("Task execution time: " + (end - start) + " ms");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private class TaskRunnable implements Runnable {

        private String taskName;

        public TaskRunnable(String taskName) {
            this.taskName = taskName;
        }

        @Override
        public void run() {
            try {
                // execute task logic here
                FileUtils.forceDelete(new File(taskName));
                Thread.sleep(1000); // simulate task execution time
                System.out.println("Task " + taskName + " completed");
            } catch (IOException e) {
                System.err.println("Error executing task: " + e.getMessage());
            }
        }
    }
}

