// Define a struct to hold OAuth2 access token response
typedef struct {
    char* access_token;
    char* token_type;
    int expires_in;
    char* refresh_token;
} oauth_response_t;

// Function to validate and parse the JSON payload
oauth_response_t* json_oauth_response(char* json_payload) {
    json_object* jobj = json_decode(json_payload, 0);

    if (!jobj) {
        return NULL; // Malformed JSON or memory allocation failure
    }

    oauth_response_t* response = (oauth_response_t*)malloc(sizeof(oauth_response_t));

    response->access_token = json_object_get_string(jobj, "access_token");
    if (!response->access_token || strlen(response->access_token) == 0) {
        json_object_put(jobj);
        free(response);
        return NULL; // Invalid or missing access token
    }

    response->token_type = json_object_get_string(jobj, "token_type");
    if (strcmp(response->token_type, "Bearer") != 0) {
        json_object_put(jobj);
        free(response);
        return NULL; // Invalid token type
    }

    response->expires_in = json_object_get_int(jobj, "expires_in");
    if (response->expires_in <= 0) {
        json_object_put(jobj);
        free(response);
        return NULL; // Invalid expiration time
    }

    char* refresh_token_str = json_object_get_string(jobj, "refresh_token");
    response->refresh_token = refresh_token_str ? strdup(refresh_token_str) : NULL;

    json_object_put(jobj);

    return response;
}

// Function to validate and process the OAuth2 access token
int process_oauth_response(oauth_response_t* response) {
    if (!response || !response->access_token || !response->token_type || response->expires_in <= 0) {
        // Invalid or missing fields
        printf("Error: Invalid or missing fields in OAuth2 access token response.\n");
        return -1;
    }

    // Perform further processing and validation as needed

    return 0; // Successful processing
}

// Function to free the memory allocated for an oauth_response_t struct
void free_oauth_response(oauth_response_t* response) {
    if (response->refresh_token)
        free(response->refresh_token);
    free(response);
}
