        private readonly HttpClient _httpClient;
        private readonly string _apiKey;
        private readonly int _keySize;
        private readonly byte[] _initializationVector;
        private readonly string _cachedData;

        public EncryptionDecryptionService(ILogger<EncryptionDecryptionService> logger, 
                                            HttpClient httpClient, 
                                            string apiKey, 
                                            int keySize, 
                                            byte[] initializationVector)
        {
            _logger = logger;
            _httpClient = httpClient;
            _apiKey = apiKey;
            _keySize = keySize;
            _initializationVector = initializationVector;
            _cachedData = null;
        }

        public async Task<int?> DecryptAndFindLargestValueAsync()
        {
            if (_cachedData == null)
            {
                try
                {
                    var response = await _httpClient.GetAsync($"https://api.example.com/encrypted-data?apiKey {_apiKey}");
                    response.EnsureSuccessStatusCode();

                    var encryptedData = await response.Content.ReadAsStringAsync();
                    _cachedData = Base64UrlEncoder.Decode(encryptedData);
                }
                catch (HttpRequestException ex)
                {
                    _logger.LogError(ex, "Failed to retrieve encrypted data");
                    return null;
                }
            }

            using var desEngine = new TripleDesEngine(new KeyParameter(Encoding.UTF8.GetBytes(_apiKey)), new IvParameter(new byte[] { 0x01, 0x02, 0x03 }));
            var decryptedData = desEngine.CreateDecryptor();

            int? largestValue = null;
            await Task.Run(() =>
            {
                var integers = new List<int>();
                foreach (var block in _cachedData.Split(new char[] { ',' }))
                {
                    try
                    {
                        var encryptedInteger = Base64UrlEncoder.Decode(block);
                        var decryptedInteger = (int)desEngine.Decrypt(encryptedInteger);

                        if (!integers.Contains(decryptedInteger))
                            integers.Add(decryptedInteger);

                        largestValue = Math.Max(largestValue ?? 0, decryptedInteger);
                    }
                    catch (CryptoApiException ex)
                    {
                        _logger.LogError(ex, "Failed to decrypt integer");
                    }
                }
            });

            return largestValue;
        }

        public class Base64UrlEncoder
        {
            public static string Decode(string base64EncodedString)
            {
                var decodedBytes = Convert.FromBase64String(base64EncodedString);
                return Encoding.UTF8.GetString(decodedBytes);
            }
        }
    }
