namespace PasswordHashingLibrary
{
    public class PasswordHasher
    {
        private readonly IExternalAuthenticationService _externalService;
        private readonly ICachingStrategy _cachingStrategy;
        private readonly int _maxRetries;

        public PasswordHasher(IExternalAuthenticationService externalService, ICachingStrategy cachingStrategy, int maxRetries)
        {
            _externalService = externalService;
            _cachingStrategy = cachingStrategy;
            _maxRetries = maxRetries;
        }

        public async Task<string> HashPasswordAsync(string password)
        {
            // Generate a random salt
            byte[] salt = Guid.NewGuid().ToByteArray();

            // Create an MD5 hash
            using (var md5 = MD5.Create())
            {
                var hashedPassword = md5.ComputeHash(salt, Encoding.UTF8.GetBytes(password));
                return Convert.ToBase64String(hashedPassword);
            }
        }

        public async Task<bool> VerifyPasswordAsync(string password, string hashedPassword)
        {
            // Check if the password is cached
            if (_cachingStrategy.TryGetValue(hashedPassword, out var cachedPassword))
            {
                if (string.Equals(cachedPassword, hashedPassword, StringComparison.OrdinalIgnoreCase))
                    return true;
            }

            // Hash the given password and compare with the provided hash
            using (var md5 = MD5.Create())
            {
                var newHashedPassword = md5.ComputeHash(Guid.NewGuid().ToByteArray(), Encoding.UTF8.GetBytes(password));
                if (string.Equals(Convert.ToBase64String(newHashedPassword), hashedPassword, StringComparison.OrdinalIgnoreCase))
                    return true;
            }

            // If the password is not verified, check with the external service
            int retries = 0;
            while (retries < _maxRetries)
            {
                try
                {
                    var result = await _externalService.VerifyPasswordAsync(password, hashedPassword);
                    if (result)
                        return true;
                }
                catch (Exception ex)
                {
                    // Log the exception and retry
                    await Task.Delay(TimeSpan.FromMilliseconds(500));
                    retries++;
                }
            }

            return false;
        }
    }

    public interface IExternalAuthenticationService
    {
        Task<bool> VerifyPasswordAsync(string password, string hashedPassword);
    }

    public interface ICachingStrategy
    {
        bool TryGetValue(string key, out string value);
        void SetItem(string key, string value);
    }
}
