namespace SecureDataLibrary
{
    public class EncryptionSettings
    {
        public string Algorithm { get; set; }
        public byte[] Key { get; set; }
        public byte[] InitializationVector { get; set; }
    }

    public interface IEncryptionAlgorithm
    {
        Stream Decrypt(Stream encryptedStream);
        Stream Encrypt(Stream plainTextStream, Stream initializationVectorStream);
    }

    public class AesGcmEncryption : IEncryptionAlgorithm
    {
        private readonly ICryptoTransform _cryptoTransform;

        public AesGcmEncryption(byte[] key, byte[] initializationVector)
        {
            var aesAlg = Aes.Create();
            aesAlg.Key = key;
            aesAlg.IV = initializationVector;

            _cryptoTransform = aesAlg.CreateDecryptor();
        }

        public Stream Decrypt(Stream encryptedStream)
        {
            var decryptor = new CryptoStream(encryptedStream, _cryptoTransform, CryptoStreamMode.Read);
            return decryptor;
        }

        public Stream Encrypt(Stream plainTextStream, Stream initializationVectorStream)
        {
            using (var cryptoStream = new CryptoStream(initializationVectorStream, _cryptoTransform, CryptoStreamMode.Write))
            {
                var buffer = new byte[4096];
                int bytesRead;

                while ((bytesRead = plainTextStream.Read(buffer, 0, buffer.Length)) > 0)
                {
                    cryptoStream.Write(buffer, 0, bytesRead);
                }

                return cryptoStream;
            }
        }
    }

    public class SerializationSettings
    {
        public string Format { get; set; }
        public Type DataContractType { get; set; }
        public JsonSchema jsonSchema { get; set; }
    }

    public interface ISerializationAlgorithm
    {
        T Deserialize<T>(Stream stream);
        Stream Serialize<T>(T obj);
    }

    public class BinarySerialization : ISerializationAlgorithm
    {
        public T Deserialize<T>(Stream stream)
        {
            var formatter = new BinaryFormatter();
            return (T)formatter.Deserialize(stream);
        }

        public Stream Serialize<T>(T obj)
        {
            using (var ms = new MemoryStream())
            {
                var formatter = new BinaryFormatter();
                formatter.Serialize(ms, obj);
                return ms;
            }
        }
    }

    public class JsonSerialization : ISerializationAlgorithm
    {
        public T Deserialize<T>(Stream stream)
        {
            using (var sr = new StreamReader(stream))
            {
                return JsonConvert.DeserializeObject<T>(sr.ReadToEnd());
            }
        }

        public Stream Serialize<T>(T obj)
        {
            using (var ms = new MemoryStream())
            {
                using (var sw = new StreamWriter(ms))
                {
                    sw.Write(JsonConvert.SerializeObject(obj));
                }
                return ms;
            }
        }
    }

