const express = require('express');
const app = express();
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const axios = require('axios');

app.use(express.json());
app.use(express.urlencoded({ extended: true }));

const configAPIUrl = 'https://config-api.com';
const placeholderRegex = /\{\{([a-zA-Z0-9_]+)\}\}/g;
const encryptionKey = process.env.ENCRYPTION_KEY;

app.post('/update-config', async (req, res) => {
  try {
    const { file, parameters } = req.body;
    if (!file || !parameters) throw new Error('Invalid request');

    const placeholderReplacements = {};
    Object.keys(parameters).forEach((key) => {
      placeholderReplacements[`{{${key}}}`] = parameters[key];
    });

    const configContent = await fs.readFile(path.join(__dirname, 'kickstart.config'), 'utf8');
    const processedConfig = configContent.replace(placeholderRegex, (match, placeholder) => placeholderReplacements[placeholder]);

    const encryptedPassword = crypto.createCipher('aes-256-cbc', encryptionKey).update(req.body.password, 'utf8', 'hex');
    const updatedConfig = `${processedConfig}\npassword: ${encryptedPassword}`;

    await fs.writeFile(path.join(__dirname, 'kickstart.config'), updatedConfig);
    res.send({ message: 'Configuration file updated successfully' });
  } catch (err) {
    console.error(err);
    if (err.message === 'Invalid request') {
      res.status(400).send({ message: err.message });
    } else {
      res.status(500).send({ message: err.message });
    }
  }
});

app.get('/config', async (req, res) => {
  try {
    const configContent = await fs.readFile(path.join(__dirname, 'kickstart.config'), 'utf8');
    res.send(configContent);
  } catch (err) {
    console.error(err);
    res.status(500).send({ message: err.message });
  }
});

app.listen(3000, () => {
  console.log('Configuration service listening on port 3000...');
});
