use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::mpsc;
use std::thread;
use std::time::{Duration, Instant};

struct JobDirManager {
    config_system: mpsc::Sender<String>,
    logger: mpsc::Sender<String>,
}

impl JobDirManager {
    fn new(config_system: mpsc::Sender<String>, logger: mpsc::Sender<String>) -> Self {
        JobDirManager { config_system, logger }
    }

    fn create_job_dir(&self, job_name: &str) -> PathBuf {
        let mut dir_path = dirs::temp_dir().unwrap();
        dir_path.push(job_name);

        if !dir_path.exists() {
            fs::create_dir_all(&dir_path).expect("Failed to create directory");
        }

        dir_path
    }

    fn set_env_var(&self, job_dir: &PathBuf) {
        let env_key = "JOB_DIR";
        let env_val = job_dir.display().to_string();
        std::env::set_var(env_key, env_val);
    }

    fn cleanup_job_dir(&self, job_dir: &PathBuf, timeout: Duration) {
        thread::spawn(move || {
            thread::sleep(timeout);
            fs::remove_dir_all(job_dir).expect("Failed to remove directory");
            self.config_system.send(format!("Directory {} cleaned up", job_dir.display())).unwrap();
        });
    }

    fn update_config(&self, job_dir: &PathBuf) {
        self.config_system
            .send(format!("Job directory set to {}", job_dir.display()))
            .unwrap();
    }

    fn log_job_op(&self, op: &str) {
        let now = Instant::now();
        self.logger
            .send(format!("{} - Job operation: {}", now, op))
            .unwrap();
    }
}

fn main() {
    let (config_system_tx, config_system_rx) = mpsc::channel(10);
    let (logger_tx, logger_rx) = mpsc::channel(10);

    let job_dir_manager = JobDirManager::new(config_system_tx, logger_tx);

    // Create job directories
    for i in 1..100 {
        let job_name = format!("job-{}", i);
        let job_dir = job_dir_manager.create_job_dir(&job_name);
        job_dir_manager.set_env_var(&job_dir);
        job_dir_manager.update_config(&job_dir);

        // Cleanup after a specified timeout
        thread::sleep(Duration::from_secs(1 * 3600));
        job_dir_manager.cleanup_job_dir(&job_dir, Duration::from_secs(10));

        // Log job operations
        job_dir_manager.log_job_op("Created");
        job_dir_manager.log_job_op("Cleaned up");

        // Handle errors and edge cases
    }

    // Close channels
    config_system_rx.recv();
    logger_rx.recv();
}
