import json

class JsonParser:
    def __init__(self):
        self.registry = {}
        self.settings = {
            'logging_level': 'INFO',
            'cache_expiration_time': 300,
            'default_data_source_uri': 'https://example.com/api'
        }

    def register_factory_function(self, factory_function_id, factory_function):
        if factory_function_id not in self.registry:
            self.registry[factory_function_id] = factory_function
        else:
            raise ValueError('Factory function with ID {} already exists')

    def get_all_registered_factory_functions(self):
        return list(self.registry.keys())

    def parse_json(self, json_string):
        try:
            data = json.loads(json_string)
            if isinstance(data, dict):
                for key, value in data.items():
                    if isinstance(value, str) and value.startswith('factory_'):
                        factory_function_id = value[9:]
                        if factory_function_id in self.registry:
                            data[key] = self.registry[factory_function_id]()
                        else:
                            raise ValueError(f'No factory function registered for ID {factory_function_id}')
            return data
        except json.JSONDecodeError as e:
            raise ValueError('Invalid JSON') from e

    def serialize_json(self, data):
        if isinstance(data, dict):
            serialized_data = {}
            for key, value in data.items():
                if isinstance(value, (int, float)):
                    serialized_data[key] = value
                elif isinstance(value, str):
                    serialized_data[key] = value
                else:
                    serialized_data[key] = self.serialize_json(value)
            return json.dumps(serialized_data)

    def start(self):
        pass

class JsonSerializer(JsonParser):
    def __init__(self):
        super().__init__()

    def serialize_object(self, obj):
        try:
            data = {}
            for attribute_name in dir(obj):
                if not attribute_name.startswith('__'):
                    value = getattr(obj, attribute_name)
                    if isinstance(value, (int, float)):
                        data[attribute_name] = value
                    elif isinstance(value, str):
                        data[attribute_name] = value
                    else:
                        data[attribute_name] = self.serialize_object(value)
            return json.dumps(data)
        except Exception as e:
            raise ValueError('Serialization failed') from e

class JsonDeserializer(JsonParser):
    def __init__(self):
        super().__init__()

    def deserialize_json(self, json_string):
        try:
            data = json.loads(json_string)
            if isinstance(data, dict):
                obj = self.deserialize_object(data)
                return obj
            else:
                raise ValueError('Invalid JSON')
        except json.JSONDecodeError as e:
            raise ValueError('Invalid JSON') from e

    def deserialize_object(self, data):
        if not isinstance(data, dict):
            return None
        obj = {}
        for key, value in data.items():
            if isinstance(value, (int, float)):
                obj[key] = value
            elif isinstance(value, str):
                obj[key] = value
            else:
                obj[key] = self.deserialize_object(value)
        return obj

    def deserialize_list(self, data):
        if not isinstance(data, list):
            return []
        result = []
        for item in data:
            if isinstance(item, (int, float)):
                result.append(item)
            elif isinstance(item, str):
                result.append(item)
            else:
                result.append(self.deserialize_object(item))
        return result

# Example usage
json_parser = JsonParser()

def factory_function1():
    return {'name': 'John', 'age': 30}

def factory_function2():
    return {'city': 'New York'}

factory_function_id1 = 'factory_function_1'
factory_function_id2 = 'factory_function_2'

json_parser.register_factory_function(factory_function_id1, factory_function1)
json_parser.register_factory_function(factory_function_id2, factory_function2)

data = json_parser.parse_json('{"name": "John", "age": 30, "city": "New York", "factory_function_1": null}')
print(data)']

