class DatabaseConnection {
public:
    DatabaseConnection(int id) : id(id) {}

    void connect() {
        // Simulate database connection establishment
        std::cout << "Connected to database with ID: " << id << std::endl;
    }

    void disconnect() {
        // Simulate database disconnection
        std::cout << "Disconnected from database with ID: " << id << std::endl;
    }

private:
    int id;
};

class ConnectionPool {
public:
    ConnectionPool(int initialSize) : connections(initialSize), connectionLimit(initialSize) {}

    void addConnection(int id) {
        connections.emplace(id);
    }

    DatabaseConnection* acquireConnection() {
        if (connections.empty()) {
            // Check if the pool size needs to be increased
            increasePoolSize();
        }

        auto connection = connections.front();
        connections.pop();

        return &connection;
    }

    void releaseConnection(DatabaseConnection* connection) {
        connection->disconnect();
        connections.push(*connection);
    }

private:
    std::queue<DatabaseConnection> connections;
    int connectionLimit;

    void increasePoolSize() {
        // Implement dynamic scaling logic here
        // For example, increase the pool size by a factor of 2
        connectionLimit *= 2;
        addConnections(connectionLimit - connections.size());
    }

    void addConnections(int count) {
        for (int i = 0; i < count; ++i) {
            addConnection(i + 1);
        }
    }
};

class ConnectionManager {
public:
    ConnectionManager(int initialPoolSize, int maxPoolSize)
        : pool(initialPoolSize), maxPoolSize(maxPoolSize) {}

    DatabaseConnection* acquireConnection() {
        return pool.acquireConnection();
    }

    void releaseConnection(DatabaseConnection* connection) {
        pool.releaseConnection(connection);
    }

private:
    ConnectionPool pool;
    int maxPoolSize;
};

int main() {
    ConnectionManager manager(5, 20);

    // Simulate acquiring and releasing connections
    for (int i = 0; i < 10; ++i) {
        DatabaseConnection* connection = manager.acquireConnection();
        // Use the connection...
        manager.releaseConnection(connection);
    }

    return 0;
}
