#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include "logging_service.h"
#include "memory_pool.h"

// Define constants for maximum string size and delimiter characters
#define MAX_STRING_SIZE (1024 * 1024) // 1 GiB
#define DELIMITER_CHARS 3

// Define a struct to represent the StringManager library
typedef struct {
    memory_pool_t* memory_pool;
    logging_service_t* logging_service;
} StringManager;

// Initialize the StringManager library with given logging and memory pool settings
StringManager* string_manager_init(logging_service_t* logging_service, memory_pool_t* memory_pool) {
    StringManager* manager = malloc(sizeof(StringManager));
    if (!manager) {
        return NULL; // Error allocating memory for manager struct
    }
    manager->memory_pool = memory_pool;
    manager->logging_service = logging_service;
    return manager;
}

// Free the StringManager library and its internal resources
void string_manager_free(StringManager* manager) {
    if (manager) {
        free(manager);
        // Free any allocated memory pools or logging services
        if (manager->memory_pool) {
            memory_pool_free(manager->memory_pool);
        }
        if (manager->logging_service) {
            logging_service_free(manager->logging_service);
        }
    }
}

// Append delimiter characters to the end of a given string
void string_append_delimiters(StringManager* manager, char* str, int delimiters) {
    // Calculate the required buffer size for the updated string
    int buffer_size = strlen(str) + (delimiters * DELIMITER_CHARS);
    // Allocate memory from the memory pool for the new string
    char* buffer = memory_pool_malloc(manager->memory_pool, buffer_size);
    if (!buffer) {
        manager->logging_service->log_error("Failed to allocate memory for appended string");
        return; // Error allocating memory for the new string
    }
    // Copy the original string and append delimiter characters
    strcpy(buffer, str);
    for (int i = 0; i < delimiters; i++) {
        strcat(buffer, " - ");
    }
    // Update the original string with the appended delimiter characters
    free(str);
    str = buffer;
}

// Trim whitespace from the start and end of a given string
void string_trim_whitespace(StringManager* manager, char** str) {
    int len = strlen(*str);
    // Calculate the required buffer size for the trimmed string
    int buffer_size = len - (len > 0 ? 1 : 0) - (len < MAX_STRING_SIZE && len > 0 ? len - 1 : 0);
    // Allocate memory from the memory pool for the new string
    char* buffer = memory_pool_malloc(manager->memory_pool, buffer_size + 1);
    if (!buffer) {
        manager->logging_service->log_error("Failed to allocate memory for trimmed string");
        return; // Error allocating memory for the new string
    }
    // Copy the original string and trim whitespace
    strcpy(buffer, (*str) + (len > 0 ? 1 : 0));
    buffer[buffer_size] = '\0';
    // Update the original string with the trimmed string
    free(*str);
    *str = buffer;
}

// Convert a given string to uppercase or lowercase as specified
void string_case_conversion(StringManager* manager, char** str, int case_type) {
    // Allocate memory from the memory pool for the new string
    char* buffer = memory_pool_malloc(manager->memory_pool, strlen(*str) + 1);
    if (!buffer) {
        manager->logging_service->log_error("Failed to allocate memory for converted string");
        return; // Error allocating memory for the new string
    }
    // Copy the original string and convert to uppercase or lowercase
    strcpy(buffer, case_type == STRING_CASE_UPPER ? toupper(*str) : tolower(*str));
    buffer[strlen(buffer)] = '\0';
    // Update the original string with the converted string
    free(*str);
    *str = buffer;
}

// Define a function pointer type for callback functions
typedef void (*callback_func)(StringManager*, char*);

// Define a function to perform asynchronous logging
void async_log(StringManager* manager, char* message) {
    // Call the logging service with the given message
    manager->logging_service->log_async(message);
}

// Define a function to perform synchronous logging
void sync_log(StringManager* manager, char* message) {
    // Call the logging service with the given message
    manager->logging_service->log_sync(message);
}
