    public void SetMinValue(int minValue)
    {
        if (minValue > maxValue) throw new ArgumentException("Min value cannot be greater than max value");
        _minValue = minValue;
        _isRangeUpdated = true;
    }

    public void SetMaxValue(int maxValue)
    {
        if (maxValue < minValue) throw new ArgumentException("Max value cannot be less than min value");
        _maxValue = maxValue;
        _isRangeUpdated = true;
    }

    public void SetStepSize(int stepSize)
    {
        _stepSize = stepSize;
    }

    public int GetRandomInteger()
    {
        return _random.Next(_minValue, _maxValue + 1);
    }

    public double GetRandomFloat()
    {
        return (double)_random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GetCustomStepBasedInteger(int stepSize)
    {
        SetMinValue(0);
        SetMaxValue(stepSize - 1);
        return _random.Next(_minValue, _maxValue + 1);
    }
