CipherContext* derive_key(uint8_t* password, int iterations) {
    CipherContext* context = (CipherContext*)malloc(sizeof(CipherContext));
    uint8_t* salt = generate_salt(16);
    uint8_t* derived_key = (uint8_t*)malloc(AES_KEY_SIZE);

    PBKDF2_CTX pbkdf2_ctx;
    if (!PBKDF2_init(&pbkdf2_ctx, password, strlen((char*)password), salt, 16, iterations)) {
        // Handle error
    }
    if (!PBKDF2_keygen(&pbkdf2_ctx, derived_key, AES_KEY_SIZE)) {
        // Handle error
    }

    context->key = derived_key;
    context->iv = (uint8_t*)malloc(AES_BLOCK_SIZE);
    for (int i = 0; i < AES_BLOCK_SIZE; i++) {
        context->iv[i] = rand() % 256;
    }

    return context;
}

// Function to encrypt data using the derived key
void encrypt(uint8_t* plaintext, int length, CipherContext* context) {
    AES_CTX aes_ctx;
    if (!AES_new(&aes_ctx, context->key, context->iv)) {
        // Handle error
    }
    if (!AES_cbc_encrypt(plaintext, plaintext + length, length, &aes_ctx)) {
        // Handle error
    }
}

// Function to decrypt data using the derived key
void decrypt(uint8_t* ciphertext, int length, CipherContext* context) {
    AES_CTX aes_ctx;
    if (!AES_new(&aes_ctx, context->key, context->iv)) {
        // Handle error
    }
    if (!AES_cbc_decrypt(ciphertext, ciphertext + length, length, &aes_ctx)) {
        // Handle error
    }
}

int main() {
    CipherContext* context = derive_key("my_secret_password", 1000);
    uint8_t plaintext[] = "Hello, World!";
    int length = strlen((char*)plaintext);

    encrypt(plaintext, length, context);

    uint8_t ciphertext[length + AES_BLOCK_SIZE];
    for (int i = 0; i < length + AES_BLOCK_SIZE; i++) {
        ciphertext[i] = plaintext[i % length];
    }

    decrypt(ciphertext, length, context);

    return 0;
