        FILE* file = fopen(filePath, "r+");
        if (file == NULL) {
            // Handle error
            logError("Failed to open file");
            continue;
        }

        fseek(file, 0, SEEK_END);
        int fileSize = ftell(file);
        rewind(file);

        char newName[255];
        sprintf(newName, "%s-%d.%09ld", ent->d_name, initialVersion++, (time_t)ent->d_mtime);

        if (renameFile(filePath, newName)) {
            // Handle error
