using System;
using System.Threading;

public class Range
{
    private int minValue;
    private int maxValue;

    public Range(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Invalid range");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public void UpdateRange(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Invalid range");

        Interlocked.Exchange(ref this.minValue, minValue);
        Interlocked.Exchange(ref this.maxValue, maxValue);
    }

    public int GetRandomValue()
    {
        return new Random().Next(minValue, maxValue + 1);
    }
}

public class DynamicRandomValueProvider
{
    private readonly Range _range;
    private readonly object _lock = new object();
    private readonly bool _useParallelProcessing;

    public DynamicRandomValueProvider(Range range, bool useParallelProcessing)
    {
        _range = range;
        _useParallelProcessing = useParallelProcessing;
    }

    public int GenerateRandomValue()
    {
        if (_useParallelProcessing)
        {
            var tasks = new[] { Task.Run(() => GetRandomValue()) };
            return await Task.WhenAll(tasks).Select(t => t.Result).FirstOrDefault();
        }
        else
        {
            return GetRandomValue();
        }
    }

    private int GetRandomValue()
    {
        lock (_lock)
        {
            return _range.GetRandomValue();
        }
    }

    public void UpdateRange(Range newRange)
    {
        lock (_lock)
        {
            _range.UpdateRange(newRange.minValue, newRange.maxValue);
        }
    }
}

public class ExternalDataSource
{
