            response.EnsureSuccessStatusCode();
            var rangeJson = await response.Content.ReadAsStringAsync();
            var newRange = JsonConvert.DeserializeObject<Range>(rangeJson);
            DynamicRandomValueProvider.UpdateRange(newRange);
        }
        catch (HttpRequestException ex)
        {
            // Handle connection failure and retry logic
        }
    }
}

