#include <openssl/aes.h>
#include <openssl/sha.h>
#include <openssl/pbkdf2.h>
#include <sys/time.h>
#include <unistd.h>

#define MAX_PASSWORD_LENGTH 256
#define MAX_IV_LENGTH 16

typedef struct {
    uint8_t* password;
    uint32_t iterationCount;
    uint8_t salt[SHA256_DIGEST_LENGTH];
} CipherContext;

CipherContext* cipherInit(const char* password, const uint32_t iterationCount) {
    CipherContext* context = (CipherContext*)malloc(sizeof(CipherContext));

    context->password = malloc(strlen(password) + 1);
    strcpy((char*)context->password, password);

    context->iterationCount = iterationCount;
    SHA256((const unsigned char*)password, strlen(password), context->salt);

    return context;
}

void cipherDeriveKey(CipherContext* context) {
    uint8_t derivedKey[AES_BLOCK_SIZE];
    PBKDF2_HMAC_SHA1(context->password, strlen((char*)context->password), context->salt, SHA256_DIGEST_LENGTH, context->iterationCount, derivedKey, AES_BLOCK_SIZE);
}

uint8_t* generateIV() {
    uint8_t* iv = (uint8_t*)malloc(MAX_IV_LENGTH);
    RAND_bytes(iv, MAX_IV_LENGTH);
    return iv;
}

void encryptData(uint8_t* data, size_t dataSize, CipherContext* context) {
    cipherDeriveKey(context);
    AES_CRYPT_DATA(data, dataSize, context->derivedKey);
}

int main() {
    // Initialize the random number generator
    srand(time(NULL));

    CipherContext* context = cipherInit("your_password_here", 10000);

    uint8_t* data = (uint8_t*)malloc(1024);
    for (size_t i = 0; i < 1024; i++) {
        data[i] = i % 256;
    }

    size_t dataSize = sizeof(data) / sizeof(*data);

    uint8_t* iv = generateIV();

    encryptData(data, dataSize, context);

    free(context->password);
    free(context);

    free(iv);
    free(data);

    return 0;
}
