#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>

// Configuration structure
typedef struct {
    char* dir_path;
    int initial_version;
    int max_version_increments;
    int skip_extensions[10]; // default: no skipping
} RenameConfig;

// Logging function wrapper
void log_message(const char* message) {
    // TO DO: integrate with external logging service here
    printf("%s\n", message);
}

// File validation helper
int validate_file_name(char* name, int max_length) {
    if (strlen(name) > max_length) return 0;
    for (int i = 0; i < strlen(name); i++) {
        if (!isalnum(name[i]) && !strchr(".-_ ", name[i])) return 0;
    }
    return 1;
}

// Versioning helper
char* get_version_string(int version, int max_length) {
    char buf[64];
    sprintf(buf, "%03d", version);
    return strdup(buf);
}

// File renaming function
void rename_file(char* src_path, RenameConfig* config) {
    struct stat sb;
    if (stat(src_path, &sb) == -1) return;

    char dst_path[PATH_MAX];
    strcpy(dst_path, src_path);
    strcat(dst_path, "_");
    strcat(dst_path, get_version_string(config->initial_version++, config->max_version_increments));
    strcat(dst_path, ".tmp");

    if (rename(src_path, dst_path) == -1) log_message("Error renaming file: ");
}

// Main function for directory renaming
void renameDirectoryWithVersioning(RenameConfig* config) {
    DIR* dir = opendir(config->dir_path);
    if (!dir) return;

    struct dirent* entry;
    while ((entry = readdir(dir))) {
        char path[PATH_MAX];
        sprintf(path, "%s/%s", config->dir_path, entry->d_name);

        if (validate_file_name(entry->d_name, PATH_MAX)) {
            rename_file(path, config);
        } else log_message("Skipping non-file/directory: ");
    }

    closedir(dir);
}

// Entry point for the library
int rename_directory_with_versioning(RenameConfig* config) {
    pthread_mutex_lock(&config->mutex); // TO DO: create a mutex

    if (renameDirectoryWithVersioning(config)) {
        log_message("Error renaming directory: ");
        return -1;
    }

    pthread_mutex_unlock(&config->mutex);
    return 0;
}

// Example usage:
int main() {
    RenameConfig config = { .dir_path = "path/to/directory", .initial_version = 0, .max_version_increments = 100 };
    rename_directory_with_versioning(&config);

    // TO DO: implement configuration API and error handling
}
