// Define a doubly-linked list node structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    int8_t data[1024]; // Data buffer
} NFAPI_CRC_INDICATION_PDU_T;

// Define the doubly-linked list structure
typedef struct _doubly_linked_list_node {
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    struct _doubly_linked_list_node* prev;
    struct _doubly_linked_list_node* next;
} doubly_linked_list_node;

// Define the doubly-linked list structure for the library
typedef struct _dll {
    doubly_linked_list_node* head;
    doubly_linked_list_node* tail;
    int size; // Current list size
    pthread_mutex_t mutex; // Lock for concurrent access
} dll;

// Initialize a new doubly-linked list node
doubly_linked_list_node* create_dll_node(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    doubly_linked_list_node* node = (doubly_linked_list_node*)malloc(sizeof(doubly_linked_list_node));
    node->pdu = pdu;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

// Insert a new node at the beginning of the list
void dll_insert_at_start(dll* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    doubly_linked_list_node* node = create_dll_node(pdu);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->next = list->head;
        list->head->prev = node;
        list->head = node;
    }
    list->size++;
}

// Remove the last node from the list
void dll_remove_last(dll* list) {
    if (list->tail != NULL) {
        doubly_linked_list_node* node = list->tail;
        list->tail = node->prev;
        if (list->tail == NULL) {
            list->head = NULL;
        } else {
            list->tail->next = NULL;
        }
        free(node);
        list->size--;
    }
}

// Lock the doubly-linked list for concurrent access
void dll_lock(dll* list) {
    pthread_mutex_lock(&list->mutex);
}

// Unlock the doubly-linked list after concurrent access
void dll_unlock(dll* list) {
    pthread_mutex_unlock(&list->mutex);
}

// Initialize a new doubly-linked list
dll* create_dll() {
    dll* list = (dll*)malloc(sizeof(dll));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Delete a doubly-linked list
void free_dll(dll* list) {
    dll_lock(list);
    doubly_linked_list_node* node = list->head;
    while (node != NULL) {
        doubly_linked_list_node* next = node->next;
        free(node);
        node = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_unlock(&list->mutex);
}

// Main entry point for the library
void nfaapi_crc_indication_pdu_t_dll_main() {
    // Initialize a new doubly-linked list
    dll* list = create_dll();

    // Insert elements into the list
    for (int i = 0; i < 10 * 1000000; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Initialize pdu structure...
        dll_insert_at_start(list, &pdu);
    }

    // Remove elements from the list
    for (int i = 0; i < 10 * 1000000; i++) {
        dll_remove_last(list);
    }

    // Free the doubly-linked list
    free_dll(list);

    return;
}
