// Function to generate a random salt using HRNG
unsigned char* generateHRNGLast(char* password, int keySize) {
    unsigned char* salt = new unsigned char[keySize];
    FILE* file = fopen("/dev/urandom", "rb");
    fread(salt, 1, keySize, file);
    fclose(file);
    return salt;
}

// Function to derive encryption keys using PBKDF2
unsigned char* deriveKey(char* password, int iterationCount, unsigned char* salt) {
    unsigned char* derivedKey = new unsigned char[32];
    BIGNUM* bn = BN_new();
    const EVP_BytesToKey* key = EVP_BytesToKey(EVP_f_query_password_cb, NULL, NULL, "AES-256-CBC", password, strlen(password), 4, 1);
    PBKDF2_CTX* ctx = new PBKDF2_CTX;
    PBKDF2_init(ctx, salt, 32, iterationCount);
    unsigned char* out = new unsigned char[32];
    int len = PBKDF2(ctx, password, strlen(password), NULL, 0);
    if (len < 32) {
        return nullptr;
    }
    memcpy(derivedKey, out, len);
    delete[] out;
    return derivedKey;
}

// Function to encrypt data using AES-256-CBC
void encryptData(unsigned char* plaintext, int plainSize, unsigned char* key, unsigned char* iv) {
    AES_KEY aes_key;
    AES_set_encrypt_key(key, 32, &aes_key);
    unsigned char* ciphertext = new unsigned char[plainSize];
    int len = AES_cbc_encrypt(plaintext, ciphertext, plainSize, &aes_key, iv, AES_ENCRYPT);
    if (len < plainSize) {
        // Handle error
    }
    delete[] ciphertext;
}

// Function to decrypt data using AES-256-CBC
void decryptData(unsigned char* ciphertext, int cipherSize, unsigned char* key, unsigned char* iv) {
    AES_KEY aes_key;
    AES_set_decrypt_key(key, 32, &aes_key);
    unsigned char* plaintext = new unsigned char[cipherSize];
    int len = AES_cbc_encrypt(ciphertext, plaintext, cipherSize, &aes_key, iv, AES_DECRYPT);
    if (len < cipherSize) {
        // Handle error
    }
    delete[] plaintext;
}

