typedef struct {
    size_t max_key;
    size_t capacity;
    Record* data;
    size_t* offsets;
    pthread_mutex_t lock;
} Dataset;

void init_dataset(Dataset* dataset, size_t max_key, size_t capacity) {
    dataset->max_key = max_key;
    dataset->capacity = capacity;
    dataset->data = (Record*)malloc(capacity * sizeof(Record));
    dataset->offsets = (size_t*)calloc(max_key + 1, sizeof(size_t));
    pthread_mutex_init(&dataset->lock, NULL);
}

void free_dataset(Dataset* dataset) {
    free(dataset->data);
    free(dataset->offsets);
    pthread_mutex_destroy(&dataset->lock);
}

void add_record(Dataset* dataset, int key, int value) {
    pthread_mutex_lock(&dataset->lock);
    size_t offset = dataset->offsets[key];
    if (offset + sizeof(Record) > capacity * sizeof(Record)) {
        // Handle out-of-memory error
    }
    memcpy(dataset->data + offset, &value, sizeof(int));
    dataset->offsets[key] = offset + sizeof(Record);
    pthread_mutex_unlock(&dataset->lock);
}

void update_record(Dataset* dataset, int key, int value) {
    pthread_mutex_lock(&dataset->lock);
    size_t offset = dataset->offsets[key];
    memcpy(dataset->data + offset, &value, sizeof(int));
    pthread_mutex_unlock(&dataset->lock);
}

int get_value(Dataset* dataset, int key) {
    pthread_mutex_lock(&dataset->lock);
    size_t offset = dataset->offsets[key];
    int value;
    memcpy(&value, dataset->data + offset, sizeof(int));
    pthread_mutex_unlock(&dataset->lock);
    return value;
}

