    int max_retries;
    time_t last_rotation;
    size_t log_size_threshold;
    size_t rotation_interval;
} LoggingState;

// Initialize the logging framework's internal state
void init_logging_state(LoggingState* state) {
    pthread_mutex_init(&state->lock, NULL);
    state->default_level = LOG_INFO;
    state->backoff_duration = 1000; // 1 second
    state->max_retries = 3;
    state->last_rotation = time(NULL);
    state->log_size_threshold = 1024 * 1024 * 10; // 10MB
    state->rotation_interval = 60 * 60 * 24; // 1 day
}

// Rotate the logs based on size and time intervals
void rotate_logs(LoggingState* state) {
    pthread_mutex_lock(&state->lock);
    if (time(NULL) - state->last_rotation >= state->rotation_interval || 
        filesize(state->log_file) >= state->log_size_threshold) {
        // Implement log rotation logic here
        state->last_rotation = time(NULL);
    }
    pthread_mutex_unlock(&state->lock);
}

