}

// Asynchronous log delivery with exponential backoff and retry
void deliver_log_message(LogMessage* message) {
    int retries = 0;
    while (retries < 3) {
        send_log_message(message, message->context);
        if (!has_transient_failure()) {
            break;
        }
        retries++;
        // Implement exponential backoff logic here
    }
}

// Main logging function
void log_message(LogLevel level, char* message, void* context) {
    LogMessage log_message;
    log_message.level = level;
    log_message.message = message;
    log_message.context = context;
    pthread_mutex_lock(&logging_state.lock);
    deliver_log_message(&log_message);
    pthread_mutex_unlock(&logging_state.lock);
}

// Set the default logging level
void set_default_level(LogLevel level) {
    pthread_mutex_lock(&logging_state.lock);
    logging_state.default_level = level;
    pthread_mutex_unlock(&logging_state.lock);
}

// Get the default logging level
LogLevel get_default_level() {
    pthread_mutex_lock(&logging_state.lock);
