namespace compression {
    class ZLibCompressor {
    public:
        ZLibCompressor(int level = 6) : level_(level) {}

        void compress(const std::string& input, std::vector<unsigned char>& output) {
            z_stream stream;
            stream.zalloc = nullptr;
            stream.zfree = nullptr;
            stream.opaque = nullptr;
            stream.total_in = input.size();
            stream.next_in = (Bytef*)input.data();
            stream.avail_in = input.size();

            int ret;
            do {
                ret = deflateInit2(&stream, level_, Z_DEFLATED, 31, 8, Z_DEFAULT_CHUNK);
                if (ret != Z_OK) {
                    throw std::runtime_error("Failed to initialize zlib compression");
                }
                ret = deflate(&stream, Z_FINISH);
                if (ret != Z_STREAM_END) {
                    throw std::runtime_error("Failed to compress data");
                }

                output.resize(stream.total_out);
                stream.next_out = &output[0];
                stream.avail_out = output.size();
                ret = deflateEnd(&stream);

                if (ret != Z_OK) {
                    throw std::runtime_error("Failed to finalize zlib compression");
                }
            } while (false);
        }

    private:
        int level_;
    };

    class ZLibDecompressor {
    public:
        ZLibDecompressor() {}

        void decompress(const std::vector<unsigned char>& input, std::string& output) {
            z_stream stream;
            stream.zalloc = nullptr;
            stream.zfree = nullptr;
            stream.opaque = nullptr;
            stream.total_out = input.size();
            stream.next_out = &output[0];
            stream.avail_out = input.size();

            int ret;
            do {
                ret = inflateInit2(&stream, 15);
                if (ret != Z_OK) {
                    throw std::runtime_error("Failed to initialize zlib decompression");
                }
                ret = inflate(&stream, Z_FINISH);
                if (ret != Z_STREAM_END) {
                    throw std::runtime_error("Failed to decompress data");
                }

                stream.next_in = nullptr;
                stream.avail_in = 0;

                ret = inflateEnd(&stream);

                if (ret != Z_OK) {
                    throw std::runtime_error("Failed to finalize zlib decompression");
                }
            } while (false);
        }

    private:
    };

    class GzipCompressor : public ZLibCompressor {
    public:
        void compress(const std::string& input, std::vector<unsigned char>& output) override {
            z_stream stream;
            stream.zalloc = nullptr;
            stream.zfree = nullptr;
            stream.opaque = nullptr;
            stream.total_in = input.size();
            stream.next_in = (Bytef*)input.data();
            stream.avail_in = input.size();

            int ret;
            do {
                ret = deflateInit2(&stream, level_, Z_GZIP, 31, 8, Z_DEFAULT_CHUNK);
                if (ret != Z_OK) {
                    throw std::runtime_error("Failed to initialize zlib compression");
                }
                ret = deflate(&stream, Z_FINISH);
                if (ret != Z_STREAM_END) {
                    throw std::runtime_error("Failed to compress data");
                }

                output.resize(stream.total_out);
                stream.next_out = &output[0];
                stream.avail_out = output.size();
                ret = deflateEnd(&stream);

                if (ret != Z_OK) {
                    throw std::runtime_error("Failed to finalize zlib compression");
                }
            } while (false);
        }
    };

    class ZstdCompressor : public ZLibCompressor {
    public:
        void compress(const std::string& input, std::vector<unsigned char>& output) override {
            z_stream stream;
            stream.zalloc = nullptr;
            stream.zfree = nullptr;
            stream.opaque = nullptr;
            stream.total_in = input.size();
            stream.next_in = (Bytef*)input.data();
            stream.avail_in = input.size();

            int ret;
            do {
                ret = deflateInit2(&stream, level_, Z_ZSTD, 31, 8, Z_DEFAULT_CHUNK);
                if (ret != Z_OK) {
                    throw std::runtime_error("Failed to initialize zlib compression");
                }
                ret = deflate(&stream, Z_FINISH);
                if (ret != Z_STREAM_END) {
                    throw std::runtime_error("Failed to compress data");
                }

                output.resize(stream.total_out);
                stream.next_out = &output[0];
                stream.avail_out = output.size();
                ret = deflateEnd(&stream);

                if (ret != Z_OK) {
                    throw std::runtime_error("Failed to finalize zlib compression");
                }
            } while (false);
        }
    };

    class CompressionManagementSystem {
    public:
        void manageCompressionDictionaries() {
            // implement CMS API
        }

        void optimizeCompressionRatios() {
            // implement CMS API
        }
    };
}

