// Semaphore configurations
#define SEMA_MUTEX 0 // Mutex semaphore value
#define SEMA_CONDITION 1 // Condition variable semaphore value

// Function to initialize semaphores
int init_semaphores() {
    // Initialize mutex semaphore with value 1 (unlocked)
    if ((sem = sem_open(SEMA_MUTEX, O_CREAT | O_EXCL, S_IRUSR | S_IWUSR, 1)) == SEM_FAILED) {
        perror("Semaphore creation failed");
        return -1;
    }

    // Initialize condition variable semaphore with value 0 (blocked)
    if ((cond = sem_open(SEMA_CONDITION, O_CREAT | O_EXCL, S_IRUSR | S_IWUSR, 0)) == SEM_FAILED) {
        perror("Condition variable creation failed");
        return -1;
    }

    return 0;
}

// Function to release semaphore
void release_semaphores() {
    // Release mutex semaphore
    sem_post(sem);

    // Release condition variable semaphore
    sem_post(cond);
}

// Function to acquire semaphore
void acquire_semaphores() {
    // Acquire mutex semaphore
    while (sem_wait(sem) == -1) {
        perror("Mutex acquisition failed");
    }

    // Acquire condition variable semaphore
    while (sem_wait(cond) == -1) {
        perror("Condition variable acquisition failed");
    }
}

int main() {
    int result = init_semaphores();
    if (result != 0) {
        return 1;
    }

    // Perform operations that require semaphore synchronization

    release_semaphores();

    sem_close(sem);
    sem_unlink(SEMA_MUTEX);

    return 0;
}
