#include <forward_list>
#include <vector>
#include <string>
#include <mutex>
#include <condition_variable>
#include <shared_mutex>
#include <functional>

class LoggerInterface {
public:
    virtual void log(const std::string& message) = 0;
};

void batchInsertOrLogError(std::forward_list<std::string>& list, const std::vector<const char*>& targets, std::shared_ptr<LoggerInterface> logger) {
    if (!logger) {
        // Handle null pointer error
        logger->log("Error: Logger interface is null.");
        return;
    }

    if (!targets.size()) {
        // Handle empty vector error
        logger->log("Error: Target vector is empty.");
        return;
    }

    std::mutex mtx;
    std::condition_variable cv;

    std::function<void(std::string)> logCallback = [&](const std::string& message) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait_for(lock, std::chrono::milliseconds(100));
        logger->log(message);
    };

    std::thread logThread([logCallback]() {
        while (true) {
            logCallback("Log submitted");
        }
    });

    for (const auto& target : targets) {
        bool found = false;
        std::string targetStr(target);

        // Process the input vector in batches
        for (auto it = list.begin(); it != list.end(); ++it) {
            if (*it == targetStr) {
                found = true;
                break;
            }
        }

        if (!found) {
            // If the target string is not found, append to the end of the list
            list.insert_after(list.cend(), target);
        } else {
            // Insert each string into the forward list after the first occurrence of its associated target string
            for (auto it = list.begin(); it != list.end(); ++it) {
                if (*it == targetStr) {
                    list.insert_after(it, target);
                    break;
                }
            }
        }

        logCallback("Batch insertion completed");
    }

    // Log submission is asynchronous to minimize latency during high-concurrency scenarios
    logThread.join();
}
