public:
    SandeshClient(io_service& ios, const std::string& server_endpoint,
                  const std::string& username, const std::string& password)
        : service_(ios), endpoint_(server_endpoint), username_(username),
          password_(password) {}

    void send_request(const std::string& request_type,
                      const std::string& payload) {
        // Create a websocket connection
        websocket::stream<tcp_socket> ws(service_, endpoint_);

        // Set the username and password headers
        ws.set_option(websocket::stream_base::set_username(username_));
        ws.set_option(websocket::stream_base::set_password(password_));

        // Send the request
        if (request_type == "GET") {
            ws.async_get(payload, boost::bind(&SandeshClient::on_response, this,
                                               _1));
        } else if (request_type == "POST") {
            ws.async_post(payload, boost::bind(&SandeshClient::on_response, this,
                                               _1));
