package com.example.ecommerce.loggingsystem;

import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.common.serialization.StringDeserializer;
import org.apache.kafka.common.serialization.StringSerializer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.Properties;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.function.Function;

public class DistributedLoggingSystem {
    private static final Logger logger = LoggerFactory.getLogger(DistributedLoggingSystem.class);

    public static void main(String[] args) {
        // Set up Kafka consumer and producer
        Properties consumerProps = new Properties();
        consumerProps.put("bootstrap.servers", "kafka-broker-1:9092,kafka-broker-2:9092");
        consumerProps.put("group.id", "ecommerce-log-group");
        consumerProps.put("key.deserializer", StringDeserializer.class.getName());
        KafkaConsumer<String, String> kafkaConsumer = new KafkaConsumer<>(consumerProps);

        Properties producerProps = new Properties();
        producerProps.put("bootstrap.servers", "kafka-broker-1:9092,kafka-broker-2:9092");
        producerProps.put("key.serializer", StringSerializer.class.getName());
        producerProps.put("value.serializer", StringSerializer.class.getName());
        KafkaProducer<String, String> kafkaProducer = new KafkaProducer<>(producerProps);

        // Set up log processing pipeline
        ExecutorService executorService = Executors.newFixedThreadPool(10);
        Function<String, String> logProcessor = s -> {
            // Process log here (e.g., filtering, aggregation)
            return s;
        };

        // Start consuming logs from Kafka topics
        kafkaConsumer.subscribe(Arrays.asList("transaction-processing", "user-authentication", "inventory-management", "payment-processing"));
        consumerLoop(kafkaConsumer, executorService, logProcessor);

        // Start producing processed logs to a target topic
        producerLoop(kafkaProducer);
    }

    private static void consumerLoop(KafkaConsumer<String, String> kafkaConsumer, ExecutorService executorService, Function<String, String> logProcessor) {
        try {
            while (true) {
                ConsumerRecords<String, String> records = kafkaConsumer.poll(100);
                for (ConsumerRecord<String, String> record : records) {
                    logger.info("Received log: {}", record.value());
                    String processedLog = logProcessor.apply(record.value());
                    executorService.submit(() -> kafkaProducer.send(new ProducerRecord<>("processed-logs", record.key(), processedLog)));
                }
                kafkaConsumer.commitSync();
            }
        } catch (Exception e) {
            logger.error("Error consuming logs:", e);
        }
    }

    private static void producerLoop(KafkaProducer<String, String> kafkaProducer) {
        try {
            while (true) {
                // Produce processed logs to target topic
                kafkaProducer.send(new ProducerRecord<>("processed-logs", "key", "log-message"));
                Thread.sleep(100); // throttling to avoid overwhelming the system
            }
        } catch (Exception e) {
            logger.error("Error producing logs:", e);
        }
    }
}
