    private final List<UserProfile> userProfiles;

    public UserProfileController() {
        userProfiles = new ArrayList<>();
    }

    // Handle GET requests to retrieve all user profiles
    @GetMapping()
    public ResponseEntity<List<UserProfile>> getAllUserProfiles() {
        return ResponseEntity.ok(userProfiles);
    }

    // Handle GET requests to retrieve a specific user profile by ID
    @GetMapping("/{id}")
    public ResponseEntity<UserProfile> getUserProfile(@PathVariable String id) {
        UserProfile userProfile = userProfiles.stream().filter(u -> u.getId().equals(id)).findFirst().orElse(null);
        return ResponseEntity.status(userProfile != null ? HttpStatus.OK : HttpStatus.NOT_FOUND).body(userProfile);
    }

    // Handle POST requests to create a new user profile
    @PostMapping()
    public ResponseEntity<UserProfile> createUserProfile(@RequestBody UserProfile userProfile) {
        userProfile.setId(UUID.randomUUID().toString());
        userProfiles.add(userProfile);
        return ResponseEntity.status(HttpStatus.CREATED).body(userProfile);
    }

    // Handle PUT requests to update an existing user profile
    @PutMapping("/{id}")
    public ResponseEntity<UserProfile> updateUserProfile(@PathVariable String id, @RequestBody UserProfile updatedUserProfile) {
        UserProfile userProfile = userProfiles.stream().filter(u -> u.getId().equals(id)).findFirst().orElse(null);
        if (userProfile != null) {
            // Update the existing user profile
            return ResponseEntity.ok(userProfile);
        }
        return ResponseEntity.status(HttpStatus.NOT_FOUND).build();
    }

    // Handle DELETE requests to delete a specific user profile by ID
    @DeleteMapping("/{id}")
    public ResponseEntity<String> deleteUserProfile(@PathVariable String id) {
        userProfiles.removeIf(u -> u.getId().equals(id));
        return ResponseEntity.status(HttpStatus.NO_CONTENT).body("User profile deleted successfully");
    }
