using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Caching.Distributed;
using Newtonsoft.Json;
using RestSharp;

public class DataEnricher : IHostedService, IDisposable
{
    private readonly ILogger _logger;
    private readonly IConfiguration _configuration;
    private readonly IDistributedCache _cache;
    private readonly RestClient _restClient;

    public DataEnricher(ILogger<DataEnricher> logger, 
                        IConfiguration configuration, 
                        IDistributedCache cache, 
                        RestClient restClient)
    {
        _logger = logger;
        _configuration = configuration;
        _cache = cache;
        _restClient = restClient;
    }

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            // Process XML files
            foreach (string file in Directory.GetFiles("path/to/files"))
            {
                string xmlContent = File.ReadAllText(file);
                processAndEnrichXML(xmlContent);
            }
        }
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;

    public void Dispose() => _logger.Dispose();

    private void processAndEnrichXML(string xmlContent)
    {
        // Parse XML
        XmlDocument xmlDoc = new XmlDocument();
        xmlDoc.LoadXml(xmlContent);

        // Enrich data with REST API metadata
        string enrichedData = _restClient.Execute(restRequest).Result;

        // Store enriched metadata in distributed cache
        _cache.Set("enriched_data", enrichedData);

        // Log success and metrics
        _logger.LogInformation($"Enriched {xmlContent} successfully");
    }
}

public class processAndEnrichXML : IFileProcessor
{
    private readonly ILogger _logger;
    private readonly IDistributedCache _cache;
    private readonly RestClient _restClient;

    public processAndEnrichXML(ILogger<processAndEnrichXML> logger, 
                                IDistributedCache cache, 
                                RestClient restClient)
    {
        _logger = logger;
        _cache = cache;
        _restClient = restClient;
    }

    public async Task ProcessAsync(string fileContent)
    {
        try
        {
            // Load and validate XML data
            XmlDocument xmlDoc = new XmlDocument();
            xmlDoc.LoadXml(fileContent);

            // Enrich data with external metadata using REST API
            string enrichedData = _restClient.Execute(restRequest).Result;

            // Store results in distributed cache
            _cache.Set("enriched_data", enrichedData);

            // Log success and metrics
            _logger.LogInformation($"Enriched {fileContent} successfully");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing file");
            await RetryAsync(ex);
        }
    }

    private async Task RetryAsync(Exception ex)
    {
        for (int i = 0; i < 3; i++)
        {
            try
            {
                // Retry REST API call
                string enrichedData = _restClient.Execute(restRequest).Result;
                break;
            }
            catch (Exception retryEx)
            {
                await Task.Delay(1000);
                if (i == 2) throw;
            }
        }
    }
}
