public static string GetMd5Hash(string input)
{
    MD5 md5 = MD5.Create();
    byte[] hashBytes = md5.ComputeHash(Encoding.ASCII.GetBytes(input));
    StringBuilder sb = new StringBuilder();
    foreach (byte b in hashBytes)
    {
        sb.Append(b.ToString("x2"));
    }
    return sb.ToString();
