function loadResourceBundle(config) {
  const primarySource = config.primarySource;
  const secondarySource = config.secondarySource;
  const maxRetries = config.maxRetries || 3;
  const retryInterval = config.retryInterval || 500;

  async function loadFromPrimary() {
    try {
      if (primarySource.startsWith('http')) {
        return await fetchResource(primarySource, retryInterval);
      } else {
        return await fs.promises.readFile(primarySource, 'utf8');
      }
    } catch (error) {
      if (maxRetries > 0) {
        await new Promise(resolve => setTimeout(() => resolve(), retryInterval));
        return loadFromPrimary();
      } else {
        throw error;
      }
    }
  }

  async function loadFromSecondary() {
    try {
      if (secondarySource.startsWith('http')) {
        return await fetchResource(secondarySource, retryInterval);
      } else {
        return await fs.promises.readFile(secondarySource, 'utf8');
      }
    } catch (error) {
      throw error;
    }
  }

  async function fetchResource(url, retryInterval) {
    const response = await fetch(url);

    if (!response.ok) {
      if (maxRetries > 0) {
        await new Promise(resolve => setTimeout(() => resolve(), retryInterval));
        return await fetchResource(url, retryInterval);
      } else {
        throw new Error(`Failed to load resource: ${url}`);
      }
    }

    const data = await response.text();
    return { items: JSON.parse(data), count: data.length };
  }

  async function loadBundle() {
    try {
      const primaryResult = await loadFromPrimary();
      if (primaryResult) {
        return primaryResult;
      } else {
        return await loadFromSecondary();
      }
    } catch (error) {
      throw error;
    }
  }

  return loadBundle().then(result => ({ items: result.items, count: result.count }));
}
