// async-processor.js
import { CSSSelector } from './selector';
import { NetworkClient } from './network-client';
import { Cacher } from './cacher';

class AsyncProcessor {
  constructor(options = {}) {
    this.options = options;
    this.cacher = new Cacher(options.cacheSize);
    this.networkClient = new NetworkClient(options.apiKeys, options.rateLimit);
  }

  async processDocument(document, selectors) {
    const filteredElements = [];
    for (const selector of selectors) {
      const cssSelector = new CSSSelector(selector);
      const elements = await this.filterElements(document, cssSelector);
      filteredElements.push(...elements);
    }
    return filteredElements;
  }

  async filterElements(document, cssSelector) {
    const elements = document.querySelectorAll(cssSelector.pattern);
    for (const element of elements) {
      if (!element.hasAttribute('data-loaded')) {
        await this.loadMetadata(element);
      }
    }
    return elements;
  }

  async loadMetadata(element) {
    try {
      const metadata = await this.networkClient.getMetadata(element.getAttribute('data-api-key'));
      element.setAttribute('data-metadata', JSON.stringify(metadata));
    } catch (error) {
      console.error(`Error loading metadata for ${element.tagName}:`, error);
    }
  }
}

export { AsyncProcessor };
