// cacher.js
class Cacher {
  constructor(cacheSize) {
    this.cache = new Map();
    this.cacheSize = cacheSize;
  }

  get(key) {
    return this.cache.get(key);
  }

  set(key, value) {
    if (this.cache.size >= this.cacheSize) {
      const oldestKey = Array.from(this.cache.keys())[0];
      this.cache.delete(oldestKey);
    }
    this.cache.set(key, value);
  }
}

export { Cacher };
