import java.util.*;
import java.io.*;

public class UnionFind {
    private int[] parent;
    private int[] rank;

    public UnionFind(int n) {
        parent = new int[n];
        rank = new int[n];

        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY) {
            return;
        }

        if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }

    public static class DistributedUnionFind extends UnionFind {
        private Map<String, UnionFind> nodes;

        public DistributedUnionFind(int n) {
            super(n);
            nodes = new HashMap<>();
        }

        public void addNode(String node) {
            nodes.put(node, this);
        }

        public void union(String x, String y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX == rootY) {
                return;
            }

            if (rank[rootX] > rank[rootY]) {
                for (String node : nodes.keySet()) {
                    nodes.get(node).union(rootX, y);
                }
            } else if (rank[rootX] < rank[rootY]) {
                for (String node : nodes.keySet()) {
                    nodes.get(node).union(x, rootY);
                }
            } else {
                for (String node : nodes.keySet()) {
                    nodes.get(node).union(rootX, rootY);
                }
                rank[rootX]++;
            }
        }

        public static class CachingMechanism {
            private Map<String, Integer> cache;

            public CachingMechanism() {
                cache = new HashMap<>();
            }

            public void update(String key, int value) {
                cache.put(key, value);
            }

            public int get(String key) {
                return cache.getOrDefault(key, -1);
            }
        }

        public static class ConsensusAlgorithm {
            private Map<String, String> consensus;

            public ConsensusAlgorithm() {
                consensus = new HashMap<>();
            }

            public void addNode(String node) {
                consensus.put(node, "init");
            }

            public boolean isConsistent() {
                for (String node : consensus.keySet()) {
                    if (!consensus.get(node).equals("sync")) {
                        return false;
                    }
                }
                return true;
            }

            public void update(String node, String value) {
                if (consensus.put(node, value) != null) {
                    throw new ConsensusFailedException();
                }
            }
        }
    }
