const express = require('express');
const app = express();
const inMemoryCache = require('./in-memory-cache');
const MongoDB = require('mongodb').MongoClient;
const AWS = require('aws-sdk');

app.use(express.json());

app.post('/update-preferences', async (req, res) => {
  const { userId, preferences } = req.body;

  try {
    // Fetch user preferences from in-memory cache
    const cachedPreferences = await inMemoryCache.get(userId);

    // Update the distributed NoSQL database using MongoDB
    const mongoUrl = 'mongodb://localhost:27017';
    const dbName = 'user-preferences';

    await MongoDB.connect(mongoUrl, (err, client) => {
      if (err) throw err;
      const db = client.db(dbName);

      // Perform atomic update to prevent race conditions
      db.collection('preferences').updateOne({ userId: userId }, { $set: preferences });

      client.close();
    });

    // Send acknowledgement to the user and SQS queue
    res.json({ success: true, message: 'Preferences updated successfully' });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to update preferences', message: err.message });
  }
});

app.listen(3000, () => {
  console.log('Node.js service listening on port 3000');
});
