import com.google.cloud.pubsub.v1.Subscription;
import redis.clients.jedis.Jedis;
import redis.clients.jedis.JedisPool;

public class UserPreferencesSync {
  public static void main(String[] args) {
    // Establish Redis connection for distributed lock
    Jedis jedis = new Jedis("localhost", 6379);

    Subscriber subscriber = Subscriber.create(
        "projects/<project-id>/subscriptions/my-subscription");

    subscriber.addListener(new Subscriber.Listener() {
      @Override
      public void receivedMessage(Message message) {
        try {
          // Acquire distributed lock using Redis
          jedis.set("lock", "acquired");
          if (!jedis.get("lock").equals("acquired")) {
            throw new Exception("Failed to acquire lock");
          }

          // Update user preferences in the distributed NoSQL database
          MongoDB.updateOne({ userId: message.getData().toString() }, { $set: message.getData().toString() });

          // Release the distributed lock after updating preferences
          jedis.set("lock", null);

          AckReply reply = subscriber.ack(message);
        } catch (Exception e) {
          System.out.println("Error processing message: " + e.getMessage());
          // Handle transient network issues and retry if necessary
        }
      }
    });

    subscriber.start();
  }
}
