namespace EmployeeDetailRetriever
{
    [ApiController]
    [Route("api/[controller]")]
    public class EmployeeController : ControllerBase
    {
        private readonly IHRAPIClient _hrAPI;
        private readonly IMemoryCache _cache;
        private readonly ILogger _logger;

        public EmployeeController(IHRAPIClient hrAPI, IMemoryCache cache, ILogger logger)
        {
            _hrAPI = hrAPI;
            _cache = cache;
            _logger = logger;
        }

        [HttpGet]
        public async Task<IActionResult> GetEmployeeDetails([FromQuery] int managerId)
        {
            // Retrieve employee details from cache or HR API
            var employeeDetails = await _cache.GetOrCreateAsync(managerId.ToString(), async () =>
            {
                try
                {
                    return await _hrAPI.GetEmployeeDetails(managerId);
                }
                catch (HttpRequestException ex)
                {
                    _logger.LogError(ex, "Failed to retrieve employee details");
                    return null;
                }
            });

            if (employeeDetails == null)
            {
                return NotFound();
            }

            // Cache the results
            await _cache.SetAsync(managerId.ToString(), employeeDetails, TimeSpan.FromDays(1));

            return Ok(employeeDetails);
        }
    }
}
