        private readonly MemoryCacheService _cache;

        public RandomValueGenerator(MemoryCacheService cache)
        {
            _cache = cache;
            _random = new Random();
        }

        public async Task<int> GenerateIntegerAsync(int minValue, int maxValue, int step)
        {
            var key = $"random:{minValue}-{maxValue}-{step}";
            if (_cache.TryGetValue(key, out int value))
            {
                return value;
            }

            try
            {
                value = _random.Next(minValue, maxValue + 1) / step * step;
                await _cache.SetAsync(key, value, TimeSpan.FromMinutes(5));
                return value;
            }
            catch (Exception ex)
            {
                // Handle errors and retries
                // ...
                return -1;
            }
        }
    }
}
