```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <chrono>

class HTTP_REQUEST_LOG_T {
public:
    int id;
    std::string requestMethod;
    std::string requestURI;
    int httpVersion;

    // Add other necessary log entry fields here
};

class LogManager {
private:
    std::vector<HTTP_REQUEST_LOG_T> logs;
    mutable std::mutex mtx;
    mutable std::condition_variable cv;
    bool shutdown = false;

public:
    void addLogEntry(HTTP_REQUEST_LOG_T& log) {
        std::unique_lock<std::mutex> lock(mtx);
        while (!shutdown && !logs.size() % 10000) {
            cv.wait(lock);
        }
        logs.push_back(log);
    }

    void removeOldLogs(size_t maxEntries) {
        std::unique_lock<std::mutex> lock(mtx);
        while (!shutdown && logs.size() > maxEntries) {
            logs.erase(logs.begin());
            cv.notify_all();
        }
    }

    void batchExportLogs(const std::function<void(std::vector<HTTP_REQUEST_LOG_T>&)>& callback, size_t batchSize) {
        std::unique_lock<std::mutex> lock(mtx);
        while (!shutdown && logs.size() < batchSize) {
            cv.wait(lock);
        }
        std::vector<HTTP_REQUEST_LOG_T> batch(logs.begin(), logs.end());
        callback(batch);
        logs.clear();
    }

    void shutdown() {
        std::unique_lock<std::mutex> lock(mtx);
        shutdown = true;
        cv.notify_all();
    }

    size_t getLogCount() const {
        return logs.size();
    }
};

