    public TransactionStatus processFinancialTransactions(List<Transaction> transactions) {
        List<Runnable> tasks = new ArrayList<>();

        for (Transaction transaction : transactions) {
            Runnable task = () -> {
                try {
                    processTransaction(transaction);
                } catch (Exception e) {
                    logError(e, "processTransaction");
                }
            };
            tasks.add(task);
        }

        executorService.invokeAll(tasks);

        return handleResults();
    }

    private void processTransaction(Transaction transaction) throws Exception {
        // Retrieve and process payment data from multiple APIs
        for (PaymentAPI api : getPaymentApis()) {
