<?php
require 'vendor/autoload.php';

use GuzzleHttp\Client;
use Redis;

class OAuthService {
    private $redis;
    private $guzzleClient;
    private $providerConfig = [];

    public function __construct() {
        $this->redis = new Redis();
        $this->guzzleClient = new Client(['timeout' => 5.0]);
        // Load provider configurations from a database or file
        $this->loadProviderConfig();
    }

    public function authenticate($provider, $code) {
        if (!isset($this->providerConfig[$provider])) {
            throw new Exception("Unknown provider: $provider");
        }
        $providerConfig = $this->providerConfig[$provider];

        // Fetch access token using authorization code
        $accessToken = $this->fetchAccessToken($provider, $code);
        if (!$accessToken) {
            return null;
        }

        // Get user profile data from provider API
        $userProfile = $this->fetchUserProfile($provider, $accessToken);

        // Cache the user profile data for future requests
        $this->redis->hMSet('users:'.$userProfile['id'], $userProfile);
        $this->redis->expire('users:'.$userProfile['id'], 3600); // 1 hour cache duration

        return $userProfile;
    }

    private function fetchAccessToken($provider, $code) {
        // Handle refresh token logic
        if ($token = $this->getRefreshTokenFromRedis($provider)) {
            $accessToken = $this->refreshAccessToken($provider, $token);
            $this->setRefreshTokenInRedis($provider, $accessToken);
            return $accessToken;
        }

        // Fetch access token using authorization code
        try {
            $response = $this->guzzleClient->post($providerConfig['tokenEndpoint'], [
                'form_params' => [
                    'grant_type' => 'authorization_code',
                    'code' => $code,
                    'redirect_uri' => $providerConfig['redirectUri'],
                ],
            ]);
            $accessToken = json_decode($response->getBody()->getContents(), true)['access_token'];
            // Cache the access token for future requests
            $this->setAccessTokenInRedis($provider, $accessToken);
            return $accessToken;
        } catch (GuzzleHttp\Exception\RequestException $e) {
            throw new Exception("Failed to fetch access token: {$e->getMessage()}");
        }
    }

    private function fetchUserProfile($provider, $accessToken) {
        // Fetch user profile data from provider API
        try {
            $response = $this->guzzleClient->get($providerConfig['userProfileEndpoint'], [
                'headers' => [
                    'Authorization' => 'Bearer ' . $accessToken,
                ],
            ]);
            return json_decode($response->getBody()->getContents(), true);
        } catch (GuzzleHttp\Exception\RequestException $e) {
            throw new Exception("Failed to fetch user profile: {$e->getMessage()}");
        }
    }

    private function getRefreshTokenFromRedis($provider) {
        return $this->redis->hGet('tokens:'.$provider, 'refresh_token');
    }

    private function refreshAccessToken($provider, $token) {
        // Handle token refresh logic
    }

    private function setRefreshTokenInRedis($provider, $accessToken) {
        $this->redis->hMSet('tokens:'.$provider, ['refresh_token' => $accessToken]);
        $this->redis->expire('tokens:'.$provider, 3600); // 1 hour cache duration
    }

    private function setAccessTokenInRedis($provider, $accessToken) {
        $this->redis->setex('access_tokens:'.$provider, 3600, $accessToken);
    }
}
