      console.error(`Invalid user activity data for user ${userId}`);
      return { status: 'failure' };
    }

    // Retrieve the top-n most relevant products from the external product catalog
    const response = await fetch('https://api.productcatalog.com/products', {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json'
      }
    });
    if (!response.ok) {
      console.error(`Error fetching products: ${response.status}`);
      return { status: 'failure' };
    }

    const products = await response.json();
    // Prioritize products based on historical purchase data and user behavior
    const recommendedProducts = prioritizeProducts(products, viewedProducts);

    // Update the user's viewing history in the database using the DAO class
    await dao.updateUserViewingHistory(userId, viewedProducts);

    return { status: 'success', products: recommendedProducts };
  } catch (error) {
    console.error(`Error processing product suggestion for user ${userId}: ${error}`);
    return { status: 'failure' };
  }
}

