    public Response processUserActivity(String activityData) {
        try {
            Activity activity = mapper.readValue(activityData, Activity.class);
            // Filtering logic here
            if (!activity.getUser().getLastKnownStatus().equals("active")) {
                return new Response(activity.getUserId(), null, 0);
