['Here is the C++ class `NetworkDataCache`:

```cpp
#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <queue>

class NetworkDataCache {
public:
    // Constructor
    NetworkDataCache() : cache_(), lock_(std::make_shared<std::mutex>()),
                         cond_(std::make_shared<std::condition_variable>()) {}

    // Destructor
    ~NetworkDataCache() {
        clear();
    }

    // Add data to the cache with given key and value
    void put(const std::string& key, const std::any& value) {
        lock_->lock();
        auto it = cache_.find(key);
        if (it == cache_.end()) {
            cache_[key] = value;
        } else {
            it->second = value;
        }
        lock_->unlock();
    }

    // Get the data from the cache with given key
    std::any get(const std::string& key) {
        lock_->lock();
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            std::any result = it->second;
            lock_->unlock();
            return result;
        } else {
            // Handle cache miss
            lock_->unlock();
            return std::any();
        }
    }

    // Remove data from the cache with given key
    void remove(const std::string& key) {
        lock_->lock();
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            cache_.erase(it);
        }
        lock_->unlock();
    }

    // Clear all data in the cache
    void clear() {
        lock_->lock();
        cache_.clear();
        lock_->unlock();
    }

private:
    std::map<std::string, std::any> cache_;
    std::shared_ptr<std::mutex> lock_;
    std::shared_ptr<std::condition_variable> cond_;
};
