#include <json/json.h>

// Define constants
const size_t MAX_LINE_LENGTH = 1024;
const int MIN_WEIGHT = 1;
const int MAX_WEIGHT = 100;

class LogEntry {
public:
    std::string timestamp;
    char logLevel;
    int version;
    double weight1, weight2, weight3;
};

void processLine(const std::string& line) {
    // Tokenize the line
    size_t pos = 0;
    std::vector<std::string> tokens;
    while ((pos = line.find(',')) != std::string::npos) {
        tokens.push_back(line.substr(0, pos));
        line.erase(0, pos + 1);
    }
    tokens.push_back(line);

    if (tokens.size() < 4 || tokens.size() > 6) {
        throw std::runtime_error("Invalid log entry");
    }

    LogEntry entry;
    entry.timestamp = tokens[0];
    entry.logLevel = tokens[1][0];
    entry.version = std::stoi(tokens[2]);
    if (tokens.size() == 4) {
        // Only three weights
        entry.weight1 = std::stod(tokens[3].substr(1));
    } else if (tokens.size() == 6) {
        // Three weights with context
        entry.weight1 = std::stod(tokens[3].substr(1));
        entry.weight2 = std::stod(tokens[4].substr(1));
        entry.weight3 = std::stod(tokens[5].substr(1));
    }
}

void computeAverage(double& average, const LogEntry& entry) {
    average = (entry.weight1 + entry.weight2 + entry.weight3) / 3.0;
}

Json::Value processLog(const std::string& filename) {
    Json::Value root;

    std::ifstream file(filename);
    if (!file) {
        throw std::runtime_error("Failed to open log file");
    }

    size_t lineNum = 1;
    double totalAverage = 0.0;

    // Process each line asynchronously
    std::vector<std::thread> threads;
    for (std::string line; std::getline(file, line);) {
        LogEntry entry;
        processLine(line);
        Json::Value metadata;
        metadata["timestamp"] = entry.timestamp;
        metadata["logLevel"] = static_cast<int>(entry.logLevel);
        metadata["version"] = entry.version;

        double average;
        computeAverage(average, entry);

        metadata["average"] = average;

        root.append(metadata);
    }

    file.close();
    return root;
}

int main() {
    try {
        Json::Value result = processLog("log.txt");
        std::cout << result.ToString() << std::endl;
        return 0;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }
}

