from kubernetes import client as k8s
from kubernetes.client import V1beta1InvalidObjectReference

eks = boto3.client('eks')
ec2 = boto3.client('ec2')

def lambda_handler(event, context):
    try:
        # Validate and sanitize the configuration data
        config_data = json.loads(event['body'])
        for key in config_data:
            if not isinstance(config_data[key], dict):
                raise ValueError('Invalid JSON format')

        # Store sensitive configuration data securely using Secrets Manager
        secrets_manager = boto3.client('secretsmanager')
        secret_name = f'container-config-{os.urandom(16).hex()}'
        response = secrets_manager.put_secret_value(
            SecretId=secret_name,
            SecretString=json.dumps(config_data)
        )

        # Deploy and manage Docker containers within the Kubernetes cluster
        k8s_config = k8s.V1beta1KubernetesApi()
        namespace = 'default'
        deployment_name = f'container-deployment-{os.urandom(16).hex()}'
        deployment_spec = {
            'apiVersion': 'apps/v1',
            'kind': 'Deployment',
            'metadata': {'name': deployment_name},
            'spec': {
                'replicas': config_data['replicas'],
                'selector': {'matchLabels': {'app': deployment_name}},
                'template': {
                    'metadata': {'name': deployment_name},
                    'spec': {
                        'containers': [
                            {
                                'name': deployment_name,
                                'image': f'{config_data["image"]}:{os.urandom(16).hex()}',
                                'ports': [{'containerPort': config_data['port']}]
                            }
                        ]
                    }
                }
            }
        }

        try:
            k8s_config.create_namespaced_deployment(
                namespace=namespace,
                body=deployment_spec
            )
        except V1beta1InvalidObjectReference as e:
            # Handle invalid object references
            print(f'Error creating deployment: {e}')
            return {
                'statusCode': 500,
                'body': json.dumps({'message': 'Failed to create deployment'})
            }

        # Monitor and alert on container health and deployment status
        k8s_config = k8s.V1beta1KubernetesApi()
        deployment_status = k8s_config.read_namespaced_deployment(
            name=deployment_name,
            namespace=namespace
        )

        while True:
            time.sleep(10)
            deployment_status = k8s_config.read_namespaced_deployment(
                name=deployment_name,
                namespace=namespace
            )
            if deployment_status.status.condition[0].status == 'True':
                break

        # Roll back deployments on startup times exceeding predefined thresholds
        if deployment_status.status.start_time > time.time() - config_data['startup_timeout']:
            print(f'Rolling back deployment {deployment_name} due to slow startup')
            try:
                k8s_config.delete_namespaced_deployment(
                    name=deployment_name,
                    namespace=namespace
                )
            except ClientError as e:
                # Handle failed rollbacks
                print(f'Error rolling back deployment: {e}')
                return {
                    'statusCode': 500,
                    'body': json.dumps({'message': 'Failed to roll back deployment'})
                }

        # Fallback strategy for degraded service conditions
        if config_data['failure_threshold'] > 0:
            print(f'Falling back on fallback strategy due to {config_data["failure_threshold"]} failures')
            try:
                k8s_config.create_namespaced_deployment(
                    namespace=namespace,
                    body={
                        'apiVersion': 'apps/v1',
                        'kind': 'Deployment',
                        'metadata': {'name': deployment_name},
                        'spec': {
                            'replicas': 0
                        }
                    }
                )
            except V1beta1InvalidObjectReference as e:
                # Handle failed fallbacks
                print(f'Error creating fallback deployment: {e}')
                return {
                    'statusCode': 500,
                    'body': json.dumps({'message': 'Failed to create fallback deployment'})
                }

        return {
            'statusCode': 200,
            'body': json.dumps({'message': 'Container deployment successful'})
        }
    except Exception as e:
        # Handle general exceptions
        print(f'Error: {e}')
        return {
            'statusCode': 500,
            'body': json.dumps({'message': 'Failed to process container configuration'})
        }
