template <typename T>
class DynamicQueue {
private:
    std::queue<T> queue_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::atomic<int> size_(0);

public:
    void enqueue(const T& item) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(item);
        ++size_;
        lock.unlock();
        cv_.notify_one();
    }

    bool dequeue(T& item) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (queue_.empty()) {
            cv_.wait(lock);
        }
        item = queue_.front();
        queue_.pop();
        --size_;
        return true;
    }

    int size() const {
        return size_;
    }
};

