// Function to rename files with timestamp and versioning
void batchFileRenamingWithVersioning(char* directory, char* timestamp_format) {
    DIR* dir = opendir(directory);
    if (dir == NULL) {
        // Handle error: invalid directory path
        return;
    }

    int current_version = initial_version;

    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        if (!strcmp(ent->d_name, ".") || !strcmp(ent->d_name, "..")) {
            continue; // Skip the . and .. directories
        }

        char file_path[1024];
        sprintf(file_path, "%s/%s", directory, ent->d_name);

        // Create a copy of the original file name for renaming
        char new_name[1024];
        sprintf(new_name, "v%d-%s-%s.%s",
            current_version,
            timestamp_format,
            ent->d_name + strlen(directory),
            strrchr(ent->d_name, '.') ? strrchr(ent->d_name, '.') : ".");

        // Simulate file renaming (actual implementation depends on the system)
        printf("Renaming %s to %s...\n", file_path, new_name);

        // Increment the version number for the next file
        current_version++;
    }

    closedir(dir);
}

int main() {
