```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_FILE_NAME_LENGTH 255
#define MAX_THREADS 10

typedef enum {
    VERSION_INCREMENT,
    VERSION_RESET
} version_type;

typedef struct {
    char* file_path;
    int version;
    version_type increment_type;
} file_info_t;

void* rename_thread(void* arg) {
    file_info_t* file_info = (file_info_t*)arg;
    // Rename the file with a timestamp and version number
    char new_file_name[MAX_FILE_NAME_LENGTH];
    sprintf(new_file_name, "%s_%d", file_info->file_path, file_info->version);
    rename(file_info->file_path, new_file_name);

    free(file_info);
}

int renameDirectoryWithVersioning(const char* directory_path, int initial_version, int max_version_increments) {
    DIR* dir = opendir(directory_path);
    if (!dir) {
        return -1; // Directory not found
    }

    pthread_t threads[MAX_THREADS];
    file_info_t* files = (file_info_t*)malloc(sizeof(file_info_t) * MAX_THREADS);

    int i = 0;
    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        if (!strcmp(ent->d_name, ".") || !strcmp(ent->d_name, "..")) {
            continue; // Skip dot files
        }

        char file_path[MAX_FILE_NAME_LENGTH];
        sprintf(file_path, "%s/%s", directory_path, ent->d_name);

        int version = initial_version;
        for (int j = 0; j < max_version_increments; j++) {
            if (rename(file_path, file_path) == -1) {
                return -1; // File already exists
            }

            char new_file_name[MAX_FILE_NAME_LENGTH];
            sprintf(new_file_name, "%s_%d", file_path, version);
            rename(file_path, new_file_name);

            version++;
        }
    }

    closedir(dir);

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, rename_thread, &files[i]);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    free(files);

    return 0;
}

