int batchProcessDirectory(const char* directory_path, BatchConfig config, MoSTState* mo_st_state) {
    if (config.transform_files && !mo_st_state) {
        // Error: cannot transform files without a valid state object
        return -1;
    }

    DIR* dir = opendir(directory_path);
    if (!dir) {
        // Error: failed to open the directory
        return -2;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char file_path[256];
        sprintf(file_path, "%s/%s", directory_path, entry->d_name);

        if (config.include_dotfiles && strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue; // skip current directory and parent directory
        }

        if (!match_file_extension(file_path, config.file_extension)) {
            continue; // skip files with incorrect extension
        }

        if (config.transform_files) {
            transform_file(file_path);
        } else {
            process_file(file_path, mo_st_state);
        }
    }

    closedir(dir);

    return 0;
}

