#include <iostream>
#include <map>
#include <vector>
#include <chrono>
#include <thread>

using namespace std;

template<typename T>
class Cache {
public:
    // Function to add an item in the cache with TTL
    void addItem(T& data, int ttl) {
        lock_guard<mutex> lock(mutex_);
        map<pair<TT, T>>::iterator it = cache_.find(ttl);
        if (it == cache_.end()) {
            pair<TT, T> newPair(TT++, data);
            cache_[newPair] = data;
        } else {
            it->second = data;
        }
        // Initialize the cache timer
        this_thread::sleep_for(chrono::seconds(ttl));
        lock.unlock();
    }

    // Function to get an item from the cache
    T getItem(int ttl) {
        lock_guard<mutex> lock(mutex_);
        map<pair<TT, T>>::iterator it = cache_.find(ttl);
        if (it != cache_.end()) {
            return it->second;
        } else {
            return nullptr;
        }
    }

    // Function to remove an item from the cache
    void removeItem(int ttl) {
        lock_guard<mutex> lock(mutex_);
        map<pair<TT, T>>::iterator it = cache_.find(ttl);
        if (it != cache_.end()) {
            cache_.erase(it);
        }
    }

private:
    mutex mutex_;
    map<pair<TT, T>, T> cache_;
};

int main() {
    Cache<int> myCache;
    for (int i = 0; i < 10; i++) {
        int data = i;
        myCache.addItem(data, 2);
    }

    // Get an item from the cache
    int getData = myCache.getItem(1);
    if (getData != nullptr) {
        cout << "Data: " << getData << endl;
    } else {
        cout << "No Data Found" << endl;
    }

    return 0;
}
