class RateLimiter {
  constructor(rate) {
    this.rate = rate;
    this.count = 0;
  }

  async process(data) {
    if (this.count >= this.rate) {
      await new Promise(resolve => setTimeout(() => resolve(), 100));
      this.count = 0;
    }
    this.count++;
  }
