int main() {
    // Example usage
    const char* filename = "/path/to/file.txt";
    const char* extension = ".txt";
    int maxDigits = 3;
    char* newFilename = renameWithTimestamp(filename, extension, maxDigits);
    printf("Renamed file to: %s\n", newFilename);

    return 0;
}

char* renameWithTimestamp(const char* filename, const char* extension, int maxDigits) {
    // Allocate memory for the new filename
    size_t len = strlen(filename) + 16; // Account for timestamp and random digits
    char* newFilename = (char*)malloc(len);

    // Generate the timestamp with configurable precision
    time_t timestamp = time(NULL);
    char timestampStr[32];
    strftime(timestampStr, sizeof(timestampStr), "%Y%m%d%H%M%S", localtime(&timestamp));

    // Add a random number of digits between 2 and 5 to the timestamp
    int randomDigits = (int)(rand() % (maxDigits - 1) + 2);
    char randomDigitStr[16];
    sprintf(randomDigitStr, "%0*d", randomDigits, rand());

    // Construct the new filename
    strcpy(newFilename, filename);
    strcat(newFilename, extension);
    strcat(newFilename, "_");
    strcat(newFilename, timestampStr);
    strcat(newFilename, randomDigitStr);

    // Log the renaming operation
    logRenameOperation(filename, extension, maxDigits, len);

    return newFilename;
}

void logRenameOperation(char* oldFilename, const char* extension, int maxDigits, int len) {
    // Simulate logging to an external service
    printf("Renamed file '%s' to '%s'\n", oldFilename, oldFilename + strlen(oldFilename) - len);

    // Buffer logs locally and flush upon successful connection reestablishment
    static char logBuffer[1024];
    sprintf(logBuffer, "Rename operation: %s -> %s (%d digits in timestamp)\n", oldFilename, oldFilename + strlen(oldFilename) - len, maxDigits);
    printf("%s\n", logBuffer);
}
