#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_FILE_NAME 128
#define MAX_EXTENSION 16
#define TIMESTAMP_FORMAT "%Y%m%d_%H%M%S"
#define RANDOM_DIGITS 3 // Default number of random digits

typedef struct {
    char file_name[MAX_FILE_NAME];
    char extension[MAX_EXTENSION];
} file_info_t;

// Function to generate a random timestamp with configurable number of random digits
char* generate_timestamp(int num_random_digits) {
    time_t now = time(NULL);
    struct tm *info = localtime(&now);
    char timestamp[MAX_TIMESTAMP_LENGTH];
    strftime(timestamp, sizeof(timestamp), TIMESTAMP_FORMAT, info);

    // Add random digits to the end of the timestamp
    for (int i = 0; i < num_random_digits; i++) {
        int random_digit = rand() % 10;
        strcat(timestamp, "%d", random_digit);
    }

    return timestamp;
}

// Function to rename a file with the given information and logging mechanism
void batch_rename_with_timestamp(int num_files, file_info_t* files, int num_random_digits) {
    // Initialize the logger
    FILE *log_file = fopen("log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return;
    }

    for (int i = 0; i < num_files; i++) {
        char new_file_name[MAX_FILE_NAME + strlen(generate_timestamp(num_random_digits)) + 1];
        // Rename the file
        sprintf(new_file_name, "%s_%s", files[i].file_name, generate_timestamp(num_random_digits));
