} file_info_t;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int get_version() {
    static int current_version = INITIAL_VERSION;
    pthread_mutex_lock(&lock);
    int new_version = current_version++;
    pthread_mutex_unlock(&lock);
    return new_version;
}

void batchFileRenamingWithVersioning(const char *directory) {
    DIR *dp = opendir(directory);
    if (!dp) return;

    struct dirent *ent;
    while ((ent = readdir(dp)) != NULL) {
        if (ent->d_type == DT_REG || ent->d_type == DT_DIR) { // filter directories
            char *filename = ent->d_name;
