#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>
#include <unordered_map>

class HTTP_REQUEST_LOG_T {
public:
    int id;
    std::string request;
    int status_code;
};

class LogManager {
private:
    const size_t MAX_LOGS = 10'000'000;
    const size_t THROTTLE_RATE = 1000;

    std::mutex mtx;
    std::condition_variable cv;
    std::queue<HTTP_REQUEST_LOG_T> log_queue;
    std::vector<HTTP_REQUEST_LOG_T> memory_pool(MAX_LOGS);
    std::unordered_map<int, HTTP_REQUEST_LOG_T*> available_slots;
    int next_available_slot = 0;

public:
    void addLogEntry(HTTP_REQUEST_LOG_T& log) {
        {
            std::unique_lock<std::mutex> lock(mtx);
            while (log_queue.size() >= MAX_LOGS / 2 && !available_slots.empty()) {
                cv.wait(lock);
            }
        }
        if (!available_slots.empty()) {
            available_slots[next_available_slot] = &memory_pool[0];
            next_available_slot++;
        }
        log_queue.push(log);
    }

    void removeLogEntry() {
        std::unique_lock<std::mutex> lock(mtx);
        while (log_queue.empty()) {
            cv.wait(lock);
        }
        log_queue.pop();
        available_slots.erase(next_available_slot - 1);
        next_available_slot--;
    }

    void processLogs() {
        while (!log_queue.empty()) {
            HTTP_REQUEST_LOG_T& log = log_queue.front();
            log_queue.pop();

            // Send log to external service
            std::cout << "Sending log: " << log.request << std::endl;

            if (log.id % THROTTLE_RATE == 0) {
                // Simulate throttle delay
                std::this_thread::sleep_for(std::chrono::milliseconds(1));
            }
        }
    }

    void startProcessing() {
        std::thread t([this]() {
            while (!log_queue.empty()) {
                cv.notify_one();
                processLogs();
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        });
        t.detach();
    }
};

int main() {
    LogManager log_manager;
    log_manager.startProcessing();

    HTTP_REQUEST_LOG_T log1 = {"Log 1", "GET /home", 200};
    HTTP_REQUEST_LOG_T log2 = {"Log 2", "POST /login", 201};
    HTTP_REQUEST_LOG_T log3 = {"Log 3", "PUT /update", 204};

    log_manager.addLogEntry(log1);
    log_manager.addLogEntry(log2);
    log_manager.removeLogEntry();

    return 0;
}

