    std::condition_variable cv;
    std::map<std::string, ServiceEndpoint> serviceEndpoints;
    int endpointCount = 0;
    bool isShuttingDown = false;

public:
    void addServiceEndpoint(ServiceEndpoint& endpoint) {
        // locking and unlocking the mutex
        unique_lock<mutex> lock(mtx);
        if (isShuttingDown) {
            throw std::runtime_error("Cannot add a service endpoint while shutting down");
        }
        serviceEndpoints[endpoint.id] = endpoint;
        endpointCount++;
    }

    void removeServiceEndpoint(std::string id) {
        // locking and unlocking the mutex
        unique_lock<mutex> lock(mtx);
        if (isShuttingDown) {
            throw std::runtime_error("Cannot remove a service endpoint while shutting down");
        }
        if (serviceEndpoints.find(id) == serviceEndpoints.end()) {
            throw std::out_of_range("Service endpoint not found");
        }
        serviceEndpoints.erase(id);
        endpointCount--;
    }

    // function to validate configuration settings
    bool validateConfig(const Config& config) {
        if (!config.namespace_ || !config.deployment_id || !config.service_version) {
            return false;
        }
        return true;
    }

    // shutting down the endpoint manager
    void shutdown() {
        isShuttingDown = true;
    }
};

