class HTTPRequestLog {
public:
    std::string ip;
    std::string url;
    int status;

    HTTPRequestLog(const std::string& _ip, const std::string& _url, int _status)
        : ip(_ip), url(_url), status(_status) {}
};

class LogManager {
private:
    std::vector<HTTPRequestLog> logData;
    std::mutex mtx;
    std::condition_variable cv;
    bool stop = false;

public:
    void addLog(const HTTPRequestLog& log) {
        {
            std::unique_lock<std::mutex> lock(mtx);
            logData.push_back(log);
        }
        cv.notify_one();
    }

    void removeLog(size_t index) {
        {
            std::unique_lock<std::mutex> lock(mtx);
            if (index < logData.size()) {
                logData.erase(logData.begin() + index);
            }
        }
    }

    void exportLogs() {
        while (!stop) {
            {
                std::unique_lock<std::mutex> lock(mtx);
                while (logData.empty()) {
                    cv.wait(lock);
                }
                // Send logs to the external service here
                logData.clear();
            }
            std::this_thread::sleep_for(std::chrono::seconds(10));
        }
    }

    void startExporting() {
        stop = false;
        std::thread t([&]{ exportLogs(); });
        t.detach();
    }

    void stopExporting() {
        stop = true;
    }
};

int main() {
    LogManager manager;

    // Add logs
    manager.addLog(HTTPRequestLog("192.168.1.100", "/index.html", 200));
    manager.addLog(HTTPRequestLog("192.168.1.101", "/images/logo.png", 404));

    // Remove log
    manager.removeLog(0);

    // Start exporting logs
    manager.startExporting();

    // Stop exporting logs
    manager.stopExporting();

    return 0;
}
