    std::string value;
    int64_t expirationTime;
    uint32_t accessFrequency;
    uint32_t lastModifiedTimestamp;

    CacheEntry(const std::string& key, const std::string& value,
               int64_t expirationTime = 0, uint32_t accessFrequency = 0,
               uint32_t lastModifiedTimestamp = 0)
        : key(key), value(value), expirationTime(expirationTime),
          accessFrequency(accessFrequency),
          lastModifiedTimestamp(lastModifiedTimestamp) {}
};

class Cache {
public:
    std::unordered_map<std::string, CacheEntry> cacheMap;
    std::mutex cacheMutex;

    void put(const std::string& key, const std::string& value,
             int64_t expirationTime = 0, uint32_t accessFrequency = 0,
             uint32_t lastModifiedTimestamp = 0) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        cacheMap[key] = CacheEntry(key, value, expirationTime, accessFrequency,
                                    lastModifiedTimestamp);
    }

    std::string get(const std::string& key) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        if (cacheMap.find(key) != cacheMap.end()) {
            return cacheMap[key].value;
        }
        return "";
    }

    void remove(const std::string& key) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        cacheMap.erase(key);
    }
};

class DistributedCache {
public:
    std::vector<std::shared_ptr<Cache>> caches;

    void put(const std::string& key, const std::string& value,
             int64_t expirationTime = 0, uint32_t accessFrequency = 0,
             uint32_t lastModifiedTimestamp = 0) {
        for (auto& cache : caches) {
            cache->put(key, value, expirationTime, accessFrequency,
                       lastModifiedTimestamp);
        }
    }

    std::string get(const std::string& key) {
        for (auto& cache : caches) {
            if (!cache->get(key).empty()) {
                return cache->get(key);
            }
        }
        return "";
    }

    void remove(const std::string& key) {
        for (auto& cache : caches) {
            cache->remove(key);
        }
    }
};

