#include <fcntl.h>
#include <time.h>
#include <pthread.h>

#define MAX_FILE_NAME_LENGTH 256
#define MAX_TIMESTAMP_LENGTH 32

// Function to get the current timestamp in YYYYMMDDHHMMSS format
const char* getCurrentTimestamp() {
    time_t now = time(NULL);
    struct tm *ltm = localtime(&now);
    static char buffer[MAX_TIMESTAMP_LENGTH];
    strftime(buffer, sizeof(buffer), "%Y%m%d%H%M%S", ltm);
    return buffer;
}

// Function to get the file name with versioning and timestamp
const char* getVersionedFileName(const char* originalName, int version) {
    static char buffer[MAX_FILE_NAME_LENGTH];
    sprintf(buffer, "%s_v%04d_%s", originalName, version, getCurrentTimestamp());
    return buffer;
}

// Thread-safe function to rename files in parallel
void* batchFileRenamingWithVersioning(void* arg) {
    pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);

    // Get the directory path and configuration from the argument
    struct {
        const char* dirPath;
        int initialVersion;
        char* timestampFormat;
        char* notificationServiceURL;
        char* notificationServiceToken;
    } *config = (struct *)arg;

    DIR* dir = opendir(config->dirPath);
    if (!dir) {
        // Handle errors
        return NULL;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue; // Skip . and ..
        }

        char filePath[MAX_FILE_NAME_LENGTH];
        sprintf(filePath, "%s/%s", config->dirPath, entry->d_name);

        int version = config->initialVersion;
        while (1) {
            char* newFilePath = getVersionedFileName(entry->d_name, version);
            if (rename(filePath, newFilePath) == 0) {
                break; // Renaming successful
            } else {
                // Handle errors
                continue;
            }

            version++;
        }

        // Integrate with notification service and log events
        printf("Renamed file: %s\n", entry->d_name);
    }

    closedir(dir);

    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc != 7) {
        printf("Usage: %s <dirPath> <initialVersion> <timestampFormat> <notificationServiceURL> <notificationServiceToken>\n", argv[0]);
        return -1;
    }

    const char* dirPath = argv[1];
    int initialVersion = atoi(argv[2]);
    char* timestampFormat = argv[3];
    char* notificationServiceURL = argv[4];
    char* notificationServiceToken = argv[5];

    // Create and launch threads for parallel renaming
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        struct {
            const char* dirPath;
            int initialVersion;
            char* timestampFormat;
            char* notificationServiceURL;
            char* notificationServiceToken;
        } config;
        config.dirPath = dirPath;
        config.initialVersion = initialVersion;
        config.timestampFormat = timestampFormat;
        config.notificationServiceURL = notificationServiceURL;
        config.notificationServiceToken = notificationServiceToken;

        pthread_create(&threads[i], NULL, batchFileRenamingWithVersioning, &config);
    }

    // Wait for threads to complete
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
