use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::process::{Command, exit};
use std::thread;
use std::time::Duration;

struct BuildSystem {
    tasks: Vec<Box<dyn Task>>,
    task_deps: HashMap<String, HashSet<String>>,
    plugins: Vec<Box<dyn Plugin>>,
}

impl BuildSystem {
    fn new() -> Self {
        BuildSystem {
            tasks: vec![],
            task_deps: HashMap::new(),
            plugins: vec![],
        }
    }

    fn load_tasks(&mut self, config_file: &str) {
        let mut tasks = vec![];
        if let Ok(config) = std::fs::read_to_string(config_file) {
            for line in config.lines() {
                if let Some(task_name) = line.strip_prefix("task ") {
                    tasks.push(Box::new(Task::new(task_name.to_string())));
                }
            }
        }
        self.tasks.extend_from_slice(&tasks);
    }

    fn execute_tasks(&self) {
        let mut task_queue: Vec<Box<dyn Task>> = self.tasks.clone();
        loop {
            if let Some(task) = task_queue.pop() {
                if let Err(err) = task.execute() {
                    eprintln!("Error executing task {}: {}", task.name(), err);
                }
            } else {
                break;
            }
        }
    }

    fn run_plugins(&self) {
        for plugin in &self.plugins {
            if let Err(err) = plugin.run() {
                eprintln!("Error running plugin: {}", err);
            }
        }
    }
}

