// batchFileRenamingWithVersioning function
#include <filesystem>
#include <chrono>

bool batchFileRenamingWithVersioning(const std::string& directoryPath, int initialVersion) {
    namespace fs = std::filesystem;

    // get all files in the specified directory
    for (const auto& entry : fs::directory_iterator(directoryPath)) {
        if (entry.is_regular_file()) {
            // generate timestamp and version number
            std::time_t time = std::time(nullptr);
            std::string timestamp = std::to_string(std::chrono::system_clock::from_time_t(time));
            int version = initialVersion++;

            // rename the file with a timestamp and version number
            fs::path filePath = entry.path();
            std::string renamedFilePath = (directoryPath + "/" + filePath.filename().string() + "_" + timestamp + "_v" + std::to_string(version) + ".txt");
            fs::rename(filePath, renamedFilePath);
        }
    }

    return true;
}

