import os
import time

def batch_file_renaming_with_versioning(directory_path, initial_version):
    for entry in os.listdir(directory_path):
        if os.path.isfile(os.path.join(directory_path, entry)):
            timestamp = str(int(time.time()))
            version = initial_version + 1

            # rename the file with a timestamp and version number
            new_file_path = os.path.join(directory_path, f"{entry}_{timestamp}_v{version}.txt")
            os.rename(os.path.join(directory_path, entry), new_file_path)
    return True

