['Here's a sample Go code block for designing an HTTP reverse proxy that meets the requirements:

```go
package main

import (
    "context"
    "fmt"
    "net/http"
    "sync"
    "time"

    "github.com/go-redis/redis/v8"
)

type proxy struct {
    // Upstream services map
    upstreams map[string]*http.Client

    // Rate limiters map
    ratelimiters map[string]*ratelimiter

    // Cache store
    cache *redis.Client

    // Connection pool
    connections *connectionPool

    // Context for canceling requests
    ctx context.Context
}

type ratelimiter struct {
    maxPerSecond int
    maxTotal     int

    mu      sync.Mutex
    counter map[string]int
}

func (r *ratelimiter) AllowIP(ip string) bool {
    r.mu.Lock()
    defer r.mu.Unlock()

    count, ok := r.counter[ip]
    if !ok || count <= 0 {
        return true
    }

    if time.Since(r.counter[ip].timestamp).Seconds() >= float64(1)/float64(r.maxPerSecond) {
        r.counter[ip] = struct{}{max: r.maxTotal, timestamp: time.Now()}
        return true
    }
    return false
}

func main() {
    // Initialize the proxy with Redis and connection pool
    p := &proxy{
        upstreams: make(map[string]*http.Client),
        ratelimiters: make(map[string]*ratelimiter),
        cache: redis.NewClient(&redis.Options{
            Addr: "localhost:6379",
        }),
        connections: newConnectionPool(),
        ctx: context.Background(),
    }

    // Start the proxy
    go p.start()
}

func (p *proxy) start() {
    http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
        // Handle requests from clients
        p.handleRequest(r)
    })

    log.Println("Proxy started on port 8080")
    if err := http.ListenAndServe(":8080", nil); err != nil {
        log.Fatal(err)
    }
}

func (p *proxy) handleRequest(r *http.Request) {
    // Get the upstream service and rate limiter for the request
    upstream, ok := p.upstreams[r.Host]
    if !ok {
        w.WriteHeader(http.StatusNotFound)
        return
    }

    ratelimiter, ok := p.ratelimiters[r.Host]
    if !ok || !ratelimiter.AllowIP(r.RemoteAddr) {
        w.WriteHeader(http.StatusTooManyRequests)
        return
    }

    // Get the cached response for the request
    cachedResponse, err := p.cache.Get(r.RequestURI).Result()
    if err == nil && cachedResponse != nil {
        w.Write(cachedResponse.([]byte))
        return
    }

    // Forward the request to the upstream service
    resp, err := upstream.DoRequest(r)
    if err != nil {
        log.Println(err)
        return
    }

    // Cache the response
    p.cache.Set(r.RequestURI, resp, 0)

    w.Write(resp)
}

type connectionPool struct {
    connections []*http.Client
    mu           sync.Mutex
}

func (cp *connectionPool) GetConnection() *http.Client {
    cp.mu.Lock()
    defer cp.mu.Unlock()

    for _, c := range cp.connections {
        if c != nil && c.Transport == nil {
            return c
        }
    }

    // Create a new connection if none are available
    conn, err := http.Client().Get("https://example.com")
    if err != nil {
        log.Println(err)
        return nil
    }

    cp.connections = append(cp.connections, conn)
    return conn
}

func (cp *connectionPool) Close() {
    for _, c := range cp.connections {
        c.Close()
    }
}
```']

