// Define the structure to represent a network session (ConnectionState)
typedef struct {
    int connection_id;
    time_t last_active_timestamp;
    float current_throughput;
    struct flow *active_flows; // linked list of active flows
} ConnectionState;

// Define the structure to represent an active flow (Flow)
typedef struct flow {
    int offset;
    char key[64];
    pthread_mutex_t lock; // for thread-safe operations
    struct flow *next;
} Flow;

// Initialize a new connection state with default values
ConnectionState* init_connection_state() {
    ConnectionState* cs = (ConnectionState*)malloc(sizeof(ConnectionState));
    cs->connection_id = 0;
    cs->last_active_timestamp = time(NULL);
    cs->current_throughput = 0.0f;
    cs->active_flows = NULL;
    return cs;
}

// Add a new flow to the connection state
void add_flow(ConnectionState* cs, int offset, char key[64]) {
    Flow* new_flow = (Flow*)malloc(sizeof(Flow));
    new_flow->offset = offset;
    strcpy(new_flow->key, key);
    new_flow->next = cs->active_flows;
    pthread_mutex_lock(&new_flow->lock);
    cs->active_flows = new_flow;
    pthread_mutex_unlock(&new_flow->lock);
}

// Remove a flow from the connection state
void remove_flow(ConnectionState* cs) {
    Flow* current = cs->active_flows;
    Flow* prev = NULL;
    while (current != NULL) {
        prev = current;
        current = current->next;
        free(prev);
    }
    cs->active_flows = NULL;
}

// Monitor connection state and update health checks
void monitor_connection_state(ConnectionState* cs) {
    // Implement periodic health checks and performance metrics updates
    printf("Connection State: %d, Last Active Timestamp: %ld, Current Throughput: %.2f\n",
           cs->connection_id, cs->last_active_timestamp, cs->current_throughput);
