    add_flow(cs, 2, "FLOW_2");
    add_flow(cs, 3, "FLOW_3");

    // Monitor the connection state
    monitor_connection_state(cs);

    // Remove a flow from the connection state
    remove_flow(cs);

    // Clean up memory allocations
    free(cs);
    return 0;
}

// Thread-safe operations for concurrent access from multiple application threads
