    time_t last_active_timestamp;
    double throughput;
    struct Flow* flows;  // Linked list of active flows
} ConnectionState;

// Define a structure to represent flow information
typedef struct {
    int id;
    int bytes_sent;
    int packets_sent;
    struct Flow* next;  // Pointer to the next flow in the list
} Flow;

// Initialize the connection state linked list
void init_flow_list(struct Flow** flows) {
    *flows = NULL;
}

// Add a new flow to the connected state linked list
void add_flow(struct ConnectionState* conn, int id) {
    struct Flow* new_flow = (struct Flow*)malloc(sizeof(struct Flow));
    new_flow->id = id;
    new_flow->bytes_sent = 0;
    new_flow->packets_sent = 0;
    new_flow->next = conn->flows;
    conn->flows = new_flow;
}

// Remove a flow from the connection state linked list
void remove_flow(struct ConnectionState* conn, int id) {
    struct Flow* current = conn->flows;
    struct Flow* previous = NULL;

    while (current != NULL && current->id != id) {
        previous = current;
        current = current->next;
    }

    if (current != NULL) {
        if (previous == NULL)
            conn->flows = current->next;
        else
            previous->next = current->next;
        free(current);
    }
}

// Define the NetworkFabric library structure
typedef struct {
    pthread_mutex_t lock;  // Mutex for thread-safe operations
    ConnectionState* connections;  // Dynamic array of connection states
    int num_connections;  // Number of active connections
