    NetworkFabric* nf = (NetworkFabric*)malloc(sizeof(NetworkFabric));
    pthread_mutex_init(&nf->lock, NULL);
    nf->connections = (ConnectionState*)malloc(max_connections * sizeof(ConnectionState));
    nf->num_connections = 0;
    return nf;
}

// Add a new connection to the network fabric
void add_connection(NetworkFabric* nf) {
    pthread_mutex_lock(&nf->lock);

    if (nf->num_connections >= nf->connections->max_size)
        // Reallocate memory for more connections
        reallocate_connections(nf, nf->num_connections * 2);

    ConnectionState* new_conn = &nf->connections[nf->num_connections];
    init_flow_list(&new_conn->flows);
    nf->num_connections++;

    pthread_mutex_unlock(&nf->lock);
}

// Remove a connection from the network fabric
void remove_connection(NetworkFabric* nf, int id) {
    pthread_mutex_lock(&nf->lock);

    for (int i = 0; i < nf->num_connections; i++) {
        if (nf->connections[i].id == id) {
            // Find and remove the flow from the linked list
            remove_flow(&nf->connections[i], id);
