    uint64_t bytes_received;
} Flow;

typedef struct ConnectionState {
    uint32_t id;
    time_t last_active_timestamp;
    float current_throughput;
    Flow* flows;
} ConnectionState;

typedef struct NetworkFabric {
    pthread_mutex_t lock;
    ConnectionState** connections;
    uint32_t connection_count;
    uint32_t max_connections;
} NetworkFabric;

// Initialize network fabric
void networkfabric_init(NetworkFabric* fabric, uint32_t max_connections) {
    fabric->connection_count = 0;
    fabric->max_connections = max_connections;
    fabric->connections = (ConnectionState**)malloc(max_connections * sizeof(ConnectionState*));
}

// Add connection to network fabric
void networkfabric_add_connection(NetworkFabric* fabric, ConnectionState* connection) {
    pthread_mutex_lock(&fabric->lock);
    if (fabric->connection_count < fabric->max_connections) {
        fabric->connections[fabric->connection_count++] = connection;
    }
