void NetworkInterfaceManager::addInterfaceStats(const std::string& interfaceName, const INTERFACE_STATS_RECORD& record) {
    // Add the new stats to the in-memory cache
    InterfaceStats stats(interfaceName, record);
    interfaceStats_.push_back(stats);

    // Update the persistent storage system
    updatePersistentStorage(stats.getInterfaceName(), stats.getRecord());
}

void NetworkInterfaceManager::removeInterfaceStats(const std::string& interfaceName) {
    // Find and remove the corresponding stats from the in-memory cache
    for (auto it = interfaceStats_.begin(); it != interfaceStats_.end(); ++it) {
        if (it->getInterfaceName() == interfaceName) {
            interfaceStats_.erase(it);
            break;
        }
    }

    // Update the persistent storage system
    updatePersistentStorage(interfaceName, INTERFACE_STATS_RECORD()); // Set stats to default values
}

