        MemoryAllocator(size_t chunkSize) : chunkSize_(chunkSize), allocatedChunks_() {}
        void* allocate(size_t size) {
            if (size <= chunkSize_) {
                return reinterpret_cast<void*>(allocatedChunks_.data());
            } else {
                // Non-contiguous allocation
                void* ptr = ::operator new(size);
                allocatedChunks_.push_back(ptr);
