typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[MAX_CRCFLAG];
} NFAPI_CRC_INDICATION_PDU_T;

void* alloc_shared_memory(int size) {
    int fd = shm_open("/crc_indications", O_RDWR | O_CREAT, 0600);
    if (fd < 0) {
        perror("shm_open");
        return NULL;
    }

    void* addr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (addr == MAP_FAILED) {
        perror("mmap");
        close(fd);
        shm_unlink("/crc_indications");
        return NULL;
    }

    shm_unlink("/crc_indications");
    close(fd);

    return addr;
}

void free_shared_memory(void* addr, int size) {
    munmap(addr, size);
}

int generate_crc_indications(int num_structures, void** shared_memory) {
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDATION_PDU_T*)((*shared_memory));

    for (int i = 0; i < num_structures; i++) {
        // Initialize CRC indications
        crc_indications[i].RX_UE_INFORMATION_TAG = rand() % 100;
        crc_indications[i].RNTI = rand() % 10000;

        // Set CRC flag dynamically
        sprintf(crc_indications[i].CRC_INDICATION_REL8_TAG, "%02X", rand() % MAX_CRCFLAG);

        // Store in shared memory
        memcpy(&crc_indications[i], &shared_memory[0], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    return 0;
}

int main() {
    void* shared_memory = alloc_shared_memory(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    int num_structures = generate_crc_indications(N, &shared_memory);

    free_shared_memory(shared_memory, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return 0;
}
