} record_t;

int main() {
    // Allocate memory for arrays
    int* keys = (int*)malloc(sizeof(int) * 10);
    long* offsets = (long*)malloc(sizeof(long) * 10);

    // Initialize arrays with values
    for (int i = 0; i < 10; i++) {
        keys[i] = i;
        offsets[i] = (long)i * 1000000;
    }

    // Allocate memory for records array
    record_t* records = (record_t*)malloc(sizeof(record_t) * 10);

    // Initialize and set random values for each record's int field
    srand(time(NULL));
    for (int i = 0; i < 10; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
        records[i].int_field = rand() % 100;
    }

    // Print the initialized array of 'record' structures
    for (int i = 0; i < 10; i++) {
        printf("Record[%d]: key=%d, offset=%ld, int_field=%d\n", i, records[i].key, records[i].offset, records[i].int_field);
    }

    // Free allocated memory
    free(keys);
    free(offsets);
    free(records);

    return 0;
}
