    class CompressionLibrary {
    public:
        // Constructor to initialize the library
        CompressionLibrary() : zlib_compressor_(nullptr), zstd_decompressor_(nullptr) {}

        // Destructor to clean up resources
        ~CompressionLibrary() {
            if (zlib_compressor_) {
                inflateEnd(zlib_compressor_);
                free(zlib_compressor_);
            }
            if (zstd_decompressor_) {
                zstd_decompressor_ = nullptr;
            }
        }

        // Function to compress data using ZLIB
        std::string zlib_compress(const std::string& input_data) {
            int ret;
            unsigned char outbuff[1024];
            z_stream strm;
            strm.zalloc = nullptr;
            strm.zfree = nullptr;
            strm.opaque = nullptr;

            // Initialize the compression stream
