                return "Error initializing zlib compressor";
            int err;
            do {
                ret = deflate(&strm, Z_NO_FLUSH);
                if (ret == Z_STREAM_ERROR)
                    return "zlib: stream error";
                if (ret == Z_DATA_ERROR)
                    return "zlib: data error";
            } while (!done);

            // Close the compression stream
            deflateEnd(&strm);

            return "";
        }

        // Function to decompress data using ZSTD
        std::string zstd_decompress(const std::string& input_data) {
