// Initialize a semaphore with an initial value of 1
sem_t my_sem;

void* thread_func(void* arg) {
    // Acquire the semaphore using sem_wait()
    sem_wait(&my_sem);

    // Critical section where shared resources are accessed
    printf("Thread %ld is executing\n", pthread_self());

    // Release the semaphore using sem_post()
    sem_post(&my_sem);

    return NULL;
}

int main() {
    // Initialize a thread pool with 10 threads
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
