#include <forward_list>
#include <vector>
#include <memory>

class LoggerInterface {
public:
    virtual void log(const std::string& message) = 0;
};

void batchInsertOrLogError(std::forward_list<std::string>& output, const std::vector<const char*>& input, std::shared_ptr<LoggerInterface> logger) {
    // Define a small constant for batch size
    constexpr int batchSize = 100;

    // Process the input vector in batches
    for (int i = 0; i < input.size(); i += batchSize) {
        int endIndex = std::min(i + batchSize, input.size());
        for (int j = i; j < endIndex; ++j) {
            const char* str = input[j];
            // Find the target string
            bool found = false;
            auto it = output.begin();
            while (it != output.end() && !found) {
                if (*it == std::string(str)) {
                    found = true;
                    break;
                }
                ++it;
            }
            // Insert or log error based on the target string
            if (!found) {
                output.insert_after(it, str);
            } else {
                logger->log(std::string(str));
            }
        }
    }
}
