using namespace boost::asio;
using namespace boost::beast;

// Function to send GET request
void sendGetRequest(ip::tcp::socket& socket, std::string url) {
    http::request<http::string_body> req;
    req.version(11);
    req.method(http::verb::get);
    req.target(url);
    req.set(http::field::host, "localhost");

    // Send the request
    boost::beast::http::write(socket.get_lowest_layer(), req);

    // Read the response
    http::response<http::string_body> res;
    boost::beast::http::read(socket.get_lowest_layer(), res);
}

// Function to send POST request
void sendPostRequest(ip::tcp::socket& socket, std::string url, std::string data) {
    http::request<http::string_body> req;
    req.version(11);
    req.method(http::verb::post);
    req.target(url);
    req.set(http::field::host, "localhost");
    req.body(data);

    // Send the request
    boost::beast::http::write(socket.get_lowest_layer(), req);

    // Read the response
    http::response<http::string_body> res;
    boost::beast::http::read(socket.get_lowest_layer(), res);
}

int main() {
    try {
        io_context ioc;

        ip::tcp::resolver resolver(ioc);
        ip::tcp::endpoint ep = *resolver.resolve("localhost", "8080");

        ip::tcp::socket socket(ioc, ep);

        // Send GET request
        sendGetRequest(socket, "/api/v1/data");

        // Send POST request
        std::string data = "{\"name\":\"John\",\"age\":30,\"city\":\"New York\"}";
        sendPostRequest(socket, "/api/v1/create", data);

    } catch (boost::system::system_error& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
