using System;
using System.Configuration;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class GameConfigService
{
    private readonly HttpClient _httpClient;
    private readonly string _configServiceUrl;
    private readonly int _pollingIntervalMilliseconds = 1000; // Update interval in milliseconds

    public GameConfigService(string configServiceUrl)
    {
        _httpClient = new HttpClient();
        _configServiceUrl = configServiceUrl;
    }

    public async Task FetchAndApplyConfigAsync()
    {
        try
        {
            string responseJson = await _httpClient.GetStringAsync(_configServiceUrl);
            ConfigData configData = JsonConvert.DeserializeObject<ConfigData>(responseJson);

            // Update game world and camera settings proportionally
            GameWorldSettings.Update(configData.TileSize, configData.WorldDimensions);
            CameraMovementSettings.Update(configData.CameraSpeed);

            // Notify users of configuration changes through in-game prompts
            Console.WriteLine($"Configuration updated: {configData.TileSize}, {configData.WorldDimensions}, {configData.CameraSpeed}");
        }
        catch (HttpRequestException ex)
        {
            // Log network failure and rethrow exception for further handling
            Console.WriteLine("Network failure: " + ex.Message);
            throw;
        }
        catch (JsonReaderException ex)
        {
            // Log invalid configuration data and rethrow exception for further handling
            Console.WriteLine("Invalid configuration data: " + ex.Message);
            throw;
        }
    }

    public async Task PollForConfigUpdatesAsync()
    {
        while (true)
        {
            await FetchAndApplyConfigAsync();
            await Task.Delay(_pollingIntervalMilliseconds);
        }
    }
}

public class ConfigData
{
    public int TileSize { get; set; }
    public Dimensions WorldDimensions { get; set; }
    public float CameraSpeed { get; set; }
}

public struct Dimensions
{
    public int Width { get; set; }
    public int Height { get; set; }
}
