import org.jdbi.v3.core.Jdbi;
import org.jooq.DSL;
import org.jooq.impl.DSL;

// Define the API resource
@Path("/api/v1/products")
@Produces(MediaType.APPLICATION_JSON)
public class ProductResource {
    // Inject JDBI instance and MetricsRegistry
    @Inject
    public ProductResource(Jdbi jdbi, MetricsRegistry metricsRegistry) {
        // Initialize the JDBI instance with the database configuration
        this.jdbi = jdbi;
        // Initialize the MetricsRegistry for monitoring performance
        this.metricsRegistry = metricsRegistry;
    }

    // Handle GET requests to retrieve product catalog
    @GET
    public Response getProducts() {
        // Use JDBI to query the database and retrieve products
        List<Product> products = jdbi.withHandle(handle -> {
            return handle.createQuery("SELECT * FROM products").execute();
        });
        // Return the products as JSON response
        return Response.ok(products).build();
    }

    // Handle POST requests to create a new product
    @POST
    public Response createProduct(BodyParam<Product> product) {
        // Use JDBI to insert the product into the database
        jdbi.withHandle(handle -> {
            handle.insertInto("products").values(product).execute();
        });
        // Return a success response indicating the product was created
        return Response.status(Status.CREATED).build();
    }

    // Handle PUT requests to update an existing product
    @PUT
    public Response updateProduct(BodyParam<Product> product) {
        // Use JDBI to update the product in the database
        jdbi.withHandle(handle -> {
            handle.update("products").set(product).execute();
        });
        // Return a success response indicating the product was updated
        return Response.status(Status.OK).build();
    }

    // Handle DELETE requests to remove an existing product
    @DELETE
    public Response deleteProduct(PathParam<String> productId) {
        // Use JDBI to delete the product from the database
        jdbi.withHandle(handle -> {
            handle.delete("products").where("id = ?", productId).execute();
        });
        // Return a success response indicating the product was deleted
        return Response.status(Status.OK).build();
    }
}

// Define the Product entity class
