        private readonly IHttpClientFactory _httpClientFactory;
        private readonly RedisConnection _redisConnection;
        private readonly IEventBus _eventBus;
        private readonly ICachingLayer _cachingLayer;
        private readonly ITokenManager _tokenManager;

        public WidgetUpdateService(
            IHttpClientFactory httpClientFactory,
            RedisConnection redisConnection,
            IEventBus eventBus,
            ICachingLayer cachingLayer,
            ITokenManager tokenManager
        )
        {
            _httpClientFactory = httpClientFactory;
            _redisConnection = redisConnection;
            _eventBus = eventBus;
            _cachingLayer = cachingLayer;
            _tokenManager = tokenManager;
        }

        [HttpPost]
        public async Task<IActionResult> UpdateWidget([FromBody] WidgetConfig widgetConfig)
        {
            // 1. Validate incoming data against JSON schema
            if (!ValidateWidgetConfig(widgetConfig))
            {
                return BadRequest("Invalid widget configuration");
            }

            // 2. Authorize access based on role and OAuth token
            if (!_tokenManager.IsValidToken(Request.Headers.Authorization))
            {
                return Unauthorized("Unauthorized access");
            }

            // 3. Process the update request asynchronously
            await _httpClientFactory.CreateClient().SendAsync(new HttpRequestMessage(HttpMethod.Post, "widget_update_endpoint"));

            // 4. Cache the updated widget configuration (TTL: 1 hour)
            _cachingLayer.SetCacheObject("widget-" + widgetConfig.Id, widgetConfig, TimeSpan.FromHours(1));

            // 5. Publish the update event to the external event bus
            await _eventBus.PublishAsync(new WidgetUpdatedEvent(widgetConfig));

            return Ok("Widget updated successfully");
        }

