#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>

using namespace std;

class FinancialTransaction {
public:
    string transactionId;
    double amount;
    string paymentMethod;

    FinancialTransaction(string transactionId, double amount, string paymentMethod) 
        : transactionId(transactionId), amount(amount), paymentMethod(paymentMethod) {}
};

class TransactionProcessor {
public:
    queue<FinancialTransaction> transactions;
    mutex mtx;
    condition_variable cv;
    bool shutdown = false;

    void processTransactions() {
        while (!shutdown) {
            unique_lock<mutex> lock(mtx);
            cv.wait(lock, [this]{ return !transactions.empty() || shutdown; });

            if (shutdown)
                break;

            FinancialTransaction transaction = transactions.front();
            transactions.pop();

            // Process the transaction here
            cout << "Processed transaction: " << transaction.transactionId << endl;
        }
    }

    void addTransaction(FinancialTransaction transaction) {
        lock_guard<mutex> lock(mtx);
        transactions.push(transaction);
        cv.notify_one();
    }

    void shutdown() {
        lock_guard<mutex> lock(mtx);
        shutdown = true;
        cv.notify_all();
    }
};

class TransactionValidator {
public:
    bool validate(FinancialTransaction transaction) {
        // Validate the transaction here
        if (transaction.amount > 1000)
            return false;

        return true;
    }
};

int main() {
    TransactionProcessor processor;
    TransactionValidator validator;

    thread t1([&processor]() {
        while (!processor.shutdown) {
            FinancialTransaction transaction = processor.transactions.front();
            processor.transactions.pop();

            if (!validator.validate(transaction)) {
                // Handle invalid transactions
                cout << "Invalid transaction: " << transaction.transactionId << endl;
                processor.addTransaction(transaction); // Fallback strategy
            } else {
                // Process valid transactions
                cout << "Processed transaction: " << transaction.transactionId << endl;
            }
        }
    });

    for (int i = 0; i < 1000; i++) {
        FinancialTransaction transaction("T" + to_string(i), 500.00, "Credit Card");
        processor.addTransaction(transaction);
    }

    this_thread::sleep_for(chrono::seconds(1));
    processor.shutdown();

    t1.join();
    return 0;
}
