// state_loader.rs
use std::collections::{HashMap, HashSet};
use serde::{Deserialize, Serialize};
use anyhow::{Result, Error};

#[derive(Serialize, Deserialize)]
enum ConfigFormat {
    Json,
    Yaml,
    Bson,
}

impl ConfigFormat {
    fn from_file(file_path: &str) -> Result<Self> {
        // implement parsing logic for each format
        // ...
    }
}

struct StateLoader {
    cache: HashMap<String, serde_json::Value>,
    config_format: ConfigFormat,
    schema: Box<dyn Serialize + Deserialize<'static>>,
}

impl StateLoader {
    fn new(config_format: &str) -> Self {
        let config_format = match config_format {
            "json" => ConfigFormat::Json,
            "yaml" => ConfigFormat::Yaml,
            "bson" => ConfigFormat::Bson,
            _ => panic!("Invalid format"),
        };

        StateLoader {
            cache: HashMap::new(),
            config_format,
            schema: Box::new(serde_json::json!({"hello": "world"})),
        }
    }

    fn load_state(&self, file_path: &str) -> Result<serde_json::Value> {
        match self.config_format {
            ConfigFormat::Json => {
                let json = serde_json::from_reader(FileReader::open(file_path)?);
                if let Ok(json) = json {
                    // validate against schema
                    // ...
                    self.cache.insert(file_path.to_string(), json.clone());
                    Ok(json)
                } else {
                    Err(Error::new("Invalid JSON file"))
                }
            },
        }
    }

    fn get_state(&self, file_path: &str) -> Result<serde_json::Value> {
        if let Some(state) = self.cache.get(file_path) {
            Ok(state.clone())
        } else {
            match self.load_state(file_path) {
                Ok(state) => Ok(state),
                Err(err) => Err(err),
            }
        }
    }
}

struct Cacher {
    cache: HashMap<String, Box<dyn Serialize + Deserialize<'static>>>,
}

impl Cacher {
    fn new() -> Self {
        Cacher { cache: HashMap::new() }
    }

    fn get(&self, key: &str) -> Option<&Box<dyn Serialize + Deserialize<'static>>> {
        self.cache.get(key)
    }

    fn set(&mut self, key: &str, value: Box<dyn Serialize + Deserialize<'static>>)
    {
        self.cache.insert(key.to_string(), value);
    }
}

// caching.rs
