            {
                await BearerAuthenticationAsync(context);
            }
            else if (context.AuthenticationScheme == "OpenIdConnect")
            {
                await OpenIdConnectAuthenticationAsync(context);
            }
            else
            {
                await _next(context);
            }
        }

        private async Task BearerAuthenticationAsync(AuthorizationContext context)
        {
            var token = context.Request.Headers["Authorization"].FirstOrDefault();
            if (!string.IsNullOrEmpty(token))
            {
                try
                {
                    var validateTokenResult = ValidateToken(token);
                    if (validateTokenResult.IsValid)
                    {
                        await SetUserAsync(context, validateTokenResult.User);
                    }
                    else
                    {
                        await HandleInvalidTokenAsync(context);
                    }
                }
                catch (Exception ex)
                {
