// Set up Redis client for caching
const redis = require('redis');
const redisClient = redis.createClient({ host: 'localhost', port: 6379 });

// Define a function to fetch geolocation data from multiple APIs
async function getGeolocationData(query) {
  // Check if the query is already cached
  const cachedResult = await redis.get(`geolocation:${query}`);
  if (cachedResult) {
    return JSON.parse(cachedResult);
  }

  // Fetch data from multiple APIs and aggregate results
  const apiResults = [];
  for (const apiUrl of ['api1', 'api2', 'api3']) {
    try {
      const response = await axios.get(`${apiUrl}?query=${query}`);
      if (response.status === 200) {
        apiResults.push(response.data);
      } else {
        // Handle API error
        console.error(`Error fetching data from ${apiUrl}: ${response.statusText}`);
      }
    } catch (error) {
      // Handle network error
      console.error(`Error fetching data: ${error.message}`);
    }
  }

  // Cache the result for future queries
  await redis.setex(`geolocation:${query}`, 3600, JSON.stringify(apiResults));

  return apiResults;
}

// Define a route to handle incoming requests
app.get('/api/geolocation/:query', async (req, res) => {
  const query = req.params.query;

  // Fetch geolocation data from multiple APIs and aggregate results
  try {
    const data = await getGeolocationData(query);
    res.json(data);
  } catch (error) {
    console.error(`Error handling request: ${error.message}`);
    res.status(500).send({ message: 'Internal Server Error' });
  }
});

// Start the Express app
app.listen(3000, () => {
  console.log('Server started on port 3000');
});
