import axios from 'axios';
import { cache } from 'redis';

interface AnalyticsApi {
  getMetrics(): Promise<any>;
}

class analyticsReportingSystem {
  private apis: AnalyticsApi[];
  private cachedData: Map<string, any>;
  private logger;
  private retryConfig = {
    attempts: 3,
    backoffFactor: 2,
    maxDelay: 30000
  };

  constructor(apis: AnalyticsApi[], logger) {
    this.apis = apis;
    this.cachedData = new Map();
    this.logger = logger;
  }

  async getMetrics(metrics: string[]): Promise<any[]> {
    const startTime = Date.now();

    // Filter APIs for requested metrics
    const filteredApis = this.apis.filter((api) => api.getMetrics().then((data) => data.metrics.some((metric) => metrics.includes(metric))));

    // Initialize cachedData with null values
    filteredApis.forEach(() => this.cachedData.set('null', null));

    try {
      // Perform API requests and cache results
      const responses = await Promise.all(
        filteredApis.map((api) =>
          axios.get(api.getMetrics()).then((response) => ({
            api,
            response,
          }))
        )
      );

      // Cache data for each API
      responses.forEach((response) => {
        this.cachedData.set(response.api.getMetrics().name, response.response.data);
      });

      const metricsData = await this.aggregateData(metrics);

      this.logger.info(`Report generation took ${Date.now() - startTime}ms`);

      return metricsData;
    } catch (error) {
      // Handle retry and logging
      if (this.retry(error)) {
        await new Promise((resolve) => setTimeout(resolve, this.retryDelay()));
        return this.getMetrics(metrics);
      }

      throw error;
    }
  }

  async aggregateData(metrics: string[]): Promise<any[]> {
    const aggregatedData = [];

    for (const metric of metrics) {
      let data = null;

      // Check cache before making API calls
      if (!this.cachedData.get(metric)) {
        try {
          data = await this.getDataFromApis(metric);
        } catch (error) {
          this.logger.error(`Failed to retrieve ${metric} from APIs: ${error}`);
        }
      } else {
        data = this.cachedData.get(metric);
      }

      aggregatedData.push(data);
    }

    return aggregatedData;
  }

  async getDataFromApis(metric: string): Promise<any> {
    const startTime = Date.now();

    // Get data from multiple APIs
    let response = null;

    try {
      response = await Promise.all(
        this.apis.map((api) =>
          axios.get(api.getMetrics(metric)).then((response) => response.data)
        )
      );

      // Aggregate and transform API responses
      const aggregatedResponse = response.reduce((acc, current) => acc.concat(current), []);

      this.logger.info(`Retrieved ${metric} data in ${Date.now() - startTime}ms`);

      return aggregatedResponse;
    } catch (error) {
      // Handle retry and logging
      if (this.retry(error)) {
        await new Promise((resolve) => setTimeout(resolve, this.retryDelay()));
        return this.getDataFromApis(metric);
      }

      throw error;
    }
  }

  retry(error: any): boolean {
    const { attempts, backoffFactor, maxDelay } = this.retryConfig;

    if (attempts <= 0) return false;

    const delay = Math.min(backoffFactor * this.retryDelay(), maxDelay);

    this.logger.error(`Error occurred. Retrying in ${delay}ms: ${error}`);

    setTimeout(() => {
      try {
        error.message === 'timeout' ? this.getDataFromApis() : this.getMetrics();
      } catch (err) {
        // Handle the second and subsequent retries
        if (this.retry(err)) {
          await new Promise((resolve) => setTimeout(resolve, delay));
          return this.retry(error);
        }

        throw err;
      }
    }, delay);

    return true;
  }

  retryDelay(): number {
    // Calculate the backoff time based on the current attempt
    const { attempts } = this.retryConfig;

    if (attempts < 3) return Math.pow(2, attempts - 1);
    else return this.retryConfig.maxDelay;
  }
}

export default analyticsReportingSystem;
