class NotificationSystem:
    def __init__(self):
        self.services = {}
        self.kafka_queue = None
        self.in_memory_fallback = None

    async def send_notification(self, message: str, service_name: str) -> bool:
        if not self.services.get(service_name):
            logging.error(f"Service {service_name} not available")
            return False

        try:
            response = await self.services[service_name].send_message(message)
            return response
        except Exception as e:
            # Retry logic with exponential backoff
            for i in range(5):
                if i > 0:
                    time.sleep(pow(2, i) + 1)
                try:
                    response = await self.services[service_name].send_message(message)
                    return response
                except Exception as e:
                    pass

            # Failover to backup service
            if self.in_memory_fallback:
                for service in self.in_memory_fallback:
                    try:
                        response = await service.send_message(message)
                        return response
                    except Exception as e:
                        pass

            logging.error(f"Failed to send notification {message} to {service_name}")
            return False

    async def init_services(self) -> None:
        # Initialize services with retry logic and failover mechanism
        self.services = {
            "web": WebService(),
            "mobile": MobileService(),
            "email": EmailService(),
            "sms": SMSservice()
        }

        self.kafka_queue = KafkaQueue()
        self.in_memory_fallback = [
            InMemoryService(),
            InMemoryService()
        ]

    async def handle_message(self, message: str) -> None:
        # Handle message and send notifications
        try:
            await asyncio.gather(
                *[
                    self.send_notification(message, service_name)
                    for service_name in self.services
                ]
            )
        except Exception as e:
            logging.error(f"Error handling message {message}: {e}")

    async def start(self) -> None:
        # Start services and message queue
        await self.init_services()
        await self.kafka_queue.start()

        while True:
