const axios = require('axios');
const { Buffer } = require('buffer');
const fs = require('fs').promises;
const { Pool } = require('pg');

function loadResourceBundle(config) {
  const { primarySource, secondarySource } = config;
  const maxRetries = parseInt(process.env.MAX_RETRIES || '5');
  const retryIntervalMs = parseInt(process.env.RETRY_INTERVAL_MS || '1000');

  async function loadFromPrimary() {
    try {
      const response = await axios.get(primarySource);
      return parseBundle(response.data);
    } catch (error) {
      if (error.response && error.response.status === 404) {
        // Resource not found, fallback to secondary source
        return loadFromSecondary();
      }
      throw error;
    }
  }

  async function loadFromSecondary() {
    try {
      const response = await axios.get(secondarySource);
      return parseBundle(response.data);
    } catch (error) {
      if (error.response && error.response.status === 404) {
        // Resource not found, log and throw
        console.error(`Failed to load resource from secondary source: ${error}`);
        throw error;
      }
      throw error;
    }
  }

  async function parseBundle(data) {
    const bundle = { count: 0, items: [] };

    for (const item of data) {
      const buffer = Buffer.allocUnsafe(1024);
      try {
        const itemBuffer = await loadItem(item, buffer);
        bundle.items.push({ ...item, data: itemBuffer });
        bundle.count++;
      } catch (error) {
        // Handle errors while loading items
        console.error(`Error loading item: ${error}`);
      }
    }

    return { count: bundle.count, items: bundle.items };
  }

  async function loadItem(item, buffer) {
    if (item.type === 'file') {
      const fileBuffer = await fs.readFile(item.path);
      return Buffer.from(fileBuffer);
    } else if (item.type === 'remote') {
      const response = await axios.get(item.url);
      return Buffer.from(response.data);
    }

    throw new Error(`Unsupported item type: ${item.type}`);
  }

  async function loadResourceBundleFromPool() {
    try {
      const pool = new Pool({
        user: process.env.POSTGRES_USER,
        host: process.env.POSTGRES_HOST,
        database: process.env.POSTGRES_DB,
        password: process.env.POSTGRES_PASSWORD,
        port: parseInt(process.env.POSTGRES_PORT || '5432')
      });

      const queryResult = await pool.query('SELECT * FROM resources');

      return parseBundle(queryResult.rows);
    } catch (error) {
      console.error(`Failed to load resource from database: ${error}`);
      throw error;
    }
  }

  async function handleLoadError(error) {
    if (maxRetries > 0 && error.response && error.response.status === 503) {
      // Retry after retry interval
      setTimeout(() => {
        loadResourceBundle(config).then((result) => console.log(result)).catch(handleLoadError);
      }, retryIntervalMs);
    } else {
      throw error;
    }
  }

  return new Promise((resolve, reject) => {
    try {
      const result = await loadFromPrimary();
      resolve(result);
    } catch (error) {
      handleLoadError(error);
    }
  });
}

module.exports = loadResourceBundle;
