        Map<String, String> params = new HashMap<>();
        for (String param : request.split("&")) {
            int equalsIndex = param.indexOf('=');
            if (equalsIndex > -1) {
                String key = param.substring(0, equalsIndex);
                String value = param.substring(equalsIndex + 1);
                params.put(key, value);
            }
        }

        // Handle the request
