```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManagerFactory;

import com.google.common.primitives.Ints;

public class SecureMicroservice {

    private static final int PORT = 8443;
    private static final String KEYSTORE_PATH = "path/to/keystore.jks";
    private static final String TRUSTSTORE_PATH = "path/to/truststore.jks";

    public static void main(String[] args) throws Exception {
        // Create SSL context
        SSLContext sslContext = SSLContext.getInstance("TLS");
        TrustManagerFactory trustManagerFactory = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        trustManagerFactory.init((java.security.KeyStore)null);
        sslContext.init(null, trustManagerFactory.getTrustManagers(), null);

        // Create server socket channel
        ServerSocketChannel ssc = ServerSocketChannel.open();
        ssc.configureBlocking(false);
        ssc.socket().bind(new InetSocketAddress(PORT));
        ssc.setOption("tcpNoDelay", true);

        // Create selector
        Selector selector = Selector.open();

        // Register server socket channel with selector
        ssc.register(selector, SelectionKey.OP_ACCEPT);

        // Start accepting connections
        while (true) {
            try {
                // Accept connection
                SelectionKey key = selector.select();
                if (key == null || !key.isValid()) {
                    continue;
                }
                ssc.accept();

                // Handle new connection
                ExecutorService executor = Executors.newCachedThreadPool();
                Runnable r = () -> handleConnection(sslContext, selector);
                executor.submit(r);

            } catch (IOException e) {
                // Log error and exit
                System.out.println("Error accepting connection: " + e.getMessage());
                break;
            }
        }

        // Close resources
        executor.shutdownNow();
        selector.close();
        ssc.close();
    }

    private static void handleConnection(SSLContext sslContext, Selector selector) {
        try {
            // Establish SSL connection
            SSLSocket socket = (SSLSocket) sslContext.getSocketFactory().createSocket(selector.socket().getLocalAddress(), PORT);
            socket.setSoTimeout(0);

            // Perform mutual TLS verification
            SSLSession session = socket.startHandshake();
            if (!session.isValid()) {
                // Handle authentication failure
                System.out.println("Authentication failed");
                return;
            }

            // Start handling request-response cycle
            RequestHandler handler = new RequestHandler(socket);
            handler.handleRequest();

        } catch (IOException e) {
            // Log error and exit
            System.out.println("Error handling connection: " + e.getMessage());
        }
    }
}
```

Please note that this is a basic implementation, and you should consider adding more features such as connection pooling, load balancing, circuit breakers, and retries for transient failures.']

