#[derive(Debug)]
pub enum HttpClientError {
    Io(std::io::Error),
    CertValidation(String),
}

impl From<std::io::Error> for HttpClientError {
    fn from(err: std::io::Error) -> Self {
        HttpClientError::Io(err)
    }
}

impl From<String> for HttpClientError {
    fn from(err: String) -> Self {
        HttpClientError::CertValidation(err)
    }
}

#[derive(Debug)]
pub struct HttpClient {
    client_id: String,
    client_secret: String,
    base_url: Url,
    rate_limiter: Arc<Mutex<RateLimiter>>,
    timeout: u64,
}

impl HttpClient {
    pub async fn new(client_id: String, client_secret: String, base_url: Url) -> Self {
        let rate_limiter = Arc::new(Mutex::new(RateLimiter::default()));
        let timeout = 3000;
        HttpClient { client_id, client_secret, base_url, rate_limiter, timeout }
    }

    pub async fn get(&self, path: &str) -> Result<String, HttpClientError> {
        let url = self.base_url.join(path)?;
        let mut stream = TcpStream::connect(url).await?;
        let request = format!("GET {} HTTP/1.1\r\nHost: {}\r\n\r\n", path, url.host_str().unwrap());
        let response = stream.write_all(request.as_bytes()).await?;
        Ok(response.to_string())
    }
}

// rate_limiter.rs
use std::sync::{Arc, Mutex};
use time::Duration;

#[derive(Debug)]
pub struct RateLimiter {
    max_requests: u32,
    interval: Duration,
}

impl RateLimiter {
    pub fn new(max_requests: u32, interval: Duration) -> Self {
        RateLimiter { max_requests, interval }
    }

    pub async fn acquire(&self) -> Result<(), ()> {
        let mut count = 0;
        loop {
            if self.max_requests <= count {
                thread::sleep(self.interval);
                count = 0;
            } else {
                count += 1;
                break;
            }
        }
        Ok(())
    }
}

