mod dynamic_resource_loader {
    use std::collections::{HashMap, HashSet};
    use std::fs;
    use std::path::PathBuf;
    use std::sync::{Arc, Mutex};
    use std::thread;

    mod resource_bundle {
        pub enum BundleType { Xml, Json }
        pub struct ResourceBundle {
            bundle_type: BundleType,
            resources: HashMap<String, String>
        }

        impl ResourceBundle {
            fn new(bundle_type: BundleType) -> Self {
                ResourceBundle {
                    bundle_type,
                    resources: HashMap::new()
                }
            }
        }
    }

    pub struct DynamicResourceLoader {
        bundles: Arc<Mutex<HashMap<String, resource_bundle::ResourceBundle>>>,
        queue: Arc<Mutex<Vec<(String, String)>>>,
        cache: Arc<Mutex<HashSet<String>>>
    }

    impl DynamicResourceLoader {
        fn new() -> Self {
            DynamicResourceLoader {
                bundles: Arc::new(Mutex::new(HashMap::new())),
                queue: Arc::new(Mutex::new(Vec::new())),
                cache: Arc::new(Mutex::new(HashSet::new()))
            }
        }

        fn load_bundle(&self, path: &PathBuf) -> Result<(), String> {
            let bundle = match fs::read_to_string(path) {
                Ok(contents) => resource_bundle::ResourceBundle::new(resource_bundle::BundleType::Xml),
                Err(_) => return Err("Failed to read bundle".to_string())
            };

            *self.bundles.lock().unwrap() = HashMap::from([(path.display().to_string(), bundle)]);
            self.cache.lock().unwrap().insert(path.display().to_string());
            Ok(())
        }

        fn get_resource(&self, path: &PathBuf) -> Result<String, String> {
            let resource_bundle = match self.bundles.lock().unwrap().get(path.display().to_string()) {
                Some(bundle) => bundle,
                None => return Err("Resource not found".to_string())
            };

            Ok(resource_bundle.resources.get(&path.file_name().unwrap().to_string_lossy().into()).cloned().unwrap_or_default())
        }

        fn queue_request(&self, path: &PathBuf, callback: impl Fn(String) + 'static) {
            self.queue.lock().unwrap().push((path.display().to_string(), callback));
        }

        fn handle_queue(&self) {
            let queue = self.queue.clone();
            thread::spawn(move || {
                while let Some((path, callback)) = queue.lock().unwrap().pop() {
                    match self.get_resource(path.as_path()) {
                        Ok(resource) => callback(resource),
                        Err(err) => println!("Error: {}", err)
                    }
                }
            });
        }

        fn start(&self) {
            self.handle_queue();
        }
    }

    #[cfg(test)]
    mod tests {
        use super::DynamicResourceLoader;
        use tempfile::{tempdir, TempDir};

        #[test]
        fn test_load_bundle() {
            let temp_dir = TempDir::new().unwrap();
            let bundle_path = temp_dir.path().join("bundle.xml");
            let mut file = std::fs::File::create(bundle_path).unwrap();
            file.write_all(b"<resources>...</resources>").unwrap();

            let loader = DynamicResourceLoader::new();
            loader.load_bundle(&bundle_path).unwrap();
        }

        #[test]
        fn test_get_resource() {
            let temp_dir = TempDir::new().unwrap();
            let bundle_path = temp_dir.path().join("bundle.xml");
            let mut file = std::fs::File::create(bundle_path).unwrap();
