#include <stdio.h>
#include <stdlib.h>

int parseTIFFFile(char *filename) {
  FILE *file = fopen(filename, "rb");
  if (!file) {
    return -1; // Error opening file
  }

  int bitsPerSample;
  int samplesPerPixel;

  fread(&bitsPerSample, sizeof(int), 1, file);
  fread(&samplesPerPixel, sizeof(int), 1, file);

  // Handle supported bits per sample values
  switch (bitsPerSample) {
    case 1:
    case 2:
    case 4:
    case 8:
    case 16:
      break;
    default:
      return -2; // Error: unsupported bits per sample value
  }

  int extraSamples = fread(NULL, sizeof(int), 1, file);
  if (extraSamples > 0) {
    printf("Extra samples: %d\n", extraSamples);
  } else {
    printf("No extra samples found\n");
  }

  fclose(file);
  return 0; // Success
}
