#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <chrono>
#include <boost/property_tree/ptree.hpp>

class NetworkEventManager {
public:
    NetworkEventManager(size_t capacity, size_t cacheSize)
        : RNTICache(cacheSize), networkEvents(capacity) {}

    void addEvent(const std::string& rnti, const std::string& timestamp, const std::vector<std::string>& errorCodes) {
        // Handle duplicate RNTI entries
        if (RNTICache.count(rnti)) {
            auto existingEntry = networkEvents[RNTICache.at(rnti)];
            if (existingEntry.timestamp < timestamp || (timestamp == existingEntry.timestamp && existingEntry.errorCodes.size() <= errorCodes.size())) {
                // Update existing entry
                existingEntry.timestamp = timestamp;
                existingEntry.errorCodes = errorCodes;
            } else {
                // Discard duplicate entry
                return;
            }
        }

        networkEvents.insert({rnti, {timestamp, errorCodes}});
        RNTICache[rnti] = rnti; // Update cache

        if (networkEvents.size() > capacity) {
            // Handle overflow by discarding oldest entries
            std::vector<std::pair<std::string, Event>> toRemove;
            for (const auto& event : networkEvents) {
                if (event.second.timestamp < timestamp - 60 * 1000) { // 1 minute old
                    toRemove.push_back(event);
                    break; // Stop at the first match
                }
            }

            for (const auto& entry : toRemove) {
                networkEvents.erase(entry.first);
                RNTICache.erase(entry.first);
            }
        }
    }

    void serializeToBinary(std::ostream& os) const {
        boost::property_tree::ptree root;
        for (const auto& event : networkEvents) {
            boost::property_tree::ptree entry;
            entry.put("rnti", event.first);
            entry.put("timestamp", event.second.timestamp);
            entry.put("errorCodes", boost::algorithm::join(event.second.errorCodes, ","));
            root.add_child("events", entry);
        }
        boost::property_tree::write_xml(os, root, std::locale(), "1.0");
    }

private:
    struct Event {
        std::string timestamp;
        std::vector<std::string> errorCodes;
    };

    std::unordered_map<std::string, size_t> RNTICache; // Distributed cache service
    std::map<std::string, Event> networkEvents; // Real-time event list

    mutable std::mutex mutex; // Concurrency safety
};

