import java.io.*;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipArchive;
import org.apache.commons.compress.utils.IOUtils;

public class FileCleaner {
    public static void main(String[] args) throws Exception {
        // Initialize configuration from external system
        Config config = getConfiguration();

        // Create thread pool for concurrent processing
        ExecutorService executor = Executors.newFixedThreadPool(5);

        // Process directories and files according to configuration
        config.getDirectories().forEach(dir -> compressDirectory(executor, dir));
        config.getFiles().forEach(file -> deleteFile(executor, file));
    }

    private static Config getConfiguration() {
        // Implement API connection and data retrieval from external system
        return new Config();
    }

    public static void compressDirectory(ExecutorService executor, String directory) throws Exception {
        for (int i = 0; i < 3; i++) { // Retry up to three times
            try {
                File dirFile = new File(directory);
                if (!dirFile.exists() || !dirFile.canRead()) {
                    System.out.println("Directory not found or unreadable: " + directory);
                    return;
                }

                ZipArchive zip = new ZipArchive();
                zip.putArchiveEntry(new FileEntry(directory));
                IOUtils.write(zip.createArchiveInputStream(), new FileOutputStream("output.zip"));
                break; // Successful compression
            } catch (IOException e) {
                System.out.println("Error compressing directory: " + e.getMessage());
                if (i < 2) { // Retry up to two times
                    try {
                        Thread.sleep(1000 * (1 << i)); // Exponential backoff
                    } catch (InterruptedException ex) {
                        Thread.currentThread().interrupt();
                    }
                } else {
                    System.out.println("Failed to compress directory: " + e.getMessage());
                }
            }
        }
    }

    public static void deleteFile(ExecutorService executor, String file) throws Exception {
        for (int i = 0; i < 3; i++) { // Retry up to three times
            try {
                File fileToDelete = new File(file);
                if (!fileToDelete.exists()) {
                    System.out.println("File not found: " + file);
                    return;
                }

                if (fileToDelete.canRead() && isFileOlderThan24Hours(fileToDelete)) { // Check file age and readability
                    executor.submit(() -> {
                        try {
                            fileToDelete.delete();
                            System.out.println("File deleted: " + file);
                        } catch (SecurityException e) {
                            System.out.println("File in use by another process: " + file);
                        }
                    });
                } else {
                    System.out.println("File not eligible for deletion: " + file);
                }
                break; // Successful deletion
            } catch (IOException e) {
                System.out.println("Error deleting file: " + e.getMessage());
                if (i < 2) { // Retry up to two times
                    try {
                        Thread.sleep(1000 * (1 << i)); // Exponential backoff
                    } catch (InterruptedException ex) {
                        Thread.currentThread().interrupt();
                    }
                } else {
                    System.out.println("Failed to delete file: " + e.getMessage());
                }
            }
        }
    }

    private static boolean isFileOlderThan24Hours(File file) throws Exception {
        Date modifiedDate = new Date(file.lastModified());
        return (new Date()).getTime() - modifiedDate.getTime() > 24 * 60 * 60 * 1000; // Check if file is older than 24 hours
    }
}

class Config {
