class PaymentGateway {
public:
    virtual ~PaymentGateway() {}
    virtual std::string processTransaction(const std::string& transaction) = 0;
};

// Stripe payment gateway class
class StripePaymentGateway : public PaymentGateway {
public:
    std::string processTransaction(const std::string& transaction) override {
        // process Stripe transaction
        return "Stripe transaction processed";
    }
};

// PayPal payment gateway class
class PayPalPaymentGateway : public PaymentGateway {
public:
    std::string processTransaction(const std::string& transaction) override {
        // process PayPal transaction
        return "PayPal transaction processed";
    }
};

// library for handling payment transactions
class PaymentLibrary {
public:
    PaymentLibrary() {}

    void addPaymentGateway(PaymentGateway* gateway) {
        paymentGateways_.push_back(gateway);
    }

    std::string processTransaction(const std::string& transaction) {
        // iterate over payment gateways and process transaction
        for (auto& gateway : paymentGateways_) {
            if (!gateway->processTransaction(transaction).empty()) {
                return "Transaction processed successfully";
            }
        }
        return "No payment gateway available to process transaction";
    }

private:
    std::vector<PaymentGateway*> paymentGateways_;
};

int main() {
    PaymentLibrary library;

    // add Stripe and PayPal payment gateways
    StripePaymentGateway* stripeGateway = new StripePaymentGateway();
    PayPalPaymentGateway* paypalGateway = new PayPalPaymentGateway();

    library.addPaymentGateway(stripeGateway);
    library.addPaymentGateway(paypalGateway);

    // process transaction using Stripe gateway
    std::string transaction = "transaction request";
    std::cout << library.processTransaction(transaction) << std::endl;

    return 0;
}

