using System.Security.Cryptography;
using System.IO;
using System.Text;
using Newtonsoft.Json;
using System.Linq;

public class SecureFileHandler
{
    public static void DecryptAndDeserialize(string filePath, string encryptionAlgorithm)
    {
        byte[] encryptedBytes = File.ReadAllBytes(filePath);
        AesGcm aesGcm;
        RSAOaep rsaOaep;
        ChaCha20Poly1305 chacha20Poly1305;

        switch (encryptionAlgorithm)
        {
            case "AES-GCM":
                aesGcm = new AesGcm();
                break;
            case "RSA-OAEP":
                rsaOaep = new RSAOaep();
                break;
            case "ChaCha20-Poly1305":
                chacha20Poly1305 = new ChaCha20Poly1305();
                break;
            default:
                throw new ArgumentException("Unsupported encryption algorithm");
        }

        byte[] decryptedBytes = aesGcm.Decrypt(encryptedBytes);
        CustomObject customObject = JsonConvert.DeserializeObject<CustomObject>(Encoding.UTF8.GetString(decryptedBytes));
    }
}

public class AesGcm
{
    public byte[] Decrypt(byte[] encryptedBytes)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = Convert.FromBase64String("your key");
            aes.IV = Convert.FromBase64String("your iv");
            using (MemoryStream ms = new MemoryStream())
            {
                using (CryptoStream cs = new CryptoStream(ms, aes.CreateDecryptor()))
                {
                    cs.Write(encryptedBytes, 0, encryptedBytes.Length);
                    return ms.ToArray();
                }
            }
        }
    }
}

public class RSAOaep
{
    public byte[] Decrypt(byte[] encryptedBytes)
    {
        using (RSAPKCS1SignatureFormatter rsa = new RSAPKCS1SignatureFormatter())
        {
            rsa.ImportParameters("your private key");
            return rsa.Decrypt(encryptedBytes);
        }
    }
}

public class ChaCha20Poly1305
{
    public byte[] Decrypt(byte[] encryptedBytes)
    {
        using (Aes a = Aes.Create())
        {
            a.Key = Convert.FromBase64String("your key");
            a.IV = Convert.FromBase64String("your iv");
            using (MemoryStream ms = new MemoryStream())
            {
                using (CryptoStream cs = new CryptoStream(ms, a.CreateDecryptor()))
                {
                    cs.Write(encryptedBytes, 0, encryptedBytes.Length);
                    return ms.ToArray();
                }
            }
        }
    }
}

public class CustomObject
{
    public string Name { get; set; }
    public int Age { get; set; }
}
