            synchronized (this) {
                // Process large-scale data stream concurrently
                ExecutorService executor = Executors.newCachedThreadPool();
                List<Future<?>> futures = new ArrayList<>();
                for (int i = 0; i < 10; i++) {
                    Future<?> future = executor.submit(() -> processLargeScaleDataStream(obj, metadata));
                    futures.add(future);
                }
                for (Future<?> future : futures) {
                    future.get();
                }
            }
        } catch (InterruptedException e) {
            log.error("Error processing large-scale data stream: {}", e.getMessage());
        }
    }

