    void start() {
        thread_ = new std::thread([this]() {
            while (true) {
                int data;
                if ((data = queue_->dequeue()) != -1) {
                    processor_->processBatch(data);
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        });
    }

    void stop() {
        thread_->join();
        delete thread_;
    }

private:
    BatchProcessor* processor_;
    DataQueue* queue_;
