// Function to create a new dynamic list
nfa_pi_crc_indication_pdu_list* nfa_pi_crc_indication_pdu_list_create(int initial_capacity) {
    nfa_pi_crc_indication_pdu_list *list = (nfa_pi_crc_indication_pdu_list*)malloc(sizeof(nfa_pi_crc_indication_pdu_list));
    if (!list) return NULL; // failed allocation

    list->structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->structures) {
        free(list);
        return NULL; // failed allocation
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Function to add a new structure to the dynamic list
int nfa_pi_crc_indication_pdu_list_add(nfa_pi_crc_indication_pdu_list *list, NFAPI_CRC_INDICATION_PDU_T *structure) {
    if (!list || !structure) return -1; // invalid input

    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        int new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_structures = (NFAPI_CRC_INDATION_PDU_T*)realloc(list->structures, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_structures) {
            pthread_mutex_unlock(&list->lock);
            return -1; // failed allocation
        }
        list->structures = new_structures;
        list->capacity = new_capacity;
    }

    list->structures[list->size] = *structure;
    list->size++;

    pthread_mutex_unlock(&list->lock);

    return 0; // success
}

