// Cipher initialization framework
void* cipher_init(const char* password, const char* salt, int iterations) {
    // Initialize OpenSSL library
    OpenSSL_add_all_algorithms();
    ERR_free_strings();

    // Compute PBKDF2-derived key and IV
    unsigned char* derived_key = NULL;
    unsigned char* iv = NULL;
    if (!PKCS5_PBKDF2(password, strlen(password), salt, strlen(salt), iterations, 32, &derived_key)) {
        return NULL; // Error computing key or IV
    }

    // Initialize AES-256-CBC cipher context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, derived_key, iv)) {
        return NULL; // Error initializing cipher context
    }

    // Cache the computed key and IV for reuse
    CacheEntry* entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    pthread_mutex_init(&entry->lock, PTHREAD_MUTEX_INITIALIZER);
    entry->data = malloc(64); // Store 32 bytes of derived_key and 32 bytes of iv
    memcpy(entry->data, derived_key, 32);
    memcpy((char*)entry->data + 32, iv, 32);
    pthread_mutex_unlock(&entry->lock);

