class FrameMetadata {
public:
    int timestamp;
    size_t packetSize;
    std::string srcIP, destIP;
    std::string protocolType;
    bool checksumStatus;

    FrameMetadata(int ts, size_t ps, const std::string& sIP, const std::string& dIP, const std::string& pt, bool cs) 
        : timestamp(ts), packetSize(ps), srcIP(sIP), destIP(dIP), protocolType(pt), checksumStatus(cs) {}
};

class FrameMetadataCollection {
private:
    std::deque<FrameMetadata> frames;
    size_t maxFrames = 1000; // configurable parameter
    std::mutex mtx;
    std::condition_variable cv;

public:
    void addFrame(FrameMetadata frame) {
        std::unique_lock<std::mutex> lock(mtx);
        while (frames.size() >= maxFrames) {
            cv.wait(lock);
        }
        frames.push_back(frame);
        cv.notify_one();
    }

    void removeFrame(size_t index) {
        std::unique_lock<std::mutex> lock(mtx);
        if (index < frames.size()) {
            frames.erase(frames.begin() + index);
        }
    }

    size_t size() {
        std::lock_guard<std::mutex> lock(mtx);
        return frames.size();
    }
};

