async fn measure_compilation_time(src_file: &str) -> Result<(), Box<dyn std::error::Error>> {
    let start = std::time::Instant::now();
    let output = Command::new("rustc")
        .arg("--edition=2018")
        .arg("-o")
        .arg("main.rs")
        .arg(src_file)
        .output()
        .await?
        .stdout;
    let end = std::time::Instant::now();

    info!("Compilation time: {} ms", (end - start).as_millis());

    // Validate the compilation result
    if !output.is_empty() {
        error!("Compilation failed");
        ExitCode::from(1)
    } else {
        Ok(())
