// Import required libraries and frameworks
const express = require('express');
const mongoose = require('mongoose');
const bodyparser = require('body-parser');
const compression = require('compression');
const helmet = require('helmet');
const rateLimit = require('rate-limit');

// Create the Express app
const app = express();

// Configure middlewares
app.use(bodyparser.json());
app.use(compression());
app.use(helmet());
app.use(rateLimit({
  duration: 1,
  max: 1000, // Allow up to 1000 requests in a second
  handler: (req, res) => {
    return res.status(429).send('Rate limit exceeded');
  }
}));

// Connect to the database using Mongoose
mongoose.connect('mongodb://localhost/product_catalog', { useNewUrlParser: true, useUnifiedTopology: true });

// Define the Product schema
const productSchema = new mongoose.Schema({
  _id: String,
  name: String,
  description: String,
  price: Number,
  categories: [{ type: mongoose.Schema.Types.ObjectId, ref: 'Category' }]
});

// Create a model for Products using the defined schema
const Product = mongoose.model('Product', productSchema);

// Define the API routes

app.get('/products', async (req, res) => {
  const products = await Product.find();
  return res.json(products);
});

app.post('/products', async (req, res) => {
  const { name, description, price } = req.body;
  const product = new Product({ name, description, price });
  try {
    await product.save();
    return res.status(201).json(product);
  } catch (error) {
    return res.status(400).send(error.message);
  }
});

