class LoadBalancer:
    def __init__(self):
        self.service_health = []
        self.response_times = []
        self.user_geolocation = []

    def get_load_balancing_strategy(self, real_time_metrics):
        service_health_score = mean_squared_error(real_time_metrics['service_health'], self.service_health)
        response_time_score = mean_squared_error(real_time_metrics['response_times'], self.response_times)
        user_geolocation_score = mean_squared_error(real_time_metrics['user_geolocation'], self.user_geolocation)

