package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"strings"

	"github.com/golang/protobuf/jsonpb"
	"github.com/gorilla/mux"
	"github.com/patrickmn/go-cache"
)

var (
	cacheDuration  = 60 * time.Second
	minCacheTTL    = 1 * time.Second
	maxCacheTTL    = 30 * time.Second
	defaultTTL     = 10 * time.Second
	redisPool      = &sql.DB{}
	httpClient    *http.Client
)

func main() {
	// Initialize Redis connection pool
	redisPool, _ = sql.Open("postgres", "host=localhost port=5432 user=username password=password dbname=proxy")

	// Create HTTP client with timeouts and retries
	client := &http.Client{
		Timeout: 5 * time.Second,
	}

	httpClient = client

	// Initialize cache store
	cache, err := cache.New(cacheDuration, cacheCleaner)
	if err != nil {
		log.Fatal(err)
	}

	r := mux.NewRouter()

	// Handle HTTP/1.1 and HTTP/2 requests
	r.HandleFunc("/path/{region}/{service}", proxyHandler).Methods("GET", "POST")

	http.ListenAndServe(":8080", r)

}

func cacheCleaner(key string, value interface{}) {
	log.Println("Cache cleaner:", key, value)
}

func proxyHandler(w http.ResponseWriter, r *http.Request) {
	// Get region and service from path
	path := strings.SplitN(r.URL.Path, "/", 4)[3]
	region, _ := strconv.Atoi(path[:1])
	serviceName := path[1:]

	// Check cache first
	cacheKey := fmt.Sprintf("cache:%d:%s", region, serviceName)
	if cachedResponse, exists := cache.Get(cacheKey); exists {
		http.ServeContent(w, r, cachedResponse.(string), cachedResponse.(*time.Time).UnixNano())
		return
	}

	// Handle request and store response in cache
	resp, err := handleRequest(region, serviceName, w, r)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	cache.Set(cacheKey, resp.StatusLine, defaultTTL)

	w.Write(resp.Body)
}

func handleRequest(region int, serviceName string, w http.ResponseWriter, r *http.Request) (*http.Response, error) {
	// Handle request and get response from upstream service
	resp, err := callUpstreamService(region, serviceName, r)
	if err != nil {
		return &http.Response{}, err
	}

	// Adapt response to HTTP/1.1 or HTTP/2 protocol
	var adapter http.RoundTripper
	switch resp.ProtoMajor {
	case 0:
		adapter = &httputil.NewClientStream{}
	default:
		adapter = &httputil.Dumper{}
	}
	resp.Write(w)

	return resp, nil
}

func callUpstreamService(region int, serviceName string, r *http.Request) (*http.Response, error) {
	// Make request to upstream service and get response
	resp, err := httpClient.Do(r)
	if err != nil {
		return &http.Response{}, err
	}
	return resp, nil
}
