['Here is the code block for implementing a Java-based connection pooling service:

```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class ConnectionPool {
    private static final int DEFAULT_MAX_CONNECTIONS = 10;
    private static final int DEFAULT_MIN_CONNECTIONS = 5;
    private static final long DEFAULT_TIMEOUT_MS = 30000L; // 30 seconds

    private final Lock lock = new ReentrantLock();
    private List<Connection> connections;
    private int maxConnections;
    private int minConnections;
    private long timeoutMs;

    public ConnectionPool(int maxConnections, int minConnections, long timeoutMs) {
        this.maxConnections = maxConnections;
        this.minConnections = minConnections;
        this.timeoutMs = timeoutMs;
        this.connections = new ArrayList<>();
    }

    public void init() throws SQLException {
        lock.lock();
        try {
            for (int i = 0; i < minConnections; i++) {
                connections.add(createConnection());
            }
        } finally {
            lock.unlock();
        }
    }

    public Connection getConnection() throws SQLException, InterruptedException {
        lock.lock();
        try {
            while (true) {
                Connection connection = getAvailableConnection();
                if (connection != null) {
                    return connection;
                }
                // Wait for a connection to become available or a new one to be created
                Thread.sleep(timeoutMs);
            }
        } finally {
            lock.unlock();
        }
    }

    public void closeConnection(Connection connection) throws SQLException {
        lock.lock();
        try {
            connections.remove(connection);
        } finally {
            lock.unlock();
        }
    }

    private Connection createConnection() throws SQLException {
        // Create a new database connection
        return DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "password");
    }

    private Connection getAvailableConnection() {
        for (Connection connection : connections) {
            if (!connection.isClosed()) {
                return connection;
            }
        }
        return null;
    }

    public static void main(String[] args) throws SQLException, InterruptedException {
        int maxConnections = Integer.parseInt(System.getProperty("maxConnections", String.valueOf(DEFAULT_MAX_CONNECTIONS)));
        int minConnections = Integer.parseInt(System.getProperty("minConnections", String.valueOf(DEFAULT_MIN_CONNECTIONS)));
        long timeoutMs = Long.parseLong(System.getProperty("timeoutMs", String.valueOf(DEFAULT_TIMEOUT_MS)));

        ConnectionPool connectionPool = new ConnectionPool(maxConnections, minConnections, timeoutMs);
        connectionPool.init();

        while (true) {
            Connection connection = connectionPool.getConnection();
            try {
                // Use the connection
            } finally {
                connectionPool.closeConnection(connection);
            }
        }
    }
}
```']

