package com.example.distributedauth;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import javax.cache.Cache;
import javax.cache.CacheManager;
import javax.cache.Caching;
import javax.cache.spi.CachingProvider;

import org.apache.commons.collections4.map.HereditableSortedMap;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.scheduling.concurrent.ConcurrentTaskExecutor;

@SpringBootApplication
public class DistributedAuthApplication {

    public static void main(String[] args) {
        SpringApplication.run(DistributedAuthApplication.class, args);
    }

    @Bean
    public CachingProvider cachingProvider() {
        return Caching.getCachingProvider();
    }

    @Bean
    public CacheManager cacheManager(CachingProvider provider) {
        return provider.getCacheManager();
    }

    @Bean
    public ExecutorService executorService(int poolSize) {
        return Executors.newFixedThreadPool(poolSize);
    }

    @Bean
    public ConcurrentTaskExecutor concurrentTaskExecutor(ExecutorService executorService) {
        return new ConcurrentTaskExecutor(executorService);
    }

    @Bean
    public Callable<Integer> myCallable() {
        return () -> 42;
    }

    @Bean
    public Future<Integer> myFuture(Callable<Integer> callable) throws Exception {
        return Executors.newCachedThreadPool().submit(callable);
    }

    @Bean
    public List<Cache> caches(List<CacheManager> cacheManagers) {
        List<Cache> caches = new ArrayList<>();
        for (CacheManager cacheManager : cacheManagers) {
            Cache cache = cacheManager.getCache("mycache");
            if (cache != null) {
                caches.add(cache);
            }
        }
        return caches;
    }

    @Bean
    public HereditableSortedMap<String, String> hereditaryMap(List<Cache> caches) {
        HereditableSortedMap<String, String> map = new HereditableSortedMap<>();
        for (Cache cache : caches) {
            for (Object o : cache.keySet()) {
                map.put((String) o, "value");
            }
        }
        return map;
    }

}
