    // Adjust logging frequency based on current load
    void adjustLoggingFrequency(float load) {
        std::lock_guard<std::mutex> lock(mutex);
        if (load > 0.5f) {
            logFile.setf(std::ios_base::ate | std::ios_base::app); 
        } else if (load < 0.1f) {
