    void addFrameMetadata(FrameMetadata* frame) {
        std::lock_guard<std::mutex> lock(mutex);
        frameList.push_back(frame);
        if (frameList.size() > maxFrames) {
            removeOldestFrame();
        }
    }

    // Remove the oldest frame from the list
    void removeOldestFrame() {
        if (!frameList.empty()) {
            std::lock_guard<std::mutex> lock(mutex);
            FrameMetadata* oldestFrame = frameList.front();
            frameList.pop_front();
            delete oldestFrame;
