class JobConfig {
public:
    int batchSize;
    bool persistenceEnabled;
};

class JobQueue {
private:
    std::queue<std::shared_ptr<void>> queue;
    mutable std::mutex mtx;
    std::condition_variable cv;

public:
    void enqueue(const std::shared_ptr<void>& item) {
        std::unique_lock<std::mutex> lock(mtx);
        queue.push(item);
        lock.unlock();
        cv.notify_one();
    }

    bool dequeue(std::shared_ptr<void>& item) {
        std::unique_lock<std::mutex> lock(mtx);
        if (queue.empty()) {
            return false;
        }
        item = queue.front();
        queue.pop();
        return true;
    }

    size_t size() const {
        std::lock_guard<stdstd::mutex> lock(mtx);
        return queue.size();
    }
};

