        sleep(1 / RATE_LIMIT); // Pause to simulate request rate limit

        // Update field value from the simulated API response
        fields[i].value = (char*)malloc((strlen(updated_input) + 1) * sizeof(char));
        strcpy(fields[i].value, updated_input);

        free(updated_input);
