        if (fields[i].value == NULL) { // Field not updated
            continue;
        }
        printf("Field %d: %s\n", fields[i].id, fields[i].value);

        free(fields[i].value);
    }

    for (int i = 0; i < MAX_FIELDS; i++) {
        if (fields[i].value != NULL) { // Field not updated
            free(fields[i].value);
        }
    }

    free(fields);
}

