class DynamicIndexManager {
public:
    DynamicIndexManager(size_t max_docs) : max_docs_(max_docs), doc_map_(), cache_(std::chrono::seconds(60)) {}

    void addDocument(const INDEX_ITEM_T& doc) {
        // Optimized indexing logic
        if (doc_map_.size() >= max_docs_) return; // Rejection policy: Limit the number of documents

        // Versioning and backward compatibility for dynamic schema changes
        if (!isValidSchema(doc)) {
            updateSchemaVersion(); // Update schema version to handle new schema
        }

        doc_map_[doc.id] = doc;
    }

    void query(const std::string& query_term) {
        auto start_time = std::chrono::high_resolution_clock::now();

        for (const auto& [id, doc] : doc_map_) {
            if (containsQueryTerm(doc, query_term)) {
                // Optimized search logic
                yield_result(id);
            }
        }

        auto end_time = std::chrono::high_resolution_clock::now();
        duration_ = end_time - start_time;
    }

    void flushCache() {
        cache_.clear(); // Evict stale entries from the cache
    }

private:
