    char* newFilename = (char*)malloc((MAX_FILENAME_LENGTH + strlen(extension) + sizeof(timestampStr) + sizeof(int)) * sizeof(char));
    sprintf(newFilename, "%s.%02d-%s", filename, randomNumber, timestampStr);

    // Rename the file using the new filename
    if (rename(filename, newFilename) != 0) {
        printf("Error renaming file: %s\n", strerror(errno));
    }

    // Document the renaming operation with an external logging service
    logEvent(NEW_FILENAME_CREATED, newFilename);

