public:
    MemoryPool(size_t capacity) : capacity(capacity), freeList(), used(0) {}

    void* allocate(size_t size) {
        if (used + size > capacity)
            return nullptr;

        void* ptr = freeList.front();
        freeList.pop();

        used += size;
        return ptr;
    }

    void deallocate(void* ptr, size_t size) {
        used -= size;

        // Readd to the free list
