#include <iostream>
#include <list>
#include <map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <shared_mutex>

class DependencyNode {
public:
    int taskId;
    bool isCompleted;

    DependencyNode(int taskId, bool isCompleted) : taskId(taskId), isCompleted(isCompleted) {}
};

class TaskState {
public:
    int taskID;
    int priorityLevel;
    int estimatedExecutionTime;
    std::list<DependencyNode*> dependencies;

    TaskState(int taskID, int priorityLevel, int estimatedExecutionTime)
        : taskID(taskID), priorityLevel(priorityLevel), estimatedExecutionTime(estimatedExecutionTime) {}
};

class ResourceScheduler {
public:
    std::map<int, TaskState> tasks;
    std::mutex mtx;
    std::condition_variable cv;

    void addTask(int taskID, int priorityLevel, int estimatedExecutionTime) {
        std::unique_lock<std::mutex> lock(mtx);
        tasks[taskID] = TaskState(taskID, priorityLevel, estimatedExecutionTime);
        lock.unlock();
        cv.notify_one();
    }

    void updateTaskStatus(int taskID, bool isCompleted) {
        std::unique_lock<std::mutex> lock(mtx);
        if (tasks.find(taskID) != tasks.end()) {
            tasks[taskID].dependencies.erase(std::remove_if(tasks[taskID].dependencies.begin(),
                tasks[taskID].dependencies.end(), 
                [isCompleted](DependencyNode* node) { return !node->isCompleted; }), 
                tasks[taskID].dependencies.end());
        }
    }

    void scheduleTasks() {
        std::vector<TaskState*> taskList;
        {
            std::unique_lock<stdstd::mutex> lock(mtx);
            for (auto& task : tasks) {
                taskList.push_back(&task.second);
            }
        }

        // Sort task list based on priority level
        std::sort(taskList.begin(), taskList.end(), 
            [](TaskState* a, TaskState* b) { return a->priorityLevel > b->priorityLevel; });

        for (auto& task : taskList) {
            // Start execution of the highest-priority task
            startTaskExecution(*task);
        }
    }

private:
    void startTaskExecution(TaskState& task) {
        // Implement logic to execute the task
    }
};
