// Module to manage log entries
class LogEntry {
public:
    std::string timestamp;
    std::string requestMethod;
    std::string requestURL;
    int statusCode;

    // Constructor
    LogEntry(const std::string& timestamp, const std::string& requestMethod,
              const std::string& requestURL, int statusCode)
        : timestamp(timestamp), requestMethod(requestMethod),
          requestURL(requestURL), statusCode(statusCode) {}
};

// Thread-safe queue for storing log entries
class LogQueue {
public:
    using Lockable = std::lock_guard<std::mutex>;
    static constexpr size_t capacity = 10000; // Adjust this according to your needs

private:
    std::queue<LogEntry> entries;
    mutable std::mutex mtx;
    mutable std::condition_variable cv;

public:
    LogQueue() : entries(), mtx(), cv() {}

    void push(const LogEntry& entry) {
        Lockable lock(mtx);
        if (entries.size() >= capacity) {
            // Handle overflow
            std::cout << "Log queue is full. Consider increasing the capacity.\n";
            return;
        }
        entries.push(entry);
        cv.notify_one();
    }

    bool try_pop(LogEntry& entry) {
        Lockable lock(mtx);
        if (entries.empty())
            return false;
        entry = std::move(entries.front());
        entries.pop();
        return true;
    }

    void wait_and_pop(LogEntry& entry) {
        Lockable lock(mtx);
        while (true) {
            cv.wait(lock, [&] { return !entries.empty(); });
            if (try_pop(entry)) break;
        }
    }
};

// Modular library for managing and exporting HTTP request logs
class LogManager {
public:
    using Lockable = std::lock_guard<std::mutex>;

    LogManager(size_t capacity) : queue(capacity) {}

    void log_request(const LogEntry& entry) {
        queue.push(entry);
    }

    void export_logs(std::ofstream& file) {
        while (true) {
            LogEntry entry;
            if (!queue.try_pop(entry)) break; // No more entries
            file << "Timestamp: " << entry.timestamp << "\n"
                 << "Method: " << entry.requestMethod << "\n"
                 << "URL: " << entry.requestURL << "\n"
                 << "Status Code: " << entry.statusCode << "\n\n";
        }
    }

private:
    LogQueue queue;
};

int main() {
    // Initialize log manager with desired capacity
    size_t capacity = 100000; // Adjust this according to your needs
    LogManager log_manager(capacity);

    // Simulate logging requests and exporting logs
    std::ofstream file("log.txt");
    for (size_t i = 0; i < 10 * 100000; ++i) {
        LogEntry entry("2023-02-20T14:30:00.000Z", "GET", "/path/to/resource", 200);
        log_manager.log_request(entry);
        if (i % 500000 == 0) {
            log_manager.export_logs(file);
            file.close();
            // Simulate network outage or transient failure
            std::this_thread::sleep_for(std::chrono::seconds(5));
            file.open("log.txt", std::ios::app); // Reopen file for appending
        }
    }

    return 0;
}
