    int concurrency = getenv("CONCURRENCY") ? atoi(getenv("CONCURRENCY")) : MAX_CONCURRENCY;

    // Set up logging service
    if (logging_service_init()) {
        logging_service_log("Failed to initialize logging service");
        return 1;
    }

    // Process files in parallel
    for (int i = 0; i < concurrency; i++) {
        file_t* file = malloc(sizeof(file_t));
        int fd = open(argv[i+1], O_RDONLY);
        if (fd == -1) {
            logging_service_log("Failed to open file %s", argv[i+1]);
            return 1;
        }
        char* buffer = malloc(BUFFER_SIZE);
        read(fd, buffer, BUFFER_SIZE);
        close(fd);

        files[total_files] = file;
        file->fd = fd;
        file->buffer = buffer;
        total_files++;

        if (pthread_create(&threads[i], NULL, process_file, &files[i]) != 0) {
            logging_service_log("Failed to create thread");
            return 1;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < concurrency; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    for (int i = 0; i < total_files; i++) {
        free(files[i]->buffer);
        close(files[i]->fd);
        free(files[i]);
    }
    logging_service_close();
}
