#include <iostream>
#include <string>
#include <map>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <http/requests.h>

using namespace std;

class CacheManager {
public:
    // Initialize cache manager with size and LRU eviction policy
    CacheManager(size_t capacity, int lruSize) : 
        cache_(new map<string, pair<string, int>>()), 
        evictQueue_(), capacity_(capacity), lruSize_(lruSize),
        lock_(), cond_(lock_)
    {
        // Initialize LRU queue with given size
        for (int i = 0; i < lruSize_; ++i) {
            evictQueue_.push(make_pair("", -1));
        }
    }

    ~CacheManager() {
        delete cache_;
    }

    // Cache entry added, updated or deleted
    void notify(const string& key, const string& value, bool isDelete = false) {
        lock_.lock();
        try {
            if (!cache_->count(key)) {
                // Add new entry to LRU queue
                evictQueue_.push(make_pair(key, (isDelete ? -1 : 0)));
            } else if (!isDelete) {
                // Update existing entry's LRU position
                auto it = cache_->find(key);
                evictQueue_.erase(evictQueue_.begin());
                evictQueue_.push(make_pair(key, it->second.second));
            }
        } catch (...) {
            lock_.unlock();
            throw;
        }
    }

    // Check if key exists in cache
    bool contains(const string& key) const {
        lock_.lock();
        try {
            return (cache_->count(key) > 0);
        } catch (...) {
            lock_.unlock();
            throw;
        }
    }

    // Get cached value for given key
    pair<string, int> get(const string& key) {
        lock_.lock();
        try {
            auto it = cache_->find(key);
            if (it != cache_->end()) {
                // Update LRU position for existing entry
                evictQueue_.erase(evictQueue_.begin());
                evictQueue_.push(make_pair(key, it->second.second));
            }
            lock_.unlock();
            return (*cache_)[key];
        } catch (...) {
            lock_.unlock();
            throw;
        }
    }

    // Remove least recently used entry
    void evict() {
        if (evictQueue_.empty()) {
            return; // No entries to evict
        }
        lock_.lock();
        try {
            auto it = evictQueue_.begin();
            string key = it->first;
            pair<string, int> value = get(key);
            cache_->erase(key);
            evictQueue_.pop();
        } catch (...) {
            lock_.unlock();
            throw;
        }
    }

    // Check if the cache is full
    bool isFull() const {
        return (cache_->size() >= capacity_);
    }

private:
    mutex lock_;
    condition_variable cond_;
    map<string, pair<string, int>>* cache_;
    priority_queue<pair<string, int>> evictQueue_;
    size_t capacity_;
    int lruSize_;
};

class RestfulAPI {
public:
    // Make a GET request to the RESTful API
    string get(const string& endpoint) {
        try {
            return http::requests::get(endpoint);
        } catch (...) {
            // Handle transient API failures with exponential backoff
            // and circuit breaker pattern
            throw;
        }
