import asyncio
from typing import Dict, Any
import logging.config

class Logger:
    def __init__(self):
        self.loggers = {}
        self.handlers = []
        self.formatters = []

    def add_logger(self, name: str, level: int) -> None:
        logger = logging.getLogger(name)
        if not self.loggers.get(name):
            self.loggers[name] = logger
            handler = logging.StreamHandler()
            formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
            handler.setFormatter(formatter)
            logger.addHandler(handler)

    def remove_logger(self, name: str) -> None:
        if self.loggers.get(name):
            self.loggers[name].removeHandler(self.handlers.pop())

    def add_handler(self, handler: Any) -> None:
        self.handlers.append(handler)

    def remove_handler(self, handler: Any) -> None:
        self.handlers.remove(handler)

    async def process_log_events(self, log_events: Dict[str, str]) -> None:
        for logger_name, log_event in log_events.items():
            if not self.loggers.get(logger_name):
                continue
            logger = self.loggers[logger_name]
            handler = [h for h in self.handlers if isinstance(h, logging.StreamHandler)][0]
            logger.handle(logging.LogRecord(*log_event.split(',')).setLevel(logging.INFO))
            await asyncio.sleep(0.01)  # simulate processing delay

    def get_log_config(self) -> Dict[str, Any]:
        return {
            'version': 1,
            'formatters': {
                'default': {'format': '%(asctime)s - %(name)s - %(levelname)s - %(message)s'},
            },
            'handlers': {
                'console': {
                    'class': 'logging.StreamHandler',
                    'level': 'INFO',
                    'formatter': 'default',
                    'stream': 'ext://sys.stdout',
                }
            },
            'loggers': {
                'my_logger': {'level': 'INFO', 'handlers': ['console'], 'propagate': False},
            },
        }

    def set_log_config(self) -> None:
        logging.config.dictConfig(self.get_log_config())

logger = Logger()
logger.add_logger('my_logger', logging.INFO)
logger.set_log_config()

async def main():
    log_events = {'my_logger': '2022-08-10 14:30:00,my_logger,INFO,some message'}
    await logger.process_log_events(log_events)

if __name__ == '__main__':
    asyncio.run(main())
