using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;

namespace YourApplication.Services
{
    public class AsyncUpdateService
    {
        private readonly ICDNService _cdnService;
        private readonly ILogger _logger;
        private readonly int _initialBackoffDelayMs = 5000;
        private readonly int _maxBackoffDelayMs = 15000;

        public AsyncUpdateService(ICDNService cdnService, ILogger logger)
        {
            _cdnService = cdnService;
            _logger = logger;
        }

        public async Task UpdatePageSectionAsync(string pageSectionId, string elementId, string sanitizedHtmlContent)
        {
            try
            {
                await UpdateWithRetry(pageSectionId, elementId, sanitizedHtmlContent);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating page section");
                throw;
            }
        }

        private async Task UpdateWithRetry(string pageSectionId, string elementId, string sanitizedHtmlContent)
        {
            int attempt = 0;
            int backoffDelayMs = _initialBackoffDelayMs;

            while (attempt <= 3)
            {
                try
                {
                    await _cdnService.UpdatePageSectionAsync(pageSectionId, elementId, sanitizedHtmlContent);
                    return;
                }
                catch (CDNUpdateFailedException ex)
                {
                    if (backoffDelayMs > _maxBackoffDelayMs)
                    {
                        throw new CDNUpdateFailedException("Max retries exceeded", ex);
                    }

                    await Task.Delay(TimeSpan.FromMilliseconds(backoffDelayMs));
                    backoffDelayMs *= 2;
                    attempt++;
                }
            }

            // Rollback on max attempts
            await RollbackPageSectionAsync(pageSectionId, elementId);
        }

        private async Task RollbackPageSectionAsync(string pageSectionId, string elementId)
        {
            try
            {
                await _cdnService.RollbackPageSectionAsync(pageSectionId, elementId);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error rolling back page section");
                throw;
            }
        }
    }

    public interface ICDNService
    {
        Task UpdatePageSectionAsync(string pageSectionId, string elementId, string sanitizedHtmlContent);
        Task RollbackPageSectionAsync(string pageSectionId, string elementId);
    }

    public class CDNUpdateFailedException : Exception { }
}
