    // Fetch user preferences from in-memory cache
    String cachedPreferences = (String) exchange.getAttribute("userPreferences");

    if (cachedPreferences != null) {
      exchange.sendResponseHeaders(200, cachedPreferences.getBytes());
    } else {
      // Update user preferences in MongoDB
      Document result = mongoClient.getDatabase().getCollection("userPreferences").find(new BasicDBObject("userId", exchange.getUserId())).first();

      if (result == null) {
        exchange.sendResponseHeaders(404, "User preferences not found".getBytes());
      } else {
        // Store updated user preferences in Redis for fast lookup
        redis.setex("user:" + exchange.getUserId(), 3600, JSON.stringify(result));

        // Enqueue task to update AWS SQS queue
        SendMessageRequest request = new SendMessageRequest();
        request.setQueueUrl(System.getenv("SQS_QUEUE_URL"));
        request.setMessageBody(JSON.stringify(new HashMap<String, String>(){{
          put("userId", exchange.getUserId());
          put("preferences", result.toJsonString());
        }}));
        sqs.sendMessage(request).get();

        exchange.sendResponseHeaders(200, result.toJsonString().getBytes());
      }
    }
