```csharp
using System;
using System.Collections.Generic;

namespace DynamicRandomValueProvider
{
    public interface IRandomValueGenerator
    {
        object Generate();
    }

    public class RandomIntGenerator : IRandomValueGenerator
    {
        private readonly Random _random = new Random();

        public object Generate()
        {
            return _random.Next();
        }
    }

    public class RandomStringGenerator : IRandomValueGenerator
    {
        private readonly Random _random = new Random();
        private readonly string[] _chars;

        public RandomStringGenerator(string chars)
        {
            _chars = chars.Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
        }

        public object Generate()
        {
            var sb = new System.Text.StringBuilder();

            for (int i = 0; i < 10; i++)
            {
                sb.Append(_chars[_random.Next(_chars.Length)]);
            }

            return sb.ToString();
        }
    }

    public class ConfigService
    {
        private readonly Dictionary<string, IRandomValueGenerator> _generators;

        public ConfigService()
        {
            _generators = new Dictionary<string, IRandomValueGenerator>();

            // Register your generators here
            _generators.Add("int", new RandomIntGenerator());
            _generators.Add("string", new RandomStringGenerator("abcdefghijklmnopqrstuvwxyz"));
        }

        public IRandomValueGenerator GetGenerator(string type)
        {
            return _generators[type];
        }
    }

    public class DynamicRandomValueProvider
    {
        private readonly ConfigService _configService;
        private readonly Dictionary<string, object> _cache;

        public DynamicRandomValueProvider(ConfigService configService)
        {
            _configService = configService;
            _cache = new Dictionary<string, object>();
        }

        public object GetRandomValue(string type)
        {
            if (!_cache.TryGetValue(type, out var value))
            {
                try
                {
                    var generator = _configService.GetGenerator(type);
                    value = generator.Generate();
                }
                catch (Exception ex)
                {
                    // Handle errors and logging here
                    throw;
                }

                _cache.Add(type, value);
            }

            return value;
        }
    }
}
```

This code provides a basic structure for your library. It defines interfaces for random value generators and uses dependency injection to manage different configuration services. The `DynamicRandomValueProvider` class uses caching to store the generated values and falls back to the configuration service if an entry is not found in the cache.']

