#include <pthread.h>

#define MAX_LINE_COUNT 1000000 // Define a maximum line count

// Structure to hold file information and line counts
typedef struct {
    char* filename;
    int line_count;
} FileStats;

// Function to process each file in the directory
void* process_file(void* arg) {
    FileStats* fs = (FileStats*)arg;
    FILE* file = fopen(fs->filename, "r");
    if (!file) {
        // Handle file opening errors
        perror("Failed to open file");
        return NULL;
    }

    int line_count = 0;
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        line_count++;
    }
    fclose(file);
    fs->line_count = line_count;
    return fs;
}

// Function to calculate the total line count across all files
int get_total_line_count(pthread_t* threads, int num_files) {
    int total_line_count = 0;
    for (int i = 0; i < num_files; i++) {
        FileStats* fs = (FileStats*)pthread_getspecific(threads[i]);
        total_line_count += fs->line_count;
    }
    return total_line_count;
}

// Main function to start the directory processing
int main(int argc, char* argv[]) {
    if (argc < 2) {
        // Display usage instructions with examples
        printf("Usage: %s [directory]\n", argv[0]);
        return 1;
    }

    pthread_t threads[10]; // Define a maximum number of threads

    DIR* dir = opendir(argv[1]); // Open the directory
    if (!dir) {
        // Handle directory opening errors
        perror("Failed to open directory");
        return 1;
    }

    FileStats fs; // Initialize file statistics structure
    int num_files = 0;

    struct dirent* ent;
    while ((ent = readdir(dir))) {
        char path[1024];
        sprintf(path, "%s/%s", argv[1], ent->d_name);
        if (strcmp(ent->d_type == DT_REG || strcmp(ent->d_type == DT_DIR), "text") == 0) {
            fs.filename = strdup(path);
            pthread_create(&threads[num_files], NULL, process_file, &fs);
            num_files++;
        }
    }

    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL); // Wait for threads to finish
    }

    int total_line_count = get_total_line_count(threads, num_files);
    printf("Total line count: %d\n", total_line_count);

    return 0;
}
