template <typename T>
class DynamicQueue {
public:
    DynamicQueue(size_t capacity) : queue_(std::make_shared<std::queue<T>>(capacity)) {}

    void push(const T& item) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (queue_->size() >= queue_->max_size()) {
            // Implement eviction policy here
        }
        queue_->push(item);
    }

    bool try_pop(T& item) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (queue_->empty()) return false;
        item = queue_->front();
        queue_->pop();
        return true;
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_->size();
    }

private:
    std::shared_ptr<std::queue<T>> queue_;
    std::mutex mutex_;
};

class DynamicQueueManager {
public:
    DynamicQueueManager(size_t capacity) : dynamic_queue_(capacity) {}

    void add(const DATA_TRANSFER_UNIT_T& item) {
        dynamic_queue_.push(item);
    }

    bool try_get(DATA_TRANSFER_UNIT_T& item) {
        return dynamic_queue_.try_pop(item);
    }

    size_t get_size() const {
        return dynamic_queue_.size();
    }

private:
    DynamicQueue<DATA_TRANSFER_UNIT_T> dynamic_queue_;
};

