fn generate_llvm_ir(input_file_path: &str) -> String {
    // Initialize the lexer and parser for the given grammar
    let mut lexer = Lexer::new(input_file_path);
    let mut parser = Parser::new(&mut lexer);

    // Parse the input file into an AST (Abstract Syntax Tree)
    let ast = match parser.parse() {
        Ok(ast) => ast,
        Err(e) => return format!("Error parsing {}: {}", input_file_path, e),
    };

    // Generate LLVM IR code for the parsed nodes
    let mut ir_code = String::new();
    for node in &ast {
        match generate_llvm_ir_node(node) {
            Ok(ir_code_fragment) => ir_code.push_str(&ir_code_fragment),
            Err(e) => return format!("Error generating LLVM IR for {}: {}", input_file_path, e),
        }
    }

    // Print debugging statements
    println!("Parsed nodes:");
    println!("{:?}", ast);
    println!("Generated LLVM IR code:");
    println!("{}", ir_code);

    ir_code
}

// Define a function to generate LLVM IR code for a given node
fn generate_llvm_ir_node(node: &Node) -> Result<String, String> {
    // Implement the logic to generate LLVM IR code for each node type
    match node {
        Node::FunctionDecl(func_decl) => {
            let mut ir_code = format!("define i32 @{}(", func_decl.name);
            ir_code.push_str(&func_decl.signature.to_string());
            ir_code.push(')');
            Ok(ir_code)
        }
        Node::VariableDecl(var_decl) => {
            let mut ir_code = format!("declare i32 {} @", var_decl.name);
            Ok(ir_code)
        }
        // ...
    }
}

