using System;
using System.Threading.Tasks;
using Newtonsoft.Json;
using System.Net.Http;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class DynamicRandomValueProvider
{
    private readonly HttpClient _httpClient;
    private readonly string _baseUrl;
    private readonly TimeSpan _cacheExpirationTimeSpan;
    private readonly object _lock = new object();

    public DynamicRandomValueProvider(string baseUrl, TimeSpan cacheExpirationTimeSpan)
    {
        _baseUrl = baseUrl;
        _cacheExpirationTimeSpan = cacheExpirationTimeSpan;
        _httpClient = new HttpClient();
    }

    public async Task<float> GetRandomFloatAsync(bool isExclusive, int count)
    {
        var ranges = await GetRangesAsync();
        return GenerateRandomFloat(ranges, isExclusive, count);
    }

    public async Task<int> GetRandomIntegerAsync(bool isExclusive, int count)
    {
        var ranges = await GetRangesAsync();
        return GenerateRandomInteger(ranges, isExclusive, count);
    }

    private async Task<Range[]> GetRangesAsync()
    {
        try
        {
            using (var requestStream = await _httpClient.GetStreamAsync(_baseUrl))
            {
                using (var reader = new StreamReader(requestStream))
                {
                    var response = await reader.ReadToEndAsync();
                    return JsonConvert.DeserializeObject<Range[]>(response);
                }
            }
        }
        catch (HttpRequestException ex)
        {
            // Handle network errors
            Console.WriteLine("Network error: " + ex.Message);
            return null;
        }
    }

    private float GenerateRandomFloat(Range[] ranges, bool isExclusive, int count)
    {
        var randomValues = new float[count];
        for (int i = 0; i < count; i++)
        {
            var range = ranges[i % ranges.Length];
            if (!isExclusive)
                randomValues[i] = (float)Random.NextDouble() * (range.Max - range.Min) + range.Min;
            else
                randomValues[i] = (float)Random.NextDouble() * (range.Max - range.Min) + range.Min;
        }
        return randomValues.Average();
    }

    private int GenerateRandomInteger(Range[] ranges, bool isExclusive, int count)
    {
        var randomValues = new int[count];
        for (int i = 0; i < count; i++)
        {
            var range = ranges[i % ranges.Length];
            if (!isExclusive)
                randomValues[i] = Random.Next(range.Min, range.Max + 1);
            else
                randomValues[i] = Random.Next(1, range.Max - range.Min) + range.Min;
        }
        return randomValues.Average();
    }

    public class Range
    {
        public int Min { get; set; }
        public int Max { get; set; }
    }
}

public static class RandomExtensions
{
    public static int Next(int min, int max)
    {
        var rand = new RNGCryptoServiceProvider();
        byte[] bytes = new byte[4];
        rand.GetBytes(bytes);
        return (int)(BitConverter.ToInt32(bytes) % (max - min)) + min;
    }
}
