class Config:
    def __init__(self, sinks=[CloudWatchLogger(), StackdriverLogger()]):
        self.sinks = sinks
        self.buffer_size = 1000
        self.flush_interval = 1

    def update_sinks(self, new_sinks):
        self.sinks = new_sinks

class LogBuffer:
    def __init__(self, buffer_size):
        self.buffer = []
        self.size = buffer_size

    def add_log_event(self, event):
        self.buffer.append(event)

    def flush(self):
        for event in self.buffer:
            for sink in Config().sinks:
                sink.log(event)
        self.buffer = []

class LoggingFramework:
    def __init__(self, config=Config()):
        self.config = config
        self.thread_pool = ThreadPoolExecutor()
        self.log_buffer = LogBuffer(config.buffer_size)

    def log(self, event):
        self.log_buffer.add_log_event(event)
        if len(self.log_buffer) >= self.config.flush_interval:
            self.log_buffer.flush()

    def start(self):
        while True:
            self.thread_pool.submit(self.check_and_flush_log_buffer)

    def check_and_flush_log_buffer(self):
        if self.log_buffer.buffer and self.log_buffer.size <= len(self.log_buffer.buffer):
            self.log_buffer.flush()
