['Here is a code block that implements a robust, scalable, and thread-safe C library for managing a doubly-linked list:

```c
#include <stdlib.h>
#include <pthread.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    // Add your fields here
} NFAPI_CRC_INDICATION_PDU_T;

// Define the doubly-linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* prev;
    struct Node* next;
} Node;

// Define the doubly-linked list
typedef struct List {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} List;

// Function to create a new node with given data
Node* create_node(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

// Function to add a new node to the list
void add_node(List* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* node = create_node(data);
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->prev = list->tail;
        list->tail->next = node;
        list->tail = node;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to remove a node from the list
void remove_node(List* list, Node* node) {
    pthread_mutex_lock(&list->lock);

    if (node == list->head) {
        list->head = node->next;
    } else if (node == list->tail) {
        list->tail = node->prev;
    }

    node->prev->next = node->next;
    node->next->prev = node->prev;

    pthread_mutex_unlock(&list->lock);
}

// Function to print the list
void print_list(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("%p\n", current->data);
        current = current->next;
    }
}
