#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

// Define a struct to hold the file information and its line count
struct FileStats {
    std::string filename;
    long long lineCount = 0;
};

// Define a function to process each file in parallel
void processFile(const std::string& filePath, const int threadId) {
    // Open the file stream with error handling
    std::ifstream fileStream(filePath);
    if (!fileStream.is_open()) {
        std::cerr << "Error opening file: " << filePath << std::endl;
        return;
    }

    // Read and count lines in parallel threads
    long long lineCount = 0;
    for (std::string line; std::getline(fileStream, line);) {
        ++lineCount;
    }
    fileStream.close();

    // Update the cumulative line count
    FileStats fileStats;
    fileStats.filename = filePath;
    fileStats.lineCount = lineCount;

    // Lock and update the shared file stats map
    std::unique_lock<std::mutex> lock(fileStatsMutex);
    fileStatsMap[filePath] = fileStats;
}

// Define a function to handle logging and reporting operations
void reportAndLog(const FileStats& fileStats) {
    // Log the line count for each file
    LOG_INFO("File: " + fileStats.filename + ", Lines: " + std::to_string(fileStats.lineCount));

    // Report the cumulative line count across all files
    LOG_INFO("Total lines: " + std::to_string(cumulativeLineCount));
}

int main(int argc, char* argv[]) {
    // Parse command-line arguments and configuration options
    if (argc < 2) {
        std::cerr << "Error: Missing directory path" << std::endl;
        return 1;
    }

    const std::string dirPath = argv[1];
    int threadCount = std::thread::hardware_concurrency();

    // Create a shared mutex for file stats updates
    fileStatsMutex = std::mutex();
    fileStatsMap = std::map<std::string, FileStats>();

    // Process each file in parallel using multithreading
    const int numFiles = countFilesInDir(dirPath);
    std::vector<std::thread> threads;
    for (int i = 0; i < threadCount && i < numFiles; ++i) {
        threads.emplace_back(processFile, dirPath + "/" + std::to_string(i), i);
    }

    // Wait for all threads to finish
    for (auto& thread : threads) {
        thread.join();
    }

    // Report and log the cumulative line count across all files
    reportAndLog(fileStatsMap.begin(), fileStatsMap.end());

    return 0;
}

