    private static final int MAX_RETRIES = 3;
    private static final long BACKOFF_MILLIS = 5000L; // in milliseconds

    private ExecutorService executor;
    private MetadataService metadataService;

    public ImageResizer() {
        this.executor = Executors.newFixedThreadPool(10); // adjust the number of threads as needed
        this.metadataService = new MetadataService();
    }

    public BufferedImage resizeImage(byte[] imageBytes, int resolution) throws IOException {
        if (imageBytes == null || imageBytes.length == 0) {
            return null; // handle invalid input
        }

        ByteArrayInputStream bais = new ByteArrayInputStream(imageBytes);
        BufferedImage originalImage = ImageIO.read(bais);

        if (resolution > DEFAULT_RESOLUTION) {
            // apply retry mechanism with backoff for transient failures
            int retries = 0;
            while (retries < MAX_RETRIES) {
                try {
                    return resizeImage(originalImage, resolution);
                } catch (IOException e) {
                    // log error and wait before retrying
                    metadataService.logError(e.getMessage());
                    if (retries >= MAX_RETRIES - 1) {
                        throw new IOException("Maximum retries exceeded");
                    }
                    Thread.sleep(BACKOFF_MILLIS);
                    retries++;
                }
            }
        }

        return resizeImage(originalImage, resolution);
    }

    private BufferedImage resizeImage(BufferedImage image, int resolution) throws IOException {
        // implement your chosen image resizing algorithm here
