                // Handle error and log it
                logging::add_common_attributes();
                logging::core::get()->set_filter(logging::expressions::attr<logging::trivial::severity>())
                    ->set_level(logging::trivial::error);
                BOOST_LOG_SEV(logging::core::get(), logging::trivial::error) << "Error occurred while processing API request: " << curl_easy_strerror(curl).c_str();
            }
        }
    }

