namespace CompressionLibrary {

    class Compressor {
    public:
        enum Algorithm { ZLIB, ZSTD, GZIP };

        Compressor(Algorithm algorithm) : algorithm_(algorithm) {}

        int compress(const char* input, size_t inputSize, char* output, size_t& outputSize) {
            switch (algorithm_) {
                case ZLIB:
                    return zlibCompress(input, inputSize, output, outputSize);
                case ZSTD:
                    return zstdCompress(input, inputSize, output, outputSize);
                case GZIP:
                    return gzipCompress(input, inputSize, output, outputSize);
            }
        }

    private:
        Algorithm algorithm_;
    };

    class Decompressor {
    public:
        enum Algorithm { ZLIB, ZSTD, GZIP };

        Decompressor(Algorithm algorithm) : algorithm_(algorithm) {}

        int decompress(const char* input, size_t inputSize, char* output, size_t& outputSize) {
            switch (algorithm_) {
                case ZLIB:
                    return zlibDecompress(input, inputSize, output, outputSize);
                case ZSTD:
                    return zstdDecompress(input, inputSize, output, outputSize);
                case GZIP:
                    return gzipDecompress(input, inputSize, output, outputSize);
            }
        }

    private:
        Algorithm algorithm_;
    };

