#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>
#include <semaphore.h>

// Define the log struct to hold metadata and contents
typedef struct {
    char timestamp[20];
    char source[50];
    char message[1024];
} Log;

// Function to process logs in real-time
void* process_logs(void* args) {
    // Initialize variables
    int i = 0;
    FILE* file;
    char buffer[1024];

    while (1) {
        // Read a line from the log file
        if ((file = fopen("/path/to/log/file.log", "r")) == NULL) {
            printf("Error opening log file.\n");
            exit(1);
        }

        fgets(buffer, sizeof(buffer), file);

        // Process each line in the log
        Log* log = (Log*)malloc(sizeof(Log));
        strcpy(log->timestamp, buffer);
        if (fgets(log->source, sizeof(log->source), file) == NULL) {
            free(log);
            fclose(file);
            return NULL;
        }
        fgets(log->message, sizeof(log->message), file);

        // Print the log entry
        printf("Timestamp: %s\n", log->timestamp);
        printf("Source: %s\n", log->source);
        printf("Message: %s\n\n");

        free(log);
        fclose(file);
    }
}

// Function to aggregate logs in real-time
void* aggregate_logs(void* args) {
    // Initialize variables
    int i = 0;
    FILE* file;
    char buffer[1024];

    while (1) {
        // Read a line from the log file
        if ((file = fopen("/path/to/log/file.log", "r")) == NULL) {
            printf("Error opening log file.\n");
            exit(1);
        }

        fgets(buffer, sizeof(buffer), file);

        // Aggregate each line in the log
        Log* log = (Log*)malloc(sizeof(Log));
        strcpy(log->timestamp, buffer);
        if (fgets(log->source, sizeof(log->source), file) == NULL) {
            free(log);
            fclose(file);
            return NULL;
        }
        fgets(log->message, sizeof(log->message), file);

        // Aggregate the log entry
        printf("Timestamp: %s\n", log->timestamp);
        printf("Source: %s\n", log->source);
        printf("Message: %s\n\n");

        free(log);
        fclose(file);
    }
}

int main() {
    pthread_t process_thread;
    pthread_t aggregate_thread;

    // Create threads to process and aggregate logs
    if (pthread_create(&process_thread, NULL, &process_logs, NULL) != 0) {
        printf("Error creating thread.\n");
        return -1;
    }

    if (pthread_create(&aggregate_thread, NULL, &aggregate_logs, NULL) != 0) {
        printf("Error creating thread.\n");
        return -1;
    }

    // Wait for threads to finish
    pthread_join(process_thread, NULL);
    pthread_join(aggregate_thread, NULL);

    return 0;
}

