async function loadResourceBundle(config) {
  const primarySource = config.primarySource;
  const secondarySource = config.secondarySource;
  const maxRetries = process.env.MAX_RETRIES || 3;
  const retryIntervalMs = parseInt(process.env.RETRY_INTERVAL_MS, 10) || 500;

  async function getResourceBundle(source) {
    try {
      if (source.startsWith('file://')) {
        const buffer = await fs.promises.readFile(source);
        return JSON.parse(buffer.toString());
      } else {
        const response = await axios.get(source, {
          maxRedirects: 0,
          retry: Axios.isRetryError,
          timeout: parseInt(process.env.REQUEST_TIMEOUT_MS, 10) || 30000,
        });

        if (!response.ok) {
          throw new Error(`Failed to load resource bundle from ${source}: ${response.statusText}`);
        }

        return response.data;
      }
    } catch (error) {
      await logger.error(`Error loading resource bundle from ${source}: ${error.message}`);

      // Implement retry logic
      for (let attempt = 1; attempt <= maxRetries; attempt++) {
        try {
          if (attempt > 1) {
            await logger.info(`Retrying attempt #${attempt} to load resource bundle from ${source}`);
          }
          const result = await getResourceBundle(source);
          return result;
        } catch (error) {
          await logger.error(`Error retrying to load resource bundle from ${source}: ${error.message}`);
          if (attempt < maxRetries) {
            await new Promise((resolve) => setTimeout(resolve, retryIntervalMs));
          }
        }
      }

      throw new Error(`Failed to load resource bundle after ${maxRetries} attempts`);
    }
  }

  try {
    const primaryBundle = await getResourceBundle(primarySource);
    if (primaryBundle) {
      return { itemCount: primaryBundle.length, items: primaryBundle };
    } else {
      return { itemCount: 0, items: [] };
    }
  } catch (error) {
    await logger.error(`Error loading primary resource bundle: ${error.message}`);

    try {
      const secondaryBundle = await getResourceBundle(secondarySource);
      if (secondaryBundle) {
        return { itemCount: secondaryBundle.length, items: secondaryBundle };
      } else {
        return { itemCount: 0, items: [] };
      }
    } catch (error) {
      await logger.error(`Error loading secondary resource bundle: ${error.message}`);
      throw error;
    }
  }
}

export default loadResourceBundle;
