public class IoTDataAggregator {
    public static void main(String[] args) throws Exception {
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Create a Flink Kafka consumer
        FlinkKafkaConsumer<String> consumer = new FlinkKafkaConsumer<>("iot-data", new StringDeserializer(), props);
        consumer.setStartFromEarliest();

        // Define the stream processing pipeline
        DataStream<String> dataStream = env.addSource(consumer)
                .map(new MapFunction<String, SensorData>() {
                    @Override
                    public SensorData map(String value) throws Exception {
                        // Deserialize and process incoming data
                        return new SensorData(value);
                    }
                })
                .keyBy("sensorId")
                .window(TumblingEventTimeWindows.of(Duration.standardMinutes(1)))
                .aggregate(new AggregateFunction<SensorData, Long>() {
                    @Override
                    public Long aggregate(Long value) throws Exception {
                        // Perform aggregation and anomaly detection
                        return new Long(value);
                    }
                })
                .map(new MapFunction<Long, Alert>(()) {
                    @Override
                    public Alert map(Long value) throws Exception {
                        // Generate real-time alerts based on aggregated data
                        return new Alert(value);
                    }
                });

        // Start the Flink application
        env.execute("IoT Data Aggregator");
    }

    private static Properties props() {
        // Configure Kafka topic and partition settings
        Properties props = new Properties();
        props.put("bootstrap.servers", "localhost:9092");
        props.put("key.deserializer", StringDeserializer.class.getName());
        props.put("value.deserializer", StringDeserializer.class.getName());
        props.put("partition.0.replication.factor", 1);
        return props;
    }
}
