void createDataset(Record** records, size_t n_records);
void freeDataset(Record** records);

int main() {
    size_t n_records = 10000;
    Record** records = new Record*[n_records];
    for (size_t i = 0; i < n_records; i++) {
        records[i] = new Record();
    }
    createDataset(records, n_records);
    // ... process records ...
    freeDataset(records);
    return 0;
}

void createDataset(Record** records, size_t n_records) {
    // Create a dynamic dataset of records
    for (size_t i = 0; i < n_records; i++) {
        Record* record = new Record();
        record->offset = i;
        char* key = new char[16];
        std::sprintf(key, "key-%zu", i);
        record->key = key;
        records[i] = record;
    }
}

void freeDataset(Record** records) {
    // Free the dataset
    for (size_t i = 0; i < n_records; i++) {
        Record* record = records[i];
        delete[] record->key;
        delete record;
    }
}
