```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int id;
    char data[1024];
} NFAPI_CRC_INDICATION_PDU_T;

// Define the library's internal representation of a collection
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_CRC_COLLECTION_T;

// Initialize a new CRC collection
NFAPI_CRC_COLLECTION_T* nfa_pi_crc_collection_init() {
    NFAPI_CRC_COLLECTION_T* result = (NFAPI_CRC_COLLECTION_T*)malloc(sizeof(NFAPI_CRC_COLLECTION_T));
    result->elements = NULL;
    result->capacity = 0;
    result->size = 0;
    pthread_mutex_init(&result->lock, NULL);
    return result;
}

// Add an element to the collection
void nfa_pi_crc_collection_add(NFAPI_CRC_COLLECTION_T* collection, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&collection->lock);

    // Resize the collection if necessary
    if (collection->size >= collection->capacity) {
        collection->elements = realloc(collection->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (collection->capacity * 2));
        collection->capacity *= 2;
    }

    collection->elements[collection->size++] = element;

    pthread_mutex_unlock(&collection->lock);
}

// Print the contents of the collection
void nfa_pi_crc_collection_print(NFAPI_CRC_COLLECTION_T* collection) {
    printf("Collection size: %zu\n", collection->size);

    for (size_t i = 0; i < collection->size; i++) {
        printf("Element %zu: id=%d, data='%s'\n", i, collection->elements[i]->id, collection->elements[i]->data);
    }
