#include <string>

// Define the log entry struct
struct LogEntry {
    std::string timestamp;
    std::string level;
    std::string message;
};

// Implement the log aggregator class
class LogAggregator {
public:
    LogAggregator(const std::string& exportPath, const size_t batchSize) 
        : exportPath_(exportPath), batchSize_(batchSize), queue_() {}

    // Add a new log entry to the queue
    void addLogEntry(const LogEntry& entry) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(entry);
        lock.unlock();
        cv_.notify_one(); // Notify the thread waiting on the condition variable
    }

    // Export logs in batches every 5 minutes
    void exportLogs() {
        while (true) {
            // Wait for at least batchSize_ log entries
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait_for(lock, std::chrono::minutes(5), 
                [this] { return queue_.size() >= batchSize_; });

            // Export the batch of logs to file
            std::vector<LogEntry> batch;
            while (!queue_.empty()) {
                batch.push_back(queue_.front());
                queue_.pop();
            }
            std::ofstream file(exportPath_);
            for (const LogEntry& entry : batch) {
                file << entry.timestamp << " " << entry.level << " " << entry.message << "\n";
            }
            file.close();

            // Reset the batch
            queue_.resize(0);
        }
    }

private:
    std::string exportPath_;
    size_t batchSize_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::queue<LogEntry> queue_;
};

int main() {
    LogAggregator aggregator("logs.txt", 1000);

    // Add log entries to the aggregator
    for (size_t i = 0; i < 10000; ++i) {
        LogEntry entry;
        entry.timestamp = std::to_string(i);
        entry.level = "INFO";
        entry.message = "This is a test message";
        aggregator.addLogEntry(entry);

        // Simulate export every 5 minutes
        if (i % 300 == 0) {
            std::thread t([&aggregator]() { aggregator.exportLogs(); });
            t.join();
        }
    }

    return 0;
}

