use tokio::{prelude::*, runtime};

async fn log_aggregator(log_events: Vec<LogEvent>) {
    let mut pipeline = LogPipeline::new();

    for event in log_events {
        pipeline.process(&event).await;
    }

    println!("Processed {} log events", log_events.len());
}

struct LogPipeline {
    storage: Storage,
    processing_rules: Vec<Box<dyn ProcessingRule>>,
}

impl LogPipeline {
    fn new() -> Self {
        Self {
            storage: Storage::new(),
            processing_rules: vec![],
        }
    }

    async fn process(&mut self, log_event: &LogEvent) {
        for rule in &self.processing_rules {
            if let Some(processed_event) = rule.process(log_event).await {
                self.storage.store(&processed_event).await;
            }
        }
    }
}

trait ProcessingRule {
    async fn process(&self, log_event: &LogEvent) -> Option<LogEvent>;
}

struct Storage {
    elasticsearch: Elasticsearch,
    mysql: Mysql,
}

impl Storage {
    fn new() -> Self {
        Self {
            elasticsearch: Elasticsearch::new(),
            mysql: Mysql::new(),
        }
    }

    async fn store(&self, log_event: &LogEvent) {
        self.elasticsearch.store(log_event).await;
        self.mysql.store(log_event).await;
    }
}

async fn main() {
    let runtime = tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
        .unwrap();

    let mut aggregator = LogPipeline::new();
    let log_events = vec![/*insert your events here*/];

    runtime.block_on(async move { log_aggregator(log_events).await });
}

