hash_table* hash_table = NULL;

void generate_and_persist_crc_indications(int N, unsigned long seed) {
    if (N > 5000) {
        printf("Warning: N exceeds the maximum limit of 5000. Capping at 5000.\n");
        N = 5000;
    }

    NFAPI_CRC_INDICATION_PDU_T* crc_indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (seed) {
        srand(seed);
    } else {
        time_t current_time = time(NULL);
        srand(current_time);
    }

    for (int i = 0; i < N; i++) {
        crc_indications[i].RX_UE_INFORMATION_TAG = rand() % 256;
        crc_indications[i].RNTI = rand() % 65536;
        crc_indications[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        crc_indications[i].CRCFLAG = (i % 2) ? 0 : 1;
    }

    // Initialize the hash table
    hash_table = malloc(sizeof(hash_table));
    pthread_mutex_init(&hash_table_lock, NULL);

    for (int i = 0; i < N; i++) {
        int RNTI = crc_indications[i].RNTI;
        pthread_mutex_lock(&hash_table_lock);
        if (!hash_table_add(RNTI)) {
            printf("Error: RNTI %d is not unique.\n", RNTI);
        }
        pthread_mutex_unlock(&hash_table_lock);
    }

    // Persist the CRC indications
    db_connect();
    for (int i = 0; i < N; i++) {
        db_insert(crc_indications[i]);
    }
    db_disconnect();

    free(crc_indications);
}

void* hash_table_add(int RNTI) {
    pthread_mutex_lock(&hash_table_lock);

    // Implement custom collision resolution strategy
    if (hash_table_find(RNTI)) {
        pthread_mutex_unlock(&hash_table_lock);
        return NULL;
    }

    // Add the new RNTI to the hash table
    hash_table_insert(RNTI);

    pthread_mutex_unlock(&hash_table_lock);
    return NULL;
}

int main() {
    generate_and_persist_crc_indications(1000, 12345);
    return 0;
}
