// Forward declaration of struct NFAPI_CRC_INDICATION_PDU_T
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Forward declaration of struct doubly_linked_list_node_t
typedef struct doubly_linked_list_node_t {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct doubly_linked_list_node_t* prev;
    struct doubly_linked_list_node_t* next;
} doubly_linked_list_node_t;

// Forward declaration of struct doubly_linked_list_t
typedef struct doubly_linked_list_t {
    doubly_linked_list_node_t* head;
    doubly_linked_list_node_t* tail;
    pthread_mutex_t mutex;
} doubly_linked_list_t;

// Function to create a new node with random CRCFLAG and return the updated node
doubly_linked_list_node_t* create_node() {
    doubly_linked_list_node_t* node = (doubly_linked_list_node_t*)malloc(sizeof(doubly_linked_list_node_t));
    if (!node) return NULL;
    node->data.RX_UE_INFORMATION_TAG = rand();
    node->data.RNTI = rand();
    node->data.CRC_INDICATION_REL8_TAG = rand();
    node->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    return node;
}

// Function to add a new node at the end of the list and synchronize with external data source
void add_node(doubly_linked_list_t* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    doubly_linked_list_node_t* node = create_node();
    if (!node) return;
    pthread_mutex_lock(&list->mutex);
    node->next = NULL;
    if (list->tail) {
        list->tail->next = node;
        list->tail = node;
    } else {
        list->head = node;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove a specified node from the list and free its memory
void remove_node(doubly_linked_list_t* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    doubly_linked_list_node_t* current = list->head;
    doubly_linked_list_node_t* prev = NULL;
    while (current && current->data.RX_UE_INFORMATION_TAG != data->RX_UE_INFORMATION_TAG) {
        prev = current;
        current = current->next;
    }
    if (!current) return; // Node not found
    pthread_mutex_lock(&list->mutex);
    if (prev) prev->next = current->next;
    else list->head = current->next;
    if (current == list->tail) list->tail = prev;
    free(current);
    pthread_mutex_unlock(&list->mutex);
}

// Function to iterate over the list and apply a callback function to each node
void iterate_list(doubly_linked_list_t* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    doubly_linked_list_node_t* current = list->head;
    while (current) {
        pthread_mutex_lock(&list->mutex);
        callback(current->data);
        pthread_mutex_unlock(&list->mutex);
        current = current->next;
    }
}

// Function to initialize the library and set up synchronization with external data source
void init_library() {
    doubly_linked_list_t* list = (doubly_linked_list_t*)malloc(sizeof(doubly_linked_list_t));
    if (!list) return; // Initialize mutex for thread safety
    pthread_mutex_init(&list->mutex, NULL);
}

// Function to cleanup the library and free allocated memory
void cleanup_library() {
    doubly_linked_list_t* list = (doubly_linked_list_t*)malloc(sizeof(doubly_linked_list_t));
    if (!list) return; // Free linked list nodes
    pthread_mutex_unlock(&list->mutex);
}
