struct NODE_T {
    int USER_ID;
    std::string USERNAME;
    std::list<RELATION_T> edges;
};

// Define a struct to represent an edge between two nodes
struct RELATION_T {
    int source_node_id;
    int target_node_id;
};

class GraphLibrary {
public:
    // Constructor to initialize the graph library
    GraphLibrary() : mutex_(), node_map_() {}

    // Add a new node to the graph with its user information and edges
    void add_node(int user_id, std::string username, const std::list<RELATION_T>& edges) {
        NODE_T node;
        node.USER_ID = user_id;
        node.USERNAME = username;
        node.edges = edges;
        // Lock the mutex to ensure thread safety
        std::lock_guard<std::mutex> lock(mutex_);
        node_map_[user_id] = node;
    }

    // Remove a node from the graph by its user ID
    void remove_node(int user_id) {
        if (node_map_.erase(user_id)) {
            // Update edges of connected nodes
            for (auto it = node_map_.begin(); it != node_map_.end(); ++it) {
                NODE_T& node = it->second;
                for (auto edge : node.edges) {
                    if (edge.source_node_id == user_id || edge.target_node_id == user_id) {
                        // Update the edge by removing the removed node
                        if (edge.source_node_id == user_id) {
                            edge.source_node_id = 0; // Update source node ID to 0
                        } else {
                            edge.target_node_id = 0; // Update target node ID to 0
                        }
                    }
                }
            }
        }
    }

    // Get the list of edges for a given node by its user ID
    std::list<RELATION_T> get_edges(int user_id) const {
        if (node_map_.count(user_id)) {
            return node_map_.at(user_id).edges;
        } else {
            return {};
        }
    }

private:
    // Mutex to ensure thread safety for concurrent read-write operations
    std::mutex mutex_;

    // Map of nodes in the graph, where keys are user IDs and values are NODE_T structures
    std::map<int, NODE_T> node_map_;
};

