import java.util.*;
import java.io.*;

public class DataProcessingFramework {

    // External data sources
    private List<Source> sources = new ArrayList<>();

    // Transformations and enrichments
    private List<Transform> transforms = new ArrayList<>();

    // Downstream consumers
    private List<Sink> sinks = new ArrayList<>();

    // Configuration options
    private Map<String, String> configOptions = new HashMap<>();

    public void start() {
        for (Source source : sources) {
            source.start();
        }
        for (Transform transform : transforms) {
            transform.start();
        }
        for (Sink sink : sinks) {
            sink.start();
        }
    }

    public void stop() {
        for (Source source : sources) {
            source.stop();
        }
        for (Transform transform : transforms) {
            transform.stop();
        }
        for (Sink sink : sinks) {
            sink.stop();
        }
    }

    // Add a new data source
    public void addSource(Source source) {
        sources.add(source);
    }

    // Remove a data source
    public void removeSource(Source source) {
        sources.remove(source);
    }

    // Add a new transformation or enrichment
    public void addTransform(Transform transform) {
        transforms.add(transform);
    }

    // Remove a transformation or enrichment
    public void removeTransform(Transform transform) {
        transforms.remove(transform);
    }

    // Add a downstream consumer
    public void addSink(Sink sink) {
        sinks.add(sink);
    }

    // Remove a downstream consumer
    public void removeSink(Sink sink) {
        sinks.remove(sink);
