    private readonly string _siteIdentifier;
    private readonly List<string> _trustedDirectories = new List<string>();
    private readonly Dictionary<string, WebHostBuilder> _webApplications = new Dictionary<string, WebHostBuilder>();

    public WebEnvironmentManager(string baseDirectoryPath, string siteIdentifier)
    {
        _baseDirectoryPath = baseDirectoryPath;
        _siteIdentifier = siteIdentifier;

        // Validate paths against trusted directories
        if (!_trustedDirectories.Any(td => Path.GetFileName(_baseDirectoryPath).StartsWith(td)))
            throw new InvalidOperationException("Unauthorized access attempt");

        // Initialize ASP.NET Core Web Host Builder for each web application
        foreach (string directory in Directory.GetFiles(_baseDirectoryPath, "*.csproj"))
        {
            string projectPath = Path.GetDirectoryName(directory);
            _webApplications.Add(Path.GetFileName(projectPath), CreateWebHostBuilder(projectPath));
        }
    }

    private WebHostBuilder CreateWebHostBuilder(string projectPath)
    {
        return WebHost.Create(new WebHostOptions { SiteIdentifier = _siteIdentifier, BaseDirectory = projectPath })
            .UseMiddleware<CustomMiddleware>()
            .UseKestrel(options => options.ListenAnyIP(5000))
            .UseWebSockets();
    }

    public void Dispose()
    {
        // Monitor health metrics and implement notification system for anomalies
        // Integrate with third-party monitoring tools if necessary

        foreach (WebHostBuilder webHost in _webApplications.Values)
        {
            try
            {
                webHost.Build().Start();
            }
            catch (Exception ex)
            {
                // Handle exceptions and notify administrators of issues
            }
        }
    }

