```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Extensions.Logging;

namespace SessionManagementLibrary
{
    public class SessionManager : IDisposable
    {
        private readonly Dictionary<string, ISessionStore> _sessionStores = new();
        private readonly ILogger _logger;

        public SessionManager(ILogger<SessionManager> logger)
        {
            _logger = logger;
        }

        public void AddSessionStore(string name, ISessionStore sessionStore)
        {
            _sessionStores.Add(name, sessionStore);
        }

        public void RemoveSessionStore(string name)
        {
            _sessionStores.Remove(name);
        }

        public T GetSession<T>(string sessionId) where T : class
        {
            foreach (var store in _sessionStores.Values)
            {
                if (store.ContainsSession(sessionId))
                {
                    return store.GetSession<T>(sessionId);
                }
            }
            throw new SessionNotFoundException($"Session {sessionId} not found");
        }

        public void SetSession(string sessionId, object sessionData)
        {
            foreach (var store in _sessionStores.Values)
            {
                if (store.ContainsSession(sessionId))
                {
                    store.SetSession(sessionId, sessionData);
                    return;
                }
            }
            throw new SessionNotFoundException($"Session {sessionId} not found");
        }

        public void RemoveSession(string sessionId)
        {
            foreach (var store in _sessionStores.Values)
            {
                if (store.ContainsSession(sessionId))
                {
                    store.RemoveSession(sessionId);
                    return;
                }
            }
            throw new SessionNotFoundException($"Session {sessionId} not found");
        }

        public void Dispose()
        {
            foreach (var store in _sessionStores.Values)
            {
                store.Dispose();
            }
        }
    }

    public interface ISessionStore
    {
        bool ContainsSession(string sessionId);
        T GetSession<T>(string sessionId) where T : class;
        void SetSession(string sessionId, object sessionData);
        void RemoveSession(string sessionId);
        void Dispose();
    }

    public class RedisSessionStore : ISessionStore
    {
        private readonly IConnectionMultiplexer _redisConnection;

        public RedisSessionStore(IConnectionMultiplexer redisConnection)
        {
            _redisConnection = redisConnection;
        }

        // implementation of ISessionStore methods
    }

    public class MemcachedSessionStore : ISessionStore
    {
        private readonly IMemcachedClient _memcachedClient;

        public MemcachedSessionStore(IMemcachedClient memcachedClient)
        {
            _memcachedClient = memcachedClient;
        }

        // implementation of ISessionStore methods
    }

    public class LocalDatabaseSessionStore : ISessionStore
    {
        private readonly DbContext _dbContext;

        public LocalDatabaseSessionStore(DbContext dbContext)
        {
            _dbContext = dbContext;
        }

        // implementation of ISessionStore methods
    }
}
```
