    async fn handle_api_request(api_url: &str) -> Result<(), Box<dyn std::error::Error>> {
        let data = get_data_from_api(api_url).await?;
        // Store the data in the cache with a TTL
        cache.write().unwrap().insert(api_url, data.clone());
        Ok(())
    }

    // Define the cache hit handler
    async fn handle_cache_hit(key: &str) -> Result<String, Box<dyn std::error::Error>> {
        let cached_data = cache.read().unwrap().get(&key).cloned();
        match cached_data {
            Some(data) => Ok(data),
            None => handle_cache_miss(key).await,
        }
    }

    // Define the API request loop
    async fn api_request_loop() -> Result<(), Box<dyn std::error::Error>> {
        let mut rng = rand::thread_rng();

        loop {
            // Generate a random API URL
            let api_url = format!("https://api.example.com/{}", rng.gen::<u16>());

            // Check if the cache hit
            match handle_cache_hit(&api_url).await {
                Ok(data) => println!("Cache hit: {}", data),
                Err(e) => println!("Error: {}", e),
            }

            // If the cache miss, make an API request and store it in the cache
            if let Err(_) = handle_api_request(&api_url).await {
                println!("API request failed");
            }
        }
    }

    // Start the API request loop
    runtime.block_on(api_request_loop());
}
