use std::path::{Path, PathBuf};
use std::fs::create_dir_all;
use std::io::{Error, ErrorKind};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

mod config {
    use serde::Deserialize;

    #[derive(Deserialize)]
    pub struct Config {
        dir_path: String,
    }
}

struct Lock {
    lock_time: Instant,
    timeout: Duration,
}

impl Lock {
    fn new(timeout: Duration) -> Self {
        Lock {
            lock_time: Instant::now(),
            timeout,
        }
    }

    fn refresh(&mut self) {
        self.lock_time = Instant::now();
    }
}

pub struct AppDirManager {
    config_service: Arc<Mutex<config::Config>>,
    lock: Arc.Mutex>,
    retries: u32,
}

impl AppDirManager {
    pub fn new(config_service: Arc<Mutex<config::Config>>, retries: u32) -> Self {
        AppDirManager { 
            config_service, 
            lock: Arc::new(Mutex::new(Lock::new(Duration::from_millis(1000)))),
            retries,
        }
    }

    pub fn create_dir(&self) -> Result<PathBuf, Error> {
        let config = self.config_service.lock().unwrap();
        let dir_path = Path::new(&config.dir_path);
        let mut lock = self.lock.lock().unwrap();

        loop {
            if let Err(e) = create_dir_all(dir_path.clone()) {
                match e.kind() {
                    ErrorKind::PermissionDenied => return Err(e),
                    _ => {}
                }

                // Wait for the distributed lock to expire
                if Instant::now().duration_since(lock.lock_time) >= lock.timeout {
                    break;
                }

                // If service is unavailable, wait and try again
                if let Err(_) = self.config_service.lock().unwrap().lock.refresh() {
                    continue;
                }
            } else {
                return Ok(dir_path.to_path_buf());
            }
        }
    }
}
