#include <set>
#include <mutex>
#include <thread>

class Node {
public:
    int userId;
    std::string username;
    // List of edges pointing to other nodes
    std::set<Node*> neighbors;

    Node(int userId, std::string username) : userId(userId), username(username) {}
};

class Graph {
private:
    std::map<int, Node*> nodes;
    std::mutex nodeMutex; // Mutex for accessing nodes

public:
    void addNode(Node* node);
    void removeNode(Node* node);
    void addEdge(Node* node1, Node* node2);
    void removeEdge(Node* node1, Node* node2);
    // List of all edges in the graph
    std::set<std::pair<Node*, Node*> > edges;

    Graph() {}

};

void Graph::addNode(Node* node) {
    nodes[node->userId] = node;
}

void Graph::removeNode(Node* node) {
    if (nodes.find(node->userId) != nodes.end()) {
        nodes.erase(node->userId);
    }
}

void Graph::addEdge(Node* node1, Node* node2) {
    node1->neighbors.insert(node2);
    node2->neighbors.insert(node1);
    edges.insert(std::make_pair(node1, node2));
}

void Graph::removeEdge(Node* node1, Node* node2) {
    if (node1->neighbors.find(node2) != node1->neighbors.end()) {
        node1->neighbors.erase(node2);
    }
    if (node2->neighbors.find(node1) != node2->neighbors.end()) {
        node2->neighbors.erase(node1);
    }
    edges.erase(std::make_pair(node1, node2));
}
