['Here is the code for the `calculate_avg_response_time` function in Rust:

```rust
use std::time::{Duration, Instant};
use reqwest;

async fn calculate_avg_response_time(url: &str) -> f64 {
    let mut total_duration = Duration::from_nanos(0);
    let mut request_count = 0;

    for _ in 0..10 { // Perform 10 requests
        let start = Instant::now();
        match reqwest::get(url).await {
            Ok(response) => {
                let duration = start.elapsed();
                total_duration += duration;
                request_count += 1;
            },
            Err(_) => break, // Stop after first failure (e.g., due to network issues)
        }
    }

    if request_count > 0 {
        let avg_response_time = total_duration.as_nanos() as f64 / request_count as f64;
        println!("Average response time: {:.2}ms", avg_response_time * 1e-3);
        avg_response_time
    } else {
        std::f64::NAN // Return NaN if no requests were successful
    }
}
