    EVP_CIPHER_CTX_set_iv_length(ctx->cipher_ctx, 16);
    EVP_EncryptInit_ex(ctx->cipher_ctx, EVP_aes_256_cbc(), NULL, derived_key, ctx->iv);
}

// Encrypt data using cipher context
void encrypt(cipher_context* ctx, const unsigned char* plaintext, int plaintext_len, unsigned char* ciphertext) {
    int len;
    EVP_EncryptUpdate(ctx->cipher_ctx, ciphertext, &len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx->cipher_ctx, ciphertext + len, &len);
}

// Decrypt data using cipher context
void decrypt(cipher_context* ctx, const unsigned char* ciphertext, int ciphertext_len, unsigned char* plaintext) {
    int len;
    EVP_DecryptUpdate(ctx->cipher_ctx, plaintext, &len, ciphertext, ciphertext_len);
    EVP_DecryptFinal_ex(ctx->cipher_ctx, plaintext + len, &len);
}

// Serialize cipher context
void serialize_cipher_context(cipher_context* ctx, unsigned char** serialized_ctx) {
    int i;
    *serialized_ctx = malloc(sizeof(unsigned char) * (16 + 32));
    for (i = 0; i < 16; i++) {
        (*serialized_ctx)[i] = ctx->iv[i];
    }
    for (i = 0; i < 32; i++) {
        (*serialized_ctx)[16 + i] = ((unsigned char*)ctx->cipher_ctx->key)[i];
    }
}

// Deserialize cipher context
void deserialize_cipher_context(cipher_context* ctx, unsigned char* serialized_ctx) {
    int i;
    memcpy(ctx->iv, serialized_ctx, 16);
    memcpy(((unsigned char*)ctx->cipher_ctx->key), serialized_ctx + 16, 32);
}

