package main

import (
	"bufio"
	"crypto/tls"
	"fmt"
	"log"
	"net/http"
	"sync"
	"time"

	"github.com/golang/protobuf/proto"
	"github.com/patthemyway/go-redis"
)

type Request struct {
	Method  string
	URL      string
	Headers map[string]string
	Body    []byte
}

func main() {
	http.HandleFunc("/api/v1/proxy", proxyHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}

func proxyHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method == "CONNECT" || r.Method == "PROPFIND" {
		httpProxy(w, r)
	} else if r.Method == "PUT" || r.Method == "GET" || r.Method == "HEAD" || r.Method == "DELETE" {
		httpTunnel(w, r)
	}
}

func httpProxy(w http.ResponseWriter, r *http.Request) {
	client := &http.Client{}
	req, err := http.NewRequest(r.Method, r.URL.String(), r.Body)
	if err != nil {
		http.Error(w, err.Error(), 500)
		return
	}
	for key, value := range r.Header {
		req.Header.Set(key, value)
	}

	resp, err := client.Do(req)
	if err != nil {
		http.Error(w, err.Error(), 500)
		return
	}

	defer resp.Body.Close()

	_, _ = io.Copy(w, resp.Body)

	w.WriteHeader(resp.StatusCode)
}

func httpTunnel(w http.ResponseWriter, r *http.Request) {
	client := &http.Client{}
	req, err := http.NewRequest(r.Method, r.URL.String(), nil)
	if err != nil {
		http.Error(w, err.Error(), 500)
		return
	}
	for key, value := range r.Header {
		req.Header.Set(key, value)
	}

	resp, err := client.Do(req)
	if err != nil {
		http.Error(w, err.Error(), 500)
		return
	}

	defer resp.Body.Close()

	_, _ = io.Copy(w, resp.Body)

	w.WriteHeader(resp.StatusCode)
}

func (r *Request) Marshal() ([]byte, error) {
	reqData, err := proto.Marshal(r)
	if err != nil {
		return nil, err
	}
	return reqData, nil
}

func (r *Request) Unmarshal(data []byte) error {
	return proto.Unmarshal(data, r)
}

func mainRedisPool(redisConnStr string) (*redis.Client, error) {
	client, err := redis.NewClient(&redis.Options{ Addr: redisConnStr })
	if err != nil {
		return nil, err
	}
	return client, nil
}

func doRedisAction(client *redis.Client, action func(*redis.Client) error) (error) {
	err := action(client)
	client.Close()
	return err
}

func mainRedis(redisConnStr string, action func(*redis.Client) error) (error) {
	client, err := mainRedisPool(redisConnStr)
	if err != nil {
		return err
	}
	err = doRedisAction(client, action)
	return err
}

