function asyncReduce(arr, initial, callback) {
  let accumulated = initial;
  (async () => {
    for await (let num of arr) {
      try {
        accumulated = await callback(accumulated, num);
      } catch (error) {
        return error;
      }
    }
    return accumulated;
  })();
}

