#define MAX_N 1000
#define HASH_TABLE_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t hash_table_lock = PTHREAD_MUTEX_INITIALIZER;
int hash_table[HASH_TABLE_SIZE] = {0};

void* generate_crc_indications(void* param) {
    int N = *(int*)param;
    pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);

    for (int i = 0; i < N; i++) {
        if (i > MAX_N) {
            fprintf(stderr, "Warning: Exceeded maximum allowed value of %d.\n", MAX_N);
            break;
        }

        int RNTI = rand() % 1000;
        int CRCFLAG = rand() % 2;

        pthread_mutex_lock(&hash_table_lock);
        if (hash_table[RNTI] != 0) {
            // Handle collision
            RNTI++;
            while (hash_table[RNTI] != 0) {
                RNTI++;
            }
        }
        hash_table[RNTI] = i;
        pthread_mutex_unlock(&hash_table_lock);

        NFAPI_CRC_INDICATION_PDU_T* crc_indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        crc_indication->RX_UE_INFORMATION_TAG = rand() % 1000;
        crc_indication->RNTI = RNTI;
        crc_indication->CRC_INDICATION_REL8_TAG = rand() % 1000;
        crc_indication->CRCFLAG = CRCFLAG;

        // Store in database or API
        // Implement retry logic and timeout mechanisms as needed

        free(crc_indication);
    }

    pthread_setcancelstate(PTHREAD_CANCEL_DISABLE, NULL);
}

int main(int argc, char* argv[]) {
    int N = 100;
    if (argc > 1) {
        N = atoi(argv[1]);
    }
    if (N > MAX_N) {
        N = MAX_N;
        fprintf(stderr, "Warning: Exceeded maximum allowed value of %d.\n", MAX_N);
    }

    pthread_t threads[MAX_N];
    int* params = malloc(sizeof(int) * MAX_N);

    for (int i = 0; i < N; i++) {
        params[i] = i + 1;
        pthread_create(&threads[i], NULL, generate_crc_indications, &params[i]);
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    free(params);

    return 0;
}

