    bool commitMessageProcessing(const DataPacket& packet);

private:
    int maxConcurrentOps;
    int maxMemoryUsageMB;

    // buffer to hold incoming packets
    std::queue<DataPacket> incomingPacketsBuffer;

    // concurrent threads to process packets
    std::vector<std::thread> processingThreads;

    // lock and condition variable for thread safety
    std::mutex mtx;
    std::condition_variable cv;
};

// constructor for DataPacketManager
DataPacketManager::DataPacketManager(int maxConcurrentOps, int maxMemoryUsageMB)
    : maxConcurrentOps(maxConcurrentOps), maxMemoryUsageMB(maxMemoryUsageMB) {}

// start processing packets asynchronously and persist them
void DataPacketManager::startProcessingPackets() {
    // start concurrent threads for packet processing
    for (int i = 0; i < maxConcurrentOps; ++i) {
        processingThreads.emplace_back([this]() {
            while (true) {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this] { return !incomingPacketsBuffer.empty(); });
                DataPacket packet = incomingPacketsBuffer.front();
                incomingPacketsBuffer.pop();
                // process packet asynchronously and persist it
                processPacket(packet);
            }
        });
    }

    // wait for all threads to finish
    for (auto& thread : processingThreads) {
        thread.join();
    }
}

// consume incoming packets from an external message broker or event stream processor
void DataPacketManager::consumePackets(const std::queue<DataPacket>& incomingPackets) {
    // add packets to the buffer
    while (!incomingPackets.empty()) {
        incomingPacketsBuffer.push(incomingPackets.front());
        incomingPackets.pop();
    }
}

// handle system dependencies and integrate with an external message broker or event stream processor
void DataPacketManager::initDependencies() {}

// retry logic with exponential backoff for transient connectivity and processing errors
