#define MAX_N 1000 // system-defined maximum
#define TABLE_SIZE 256 // size of hash table

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Hash function for RNTI
uint32_t rnti_hash(uint32_t rnti) {
    return rnti % TABLE_SIZE;
}

// Collision resolution using separate chaining
NFAPI_CRC_INDATION_PDU_T** table[TABLE_SIZE];

void nfa_pi_crc_indication_pdu_t_init(int N, uint32_t seed) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        table[i] = NULL;
    }
}

int nfa_pi_crc_indication_pdu_t_insert(RNTI rnti, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    uint32_t index = rnti_hash(rnti);
    NFAPI_CRC_INDATION_PDU_T** slot = &table[index];

    // Check if the RNTI is already present
    for (int i = 0; i < MAX_N && *slot != NULL; i++) {
        if (((*slot)->rnti == rnti)) {
            return -1; // RNTI already exists
        }
        slot++;
    }

    // Insert the new entry
    *slot = pdu;
    return 0;
}

NFAPI_CRC_INDATION_PDU_T* nfa_pi_crc_indication_pdu_t_lookup(RNTI rnti) {
    uint32_t index = rnti_hash(rnti);
    NFAPI_CRC_INDATION_PDU_T** slot = &table[index];

    // Search for the RNTI
    while (*slot != NULL && (*slot)->rnti != rnti) {
        slot++;
    }

    return *slot;
}

void nfa_pi_crc_indication_pdu_t_free() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        free(table[i]);
    }
}
