// Shared memory structure for cooldowns
struct Cooldown {
    std::atomic<uint32_t> currentCooldown;
    uint32_t minCooldownTime; // configurable via server config file (5-15 seconds)
};

// Thread-safe, persistent cooldown mechanism
class CooldownManager {
public:
    CooldownManager(uint32_t minCooldownTime) : minCooldownTime(minCooldownTime) {}

    void setCooldown(int attackId) {
        std::unique_lock<std::mutex> lock(cooldownsMutex);
        auto& cooldown = cooldowns[attackId];
        if (cooldown.currentCooldown > 0) {
            // Cooldown in progress, record failure
            gameLog("Failed to execute " + std::to_string(attackId) + " due to active cooldown");
        } else {
            // Start new cooldown
            cooldown.currentCooldown = minCooldownTime;
            gameLog("Cooldown started for " + std::to_string(attackId));
        }
    }

    bool isReady(int attackId) const {
        std::unique_lock<std::mutex> lock(cooldownsMutex);
        auto& cooldown = cooldowns[attackId];
        return cooldown.currentCooldown <= 0;
    }

private:
    mutable std::mutex cooldownsMutex;
    std::map<int, Cooldown> cooldowns;
    uint32_t minCooldownTime;
};

// System integration and combat engine
class CombatSystem {
public:
    void executeStrategicAttack(int attackId) {
        // Dynamically select and execute one of three strategic attacks
        if (isReady(attackId)) {
            // Execute attack and log success
            gameLog("Successful " + std::to_string(attackId) + " execution");
        } else {
            // Cooldown in progress, re-check after cooldown duration
            setTimer(attackId);
        }
    }

private:
    void setTimer(int attackId) {
        // Asynchronous timer to re-check cooldown status
        std::thread([this, attackId]() {
            std::this_thread::sleep_for(std::chrono::seconds(CooldownManager::minCooldownTime));
            if (isReady(attackId)) {
                // Cooldown completed, execute attack
                gameLog("Cooldown completed for " + std::to_string(attackId) + ", executing now");
                // Execute combat logic here
            }
        }).detach();
    }

    bool isReady(int attackId) const {
        return cooldownManager.isReady(attackId);
    }

    CooldownManager cooldownManager;
};

// External query support and API endpoint
class StatusQueryEndpoint {
public:
    void resetCooldowns() {
        // Reset all cooldowns for emergency scenarios (game resets, server maintenance)
        for (auto& [attackId, cooldown] : cooldownManager.cooldowns) {
            cooldown.currentCooldown = 0;
        }
    }

    bool isReady(int attackId) const {
        return cooldownManager.isReady(attackId);
    }

private:
    CooldownManager cooldownManager;

    // RESTful API endpoint for external queries
    void handleQuery(const std::string& query) {
        if (query == "reset") {
            resetCooldowns();
        } else {
            // Handle other query types or errors
        }
    }
};

// Performance optimization and concurrency
class GameServer {
public:
    void mainGameLoop() {
        // Asynchronous game loop to handle attacks, cooldowns, and external queries
        std::thread([this]() {
            while (true) {
                // Check for pending attacks and execute if ready
                for (auto& attack : combatSystem.attacksToExecute) {
                    if (combatSystem.isReady(attack)) {
                        combatSystem.executeStrategicAttack(attack);
                    } else {
                        // Cooldown in progress, re-check after cooldown duration
                        setTimer(attack);
                    }
                }

                // Handle external queries and reset cooldowns as needed
                statusQueryEndpoint.handleQuery(query);
            }
        }).detach();
    }

private:
    CombatSystem combatSystem;
    StatusQueryEndpoint statusQueryEndpoint;

    // Fallback strategy for delayed cooldown checks during network issues
    void setTimer(int attackId) {
        std::thread([this, attackId]() {
            std::this_thread::sleep_for(std::chrono::seconds(CooldownManager::minCooldownTime));
            if (combatSystem.isReady(attackId)) {
                // Cooldown completed, execute attack
                gameLog("Cooldown completed for " + std::to_string(attackId) + ", executing now");
                // Execute combat logic here
            }
        }).detach();
    }

    // Tiered performance monitoring system
    void collectPerformanceData() {
