int appendDelimiter(const char* str, int maxLength, const char* delimiter) {
    if (str == nullptr || strlen(str) >= maxLength) {
        return strlen(str);
    }
    int len = strlen(str);
    char result[len + 1];
    strcpy(result, str);
    for (int i = 0; i < strlen(delimiter); i++) {
        if (len + i >= maxLength) {
            break;
        }
        strcat(result, delimiter);
    }
    return strlen(result);
}

