    int throughput;
};

class ConnectionState {
public:
    int connectionId;
    long lastActiveTimestamp;
    int currentThroughput;
    std::list<Flow> activeFlows;
};

class DynamicNetworkSessionManager {
private:
    std::map<int, ConnectionState> connections;
    std::mutex mutex;
    int connectionCount;

public:
    DynamicNetworkSessionManager() : connectionCount(0) {}

    void addConnection(int connectionId, long lastActiveTimestamp, int currentThroughput) {
        ConnectionState state = {connectionId, lastActiveTimestamp, currentThroughput, {}};
        connections[connectionId] = state;
        connectionCount++;
    }

    void removeConnection(int connectionId) {
        if (connections.find(connectionId) != connections.end()) {
            connections.erase(connections.find(connectionId));
            connectionCount--;
        }
    }

    ConnectionState getConnectionState(int connectionId) {
        std::lock_guard<std::mutex> lock(mutex);
        return connections[connectionId];
    }

    void updateConnectionState(int connectionId, long lastActiveTimestamp, int currentThroughput) {
        std::lock_guard<std::mutex> lock(mutex);
        if (connections.find(connectionId) != connections.end()) {
            ConnectionState& state = connections[connectionId];
            state.lastActiveTimestamp = lastActiveTimestamp;
            state.currentThroughput = currentThroughput;
        }
    }

    int getConnectionsCount() {
        return connectionCount;
    }
};

