public class DistributedCachingInfrastructure
{
    private readonly DistributedKeyStore _distributedKeyStore;
    private readonly ILogger<DistributedCachingInfrastructure> _logger;
    private readonly HybridEvictionPolicy _hybridEvictionPolicy;
    private readonly MetadataService _metadataService;

    public DistributedCachingInfrastructure(IConfiguration configuration, ILogger<DistributedCachingInfrastructure> logger)
    {
        _distributedKeyStore = new DistributedKeyStore(configuration["DistributedKeyStoreConnectionString"]);
        _logger = logger;
        _hybridEvictionPolicy = new HybridEvictionPolicy();
        _metadataService = new MetadataService(configuration["MetadataServiceConnectionString"]);
    }

    public void Start()
    {
        _distributedKeyStore.Start();
        _metadataService.Start();

        // Initialize cache
        foreach (var key in _distributedKeyStore.GetKeys())
        {
            var value = _distributedKeyStore.GetValue(key);
            if (value != null)
            {
                Cache.Add(key, value);
            }
        }
    }

    public void Stop()
    {
        _distributedKeyStore.Stop();
        _metadataService.Stop();

        // Clear cache
        Cache.Clear();
    }

    public T Get<T>(string key) where T : class
    {
        var value = Cache.Get(key);
        if (value == null)
        {
            try
            {
                value = _distributedKeyStore.GetValue(key);
                if (value != null)
                {
                    Cache.Add(key, value);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to retrieve value from distributed key store");
                return default(T);
            }
        }

        return (T)value;
    }

    public void Put(string key, object value)
    {
        Cache.Add(key, value);

        try
        {
            _distributedKeyStore.Put(key, value);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to store value in distributed key store");
        }
    }

    public void Remove(string key)
    {
        Cache.Remove(key);

        try
        {
            _distributedKeyStore.Remove(key);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to remove value from distributed key store");
        }
    }

    // Implementation of HybridEvictionPolicy and MetadataService classes omitted for brevity.
}

public class Cache
{
