    public Cache()
    {
        _cache = new Dictionary<string, object>();
    }

    public void Add(string key, object value)
    {
        _cache.Add(key, value);
    }

    public object Get(string key)
    {
        return _cache.GetValueOrDefault(key, null);
    }

    public void Remove(string key)
    {
        _cache.Remove(key);
    }

    public void Clear()
    {
        _cache.Clear();
    }
}

