import java.io.IOException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ImageResizer {
    private static final int MAX_RESOLUTION = 1024;
    private static final int RETRY_ATTEMPTS = 3;
    private static final long BACKOFF_INTERVAL = 1000; // 1 second

    private MetadataService metadataService;
    private ExecutorService executor;

    public ImageResizer(MetadataService metadataService) {
        this.metadataService = metadataService;
        this.executor = Executors.newCachedThreadPool();
    }

    public BufferedImage resize(Image image, int width, int height) throws IOException {
        // Resize the image
        BufferedImage resizedImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        Graphics2D g2d = resizedImage.createGraphics();
        g2d.drawImage(image, 0, 0, null);

        // Log performance metrics and debug information
        metadataService.log("ImageResizer", "resize", image.getWidth(), image.getHeight(), width, height);

        return resizedImage;
    }

    public void process(Image image) throws IOException {
        try {
            BufferedImage resizedImage = resize(image, MAX_RESOLUTION, MAX_RESOLUTION);
            // Handle transient failures and retries
            if (resizedImage == null) {
                int attempts = 0;
                while (attempts < RETRY_ATTEMPTS) {
                    Thread.sleep(BACKOFF_INTERVAL * attempts);
                    resizedImage = resize(image, MAX_RESOLUTION, MAX_RESOLUTION);
                    if (resizedImage != null) break;
                    attempts++;
                }
                if (resizedImage == null) throw new IOException("Failed to process image");
            }

            // Cache the resized image
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            ImageIO.write(resizedImage, "jpg", bos);
            ByteArrayInputStream bis = new ByteArrayInputStream(bos.toByteArray());

            // Asynchronous processing for non-critical data updates
            executor.submit(() -> {
                try {
                    // Update cache or database with processed image
                } catch (Exception e) {
                    metadataService.log("ImageResizer", "error", e.getMessage());
                }
            });
        } catch (IOException | InterruptedException e) {
            metadataService.log("ImageResizer", "error", e.getMessage());
        }
    }
}
