    pthread_mutex_init(&rename_lock, NULL);
    pthread_cond_init(&rename_queue, NULL);

    // Create a thread pool for concurrent renaming
    pthread_t threads[count];
    for (int i = 0; i < count; i++) {
        pthread_create(&threads[i], NULL, rename_thread, &requests[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < count; i++) {
