    // Generate a unique sequence of random digits
    srand(time(NULL));
    char* random_sequence = malloc(10);
    for (int i = 0; i < 10; i++) {
        random_sequence[i] = (char)(rand() % 10 + '0');
    }
    random_sequence[10] = '\0';

    // Get the original file extension
    char* original_extension = strrchr(original_path, '.');

    // Create the new file name with the appended sequence and extension
    char* new_name = malloc(strlen(original_path) + strlen(random_sequence) + strlen(new_extension) + 2);
    strcpy(new_name, original_path);
    strcat(new_name, random_sequence);
    strcat(new_name, new_extension);

