void *populateUERxIndications(int num_ues) {
    pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);

    // Dynamic allocation for the array of structures
    NFAPI_CRC_INDICATION_PDU_T **indications = (NFAPI_CRC_INDICATION_PDU_T **)calloc(num_ues, sizeof(NFAPI_CRC_INDICATION_PDU_T *));

    if (!indications) {
        LOG_ERROR("Failed to allocate memory for UE indications");
        return NULL;
    }

    // Initialize each structure with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < num_ues; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!pdu) {
            LOG_ERROR("Failed to allocate memory for UE indication");
            free(indications);
            return NULL;
        }

        pdu->rx_ue_info_tag = i;
        pdu->rnti = (unsigned char)(rand() % 256); // Random RNTI value
        pdu->crc_ind_rel8_tag = i;
        pdu->crcflag = rand() % 2; // Random CRC flag value

        indications[i] = pdu;
    }

    return indications;
}

void populateUERxIndicationsConcurrent(int num_ues, int *num_threads) {
    pthread_t threads[*num_threads];
    NFAPI_CRC_INDICATION_PDU_T **indications;

    // Create worker threads
    for (int i = 0; i < *num_threads; i++) {
        pthread_create(&threads[i], NULL, populateUERxIndications, num_ues / *num_threads);
    }

    // Wait for all threads to finish
    for (int i = 0; i < *num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

void freeUEIndications(NFAPI_CRC_INDICATION_PDU_T **indications, int num_ues) {
    for (int i = 0; i < num_ues; i++) {
        if (indications[i]) {
            free(indications[i]);
        }
    }

    free(indications);
}
