```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/md5.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void MD5HashAndPopulateUERxIndications(int numUEs, char *inputString) {
    NFAPI_CRC_INDICATION_PDU_T *crcPduArray = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numUEs * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < numUEs; i++) {
        crcPduArray[i].RX_UE_INFORMATION_TAG = rand() % 100000;
        crcPduArray[i].RNTI = rand() % 65535;

        // Generate random CRC flag
        uint8_t crcFlag = (uint8_t)rand() % 2;
        crcPduArray[i].CRC_INDICATION_REL8_TAG[0] = (crcFlag & 1);
        crcPduArray[i].CRC_INDICATION_REL8_TAG[1] = (crcFlag >> 1) & 1;
        crcPduArray[i].CRC_INDICATION_REL8_TAG[2] = (crcFlag >> 2) & 1;
        crcPduArray[i].CRC_INDICATION_REL8_TAG[3] = (crcFlag >> 3);

        // Compute MD5 hash
        unsigned char md5[MD5_DIGEST_LENGTH];
        MD5(inputString, strlen(inputString), md5);

        // Store the MD5 hash in the CRC flag
        crcPduArray[i].CRCFLAG = 0;
        for (int j = 0; j < MD5_DIGEST_LENGTH; j++) {
            crcPduArray[i].CRCFLAG |= ((md5[j] >> (7 - j)) & 1) << i % 8;
        }
    }

    // Free the memory
    free(crcPduArray);
}
