void processUEIndications(int num_ue_instances) {
    int i, thread_id;
    pthread_attr_t attr;

    // Allocate the initial array size based on the number of UE instances
    indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_INDICATIONS);

