    for (thread_id = 0; thread_id < WORKER_THREADS; thread_id++) {
        pthread_create(&threads[thread_id], &attr, process_ue_indications_thread, NULL);
    }
    pthread_attr_destroy(&attr);

    // Wait for the threads to finish
    for (thread_id = 0; thread_id < WORKER_THREADS; thread_id++) {
        pthread_join(threads[thread_id], NULL);
    }

    free(indications);
}

void process_ue_indications_thread(void *args) {
    int i, thread_id;
    pthread_mutex_lock(&lock);

