        for (i = 0; i < indication_count; i++) {
            // Update CRCFLAG based on real-time sensor data
            indications[i].CRCFLAG = get_crcflag_from_sensor_data();
        }

        // Release the lock and wait for new indications
        pthread_cond_signal(&cond_var);
        pthread_mutex_unlock(&lock);

        // Wait for new indications
        pthread_cond_wait(&cond_var, &lock);
    }
}

