class Logger {
public:
    enum class Level { DEBUG, INFO, WARNING, ERROR };
    struct LogEntry {
        std::string message;
        TimeStamp timestamp;
        Level level;
    };

    void setLevel(Level level) {
        this->level = level;
    }

    void addSink(std::shared_ptr<Sink> sink) {
        sinks_.insert({sink->getName(), sink});
    }

    void log(const LogEntry& entry) {
        if (entry.level >= level_) {
            for (const auto& pair : sinks_) {
                pair.second->write(entry);
            }
        }
    }

private:
    Level level_;
    std::map<std::string, std::shared_ptr<Sink>> sinks_;
};

class Sink {
public:
    virtual ~Sink() {}
    virtual void write(const Logger::LogEntry& entry) = 0;
    virtual std::string getName() const = 0;
};

class FileSink : public Sink {
public:
    FileSink(std::string filename) : filename_(filename), file_(filename, std::ios_base::app) {}

    void write(const Logger::LogEntry& entry) override {
        file_ << entry.timestamp.toString() << " [" << entry.level << "] " << entry.message << "\n";
    }

