**Gateway Application**

```java
import io.vertx.core.Vertx;
import io.vertx.ext.web.Router;
import io.vertx.ext.web.handler.BodyHandler;
import io.vertx.ext.web.handler.CORSHandler;

public class GatewayApplication {

    public static void main(String[] args) {
        Vertx vertx = Vertx.vertx();
        Router router = Router.router(vertx);

        // Configure CORS handler
        router.route().handler(CORSHandler.create("*")
                .allowedMethods("GET", "POST", "PUT", "DELETE")
                .allowedHeaders("Content-Type"));

        // Handle incoming requests
        router.route().handler(BodyHandler.create());

        // Route requests to respective services
        router.get("/api/v1/users").handler(UserService::handleGetUsers);
        router.post("/api/v1/users").handler(UserService::handleCreateUser);
        router.put("/api/v1/users/:id").handler(UserService::handleUpdateUser);
        router.delete("/api/v1/users/:id").handler(UserService::handleDeleteUser);

        // Start the gateway
        vertx.deployVerticle(router);
    }
}
```

