void manageUERxIndications(int num_uels, NFAPI_CRC_INDICATION_PDU_T **pues) {
    // Configuration variables
    int max_ues = getenv("MAX_UES") ? atoi(getenv("MAX_UES")) : MAX_UES;
    int min_crc_interval = getenv("MIN_CRC_INTERVAL") ? atoi(getenv("MIN_CRC_INTERVAL")) : MIN_CRC_INTERVAL;
    float prob_successful_crc = getenv("PROB_SUCCESSFUL_CRC") ? atof(getenv("PROB_SUCCESSFUL_CRC")) : PROB_SUCCESSFUL_CRC;

    // Initialize the array
    *pues = (NFAPI_CRC_INDICATION_PDU_T **)malloc(num_uels * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    for (int i = 0; i < num_uels; i++) {
        (*pues)[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        strcpy((*pues)[i]->RX_UE_INFORMATION_TAG, "valid_tag");
        (*pues)[i]->RNTI = rand() % 100;
        strcpy((*pues)[i]->CRC_INDICATION_REL8_TAG, "valid_tag");
        if (rand() % 100 < prob_successful_crc * 100) {
            (*pues)[i]->CRCFLAG = 0x01; // Randomly set CRC flag
        } else {
            (*pues)[i]->CRCFLAG = 0x00;
        }
    }

    // Dynamic resizing of the array
    for (int i = num_uels; i < max_ues; i++) {
        if ((max_ues - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T *) > sysconf(_SC_PAGE_SIZE)) {
            (*pues) = (NFAPI_CRC_INDICATION_PDU_T **)realloc(*pues, (max_ues + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
        }
    }

    // Concurrent access and thread safety
