#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CACHE_SIZE 1000
#define LOGGING_LEVEL 1
#define TIMEOUT 60 // seconds

typedef struct {
    int timestamp;
    int key;
    int value;
} Record;

Record* cache = NULL;
int cache_size = 0;
int timeout = TIMEOUT;

void* log_thread(void* arg) {
    while (1) {
        sleep(1);
        if (LOGGING_LEVEL == 1) {
            printf("Cache hit/miss: %d\n", *(int*)arg);
        } else if (LOGGING_LEVEL == 2) {
            char buffer[100];
            sprintf(buffer, "Timestamp: %d, Key: %d, Value: %d", ((Record*)arg)->timestamp, ((Record*)arg)->key, ((Record*)arg)->value);
            printf("%s\n", buffer);
        }
    }
}

void* resize_thread(void* arg) {
    while (1) {
        sleep(10);
        int new_size = cache_size + rand() % 5;
        if (new_size > MAX_CACHE_SIZE) {
            new_size = MAX_CACHE_SIZE;
        }
        Record* new_cache = (Record*)realloc(cache, new_size * sizeof(Record));
        if (new_cache == NULL) {
            printf("Error: unable to reallocate memory\n");
        } else {
            cache = new_cache;
            cache_size = new_size;
            printf("Cache size updated to %d\n", cache_size);
        }
    }
}

void* timeout_thread(void* arg) {
    while (1) {
        sleep(timeout);
        for (int i = 0; i < cache_size; i++) {
            if (cache[i].timestamp + timeout <= time(NULL)) {
                free(cache[i]);
                memmove(&cache[i], &cache[i+1], (cache_size - i - 1) * sizeof(Record));
                cache_size--;
                printf("Expired record removed\n");
            }
        }
    }
}

void* access_thread(void* arg) {
    int id = *(int*)arg;
    while (1) {
        int key = rand() % 1000;
        for (int i = 0; i < cache_size; i++) {
            if (cache[i].key == key) {
                printf("Cache hit by thread %d\n", id);
                break;
            }
        }
        sleep(1);
    }
}

int main(int argc, char** argv) {
    pthread_t log_thread_id = pthread_self();
    pthread_create(&log_thread_id, NULL, &log_thread, (void*)&cache_size);

    pthread_t resize_thread_id = pthread_self();
    pthread_create(&resize_thread_id, NULL, &resize_thread, (void*)&cache_size);

    pthread_t timeout_thread_id = pthread_self();
    pthread_create(&timeout_thread_id, NULL, &timeout_thread, (void*)&cache_size);

    for (int i = 0; i < 5; i++) {
