```go
package main

import (
	"bufio"
	"fmt"
	"log"
	"net/http"
	"os"
	"sync"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
	"github.com/grpc-ecosystem/go-grpc-middleware/common"
	"github.com/irisnet/go-iris/app"
	"github.com/irisnet/go-iris/core"
	"github.com/irisnet/go-iris/types"

	_ "github.com/lib/pq" // Import PostgreSQL driver
)

const (
	// DefaultRateLimitPerSecond represents the default rate limit per second.
	DefaultRateLimitPerSecond = 100

	// DefaultRateLimitPerMinute represents the default rate limit per minute.
	DefaultRateLimitPerMinute = 6000

	// DefaultRateLimitPerHour represents the default rate limit per hour.
	DefaultRateLimitPerHour = 36000
)

type (
	RateLimiter struct {
		rateLimiter map[string]struct{}
		mu          sync.Mutex
	}

	proxyConfig struct {
		acl       []string
		ratelimit map[string]int64
	}
)

func main() {
	// Initialize the proxy service.
	proxy := &proxyConfig{
		acl: ACL(),
		ratelimit: map[string]int64{
			"default": DefaultRateLimitPerSecond,
		},
	}

	// Create a new HTTP handler.
	httpHandler := http.NewServeMux()
	httpHandler.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		// Enforce the access control list (ACL).
		if !proxy.enforceAcl(r.RemoteAddr, r.Header.Get("User-Agent")) {
			http.Error(w, "Unauthorized", http.StatusUnauthorized)
			return
		}

		// Rate limit the request.
		if err := proxy.rateLimit(r); err != nil {
			http.Error(w, err.Error(), http.StatusTooManyRequests)
			return
		}

		// Forward the request to the backend service.
		backendURL := "http://localhost:8080" // Replace with your backend URL.
		resp, err := http.Get(backendURL + r.URL.Path)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		defer resp.Body.Close()

		// Copy the response headers and body to the client.
		for k, v := range resp.Header {
			w.Header().Add(k, v[0])
		}
		_, err = io.Copy(w, resp.Body)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
	})

	// Start the HTTP server.
	fmt.Println("Starting proxy service...")
	log.Fatal(http.ListenAndServe(":8081", &middleware.Default Middleware{Handler: httpHandler}))
}

func (proxy *proxyConfig) enforceAcl(ip string, userAgent string) bool {
	for _, aclEntry := range proxy.acl {
		if ipMatches(aclEntry, ip) && userAgentsMatch(userAgent, aclEntry) {
			return true
		}
	}
	return false
}

func (proxy *proxyConfig) rateLimit(r *http.Request) error {
	ip := r.RemoteAddr
	ratelimit, ok := proxy.ratelimit["default"]
	if !ok || ratelimit <= 0 {
		return nil
	}

	// Implement the request rate limiting logic here.
	// For demonstration purposes, we'll just count the requests.
	requests, ok := requestCounts[ip]
	if !ok || requests < ratelimit {
		requestCounts[ip] = requests + 1
		return nil
	}

	// Rate limit exceeded. Sleep for a short duration before retrying.
	time.Sleep(10 * time.Second)
	return errors.New("Rate limit exceeded")
}
```']

