#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>

int renameDirectoryWithVersioning(const char *dirPath, const char *initialVersionNumber,
                                   int maxAllowedIncrements) {
    DIR *dp;
    struct dirent *entry;

    if ((dp = opendir(dirPath)) == NULL) {
        perror("Error opening directory");
        return -1;
    }

    while ((entry = readdir(dp)) != NULL) {
        char filePath[256];
        sprintf(filePath, "%s/%s", dirPath, entry->d_name);

        // Validate file name
        if (strlen(entry->d_name) > MAX_FILE_NAME_LENGTH || !isalnum(entry->d_name[0])) {
            continue;
        }

        time_t currentTime = time(NULL);
        char versionedFileName[256];
        sprintf(versionedFileName, "%s-%.4s%.2s%.2s%.3s", entry->d_name,
                iso8601Date(currentTime), iso8601Time(currentTime));

        // Check if file already exists with the new name
        int existingFileIndex = 0;
        while (access(versionedFileName, F_OK) == 0) {
            char versionedFileNameTemp[256];
            sprintf(versionedFileNameTemp, "%s-%.4s%.2s%.2s%.3s",
                    entry->d_name, iso8601Date(currentTime), iso8601Time(currentTime));
            if (existingFileIndex > maxAllowedIncrements) {
                printf("Error: file %s already exists with the new name\n", versionedFileName);
                return -1;
            }
            sprintf(versionedFileName, "%s-%.4s%.2s%.2s%.3d",
                    entry->d_name, iso8601Date(currentTime), iso8601Time(currentTime),
                    existingFileIndex + 1);
            existingFileIndex++;
        }

        // Rename the file
        int renameStatus = rename(filePath, versionedFileName);
        if (renameStatus == -1) {
            perror("Error renaming file");
            return -1;
        }
    }

    closedir(dp);
    return 0;
}
