```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Customizable versioning strategy (e.g., incrementing numbers)
int versionCounter = 0;

void batchRenameWithVersioning(const char *directory) {
    DIR *dir;
    struct dirent *ent;
    int i, len;

    dir = opendir(directory);
    if (!dir) {
        printf("Error opening directory: %s\n", directory);
        return;
    }

    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        len = strlen(ent->d_name);

        // Dynamically rename files with timestamp and version number
        char newFileName[255];
        sprintf(newFileName, "%s_%d_v%d.txt", ent->d_name, time(NULL), ++versionCounter);
        int result = rename(directory, ent->d_name, newFileName);
        if (result == -1) {
            printf("Error renaming file: %s\n", directory);
        }
    }

    closedir(dir);
}

int main() {
    batchRenameWithVersioning("/path/to/directory");
    return 0;
}
```

