# Define a custom logging handler that writes to Kafka
class KafkaHandler(logging.Handler):
    def __init__(self, bootstrap_servers, schema_registry_url):
        self.producer = KafkaProducer(bootstrap_servers=bootstrap_servers)
        self.schema_registry_client = SchemaRegistryClient(schema_registry_url)

    def emit(self, record):
        serializer = self.get_serializer(record)
        self.producer.send("my_topic", value=serializer.dumps(record).encode("utf-8"))

    def get_serializer(self, record):
        if record.levelno == logging.INFO:
            return JSONSerializer()
        elif record.levelno >= logging.WARNING:
            return CSVSerializer()

# Define a custom serialization class for JSON
class JSONSerializer:
    def dumps(self, obj):
        import json
        return json.dumps(obj)

# Define a custom serialization class for CSV
