// Function to safely rename all files in a specified directory,
// appending a timestamp and version number to each file's name
void batchFileRenamingWithVersioning(const char *directory) {
    // Initialize the file renaming logic
    DIR *dir = opendir(directory);
    if (dir == NULL) {
        printf("Error opening directory: %s\n", directory);
        return;
    }

    // Iterate through all files in the directory
    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        char filePath[256];
        sprintf(filePath, "%s/%s", directory, ent->d_name);

        // Append timestamp and version number to each file's name
        time_t timestamp = time(NULL);
        char fileName[128];
        sprintf(fileName, "%ld_%s.txt", timestamp, ent->d_name);

        // Perform the actual renaming (replacing existing files)
        rename(filePath, fileName);

        // Log any errors during the renaming process
        if (errno) {
            perror("Error renaming file:");
        }
    }

    // Close the directory stream
    closedir(dir);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        printf("Usage: %s <directory>\n", argv[0]);
        return 1;
    }

    batchFileRenamingWithVersioning(argv[1]);

    return 0;
}
