// Define a struct to represent IoT device telemetry data
struct TelemetryData {
    std::string deviceId;
    std::string sensorId;
    int timestamp;
    float value;
};

// Define a class for the ingestion and processing component
class TelemetryProcessor {
public:
    TelemetryProcessor(int numDevices, int maxDataSize) : 
        devices(numDevices), deviceData(queue()), dataStorage(map()), running(true) {}

    void run() {
        std::thread processThread(&TelemetryProcessor::processDeviceData, this);
        processThread.detach();
    }

    void stop() { running = false; }

private:
    int numDevices;
    std::queue<TelemetryData> deviceData;
    std::map<std::string, TelemetryData> dataStorage;
    bool running;

    // Process device data and store it in the time-series database
    void processDeviceData() {
        while (running) {
            if (!deviceData.empty()) {
                auto data = deviceData.front();
                deviceData.pop();

                // Transform and export telemetry data to the message broker
                std::cout << "Processing device " << data.deviceId << " sensor " << data.sensorId 
                          << " value: " << data.value << std::endl;

                // Store the processed data in the time-series database
                dataStorage[data.deviceId] = data;
            } else {
                std::this_thread::sleep_for(std::chrono::milliseconds(1));
            }
        }
    }

    void ingestData(int deviceId, TelemetryData data) {
        deviceData.push(data);
    }

    void exportData() {
        // Export processed data to the message broker
    }
};

int main() {
    int numDevices = 10000;
    int maxDataSize = 1048576; // 1 MB

    TelemetryProcessor processor(numDevices, maxDataSize);

    std::thread producerThread([&processor]() {
        for (int i = 0; i < numDevices; ++i) {
            TelemetryData data;
            // Simulate generating telemetry data
            for (int j = 0; j < maxDataSize / sizeof(TelemetryData); ++j) {
                data.deviceId = std::to_string(i);
                data.sensorId = std::to_string(j);
                data.timestamp = std::chrono::system_clock::now().time_since_epoch().count();
                data.value = static_cast<float>(i * j);

                processor.ingestData(data.deviceId, data);
            }
        }
    });

    processor.run();

    // Start the producer thread
    producerThread.join();

    processor.stop();

    return 0;
}
