import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousServerSocketChannel;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLSocketFactory;

import com.google.inject.Inject;
import com.google.inject.Singleton;
import io.netty.bootstrap.ServerBootstrap;
import io.netty.channel.ChannelOption;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.handler.ssl.SslContextServerSocketFactory;

@Singleton
public class Microservice {
    @Inject
    private AsynchronousChannelGroup channelGroup;

    @Inject
    private ExecutorService executorService;

    public void start() throws Exception {
        NioEventLoopGroup boss = new NioEventLoopGroup();
        NioEventLoopGroup worker = new NioEventLoopGroup();

        ServerBootstrap bootstrap = new ServerBootstrap()
            .group(boss, worker)
            .channel(AsynchronousServerSocketChannel.class)
            .childHandler(new MicroserviceInitializer());

        InetSocketAddress bindAddress = new InetSocketAddress("0.0.0.0", 8443);
        AsynchronousServerSocketChannel channel = (AsynchronousServerSocketChannel) bootstrap.bind(bindAddress).sync().channel();

        channel.setOption(ChannelOption.SO_BACKLOG, 100);
        channel.setOption(ChannelOption.SO_REUSEADDR, true);

        SSLContext sslContext = SSLContext.getInstance("TLS");
        SSLSocketFactory factory = sslContext.getServerSocketFactory();
        channel.setOption(ChannelOption.SSL_CONTEXT, sslContext);

        channelGroup.add(channel);
        executorService.submit(() -> {
            try {
                while (true) {
                    AsynchronousServerSocketChannel incoming = channel.accept();
                    if (incoming != null) {
                        handler(incoming);
                    }
                }
            } catch (IOException e) {
                // handle errors
            }
        });
    }

    private void handler(AsynchronousServerSocketChannel incoming) {
        // handle connection
    }
}
