    // Transcode and process file in parallel
    const transcodingQueue = [];
    const processingQueue = [];

    // Add tasks to queues based on user preferences and device capabilities
    if (req.metadata.format === 'video') {
      transcodingQueue.push({
        type: 'transcoding',
        input: req.file,
        output: { format: 'mp4', resolution: '1080p' },
      });
      processingQueue.push({
        type: 'processing',
        input: req.file,
        output: { resolution: '720p' },
      });
    } else {
      transcodingQueue.push({
        type: 'transcoding',
        input: req.file,
        output: { format: 'jpg', resolution: '1024x768' },
      });
    }

    // Process queues concurrently
    Promise.all([
      ...transcodingQueue.map((task) => {
        return new Promise((resolve, reject) => {
          const worker = async () => {
            try {
              await sharp(task.input)
                .resize(task.output.resolution)
                .toFormat(task.output.format)
                .then((output) => {
                  req.metadata[task.type] = output;
                  resolve();
                })
                .catch((err) => reject(err));
            } catch (error) {
              reject(error);
            }
          };
          worker().then(() => {
            fs.writeFileSync(path.join(__dirname, 'path-to-your-transcoded-file'), output);
          });
        });
      }),
      ...processingQueue.map((task) => {
        return new Promise((resolve, reject) => {
          const worker = async () => {
            try {
              await sharp(task.input)
                .resize(task.output.resolution)
                .toFormat(task.output.format)
                .then((output) => {
                  req.metadata[task.type] = output;
                  resolve();
                })
                .catch((err) => reject(err));
            } catch (error) {
              reject(error);
            }
          };
          worker().then(() => {
            fs.writeFileSync(path.join(__dirname, 'path-to-your-processed-file'), output);
          });
        });
      }),
    ]).then(() => {
      // File processing complete
      res.status(201).send(`File uploaded and processed successfully!`);
    }).catch((error) => {
      console.error(error);
      res.status(500).send('Error processing file');
    });
  });

// Handle file versioning and lifecycle management
