        if (!isRunning_) {
            isRunning_ = true;
            thread_ = std::thread([this]() { generateRandomNumbers(); });
        }
    }

    void stop() {
        std::unique_lock<std::mutex> lock(mutex_);
        if (isRunning_) {
            isRunning_ = false;
            thread_.join();
        }
    }

    int getRandomNumber(int min, int max) {
