        for (int i = 0; i < numInstances; i++) {
            std::string seed = generateRandomSeed(minSeed, maxSeed);
            RandomNumberGenerator* rngInstance = new RandomNumberGenerator(seed);
            rngInstances_.insert({seed, rngInstance});
            rngInstance->start();
        }
    }

    void stopRNGInstances() {
        for (auto& it : rngInstances_) {
            it.second->stop();
        }
    }

    int getRandomNumberFromInstance(std::string seed) {
        auto it = rngInstances_.find(seed);
        if (it != rngInstances_.end()) {
            return it->second->getRandomNumber(1, 100); // Replace with your desired RNG range
        } else {
            return -1; // Handle the case where the requested seed does not exist
        }
    }

private:
