// Initialize the network interface management system
NetworkInterfaceManagementSystem* init_network_interface_management_system(int num_interfaces) {
    NetworkInterfaceManagementSystem* system = (NetworkInterfaceManagementSystem*)malloc(sizeof(NetworkInterfaceManagementSystem));
    system->num_interfaces = num_interfaces;
    system->interface_names = (char**)malloc(num_interfaces * sizeof(char*));
    for (int i = 0; i < num_interfaces; i++) {
        system->interface_names[i] = (char*)malloc(strlen("interface") + 1);
        strcpy(system->interface_names[i], "interface");
    }
    pthread_mutex_init(&system->mutex, NULL);
    return system;
}

// Add a new interface to the network interface management system
void add_interface(NetworkInterfaceManagementSystem* system) {
    pthread_mutex_lock(&system->mutex);
    system->num_interfaces++;
    char** new_names = (char**)malloc(system->num_interfaces * sizeof(char*));
    for (int i = 0; i < system->num_interfaces - 1; i++) {
        new_names[i] = (char*)strdup(system->interface_names[i]);
    }
    free(system->interface_names);
    system->interface_names = new_names;
    pthread_mutex_unlock(&system->mutex);
}

// Remove an interface from the network interface management system
void remove_interface(NetworkInterfaceManagementSystem* system) {
    pthread_mutex_lock(&system->mutex);
    system->num_interfaces--;
    char** new_names = (char**)malloc(system->num_interfaces * sizeof(char*));
    for (int i = 0; i < system->num_interfaces; i++) {
        new_names[i] = (char*)strdup(system->interface_names[i]);
    }
    free(system->interface_names);
    system->interface_names = new_names;
