    public void processRecords() {
        ExecutorService executorService = Executors.newFixedThreadPool(5);
        try {
            while (true) {
                List<LogicalDeviceRecord> records = consumeFromKafka();
                if (!records.isEmpty()) {
                    ProcessRecordsTask task = new ProcessRecordsTask(records, jedisPool, producer);
                    executorService.submit(task);
                }
                Thread.sleep(1000); // process records every 1 second
            }
        } catch (Exception e) {
            logger.error("Error processing records: " + e.getMessage());
        } finally {
            executorService.shutdown();
        }
    }

    private List<LogicalDeviceRecord> consumeFromKafka() {
        List<LogicalDeviceRecord> records = new ArrayList<>();
        try {
            ConsumerRecords<String, String> consumerRecords = consumer.poll(100);
            for (ConsumerRecord<String, String> record : consumerRecords) {
                LogicalDeviceRecord logicalDeviceRecord = deserialize(record.value());
                records.add(logicalDeviceRecord);
            }
            consumer.commitSync();
