['```
function runModuleTests(moduleName, testCases, logger, externalServiceConfig) {
  const { concurrencyLimit } = externalServiceConfig;
  const concurrentTestExecutors = [];

  async function executeTestCase(testCase) {
    try {
      await testCase();
    } catch (error) {
      await retryFailedTest(testCase, error);
    }
  }

  async function retryFailedTest(testCase, error) {
    for (let i = 0; i < externalServiceConfig.maxRetries; i++) {
      try {
        await executeTestCase(testCase);
        return;
      } catch (error) {
        if (i === externalServiceConfig.maxRetries - 1) {
          logger.error(`Test ${testCase.name} failed with error:`, error);
          throw error;
        }
      }
    }
  }

  async function runTests() {
    let testsRun = 0;
    let testsPassed = 0;
    let testsFailed = 0;
    let totalExecutionTime = 0;

    while (concurrentTestExecutors.length < concurrencyLimit) {
      const testCase = testCases.pop();
      if (!testCase) break;

      concurrentTestExecutors.push(executeTestCase(testCase));
      testsRun++;
    }

    await Promise.all(concurrentTestExecutors);

    for (const executor of concurrentTestExecutors) {
      const result = await executor;
      if (result) {
        testsPassed++;
      } else {
        testsFailed++;
        totalExecutionTime += Math.round(result.duration / 1000); // Convert to seconds
      }
    }

    logger.info(`Module ${moduleName} test results: 
    Total Tests Run: ${testsRun}
    Passed: ${testsPassed}
    Failed: ${testsFailed}
    Average Execution Time per Test: ${totalExecutionTime / testsRun} seconds`);
  }

  async function startTests() {
    await blueslip.reset();
    await runTests();
  }

  startTests();
}

