// WebFooterRenderer.js
import { version } from './package.json';
const CDN_FALLBACKS = {
  'cdn1': 'https://cdn1.com/script.js',
  'cdn2': 'https://cdn2.com/script.js'
};
class WebFooterRenderer {
  constructor(options) {
    this.options = options;
    this.cachedScripts = {};
    this.metadataProvider = null;
    this.logger = console;
    this.version = version;
  }

  async fetchScriptMetadata(scriptName) {
    try {
      const response = await fetch(`https://metadata-provider.com/${scriptName}`);
      if (!response.ok) throw new Error('Failed to fetch metadata');
      return await response.json();
    } catch (error) {
      this.logger.error(error);
      // Fall back to local cache
      return this.cachedScripts[scriptName] || {};
    }
  }

  async getScript(scriptName, cdn = 'cdn1') {
    const metadata = await this.fetchScriptMetadata(scriptName);
    if (!metadata) throw new Error(`No script metadata found for ${scriptName}`);

    // Check CDN fallbacks
    if (!this.options.cdn || !this.CDN_FALLBACKS[cdn]) {
      return `https://${cdn}.com/${scriptName}`;
    }

    // Fallback to local cache if no CDNs available
    if (!this.cachedScripts[scriptName] && this.options.localCache) {
      const response = await fetch(`local-cache-${scriptName}.js`);
      if (response.ok) {
        this.cachedScripts[scriptName] = await response.text();
      } else {
        throw new Error('Failed to load script from local cache');
      }
    }

    return this.cachedScripts[scriptName] || `https://${cdn}.com/${scriptName}`;
  }

  async renderFooterScripts(scripts) {
    const renderedScripts = [];
    for (const script of scripts) {
      try {
        const src = await this.getScript(script.name, script.cdn);
        renderedScripts.push(`<script src="${src}" defer></script>`);
      } catch (error) {
        this.logger.error(error);
        // Fallback to a default script
        renderedScripts.push('<script>alert("Error: Script failed to load");</script>');
      }
    }

    return renderedScripts.join('');
  }

  async renderFooter() {
    const scripts = await this.options.getScripts();
    return this.renderFooterScripts(scripts);
  }
}

