class FileProcessor {
public:
    FileProcessor(size_t maxFileSize, size_t numWorkers)
        : maxFileSize_(maxFileSize), numWorkers_(numWorkers) {}

    // Function to process a file concurrently
    void processFile(const std::string& inputFile, const std::string& outputFile) {
        // Read the file in chunks and split into threads for processing
        std::vector<std::future<void>> futures;
        size_t chunkSize = maxFileSize_ / numWorkers_;
        size_t remainingBytes = std::ifstream(inputFile)->size() % chunkSize;

        for (size_t i = 0; i < numWorkers_; ++i) {
            size_t start = i * chunkSize + (remainingBytes > 0 ? i < remainingBytes : 0);
            size_t end = start + chunkSize;
            if (remainingBytes > 0 && i == remainingBytes - 1) {
                end += remainingBytes;
            }
            futures.emplace_back(std::async(std::launch::async, [this, inputFile, outputFile, start, end]() {
                processChunk(inputFile, outputFile, start, end);
            }));
        }

        // Wait for all threads to finish
        for (auto& future : futures) {
