import { readFileSync } from 'fs';
import { dirname, join } from 'path';
import { resolve } from 'url';
import { v4 as uuidv4 } from 'uuid';
import { promises as fsPromises } from 'fs';
import { performance } from 'perf_hooks';

const modulesDir = './modules'; // adjust to your desired module directory
let activeModules = {};
let inactiveModules = [];

async function loadModule(moduleName) {
  const filePath = join(modulesDir, `${moduleName}.js`);
  try {
    const moduleCode = readFileSync(filePath, 'utf8');
    const moduleDef = await import(`file://${filePath}`);
    return { code: moduleCode, def: moduleDef };
  } catch (error) {
    console.error(`Error loading ${moduleName}: ${error}`);
  }
}

async function executeModule(moduleName, data) {
  if (!activeModules[moduleName]) {
    activeModules[moduleName] = await loadModule(moduleName);
  }

  try {
    await activeModules[moduleName].def(data);
  } catch (error) {
    console.error(`Error executing ${moduleName}: ${error}`);
  }
}

async function unloadModule(moduleName) {
  if (!activeModules[moduleName]) return;

  delete activeModules[moduleName];
  inactiveModules.push({ name: moduleName, code: activeModules[moduleName].code });
}

async function reloadModule(moduleName) {
  try {
    const { code, def } = await loadModule(moduleName);
    activeModules[moduleName] = { code, def };
  } catch (error) {
    console.error(`Error reloading ${moduleName}: ${error}`);
  }
}

async function startService() {
  while (true) {
    // Monitor the modules directory for changes
    const dirContents = await fsPromises.readdir(modulesDir);
    for (const file of dirContents) {
      if (!file.endsWith('.js')) continue;

      const moduleName = file.replace('.js', '');
      try {
        await loadModule(moduleName);
      } catch (error) {
        console.error(`Error loading ${moduleName}: ${error}`);
      }
    }

    // Periodically unload and reload modules to ensure memory efficiency
    for (const module of Object.keys(activeModules)) {
      const moduleStats = process.memoryUsage();
      if (moduleStats.rss > 10000) {
        await unloadModule(module);
        try {
          await reloadModule(module);
        } catch (error) {
          console.error(`Error reloading ${module}: ${error}`);
        }
      }
    }

    // Wait for some time before checking again
    await new Promise(resolve => setTimeout(resolve, 5000));
  }
}

startService();
