        let mut client = Self {
            state: Default::default(),
            reqwest_client: reqwest::Client::new(),
            task_mpsc: mpsc::channel(10),
        };
        // Initialize the client here
        client
    }

    pub async fn perform_request(&self, method: &str, url: &str) -> Result<String, RequestError> {
