class MemoryPoolAllocator {
public:
    MemoryPoolAllocator(size_t initialSize) {
        memoryPool_.reserve(initialSize);
    }

    void* allocate(size_t size) {
        if (size > maxChunkSize_) {
            // handle allocation failure
            return nullptr;
        }
        auto chunk = memoryPool_.allocate(size);
        if (!chunk) {
            // handle allocation failure
            return nullptr;
        }
        allocatedMemory_ += size;
        return chunk;
    }

    void deallocate(void* ptr, size_t size) {
        memoryPool_.deallocate(ptr, size);
        allocatedMemory_ -= size;
    }

