{
    private readonly string _connectionString;
    private readonly int _iterationCountBase;

    public SecurePasswordService(string connectionString, int iterationCountBase)
    {
        _connectionString = connectionString;
        _iterationCountBase = iterationCountBase;
    }

    public async Task AuthenticateAsync(string username, string password)
    {
        try
        {
            using (var connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();

                var storedHash = await GetStoredHash(username);
                if (storedHash == null) throw new AuthenticationException("Invalid username");

                var hashedPassword = PBKDF2Hash(password, storedHash.Salt);
                if (!VerifyHashedPassword(hashedPassword, storedHash.HashedPassword))
                    throw new AuthenticationException("Invalid password");
            }
        }
        catch (SqlException ex)
        {
            if (ex.Number == 18456) // Connection timeout
            {
                await Task.Delay(TimeSpan.FromSeconds(5)); // retry after 5 seconds

                try
                {
                    await AuthenticateAsync(username, password);
                }
                catch (AuthenticationException)
                {
                    throw;
                }
            }
