public class CryptoLibrary
{
    public static byte[] Encrypt(byte[] data, byte[] key, byte[] iv)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            using (var encryptor = aes.CreateEncryptor())
            {
                return TransformData(encryptor, data);
            }
        }
    }

    public static byte[] Decrypt(byte[] data, byte[] key, byte[] iv)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            using (var decryptor = aes.CreateDecryptor())
            {
                return TransformData(decryptor, data);
            }
        }
    }

    private static byte[] TransformData(ICryptoTransform transform, byte[] data)
    {
        using (var ms = new MemoryStream(data))
        {
            using (var cs = new CryptoStream(ms, transform, CryptoStreamMode.Write))
            {
                cs.FlushFinalBlock();
                return ms.ToArray();
            }
        }
    }

    public static void SerializeObject<T>(T obj, byte[] data)
    {
        var json = JsonConvert.SerializeObject(obj);
        data = Encoding.UTF8.GetBytes(json);
    }

    public static T DeserializeObject<T>(byte[] data)
    {
        data = TransformData(Aes.Create().CreateDecryptor(), data);
        return JsonConvert.DeserializeObject<T>(Encoding.UTF8.GetString(data));
    }
}

