    return (id % 1024);
}

void insert_task(Task *task, int *table) {
    int index = hash(task->id);
    table[index].task = task;
}

Task* get_task(int id, int *table) {
    int index = hash(id);
    return table[index].task;
}

// Define a lock-free data structure for concurrent access
typedef struct _hash_node {
    Task* task;
    struct _hash_node* next;
} HashNode;

typedef struct _lock_free_hash_table {
    int size;
    HashNode** buckets;
} LockFreeHashTable;

void hash_insert(LockFreeHashTable* table, Task* task) {
    int index = task->id % table->size;
    if (!table->buckets[index]) {
        table->buckets[index] = malloc(sizeof(HashNode));
        table->buckets[index]->task = task;
        table->buckets[index]->next = NULL;
    } else {
        HashNode* current = table->buckets[index];
        while (current) {
            if (current->task->id == task->id) {
                // Update existing entry
                return;
            }
            current = current->next;
        }
        HashNode* new_node = malloc(sizeof(HashNode));
        new_node->task = task;
        new_node->next = table->buckets[index];
        table->buckets[index] = new_node;
    }
}

