void chunked_md5(const char* filename, size_t chunk_size, uint8_t** md5_hashes) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) return;

    size_t file_size = 0;
    fseek(file, 0L, SEEK_END);
    file_size = ftell(file);
    rewind(file);

    *md5_hashes = (uint8_t*)malloc((file_size / chunk_size + 1) * sizeof(uint8_t));
    uint8_t* current_chunk = *md5_hashes;

    for (size_t i = 0; i < file_size; i += chunk_size) {
        size_t chunk_left = file_size - i;
        if (chunk_left > chunk_size) chunk_left = chunk_size;

        char buffer[chunk_left + 1];
        fread(buffer, 1, chunk_left, file);
        buffer[chunk_left] = '\0';

        // Compute MD5 hash for this chunk
        uint8_t* md5_hash;
        size_t md5_len = strlen((char*)buffer);
        size_t md5_hash_size = sizeof(uint8_t) * (md5_len / 4 + 1);
        md5_hash = (uint8_t*)malloc(md5_hash_size);
