void* manage_list_of_nfapi_crc_indication_pdu_ts(void*) {
    sem_wait(&update_semaphore);

    // List of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_ts = 
        (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_NFAPI_CRC_INDICATION_PDU_T * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the list with initial data from an external data source
    for (int i = 0; i < MAX_NFAPI_CRC_INDICATION_PDU_T; i++) {
        nfapi_crc_indication_pdu_ts[i].rnti = 0;
    }

    while (1) {
        // Periodically refresh the list based on incoming network data
        int num_new_entries = refresh_list_from_external_data_source();

        for (int i = 0; i < num_new_entries; i++) {
            NFAPI_CRC_INDICATION_PDU_T new_entry;

            // Validate RNTI values against a specified valid range
            if (validate_rnti(&new_entry.rnti) == false) {
                // Log error and skip invalid entry
