                continue;
            }

            int inserted = insert_into_list(nfapi_crc_indication_pdu_ts, &new_entry);

            if (inserted < 0) {
                // Log error and skip insertion
                log_error("Failed to insert NFAPI_CRC_INDICATION_PDU_T structure");
                continue;
            }
        }

        // Handle concurrent updates from different threads and processes
        pthread_mutex_lock(&lock);
        for (int i = 0; i < MAX_NFAPI_CRC_INDICATION_PDU_T; i++) {
