        pthread_mutex_unlock(&lock);

        sem_post(&update_semaphore);
    }

    free(nfapi_crc_indication_pdu_ts);
    return NULL;
}

int main() {
    // Initialize the semaphore for thread-safe operations
    if (sem_init(&update_semaphore, 0, 1) != 0) {
        log_error("Failed to initialize update semaphore");
        return -1;
