// Define the dynamic linked list node structure
typedef struct DynListNode {
    NFAPI_CRC_INDICATION_PDU_T* pdu_data;
    struct DynListNode* next;
} DynListNode;

// Define the DynamicDataFlowManager struct to hold configuration and data
typedef struct {
    int memory_pool_size; // configurable memory pool size
    pthread_mutex_t lock; // thread-safe lock for concurrent access
    DynListNode* head; // head of the dynamic linked list
    void (*pdu_handler)(NFAPI_CRC_INDICATION_PDU_T*); // callback function to handle PDUs
} DynamicDataFlowManager;

// Initialize the DynamicDataFlowManager with a given memory pool size and callback handler
void init_DynamicDataFlowManager(int memory_pool_size, void (*pdu_handler)(NFAPI_CRC_INDICATION_PDU_T*)) {
    // allocate memory for the DynamicDataFlowManager struct
    DynamicDataFlowManager* ddfm = (DynamicDataFlowManager*)malloc(sizeof(DynamicDataFlowManager));

    // set the memory pool size and callback handler
    ddfm->memory_pool_size = memory_pool_size;
    ddfm->pdu_handler = pdu_handler;

    // initialize the thread-safe lock
    pthread_mutex_init(&ddfm->lock, NULL);

    // initialize the head of the dynamic linked list to NULL
    ddfm->head = NULL;
}

// Add a new PDU to the dynamic linked list
void add_PDU(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // allocate memory for a new DynListNode
    DynListNode* node = (DynListNode*)malloc(sizeof(DynListNode));

    // set the PDU data and next pointer
    node->pdu_data = pdu;
    node->next = NULL;

    // lock the dynamic linked list to ensure thread safety
    pthread_mutex_lock(&ddfm->lock);

    // insert the new node at the head of the list
    node->next = ddfm->head;
    ddfm->head = node;

