    pthread_mutex_t lock;
    int pending_ops;
    pthread_cond_t cond;
} lb_queue_t;

lb_queue_t* create_lb_queue();
void enqueue_lb_queue(lb_queue_t*, int);
int dequeue_lb_queue(lb_queue_t*);

// Error handling and logging mechanism
