                throw new InvalidOperationException($"Manager with ID {managerId} is not active");

            var employee = new Employee(employeeName, department, birthdate);

            await _hrApis[GetHRApiIndex(tenantId)].GetEmployeeDetailsAsync(employee);

            // cache the updated employee details
            if (!_employeesByTenantId.TryGetValue(tenantId, out var employees))
                _employeesByTenantId.Add(tenantId, employees = new());
            employees.Add(employee);
        }

