    {"username": "user1", "password": "password1", "roles": ["admin", "user"]},
    {"username": "user2", "password": "password2", "roles": ["user"]},
]

# User roles and permissions data structure
roles_permissions = {
    "admin": ["create_post", "delete_post", "edit_post"],
    "user": ["read_post", "comment_post"],
}

# Token generation function
def generate_token(username, password):
    if username in users and users[username]["password"] == password:
        payload = {"username": username, "exp": datetime.utcnow() + timedelta(minutes=30)}
        token = jwt.encode(payload, "secret_key", algorithm="HS256")
        return token.decode("utf-8")
    else:
        return None

# API endpoint for login
@app.route("/login", methods=["POST"])
def login():
    username = request.json["username"]
    password = request.json["password"]
    token = generate_token(username, password)
    if token:
        return jsonify({"token": token})
    else:
        return jsonify({"error": "Invalid credentials"}), 401

# API endpoint for protected routes
@app.route("/protected", methods=["GET"])
@jwt_required
def protected():
    # Check user roles and permissions
    current_user = get_jwt_identity()
    if current_user in roles_permissions and request.path == "/protected":
        return jsonify({"message": f"Welcome, {current_user}!"})
    else:
        return jsonify({"error": "Access denied"}), 403

if __name__ == "__main__":
    app.run(debug=True)

