                 const config_t* config) {

    // Validate and sanitize the input
    if (!input_text || strlen(input_text) > limit) {
        return -1;  // invalid input
    }

    // Allocate memory for processed text
    char* output_text = (char*) malloc((limit + 1) * sizeof(char));
