        output_text[limit] = '\0';
        if (case_sensitivity) {
            for (size_t i = limit; i < strlen(output_text); i++) {
                output_text[i] = toupper(output_text[i]);
            }
        } else {
            // Do nothing
        }
    }

    // Deallocate memory to prevent leaks
    free(output_text);

    return 0;
}

