DynamicSecureMessageProcessor::DynamicSecureMessageProcessor(int numWorkerThreads, int batchSize) :
    workerThreads(numWorkerThreads), currentBatchSize(0) {
    for (int i = 0; i < numWorkerThreads; ++i) {
        workerThreads[i] = std::thread([this, batchSize]() {
            while (true) {
                SecureMessage message;
                {
                    std::unique_lock<std::mutex> lock(queueMutex);
                    if (messageQueue.empty()) {
                        queueCondition.wait(lock);
                    }
                    message = messageQueue.front();
                    messageQueue.pop();
                }

                // ... (process the message)

                currentBatchSize++;
                if (currentBatchSize >= batchSize) {
                    // ... (send batch to external APIs or brokers)
                    currentBatchSize = 0;
                }
            }
        });
    }
}

void DynamicSecureMessageProcessor::processMessages(std::queue<SecureMessage>& messageQueue) {
    std::unique_lock<std::mutex> lock(queueMutex);
    messageQueueCondition.wait(lock, [&messageQueue]() { return messageQueue.empty(); });

