package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"sync"
	"time"

	"github.com/go-redis/redis/v8"
)

const (
	defaultMaxConns = 15000
	defaultMaxIdle = 5000
	defaultPoolSize = 100
	defaultTimeout = time.Second * 30
)

var (
	maxConns       int
	maxIdle        int
	poolSize       int
	timeout       time.Duration
	redisClient   *redis.Client
)

func main() {
	// Initialize Redis client
	redisClient = redis.NewClient(&redis.Options{
		Addr:     "localhost:6379",
		Password: "",
		DB:       0,
	})

	// Start HTTP server
	http.HandleFunc("/proxy", proxyHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}

func proxyHandler(w http.ResponseWriter, r *http.Request) {
	// Extract request path and method
	path := r.URL.Path
	method := r.Method

	// Get upstream service from Redis
	upstreamService := getUpstreamServiceFromRedis(path)

	// Create a new context with the requested URL and method
	ctx := context.WithValue(context.Background(), "path", path)
	ctx = context.WithValue(ctx, "method", method)

	// Start a new goroutine to handle the request
	go handleRequest(ctx, w, r, upstreamService)
}

func getUpstreamServiceFromRedis(path string) *http.Response {
	// Retrieve the upstream service from Redis using the requested path
	service := redisClient.Get(context.Background(), path).Result()

	// Convert the service response to an HTTPResponse object
	upstreamService := &http.Response{
		StatusCode: 200,
		Body:        ioutil.NopCloser(strings.NewReader(service)),
	}

	return upstreamService
}

func handleRequest(ctx context.Context, w http.ResponseWriter, r *http.Request, upstreamService *http.Response) {
	// Send the request to the upstream service
	req, err := http.NewRequest(method, upstreamService.Request.URL.String(), r.Body)
	if err != nil {
		http.Error(w, err.Message, 500)
		return
	}

	client := &http.Client{}
	resp, err := client.Do(req)

	// Update the response status code and body
	w.WriteHeader(resp.StatusCode)
	w.Write(resp.Body.Bytes())

}
