    // Scale up worker nodes for high concurrency
    client.scale('worker-node', 'my-deployment', { replicas: 5 });
  } else if (metrics.queryLoad < 10) {
    // Scale down worker nodes for low query load
    client.scale('worker-node', 'my-deployment', { replicas: 1 });
  }
}

