```
package com.example.cdn;

import java.util.List;
import reactor.core.publisher.Flux;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.contract.verifier.ContractVerifierConfig;
import org.springframework.cloud.contract.verifier.JacksonMapperConfig;
import org.springframework.cloud.contract.verifier.ScalaContractVerifierConfig;
import org.springframework.cloud.function.export.CloudFunctionExport;

@SpringBootApplication
public class CdnApplication {

    public static void main(String[] args) {
        SpringApplication.run(CdnApplication.class, args);
    }
}

package com.example.cdn.config;

import org.springframework.boot.autoconfigure.EnableAutoConfiguration;
import org.springframework.cloud.contract.verifier.ContractVerifierConfig;
import org.springframework.cloud.function.export.CloudFunctionExport;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
@EnableAutoConfiguration
public class CdnConfig {

    @Bean
    public CloudFunctionExport cloudFunctionExport() {
        return new CloudFunctionExport();
    }
}

package com.example.cdn.service;

import org.springframework.cloud.contract.verifier.ContractVerifierConfig;
import reactor.core.publisher.Flux;
import java.util.List;

public interface ContentDeliveryNetworkService {
    Flux<String> deliverContent(String contentId);
}

package com.example.cdn.repository;

import reactor.core.publisher.Flux;
import java.util.List;

public interface ContentRepository {
    Flux<String> getContent();
}

package com.example.cdn.controller;

import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;
import com.example.cdn.service.ContentDeliveryNetworkService;

@RestController
public class CdnController {

    private final ContentDeliveryNetworkService contentDeliveryNetworkService;

    public CdnController(ContentDeliveryNetworkService contentDeliveryNetworkService) {
        this.contentDeliveryNetworkService = contentDeliveryNetworkService;
    }

    @GetMapping("/content")
    public Flux<String> getContent() {
        return contentDeliveryNetworkService.deliverContent("example-content");
    }
}

package com.example.cdn.error;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

public class CdnException extends RuntimeException {

    private static final long serialVersionUID = 1L;

    @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR)
    public CdnException(String message) {
        super(message);
    }
}

package com.example.cdn.metrics;

import reactor.core.publisher.Flux;
import java.util.List;

public interface MetricsAggregator {
    Flux<String> aggregateMetrics();
}
```
This code provides the foundation for a microservices architecture that manages and optimizes a global content delivery network (CDN). It includes:

1.  A `CdnApplication` class that serves as the main entry point for the application.
2.  A `CdnConfig` class that configures the application, including enabling auto-configuration and defining a cloud function export.
3.  An interface `ContentDeliveryNetworkService` that defines the contract for delivering content from the CDN.
4.  An interface `ContentRepository` that defines the contract for retrieving content from the repository.
5.  A `CdnController` class that handles requests for content delivery and uses the `ContentDeliveryNetworkService` to deliver content.
6.  An exception class `CdnException` that is used to handle errors in the application.
7.  An interface `MetricsAggregator` that defines the contract for aggregating metrics from various sources.

This code provides a starting point for building a resilient, modular microservices architecture that can efficiently manage and optimize a global content delivery network (CDN).']

