        try {
            // obtain distributed lock for user
            commands.set("user:lock:" + userId, "1", 30000);
        } catch (Exception e) {
            // handle lock acquisition failure
        }
    }

    public static void releaseLock(String userId) {
        RedisAsyncCommands<String, String> commands = RedisClient.create().connect("localhost", 6379).async();
        try {
            // release distributed lock for user
            commands.delete("user:lock:" + userId);
        } catch (Exception e) {
