import java.util.concurrent.ExecutionException;
import java.util.concurrent.Future;

public class DistributedUserPreferenceService {

    public static void main(String[] args) throws IOException, InterruptedException {
        // Create an Asynchronous Channel Group
        AsynchronousChannelGroup group = new AsynchronousChannelGroup(1);

        // Open the asynchronous server socket
        AsynchronousServerSocket serverSocket = AsynchronousServerSocket.open(group);
        serverSocket.bind(new InetSocketAddress("localhost", 8080));

        // Start listening for incoming connections
        Future<AsynchronousSocketChannel> future = serverSocket.accept();
        try {
            AsynchronousSocketChannel channel = future.get();

            // Handle connection state changes
            while (true) {
                Future<Integer> futureRead = channel.read(channel.buffer());
                try {
                    int bytesRead = futureRead.get().intValue();
                    System.out.println("Received " + bytesRead + " bytes");
                } catch (ExecutionException e) {
                    throw new RuntimeException(e);
                }
            }
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException(e);
        }

    }
}
