```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define maximum connections
#define MAX_CONNECTIONS 1000

// Define Network Status enumeration
enum NetworkStatus { UP, DOWN, UNKNOWN };

// Define ConnectionStatus structure
typedef struct {
    time_t Timestamp;
    int ConnectionID;
    enum NetworkStatus NetworkStatus;
} ConnectionStatus;

// Function to initialize and manage the doubly linked list of ConnectionStatus structures
ConnectionStatus* connection_list = NULL;
int n_connections = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_connection_list(int N) {
    if (N > MAX_CONNECTIONS) {
        printf("Error: Maximum connections exceeded.\n");
        return;
    }

    // Allocate memory for the list
    connection_list = (ConnectionStatus*) malloc(N * sizeof(ConnectionStatus));
    if (!connection_list) {
        printf("Memory allocation failed.\n");
        return;
    }

    n_connections = N;
}

void add_connection(int ConnectionID, enum NetworkStatus NetworkStatus) {
    pthread_mutex_lock(&lock);

    // Check for connection ID uniqueness
    for (int i = 0; i < n_connections; i++) {
        if (connection_list[i].ConnectionID == ConnectionID) {
            printf("Error: Duplicate connection ID.\n");
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // Add new connection status to the list
    if (n_connections < MAX_CONNECTIONS) {
        connection_list[n_connections].Timestamp = time(NULL);
        connection_list[n_connections].ConnectionID = ConnectionID;
        connection_list[n_connections].NetworkStatus = NetworkStatus;

        n_connections++;
    } else {
        printf("Error: Maximum connections reached.\n");
    }

    pthread_mutex_unlock(&lock);
}

void update_connection_status(int ConnectionID, enum NetworkStatus NetworkStatus) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < n_connections; i++) {
        if (connection_list[i].ConnectionID == ConnectionID) {
            connection_list[i].NetworkStatus = NetworkStatus;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void remove_connection(int ConnectionID) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < n_connections; i++) {
        if (connection_list[i].ConnectionID == ConnectionID) {
            // Shift elements to fill the gap
            memmove(&connection_list[i], &connection_list[i+1], (n_connections - i - 1) * sizeof(ConnectionStatus));

            n_connections--;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void print_connection_list() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < n_connections; i++) {
        printf("Timestamp: %ld, Connection ID: %d, Network Status: %s\n", connection_list[i].Timestamp, connection_list[i].ConnectionID,
               NetworkStatusToString(connection_list[i].NetworkStatus));
    }

    pthread_mutex_unlock(&lock);
}

const char* NetworkStatusToString(enum NetworkStatus status) {
    switch (status) {
        case UP:
            return "UP";
        case DOWN:
            return "DOWN";
        case UNKNOWN:
            return "UNKNOWN";
        default:
            return "Unknown";
    }
}
