import java.util.concurrent.ExecutionException;
import com.amazonaws.services.sqs.AWSSQS;
import com.mongodb.client.MongoClient;
import org.redisson.api.RLock;
import redis.clients.jedis.Jedis;

public class UserPreferenceSyncMicroservice {

    public static void main(String[] args) {
        // Initialize Redis client
        Jedis jedis = new Jedis("localhost", 6379);

        // Initialize MongoDB connection
        MongoClient mongoClient = new MongoClient("mongodb://localhost/user-preferences");

        // Initialize SQS client
        AWSSQS sqs = new AWSSQS("your-aws-access-key-id", "your-aws-secret-access-key");

        // Fetch user preferences from in-memory cache
        String cachedPrefs = jedis.get(req.user.id);

        // Update user preferences in MongoDB
        mongoClient.getDatabase("user-preferences").getCollection("UserPreferences").updateOne(new Document("userId", req.user.id), new Document("$set", cachedPrefs));

        // Send asynchronous task to SQS queue
        sqs.sendMessage(new SendMessageRequest().withQueueUrl("your-sqs-queue-url").withMessageBody(JSON.stringify({ userId: req.user.id })));

        // Distributed lock mechanism using Redis
        RLock redisLock = redisson.getLock("user-preferences-lock");
        try {
            redisLock.lock(10000, TimeUnit.MILLISECONDS); // 10 seconds

            // Update user preferences in MongoDB and SQS queue (atomic operation)
            mongoClient.getDatabase("user-preferences").getCollection("UserPreferences").updateOne(new Document("userId", req.user.id), new Document("$set", cachedPrefs));
            sqs.sendMessage(new SendMessageRequest().withQueueUrl("your-sqs-queue-url").withMessageBody(JSON.stringify({ userId: req.user.id })));

        } catch (ExecutionException | InterruptedException e) {
            System.out.println("Error locking Redis");
        } finally {
            redisLock.unlock();
        }
    }
}
