    private AtomicLong lastActiveTime = new AtomicLong();
    private long sessionExpirationTime = 3600000; // default to 1 hour
    private int maxConcurrentSessions = 10000;
    private int cacheSize = 10000;

    public DynamicUserSessionManager(long sessionExpirationTime, int maxConcurrentSessions, int cacheSize) {
        this.sessionExpirationTime = sessionExpirationTime;
        this.maxConcurrentSessions = maxConcurrentSessions;
        this.cacheSize = cacheSize;
    }

    public void createSession(String userID, String authenticationMethod) throws Exception {
        // implement fine-grained locking mechanism
        synchronized (this) {
            if (sessions.size() >= maxConcurrentSessions) {
                throw new Exception("Maximum concurrent sessions reached");
            }
            Session session = new Session(userID, lastActiveTime.get(), generateSessionToken(authenticationMethod));
            sessions.put(session.getSessionToken(), session);
            sessionTokens.computeIfAbsent(authenticationMethod, k -> new CopyOnWriteArrayList<>()).add(session.getSessionToken());
        }
    }

    public void validateSession(String sessionToken) throws Exception {
        // implement fine-grained locking mechanism
        synchronized (this) {
            Session session = sessions.get(sessionToken);
            if (session == null || isExpired(session.getLastActiveTime())) {
                throw new Exception("Invalid or expired session");
            }
        }
    }

