            if (session == null) {
                throw new Exception("Unknown session token");
            }
            session.setState(newState);
            lastActiveTime.set(System.currentTimeMillis());
        }
    }

    public void removeSession(String sessionToken) throws Exception {
        // implement fine-grained locking mechanism
        synchronized (this) {
            Session session = sessions.remove(sessionToken);
            if (session == null) {
                throw new Exception("Unknown session token");
            }
            CopyOnWriteArrayList<SessionToken> tokens = sessionTokens.get(session.getState());
            tokens.remove(sessionToken);
