// Define the maximum number of events in the list
#define MAX_EVENTS 1000

// Define the maximum age of an event before it is removed (in seconds)
#define EVENT_AGE_THRESHOLD 3600 // 1 hour

typedef struct {
    network_event_t* events;
    size_t size;
    size_t capacity;
} event_list_t;

event_list_t* event_list_create() {
    event_list_t* list = malloc(sizeof(event_list_t));
    if (!list) {
        LOG_ERROR("Failed to allocate memory for event list");
        return NULL;
    }
    list->size = 0;
    list->capacity = MAX_EVENTS;
    list->events = calloc(list->capacity, sizeof(network_event_t));
    if (!list->events) {
        LOG_ERROR("Failed to allocate memory for events");
        free(list);
        return NULL;
    }
    return list;
}

void event_list_destroy(event_list_t* list) {
    if (!list) {
        return;
    }
    free(list->events);
    free(list);
}

void event_list_add(event_list_t* list, network_event_t* event) {
    if (!list || !event) {
        LOG_ERROR("Invalid input for adding an event");
        return;
    }
    if (list->size == list->capacity) {
        // Reallocate the events array with double capacity
        list->events = realloc(list->events, 2 * list->capacity * sizeof(network_event_t));
        if (!list->events) {
            LOG_ERROR("Failed to reallocate memory for events");
            return;
        }
        list->capacity *= 2;
    }
    list->events[list->size++] = event;
}

void event_list_remove_old_events(event_list_t* list, time_t threshold) {
    if (!list) {
        return;
    }
    size_t i = 0;
    while (i < list->size) {
        network_event_t* event = &list->events[i];
        if (event->timestamp + EVENT_AGE_THRESHOLD <= threshold) {
            // Event is older than the threshold, remove it
            memmove(&list->events[i], &list->events[i + 1], (list->size - i - 1) * sizeof(network_event_t));
            list->size--;
            i--;
        }
        i++;
    }
}

