        LOG_ERROR("Invalid input for getting recent events");
        return NULL;
    }
    network_event_t* events = malloc(num_events * sizeof(network_event_t));
    if (!events) {
        LOG_ERROR("Failed to allocate memory for recent events");
        return NULL;
    }
    memcpy(events, &list->events[list->size - num_events], num_events * sizeof(network_event_t));
    return events;
}

