class ResourceRequest {
public:
    int requestId;
    std::string priorityLevel;
    std::string resourceType;
    long timestamp;

    ResourceRequest(int requestId, const std::string& priorityLevel, const std::string& resourceType, long timestamp)
        : requestId(requestId), priorityLevel(priorityLevel), resourceType(resourceType), timestamp(timestamp) {}
};

class ResourceManager {
public:
    ResourceManager() : requests_, ready_(false), shutdown_(false) {}

    void addRequest(const ResourceRequest& request) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            requests_.push(request);
        }
        cv_.notify_one();
    }

    void removeRequest(int requestId) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            while (!requests_.empty()) {
                if (requests_.front().requestId == requestId) {
                    requests_.pop();
                    break;
                }
                requests_.pop();
            }
        }
    }

    bool hasReadyRequest() const {
        return !requests_.empty() && ready_;
    }

    void setReady() {
        std::lock_guard<std::mutex> lock(mutex_);
        ready_ = true;
    }

    void setShutdown() {
        std::lock_guard<std::mutex> lock(mutex_);
        shutdown_ = true;
    }

private:
    std::priority_queue<ResourceRequest, std::vector<ResourceRequest>, decltype([](const ResourceRequest& a, const ResourceRequest& b) { return a.priorityLevel < b.priorityLevel; })> requests_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool ready_;
    bool shutdown_;
};

