// LRU Cache Mechanism
class LRUCache {
public:
    LRUCache(size_t capacity) : cache_(capacity), hit_rate_(0), miss_rate_(0) {}

    template<typename T>
    void insert(const std::string& key, T&& value) {
        if (cache_.size() >= cache_.capacity()) {
            // Evict the least recently used item
            auto it = cache_.begin();
            cache_.erase(it);
        }
        cache_[key] = value;
    }

    template<typename T>
    std::any get(const std::string& key) {
        if (cache_.find(key) != cache_.end()) {
            // Cache hit
            hit_rate_++;
            return cache_[key];
        } else {
            // Cache miss
            miss_rate_++;
            return std::any(); // Return an empty any object for misses
        }
    }

    double getHitRate() { return static_cast<double>(hit_rate_) / (hit_rate_ + miss_rate_); }
    double getMissRate() { return static_cast<double>(miss_rate_) / (hit_rate_ + miss_rate_); }

private:
    std::unordered_map<std::string, std::any> cache_;
    size_t hit_rate_;
    size_t miss_rate_;
};

// Node Class
