        kv_store_[kv_pair.key] = kv_pair.value;
        condition_variable_.notify_all();
    }

    // Read a KV pair from memory
    std::any readKVPair(const std::string& key) {
        std::unique_lock<std::mutex> lock(*lock_);
        if (kv_store_.find(key) != kv_store_.end()) {
            return kv_store_[key];
        } else {
            return std::any(); // Return an empty any object for missing keys
        }
    }

private:
    int id_;
    std::unique_ptr<std::mutex> lock_;
    std::condition_variable condition_variable_;
    std::map<std::string, std::any> kv_store_;
    bool leader_;
    Cluster* cluster_;
};

// Cluster Class
