#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <thread>

// Forward declaration of classes
class Node;
class Cluster;

// Abstract base class for nodes in the cluster
class Node {
public:
    virtual ~Node() {}
    virtual void receiveRequest(const std::string& request) = 0;
};

// Concrete node implementation
class DistributedNode : public Node {
private:
    // Internal key-value store
    std::unordered_map<std::string, std::string> store;

    // Mutex for concurrent access
    std::mutex mutex;

public:
    void receiveRequest(const std::string& request) override {
        // Handle incoming requests (read/write)
        if (request.find("PUT") != std::string::npos) {
            // Update key-value pair
            auto parts = splitRequest(request);
            store[parts[0]] = parts[1];
        } else if (request.find("GET") != std::string::npos) {
            // Retrieve key-value pair
            auto parts = splitRequest(request);
            if (store.find(parts[0]) != store.end()) {
                std::cout << "Value: " << store[parts[0]] << std::endl;
            } else {
                std::cout << "Key not found." << std::endl;
            }
        }
    }

private:
    // Helper function to split requests into key and value
    std::vector<std::string> splitRequest(const std::string& request) {
        std::vector<std::string> parts;
        size_t pos = 0, prev = 0;
        while ((pos = request.find(" ", pos)) != std::string::npos) {
            parts.push_back(request.substr(prev, pos - prev));
            prev = pos + 1;
        }
        parts.push_back(request.substr(prev));
        return parts;
    }
};

// Abstract base class for clusters
class Cluster {
public:
    virtual ~Cluster() {}
    virtual void receiveRequest(const std::string& request) = 0;
};

// Concrete cluster implementation
class DistributedCluster : public Cluster {
private:
    // List of nodes in the cluster
    std::vector<std::unique_ptr<Node>> nodes;

public:
    void receiveRequest(const std::string& request) override {
        // Distribute requests across nodes
        for (auto& node : nodes) {
            node->receiveRequest(request);
        }
    }

    // Add a new node to the cluster
    void addNode(std::unique_ptr<Node> newNode) {
        nodes.push_back(std::move(newNode));
    }
};

int main() {
    // Create a distributed cluster
    DistributedCluster cluster;

    // Create two nodes in the cluster
    auto node1 = std::make_unique<DistributedNode>();
    auto node2 = std::make_unique<DistributedNode>();

    // Add nodes to the cluster
    cluster.addNode(std::move(node1));
    cluster.addNode(std::move(node2));

    // Send requests to the cluster
    cluster.receiveRequest("PUT key1 value1");
    cluster.receiveRequest("GET key1");

    return 0;
}

