void rename_files(char *dir_path, int precision) {
    DIR *dir;
    struct dirent *ent;
    char timestamp[TIMESTAMP_LENGTH];
    time_t now = time(NULL);
    srand((unsigned)now);
    int digits = (rand() % 3) + 2;

    dir = opendir(dir_path);
    if (dir == NULL) {
        // handle error
    }

    while ((ent = readdir(dir)) != NULL) {
        char new_name[TIMESTAMP_LENGTH];
        strftime(timestamp, TIMESTAMP_LENGTH, "%Y%m%d%H%M%S", localtime(&now));
        for (int i = 0; i < digits; i++) {
            timestamp[strlen(timestamp)] = '0' + rand() % 10;
        }
        sprintf(new_name, "%s-%s", ent->d_name, timestamp);
        renameat(dirfd(dir), dir_path, strlen(ent->d_name) + strlen(timestamp) + 1, ent->d_name, new_name);
    }

    closedir(dir);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        // handle error
    }
    rename_files(argv[1], atoi(argv[2]));
    return 0;
}
