#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>

// Function to batch rename files with versioning
void batchFileRenamingWithVersioning(const std::string& directoryPath,
                                       int initialVersion = 1, int maxVersionIncrement = 10) {
    // Set custom directory path
    const std::string path = (directoryPath.empty()) ? "." : directoryPath;

    // Get list of files in the specified directory
    std::vector<std::string> files;
    for (const auto& file : std::filesystem::directory_iterator(path)) {
        if (file.is_regular_file()) {
            files.emplace_back(file.path().string());
        }
    }

    // Lock to ensure thread safety and prevent concurrent modifications
    static std::mutex lock;

    for (auto& file : files) {
        try {
            // Acquire lock before renaming the file
            lock.lock();

            // Get file name without extension
            auto filename = file.substr(0, file.find_last_of('.'));

            // Check if versioning is necessary
            if (!file.find("v") != std::string::npos) {
                int currentVersion = 1;
                for (auto& vFile : files) {
                    if (vFile.find(filename + "v") == 0) {
                        auto verStr = vFile.substr(vFile.find_last_of('.') + 1);
                        currentVersion = std::stoi(verStr.substr(1));
                    }
                }

                // Check version increment constraints
                if (currentVersion >= initialVersion && 
                    currentVersion + maxVersionIncrement > initialVersion) {
                    // Rename the file with a new version number
                    auto newName = filename + "v" + std::to_string(currentVersion + 1).substr(1);
                    std::rename(file.c_str(), (path + "/" + newName).c_str());
                }
            }

            // Release lock after renaming the file
            lock.unlock();
        } catch (...) {
            // Log error and skip renaming for this file
            std::cerr << "Error renaming file: " << file << std::endl;
        }
    }

    // Start a separate thread to handle logging errors asynchronously
    std::thread logThread([directoryPath]() {
        while (true) {
            auto err = std::filesystem::get_last_write_time(path);
            if (!err) {
                break;
            }
            std::cout << "Error occurred at: " << err.time_since_epoch().count() << " seconds" << std::endl;
        }
    });

    // Wait for the logging thread to finish
    logThread.join();
}
```']

