MemoryPool* init_memory_pool(size_t capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->data = (long*)malloc(capacity * sizeof(long));
    pool->capacity = capacity;
    pool->used = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

// Function to get memory from the pool
long* get_memory_from_pool(MemoryPool* pool) {
    long* result = NULL;

    pthread_mutex_lock(&pool->mutex);

    if (pool->used < pool->capacity) {
        result = &pool->data[pool->used];
        pool->used++;
    } else {
        // Handle memory allocation failure
    }

    pthread_mutex_unlock(&pool->mutex);

    return result;
}

// Function to release memory back to the pool
