use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::sync::RwLock;
use std::thread;

mod dir_util {
    pub fn create_dir(parent_path: &str) -> Result<PathBuf, std::io::Error> {
        let path = format!("{}/new_dir", parent_path);
        fs::create_dir_all(path.as_str())?;
        Ok(PathBuf::from(path))
    }
}

struct EnvVarManager {
    env_var_name: String,
    dir_path_pool: Arc<RwLock Vec<PathBuf>>,
}

impl EnvVarManager {
    fn new(env_var_name: &str) -> Self {
        Self {
            env_var_name: env_var_name.to_string(),
            dir_path_pool: Arc::new(RwLock::new(Vec::new())),
        }
    }

    fn set_env_var(&self, path: &Path) -> Result<(), std::io::Error> {
        let mut dir_path_pool = self.dir_path_pool.write().unwrap();
        dir_path_pool.push(path.clone());
        env::set_var(&self.env_var_name, &format!("{}", path.display()));
        Ok(())
    }

    fn get_env_var(&self) -> Option<PathBuf> {
        let dir_path_pool = self.dir_path_pool.read().unwrap();
        dir_path_pool.last().cloned()
    }
}

