void update_network_interface(NetworkInterface* interface, int mac_id, const char* ip_address, int port) {
    pthread_mutex_lock(&interface->lock);

    for (int i = 0; i < MAX_INTERFACE_COUNT; i++) {
        if (interface->configs[i].mac_id == -1) {
            interface->configs[i].mac_id = mac_id;
            strcpy(interface->configs[i].ip_address, ip_address);
            interface->configs[i].port = port;
