use std::fs;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::sync::atomic::AtomicUsize;
use std::thread;
use std::time::Duration;

// Module to asynchronously create and manage hierarchical directory structure
pub mod dir_manager {
    use std::collections::HashMap;
    use std::fs::{self, DirEntry};
    use std::path::{Path, PathBuf};
    use std::sync::Arc;
    use std::thread;
    use std::time::Duration;

    // Structure to hold the directory hierarchy
    pub struct DirectoryHierarchy {
        root: Arc<PathBuf>,
        dir_map: HashMap<String, Arc<PathBuf>>,
    }

    impl DirectoryHierarchy {
        fn new(root: &str) -> Self {
            let mut dir_map = HashMap::new();
            let root_path = Path::new(root).to_path_buf();
            let root_arc = Arc::new(root_path);
            DirectoryHierarchy { root: root_arc.clone(), dir_map }
        }

        fn create_directory(&mut self, path: &str) -> Result<(), String> {
            let mut curr_dir = &self.root;
            for part in path.split('/') {
                if part.is_empty() || part == "." || part == ".." {
                    continue;
                }
                let new_path = curr_dir.join(part);
                match fs::create_dir_all(&new_path) {
                    Ok(_) => {
                        curr_dir = &new_path;
                        self.dir_map.insert(path.to_string(), Arc::clone(&curr_dir));
                    }
                    Err(e) => return Err(format!("Error creating directory: {}", e)),
                };
            }
            Ok(())
        }

        fn get_directory(&self, path: &str) -> Result<&PathBuf, String> {
            let path = Path::new(path).to_path_buf();
            if self.dir_map.contains_key(path.file_name().unwrap_or_default()) {
                return Ok(self.dir_map.get(path.file_name().unwrap_or_default()).unwrap().clone());
            }
            Err("Directory not found".to_string())
        }
    }

    // Structure to hold the external data source and fallback directory
    pub struct DirectoryManager {
        dir_hierarchy: Arc<DirectoryHierarchy>,
        data_source: Option<Box<dyn Fn() -> Result<String, String>>>,
        fallback_dir: Arc<PathBuf>,
    }

    impl DirectoryManager {
        fn new(data_source: Box<dyn Fn() -> Result<String, String>>, fallback_dir: &str) -> Self {
            let dir_hierarchy = Arc::new(DirectoryHierarchy::new(fallback_dir));
            DirectoryManager { dir_hierarchy, data_source: Some(data_source), fallback_dir: Arc::new(Path::new(fallback_dir).to_path_buf()) }
        }

        fn create_directory(&mut self) -> Result<(), String> {
            match &self.data_source {
                Some(data_source) => {
                    let path = (data_source)().unwrap_or_default();
                    if path.is_empty() {
                        return Ok(());
                    }
                    if let Err(e) = self.dir_hierarchy.create_directory(path.as_str()) {
                        println!("Error creating directory: {}", e);
                        // Fallback to fallback directory
                        let fallback_path = &self.fallback_dir.join("fallback");
                        match fs::create_dir_all(&fallback_path) {
                            Ok(_) => {
                                println!("Fallback directory created at {}", fallback_path.display());
                            }
                            Err(e) => println!("Error creating fallback directory: {}", e),
                        };
                    } else {
                        println!("Directory successfully created at {}", path);
                    }
                }
                None => Ok(()),
            }
        }

        fn get_directory(&self, path: &str) -> Result<&PathBuf, String> {
            self.dir_hierarchy.get_directory(path)
        }
    }
}

// Example usage
fn main() {
    let data_source = Box::new(|| -> Result<String, String> { /* Your external data source implementation */ });
    let fallback_dir = "/path/to/fallback/directory";
    let mut dir_manager = dir_manager::DirectoryManager::new(data_source, fallback_dir);
    if let Err(e) = dir_manager.create_directory() {
        println!("Error creating directory: {}", e);
    } else {
        println!("Directory successfully created");
    }
}
