#define LOG_MAX_SIZE 1024
#define RETRY_MAX 5
#define BACKOFF_DURATION 1000 // in milliseconds
#define CIRCUIT_BREAKER_TIMEOUT 5000 // in milliseconds

// Custom lock-free queue for efficient inter-thread communication
typedef struct {
    void** elements;
    int size;
    int front;
    int rear;
} Queue;

Queue* create_queue(int capacity) {
    Queue* q = (Queue*) malloc(sizeof(Queue));
    q->elements = (void**) calloc(capacity, sizeof(void*));
    q->size = 0;
    q->front = 0;
    q->rear = 0;
    return q;
}

void enqueue(Queue* q, void* element) {
    if(q->rear >= q->size)
        q->size *= 2; // Double the size of the queue when it's full
    q->elements[q->rear++] = element;
}

void* dequeue(Queue* q) {
    if(q->front == q->rear)
        return NULL; // Queue is empty
    void* result = q->elements[q->front++];
    if(q->front >= q->size/2) // If the queue is half full, shrink it to save memory
        q->size /= 2;
    return result;
}

