    Unit,
    Integration,
}
impl Task for TestTask {
    fn execute(&self) -> Result<String, &str> {
        match self {
            TestTask::Unit => {
                // Execute unit tests
                Ok("Unit tests passed successfully".to_string())
            }
            TestTask::Integration => {
                // Execute integration tests
                Ok("Integration tests passed successfully".to_string())
            }
        }
    }
}

