    public ConnectionHandler(AsynchronousSocketChannel socket) {
        this.socket = socket;
    }

    public void handle(RetryStrategy retryStrategy) {
        try {
            // Handle incoming connection
            processConnection(socket);
        } catch (Exception e) {
            // Log error and notify load balancer
            logger.error("Error handling connection", e);
            retryStrategy.handle(this);
        }
