#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <map>
#include <queue>

class CooldownManager {
public:
    CooldownManager() : cooldowns{} {}

    void updateCooldown(const std::string& player, int cooldownTime) {
        std::lock_guard<std::mutex> lock(cooldownMutex);
        cooldowns[player] = cooldownTime;
    }

    bool isReadyForAttack(const std::string& player) {
        std::unique_lock<std::mutex> lock(cooldownMutex);
        if (cooldowns.find(player) != cooldowns.end()) {
            int remainingCooldown = cooldowns[player];
            if (remainingCooldown > 0) {
                return false;
            }
        }
        return true;
    }

private:
    std::map<std::string, int> cooldowns;
    std::mutex cooldownMutex;
};

class StrategicAttackExecutor {
