{
    public class DataProcessor : ActorBase
    {
        private readonly ILogger _logger;
        private readonly IActorRef _processorActor;
        private readonly IActorRef _serializerActor;
        private readonly IActorRef _cacheActor;

        public DataProcessor(ILogger<DataProcessor> logger)
        {
            _logger = logger;
            _processorActor = Context.ActorOf(Props.Create<DataProcessorActor>());
            _serializerActor = Context.ActorOf(Props.Create<SerializerActor>());
            _cacheActor = Context.ActorOf(Props.Create<CachedDataActor>());
        }
    }

    public class DataProcessorActor : ActorBase
    {
        private readonly ILogger _logger;
        private readonly IActorRef _serializerActor;
        private readonly IActorRef _cacheActor;

        public DataProcessorActor(ILogger<DataProcessorActor> logger, IActorRef serializerActor, IActorRef cacheActor)
        {
            _logger = logger;
            _serializerActor = serializerActor;
            _cacheActor = cacheActor;
        }

        public override void OnReceive(object message)
        {
            if (message is BinaryDataRecord record)
            {
                try
                {
                    var serializedRecord = _serializerActor.Tell(record).Result;
                    _cacheActor.Tell(serializedRecord);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing binary data");
                }
            }
            else
            {
                throw new ArgumentException("Invalid message type", nameof(message));
            }
        }
    }

    public class SerializerActor : ActorBase
    {
        private readonly ILogger _logger;
        private readonly IVersionedSerializer _serializer;

        public SerializerActor(ILogger<SerializerActor> logger, IVersionedSerializer serializer)
        {
            _logger = logger;
            _serializer = serializer;
        }

        public override void OnReceive(object message)
        {
            if (message is BinaryDataRecord record)
            {
                try
                {
                    var serializedRecord = _serializer.Serialize(record);
                    Sender.Tell(serializedRecord);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error serializing binary data");
                }
            }
            else
            {
                throw new ArgumentException("Invalid message type", nameof(message));
            }
        }
    }

    public class CachedDataActor : ActorBase
    {
        private readonly ILogger _logger;
        private readonly ICacheManager _cache;

        public CachedDataActor(ILogger<CachedDataActor> logger, ICacheManager cache)
        {
            _logger = logger;
            _cache = cache;
        }

        public override void OnReceive(object message)
        {
            if (message is SerializedBinaryDataRecord record)
            {
                try
                {
                    _cache.Add(record);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error caching serialized data");
                }
            }
            else
            {
                throw new ArgumentException("Invalid message type", nameof(message));
            }
        }
    }

