using namespace std;

class DistributedCache {
public:
    map<string, pair<int, string>> cache;
    unordered_map<string, thread::id> workerThreads;
    mutex mtx;
    condition_variable cv;
    bool shutdown = false;

    void put(const string& key, int expirationTime, const string& value) {
        unique_lock<mutex> lock(mtx);
        if (shutdown) {
            throw runtime_error("Cache is shut down");
        }
        cache[key] = {expirationTime, value};
        cv.notify_one();
    }

    void get(const string& key, string& result) {
        unique_lock<mutex> lock(mtx);
        while (!cache.count(key)) {
            this_thread::sleep_for(chrono::milliseconds(100));
        }
        result = cache[key].second;
    }

    void remove(const string& key) {
        unique_lock<mutex> lock(mtx);
        if (shutdown) {
            throw runtime_error("Cache is shut down");
        }
        cache.erase(key);
    }

    void shutdown() {
        {
            lock_guard<mutex> lock(mtx);
            shutdown = true;
        }
        cv.notify_all();
    }

    thread<void()> startWorkerThread(int workerID) {
        thread t([this, workerID]() {
            while (true) {
                unique_lock<mutex> lock(mtx);
                if (shutdown) {
                    return;
                }
                while (!cv.wait_for(lock, chrono::milliseconds(100), [&]{return !cache.empty();})) {
                    // Spin and do nothing
                }
                for (auto& entry : cache) {
                    if (chrono::system_clock::now().time_since_epoch() >= chrono::system_clock::from_time_t(entry.second.first)) {
                        remove(entry.first);
                    }
                }
            }
        });
        workerThreads[workerID] = t.get_id();
        return t;
    }
};

int main() {
    DistributedCache cache;

    // Start worker threads
    vector<thread> workerThreads;
    for (int i = 0; i < 4; ++i) {
        workerThreads.push_back(cache.startWorkerThread(i));
    }

    // Put key-value pairs into the cache
    cache.put("key1", 10000, "value1");
    cache.put("key2", 5000, "value2");

    // Get values from the cache
    string value;
    cache.get("key1", value);
    cout << "Value for 'key1': " << value << endl;

    // Remove a key-value pair from the cache
    cache.remove("key2");

    // Shut down the cache
    cache.shutdown();

    return 0;
}
```

