// Cooldown mechanism using atomic counters and shared memory
class Cooldown {
public:
    Cooldown(const int& cooldownPeriod) : cooldown_(cooldownPeriod), lock_() {}

    bool isReady() const {
        return cooldown_.load(std::memory_order_relaxed) <= 0;
    }

    void resetCooldown() {
        std::unique_lock<std::mutex> lock(lock_);
        cooldown_.store(cooldownPeriod, std::memory_order_relaxed);
    }

    void decrementCooldown() {
        std::unique_lock<std::mutex> lock(lock_);
        while (!cooldown_.load(std::memory_order_relaxed)) {
            this_thread::yield();
        }
        --cooldown_;
    }

private:
    std::atomic<int> cooldown_;
    mutable std::mutex lock_;
};

