class BackendService {
public:
    BackendService(int cacheSize);

    void createDocument(const Json::Value& metadata, const std::vector<char>& binaryData);
    void updateDocument(const std::string& id, const Json::Value& newMetadata, const std::vector<char>& newBinaryData);
    void deleteDocument(const std::string& id);

private:
    // Define a distributed caching layer using a shared_mutex
    std::shared_mutex cacheMutex;
    std::unordered_map<std::string, JsonDocument> cache;

    // Define a utility function for updating the cache
    void updateCache(const std::string& id, const JsonDocument& document);
};

// Implement the BackendService class
BackendService::BackendService(int cacheSize) {
    // Initialize the cache with the specified size
    cache.reserve(cacheSize);
}

void BackendService::createDocument(const Json::Value& metadata, const std::vector<char>& binaryData) {
    // Create a new JSON document and add it to the cache
    JsonDocument document;
    document.id = generateUniqueId();
    document.metadata = metadata;
    document.binaryData = binaryData;
    updateCache(document.id, document);
}

void BackendService::updateDocument(const std::string& id, const Json::Value& newMetadata, const std::vector<char>& newBinaryData) {
    // Update the existing JSON document in the cache
    if (cache.find(id) != cache.end()) {
        auto document = cache.at(id);
        document.metadata = newMetadata;
        document.binaryData = newBinaryData;
        updateCache(id, document);
    }
}

void BackendService::deleteDocument(const std::string& id) {
    // Remove the JSON document from the cache
    if (cache.find(id) != cache.end()) {
        cache.erase(id);
    }
}

// Define a utility function for updating the cache
void BackendService::updateCache(const std::string& id, const JsonDocument& document) {
    // Acquire a shared lock on the cache
    std::shared_lock<std::shared_mutex> lock(cacheMutex);

    // Update the cache with the new JSON document
    cache[id] = document;
}

