package main

import (
	"context"
	"fmt"
	"log"
	"sync"

	"github.com/go-redis/redis/v8"
	"github.com/gorilla/mux"
)

// DynamicDataProcessor represents a dynamic data processing system.
type DynamicDataProcessor struct {
	ctx        context.Context
	inventory  map[string]int
	cache      *redis.Client
	mu         sync.Mutex
	retryPolicy retryPolicy
}

func NewDynamicDataProcessor(ctx context.Context) *DynamicDataProcessor {
	return &DynamicDataProcessor{
		ctx:       ctx,
		inventory: make(map[string]int),
		cache:     redis.NewClient(&redis.Options{}),
	}
}

// HandleRequest handles incoming requests and processes data accordingly.
func (d *DynamicDataProcessor) HandleRequest(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	itemID := vars["item_id"]
	quantity := 0

	d.mu.Lock()
	defer d.mu.Unlock()

	if quantity, ok := d.inventory[itemID]; ok {
		fmt.Fprintf(w, "Item %s quantity: %d", itemID, quantity)
	} else {
		w.WriteHeader(http.StatusNotFound)
		fmt.Fprint(w, "Item not found")
	}
}

func main() {
	ctx = context.Background()
	dp := NewDynamicDataProcessor(ctx)

	http.HandleFunc("/items/{item_id}", dp.HandleRequest)
	log.Fatal(http.ListenAndServe(":8080", nil))
}

// retryPolicy represents a retry policy for the system.
type retryPolicy struct{}

// Try attempts to execute an action with retries.
func (r *retryPolicy) Try(action func() error, maxAttempts int) {
	attempts := 0
	for attempt := 1; attempt <= maxAttempts; attempt++ {
		err := action()
		if err == nil {
			return
		}
		log.Println("Attempt failed: ", err)
		if attempt < maxAttempts {
			log.Printf("Retrying in %d seconds...", r.getBackoffTime(attempt))
			time.Sleep(r.getBackoffTime(attempt))
		} else {
			log.Println("Maximum attempts reached. Giving up.")
			return
		}
	}
}

// getBackoffTime returns the time to wait before the next attempt.
func (r *retryPolicy) getBackoffTime(attempt int) time.Duration {
	backoffTime := 1 << uint(attempt)
	return time.Duration(backoffTime) * time.Second
}

