use std::fs;
use std::path::{Path, PathBuf};
use std::collections::HashMap;

mod grammar {
    pub struct Grammar {
        pub name: String,
        pub version: String,
        pub rules: HashMap<String, String>,
    }
}

fn load_grammar(path: &str) -> Option<grammar::Grammar> {
    // Load the grammar from the file
    let contents = fs::read_to_string(Path::new(path))?;
    let grammar = match serde_json::from_str(&contents) {
        Ok(g) => g,
        Err(_) => return None,
    };
    Some(grammar)
}

fn parse_file(file_path: &str, grammar: &grammar::Grammar) -> Result<(), String> {
    // Parse the file using the loaded grammar
    let contents = fs::read_to_string(Path::new(file_path))?;
    let ast = match parser::parse(&contents, grammar) {
        Ok(ast) => ast,
        Err(err) => return Err(err.to_string()),
    };
    // Generate LLVM IR code from the AST
    let ir_code = compiler::compile(ast)?;
    // Store the generated LLVM IR code in the database and cloud storage
    store_ir_code(ir_code, file_path)?;
    Ok(())
}

fn main() {
    let grammar_dir = Path::new("grammars");
    let db_url = "mongodb://localhost:27017";
    let cloud_storage_bucket = "my-bucket";

    // Load grammars from directory
    let mut grammars = HashMap::new();
    for entry in grammar_dir.read_dir().unwrap() {
        match entry {
            Ok(entry) => {
                let path = entry.path();
                if let Some(grammar) = load_grammar(path.as_str()) {
                    grammars.insert(grammar.name.clone(), grammar);
                }
            },
            Err(_) => continue,
        }
    }

    // Start processing files
    for file_path in Path::new("files").read_dir().unwrap() {
        match file_path {
            Ok(file_path) => {
                let file_name = file_path.file_name();
                if let Some(grammar) = grammars.get(file_name.unwrap().to_str()) {
                    match parse_file(&file_path, grammar) {
                        Ok(_) => println!("File processed successfully!"),
                        Err(err) => println!("Error processing file: {}", err),
                    }
                } else {
                    eprintln!("Unknown grammar for file '{}'", file_name.unwrap());
                }
            },
            Err(_) => continue,
        }
    }
}

fn store_ir_code(ir_code: String, file_path: &str) {
    // Store the LLVM IR code in the database
    let client = mongodb::Client::with_uri(&db_url).unwrap();
    let db = client.db("my-database");
    let coll = db.collection("ir-code");
    coll.insert_one(doc! {"file_path" => file_path, "ir_code" => ir_code}, None).unwrap();

    // Upload the LLVM IR code to cloud storage
    let bucket = cloud_storage::Bucket::new(cloud_storage_bucket);
    let object_name = format!("{}-{}.ll", file_path.file_stem().unwrap(), ir_code);
    bucket.put_object(object_name, ir_code.as_bytes());
}
