class SandeshClient {
public:
    SandeshClient(io_context& io_ctx, string endpoint)
        : socket_(io_ctx) {
        // Set up the connection
        beast::error_code ec;
        socket_.connect(endpoint, ec);
        if (ec) {
            throw system_error(ec);
        }
    }

    void send_request(string request_method, string request_body) {
        // Send the request
        beast::http::request<beast::http::string_body> req;
        req.method(request_method);
        req.body(request_body);

        // Set up the response handler
        response_handler_ = [this](const beast::error& ec) {
            if (ec) {
                throw system_error(ec);
            }
        };

        // Start the asynchronous request
        socket_.async_send(beast::http::request_parser::parse(req), 
                            beast::bind_front(&SandeshClient::on_response, this),
                            response_handler_);
    }

private:
    void on_response(beast::error_code ec) {
        // Handle the response
        if (ec) {
            throw system_error(ec);
        }
    }

    io_context& socket_;
    function<void(const beast::error&)>& response_handler_;
};

int main() {
    io_context io_ctx;

    string endpoint = "http://example.com";
    SandeshClient client(io_ctx, endpoint);

    string request_method = "GET";
    string request_body = "{\"key\": \"value\"}";

    client.send_request(request_method, request_body);

    return 0;
}
